CREATE FUNCTION public.ai_cancel_prepared_request(p_request uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare current_state text;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null then raise exception 'invalid request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select state into current_state from public.ai_request_preparations where request_id=p_request for update;
 if current_state is null then raise exception 'preparation unavailable'; end if;
 if current_state='cancelled' then return false; end if;
 if current_state<>'prepared' then raise exception 'checked request requires reconciliation'; end if;
 update public.ai_request_preparations set state='cancelled',state_changed_at=clock_timestamp() where request_id=p_request;
 return true;
end $$;



CREATE FUNCTION public.ai_check_article_body_snapshot(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare r public.article_body_requests%rowtype; c public.article_body_request_context%rowtype; receipt public.article_body_receipts%rowtype;
 cfg public.article_stage_configs%rowtype; route public.ai_model_routes%rowtype; prep public.ai_request_preparations%rowtype;
 facts jsonb; deadline timestamptz; title_deadline timestamptz; n integer;
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 if current_setting('transaction_isolation')<>'read committed' or p_request is null then raise exception 'invalid article request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists
  (select 1 from public.ai_execution_safety_resolutions s where s.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into prep from public.ai_request_preparations where request_id=p_request for update;
 if prep.request_id is null or prep.state<>'prepared' or prep.created_at<=clock_timestamp()-interval '5 minutes' or prep.request_max_output_tokens is null
 then raise exception 'article request unavailable or expired'; end if;
 select * into r from public.article_body_requests where request_id=p_request;
 select * into c from public.article_body_request_context where request_id=p_request;
 select * into receipt from public.article_body_receipts where id=r.snapshot_id;
 select * into cfg from public.article_stage_configs where id=c.stage_config_id for share;
 select * into route from public.ai_model_routes where id=prep.model_route_id for share;
 if cfg.id is null or cfg.stage is distinct from c.stage or cfg.route_id is distinct from route.id or cfg.expires_at<=clock_timestamp()
  or exists(select 1 from public.article_stage_config_revocations where config_id=cfg.id)
  or route.id is null or not route.enabled or route.provider<>'deepseek' or route.processing_region is distinct from prep.processing_region
  or route.model_id is distinct from prep.requested_model or route.model_id is distinct from (case when c.stage='summary' then 'deepseek-flash' else 'deepseek-v4-pro' end)
  or route.purpose is distinct from (case when c.stage='summary' then 'article_summary.v1' else 'article_draft.v1' end)
  or prep.request_prompt_version is distinct from (case when c.stage='summary' then 'body_summary_context.v1' else 'full_article_context.v2' end)
  or prep.request_schema_version is distinct from (case when c.stage='summary' then 'summary_proposal.v1' else 'full_article.v1' end)
 then raise exception 'article stage configuration unavailable'; end if;
 perform public.article_body_scope(receipt.article_id,receipt.region,case when c.stage='summary' then array['process_summary_deepseek','store_summary','display_summary'] else array['process_deepseek','store_draft','display_draft'] end);
 if c.request_id is null or not public.article_stage_accessible(p_request) or not public.article_body_available(r.snapshot_id)
  or exists(select 1 from unnest(r.grant_ids) gid where not public.article_body_grant_live(gid)) or receipt.body_sha256 is distinct from c.body_sha256
 then raise exception 'original body grants unavailable'; end if;
 facts:=public.article_body_claims(r.snapshot_id,c.claim_ids);
 if encode(sha256(convert_to(facts::text,'UTF8')),'hex') is distinct from c.claims_sha256 then raise exception 'claims changed'; end if;
 select count(*),min(i.grant_expires_at) into n,title_deadline
 from public.ai_lock_provider_title_inputs(array[receipt.article_id],prep.processor,prep.processing_region) i
 join public.ai_request_preparation_inputs saved on saved.request_id=p_request and saved.article_id=i.article_id
  and saved.policy_id=i.policy_id and saved.provider_grant_id=i.grant_id
  and saved.title_sha256=encode(sha256(convert_to(i.title,'UTF8')),'hex');
 if n<>1 then raise exception 'article source input changed'; end if;
 select least(cfg.expires_at,bs.expires_at,prep.created_at+interval '5 minutes',title_deadline,
  (select expires_at from public.article_runtime_principals where role_name=session_user),
  (select expires_at from public.article_body_summaries where id=c.summary_id),
  (select min(g.expires_at) from public.article_body_summary_receipts sr join public.article_body_requests rq on rq.request_id=sr.request_id join public.article_body_grants g on g.id=any(rq.grant_ids) where sr.id=c.summary_id),
  (select min(expires_at) from public.article_body_grants where id=any(r.grant_ids||receipt.grant_ids))) into deadline
 from public.article_body_snapshots bs where bs.id=r.snapshot_id;
 if deadline is null or deadline<=clock_timestamp() then raise exception 'expired body request'; end if;
 update public.ai_request_preparations set state='checked',state_changed_at=clock_timestamp() where request_id=p_request;
 return jsonb_build_object('request_id',p_request,'provider',prep.processor,'processing_region',prep.processing_region,
  'model_id',prep.requested_model,'request_mode','standard','max_output_tokens',prep.request_max_output_tokens,
  'snapshot',(select jsonb_build_object('snapshot_id',bs.id,'body',bs.body,'sha256',receipt.body_sha256,'original_url',receipt.original_url,'fetched_at',receipt.fetched_at) from public.article_body_snapshots bs where bs.id=r.snapshot_id),
  'claims',facts,'stage',c.stage,
  'summary',(select jsonb_build_object('summary_id',sr.id,'request_id',sr.request_id,'content',ss.content,'content_sha256',sr.content_sha256) from public.article_body_summary_receipts sr join public.article_body_summaries ss on ss.id=sr.id where sr.id=c.summary_id),
  'prompt_version',prep.request_prompt_version,'schema_version',prep.request_schema_version,'max_payload_bytes',cfg.max_payload_bytes,'prompt_sha256',cfg.prompt_sha256,
  'draft_expires_epoch',floor(extract(epoch from least((select expires_at from public.article_body_snapshots where id=r.snapshot_id),
   (select min(expires_at) from public.article_body_grants where id=any(r.grant_ids||receipt.grant_ids)),
   (select expires_at from public.article_body_summaries where id=c.summary_id),
   (select min(g.expires_at) from public.article_body_summary_receipts sr join public.article_body_requests rq on rq.request_id=sr.request_id join public.article_body_grants g on g.id=any(rq.grant_ids) where sr.id=c.summary_id))))::bigint,
  'send_before_epoch',floor(extract(epoch from deadline))::bigint,'server_now_epoch',ceil(extract(epoch from clock_timestamp()))::bigint);
end $$;



CREATE FUNCTION public.ai_check_bounded_snapshot(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prep public.ai_request_preparations%rowtype; route public.ai_model_routes%rowtype;
 ids uuid[]; n integer; matched integer; deadline timestamptz; items jsonb;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null then raise exception 'invalid AI request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists(
  select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into prep from public.ai_request_preparations where request_id=p_request for update;
 if prep.request_id is null or prep.state<>'prepared' or prep.created_at<=clock_timestamp()-interval '5 minutes'
  or prep.request_prompt_version is distinct from 'claim_extract_titles.v1'
  or prep.request_schema_version is distinct from 'claim_extraction.v1' or prep.request_max_output_tokens is null
 then raise exception 'request unavailable or expired'; end if;
 select * into route from public.ai_model_routes where id=prep.model_route_id for share;
 if route.id is null or not route.enabled or route.provider is distinct from prep.processor
  or route.processing_region is distinct from prep.processing_region or route.model_id is distinct from prep.requested_model
  or route.purpose<>'claim_extraction.v1' then raise exception 'model route changed or unavailable'; end if;
 select array_agg(article_id order by article_id),count(*) into ids,n from public.ai_request_preparation_inputs where request_id=p_request;
 if n not between 1 and 50 then raise exception 'request inputs unavailable'; end if;
 select count(*),jsonb_agg(jsonb_build_object('article_id',i.article_id,'title',i.title) order by i.article_id),
  least(prep.created_at+interval '5 minutes',min(i.grant_expires_at)) into matched,items,deadline
 from public.ai_lock_provider_title_inputs(ids,prep.processor,prep.processing_region) i
 join public.ai_request_preparation_inputs saved on saved.request_id=p_request and saved.article_id=i.article_id
  and saved.policy_id=i.policy_id and saved.provider_grant_id=i.grant_id
  and saved.title_sha256=encode(sha256(convert_to(i.title,'UTF8')),'hex');
 if matched<>n or deadline is null or deadline<=clock_timestamp() then raise exception 'source input changed or expired'; end if;
 update public.ai_request_preparations set state='checked',state_changed_at=clock_timestamp() where request_id=p_request;
 return jsonb_build_object('request_id',p_request,'provider',prep.processor,'processing_region',prep.processing_region,
  'model_id',prep.requested_model,'request_mode','standard','max_output_tokens',prep.request_max_output_tokens,
  'prompt_version',prep.request_prompt_version,'schema_version',prep.request_schema_version,'articles',items,
  'send_before_epoch',floor(extract(epoch from deadline))::bigint,'server_now_epoch',ceil(extract(epoch from clock_timestamp()))::bigint);
end $$;



CREATE FUNCTION public.ai_check_classification_snapshot(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prep public.ai_request_preparations%rowtype; route public.ai_model_routes%rowtype;
 article uuid; n integer; matched integer; deadline timestamptz; process_deadline timestamptz; cat jsonb; items jsonb; title_deadline timestamptz;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null then raise exception 'invalid classification request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists
   (select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into prep from public.ai_request_preparations where request_id=p_request for update;
 if prep.request_id is null or prep.state<>'prepared' or prep.created_at<=clock_timestamp()-interval '5 minutes'
  or prep.request_prompt_version is distinct from 'classification_titles.v1'
  or prep.request_schema_version is distinct from 'classification_proposal.v1' or prep.request_max_output_tokens is null
 then raise exception 'classification request unavailable or expired'; end if;
 select * into route from public.ai_model_routes where id=prep.model_route_id for share;
 if route.id is null or not route.enabled or route.provider is distinct from prep.processor
  or route.processing_region is distinct from prep.processing_region or route.model_id is distinct from prep.requested_model
  or route.purpose<>'classification.v1' then raise exception 'classification model route changed or unavailable'; end if;
 select count(*),min(article_id::text)::uuid into n,article from public.ai_request_preparation_inputs where request_id=p_request;
 if n<>1 then raise exception 'classification input unavailable'; end if;
 process_deadline:=public.lock_classification_processing(article,prep.processor,prep.processing_region);
 perform c.id from public.categories c join public.classification_request_categories x on x.category_id=c.id
  where x.request_id=p_request order by c.id for share of c;
 select count(*),count(*) filter(where c.active and x.name_sha256=encode(sha256(convert_to(c.name,'UTF8')),'hex')),
  jsonb_agg(jsonb_build_object('category_id',c.id,'name',c.name) order by c.id)
  into n,matched,cat from public.classification_request_categories x join public.categories c on c.id=x.category_id where x.request_id=p_request;
 if n not between 1 and 50 or n<>matched then raise exception 'classification category snapshot changed'; end if;
 select count(*),jsonb_agg(jsonb_build_object('article_id',i.article_id,'title',i.title) order by i.article_id),min(i.grant_expires_at)
  into matched,items,title_deadline from public.ai_lock_provider_title_inputs(array[article],prep.processor,prep.processing_region) i
 join public.ai_request_preparation_inputs saved on saved.request_id=p_request and saved.article_id=i.article_id
  and saved.policy_id=i.policy_id and saved.provider_grant_id=i.grant_id
  and saved.title_sha256=encode(sha256(convert_to(i.title,'UTF8')),'hex');
 if matched<>1 then raise exception 'classification source input changed'; end if;
 deadline:=least(prep.created_at+interval '5 minutes',process_deadline,title_deadline);
 if deadline is null or deadline<=clock_timestamp() then raise exception 'classification request expired'; end if;
 update public.ai_request_preparations set state='checked',state_changed_at=clock_timestamp() where request_id=p_request;
 return jsonb_build_object('request_id',p_request,'provider',prep.processor,'processing_region',prep.processing_region,
  'model_id',prep.requested_model,'request_mode','standard','max_output_tokens',prep.request_max_output_tokens,
  'prompt_version',prep.request_prompt_version,'schema_version',prep.request_schema_version,'articles',items,'categories',cat,
  'send_before_epoch',floor(extract(epoch from deadline))::bigint,'server_now_epoch',ceil(extract(epoch from clock_timestamp()))::bigint);
end $$;



CREATE FUNCTION public.ai_check_monthly_bounded_snapshot(p_request uuid) RETURNS jsonb
