CREATE FUNCTION public.ai_check_monthly_cny_budget(p_day date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare fx record; total numeric; fen numeric;
begin
  select * into fx from public.ai_effective_monthly_cny_fx(p_day);
  select coalesce(sum(case when state='settled' then actual_nanos else reserved_nanos end),0)
    into total from public.ai_budget_reservations
    where budget_day>=fx.month_start and budget_day<(fx.month_start+interval '1 month')::date;
  -- Every previously settled/unknown/reserved request remains counted. A rate
  -- renewal never resets spent USD or creates a new monthly budget identity.
  fen:=ceil(total*fx.cny_per_usd_micros/10000000000000::numeric);
  if fen>fx.limit_fen then raise exception 'monthly budget exceeded'; end if;
  if fx.fx_valid_until<=clock_timestamp() then raise exception 'latest monthly FX expired'; end if;
  if p_day<>(clock_timestamp() at time zone 'UTC')::date then raise exception 'budget day changed'; end if;
end $$;



