CREATE FUNCTION public.ai_check_story_summary_snapshot(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prep public.ai_request_preparations%rowtype; route public.ai_model_routes%rowtype;
 ids uuid[]; n integer; matched integer; title_deadline timestamptz; scope_deadline timestamptz; deadline timestamptz; facts jsonb;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null then raise exception 'invalid story summary request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists
  (select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into prep from public.ai_request_preparations where request_id=p_request for update;
 if prep.request_id is null or prep.state<>'prepared' or prep.created_at<=clock_timestamp()-interval '5 minutes'
  or prep.request_prompt_version is distinct from 'summary_story_facts.v1'
  or prep.request_schema_version is distinct from 'summary_proposal.v1' or prep.request_max_output_tokens is null
 then raise exception 'story summary request unavailable or expired'; end if;
 select * into route from public.ai_model_routes where id=prep.model_route_id for share;
 if route.id is null or not route.enabled or route.provider is distinct from prep.processor
  or route.processing_region is distinct from prep.processing_region or route.model_id is distinct from prep.requested_model
  or route.purpose<>'summary_story.v1' then raise exception 'story summary model route changed or unavailable'; end if;
 scope_deadline:=public.ai_lock_story_summary_request(p_request);
 select jsonb_agg(jsonb_build_object('claim_id',f.id,'text',f.fact_text) order by f.id) into facts
  from public.story_summary_request_facts x join public.ai_verified_facts f on f.id=x.fact_id where x.request_id=p_request;
 select array_agg(article_id order by article_id),count(*) into ids,n from public.ai_request_preparation_inputs where request_id=p_request;
 if n not between 1 and 50 then raise exception 'story summary source inputs unavailable'; end if;
 select count(*),min(i.grant_expires_at) into matched,title_deadline
 from public.ai_lock_provider_title_inputs(ids,prep.processor,prep.processing_region) i
 join public.ai_request_preparation_inputs saved on saved.request_id=p_request and saved.article_id=i.article_id
  and saved.policy_id=i.policy_id and saved.provider_grant_id=i.grant_id
  and saved.title_sha256=encode(sha256(convert_to(i.title,'UTF8')),'hex');
 if matched<>n then raise exception 'story summary source input changed'; end if;
 deadline:=least(prep.created_at+interval '5 minutes',scope_deadline,title_deadline);
 if deadline is null or deadline<=clock_timestamp() then raise exception 'story summary request expired'; end if;
 update public.ai_request_preparations set state='checked',state_changed_at=clock_timestamp() where request_id=p_request;
 return jsonb_build_object('request_id',p_request,'provider',prep.processor,'processing_region',prep.processing_region,
  'model_id',prep.requested_model,'request_mode','standard','max_output_tokens',prep.request_max_output_tokens,
  'prompt_version',prep.request_prompt_version,'schema_version',prep.request_schema_version,'facts',facts,
  'send_before_epoch',floor(extract(epoch from deadline))::bigint,'server_now_epoch',ceil(extract(epoch from clock_timestamp()))::bigint);
end $$;



CREATE FUNCTION public.ai_check_summary_snapshot(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prep public.ai_request_preparations%rowtype; route public.ai_model_routes%rowtype; input public.summary_request_facts%rowtype;
 f public.ai_verified_facts%rowtype; ids uuid[]; n integer; matched integer; title_deadline timestamptz; scope_deadline timestamptz; deadline timestamptz;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null then raise exception 'invalid summary request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists
  (select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into prep from public.ai_request_preparations where request_id=p_request for update;
 if prep.request_id is null or prep.state<>'prepared' or prep.created_at<=clock_timestamp()-interval '5 minutes'
  or prep.request_prompt_version is distinct from 'summary_reviewed_fact.v1'
  or prep.request_schema_version is distinct from 'summary_proposal.v1' or prep.request_max_output_tokens is null
 then raise exception 'summary request unavailable or expired'; end if;
 select * into route from public.ai_model_routes where id=prep.model_route_id for share;
 if route.id is null or not route.enabled or route.provider is distinct from prep.processor
  or route.processing_region is distinct from prep.processing_region or route.model_id is distinct from prep.requested_model
  or route.purpose<>'summary_fact.v1' then raise exception 'summary model route changed or unavailable'; end if;
 select * into input from public.summary_request_facts where request_id=p_request;
 if input.fact_id is null then raise exception 'summary fact snapshot unavailable'; end if;
 select min(x.deadline) into scope_deadline from public.lock_summary_processing(input.fact_id,prep.processor,prep.processing_region,p_request) x;
 select * into f from public.ai_verified_facts where id=input.fact_id;
 if f.id is null or input.fact_sha256 is distinct from encode(sha256(convert_to(f.fact_text,'UTF8')),'hex') then raise exception 'summary fact snapshot changed'; end if;
 select array_agg(article_id order by article_id),count(*) into ids,n from public.ai_request_preparation_inputs where request_id=p_request;
 if n not between 1 and 50 then raise exception 'summary source inputs unavailable'; end if;
 select count(*),min(i.grant_expires_at) into matched,title_deadline
 from public.ai_lock_provider_title_inputs(ids,prep.processor,prep.processing_region) i
 join public.ai_request_preparation_inputs saved on saved.request_id=p_request and saved.article_id=i.article_id
  and saved.policy_id=i.policy_id and saved.provider_grant_id=i.grant_id
  and saved.title_sha256=encode(sha256(convert_to(i.title,'UTF8')),'hex');
 if matched<>n then raise exception 'summary source input changed'; end if;
 deadline:=least(prep.created_at+interval '5 minutes',scope_deadline,title_deadline);
 if deadline is null or deadline<=clock_timestamp() then raise exception 'summary request expired'; end if;
 update public.ai_request_preparations set state='checked',state_changed_at=clock_timestamp() where request_id=p_request;
 return jsonb_build_object('request_id',p_request,'provider',prep.processor,'processing_region',prep.processing_region,
  'model_id',prep.requested_model,'request_mode','standard','max_output_tokens',prep.request_max_output_tokens,
  'prompt_version',prep.request_prompt_version,'schema_version',prep.request_schema_version,'fact_id',f.id,'fact_text',f.fact_text,
  'send_before_epoch',floor(extract(epoch from deadline))::bigint,'server_now_epoch',ceil(extract(epoch from clock_timestamp()))::bigint);
end $$;



CREATE FUNCTION public.ai_check_translation_snapshot(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare req public.translation_requests%rowtype; intent public.translation_task_intents%rowtype; prep public.ai_request_preparations%rowtype;
 route public.ai_model_routes%rowtype; scope_deadline timestamptz; deadline timestamptz; title_deadline timestamptz;
 source_count integer; grant_count integer; ids uuid[]; n integer; matched integer;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null then raise exception 'invalid translation snapshot'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists
  (select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into prep from public.ai_request_preparations where request_id=p_request for update;
 if prep.request_id is null or prep.state<>'prepared' or prep.created_at<=clock_timestamp()-interval '5 minutes'
  or prep.request_prompt_version is distinct from 'translation_context.v1'
  or prep.request_schema_version is distinct from 'translation_proposal.v1' or prep.request_max_output_tokens is null
 then raise exception 'translation request unavailable or expired'; end if;
 select * into route from public.ai_model_routes where id=prep.model_route_id for share;
 if route.id is null or not route.enabled or route.provider is distinct from prep.processor
  or route.processing_region is distinct from prep.processing_region or route.model_id is distinct from prep.requested_model
  or route.purpose<>'translation.v1' then raise exception 'translation model route changed or unavailable'; end if;
 select * into req from public.translation_requests where request_id=p_request;
 select * into intent from public.translation_task_intents where id=req.intent_id;
 if req.request_id is null or intent.id is null then raise exception 'translation request unavailable'; end if;
 scope_deadline:=public.ai_lock_translation_scope(intent.source_revision_id,prep.processor,prep.processing_region,array['process','store','editor_display']);
 if req.draft_sha256 is distinct from encode(sha256(convert_to(public.translation_source_payload(intent.source_revision_id)::text,'UTF8')),'hex')
 then raise exception 'translation source changed'; end if;
 select count(distinct a.source_id) into source_count from public.claims c join public.claim_evidence e on e.claim_id=c.id
  join public.articles a on a.id=e.article_id where c.revision_id=intent.source_revision_id;
 select count(*) into grant_count from public.translation_request_grants where request_id=p_request;
 if source_count<1 or grant_count<>source_count*9 or exists(
  select 1 from public.translation_request_grants rg join public.translation_scope_grants g on g.id=rg.grant_id
  join public.source_policies sp on sp.id=g.policy_id where rg.request_id=p_request
  and (g.provider is distinct from prep.processor or g.processing_region is distinct from prep.processing_region
   or g.expires_at<=clock_timestamp() or exists(select 1 from public.translation_scope_revocations rv where rv.grant_id=g.id)
   or sp.id is distinct from (select p.id from public.source_policies p where p.source_id=sp.source_id order by p.version desc limit 1)
   or not exists(select 1 from public.claims c join public.claim_evidence e on e.claim_id=c.id
    join public.articles a on a.id=e.article_id where c.revision_id=intent.source_revision_id and a.source_id=sp.source_id)))
 then raise exception 'translation request permissions changed'; end if;
 select array_agg(article_id order by article_id),count(*) into ids,n from public.ai_request_preparation_inputs where request_id=p_request;
 if n not between 1 and 50 then raise exception 'translation source inputs unavailable'; end if;
 select count(*),min(i.grant_expires_at) into matched,title_deadline
 from public.ai_lock_provider_title_inputs(ids,prep.processor,prep.processing_region) i
 join public.ai_request_preparation_inputs saved on saved.request_id=p_request and saved.article_id=i.article_id
  and saved.policy_id=i.policy_id and saved.provider_grant_id=i.grant_id
  and saved.title_sha256=encode(sha256(convert_to(i.title,'UTF8')),'hex');
 if matched<>n then raise exception 'translation source input changed'; end if;
 deadline:=least(scope_deadline,title_deadline,prep.created_at+interval '5 minutes',
  (select min(g.expires_at) from public.translation_request_grants x join public.translation_scope_grants g on g.id=x.grant_id where x.request_id=p_request));
 if deadline is null or deadline<=clock_timestamp() then raise exception 'translation snapshot expired'; end if;
 update public.ai_request_preparations set state='checked',state_changed_at=clock_timestamp() where request_id=p_request;
 return jsonb_build_object('request_id',p_request,'provider',prep.processor,'processing_region',prep.processing_region,
  'model_id',prep.requested_model,'request_mode','standard','max_output_tokens',prep.request_max_output_tokens,
  'source_revision_id',intent.source_revision_id,'source_locale',intent.source_locale,'target_locale',intent.target_locale,
  'glossary_version',intent.glossary_version,'source',public.translation_source_payload(intent.source_revision_id),
  'prompt_version',prep.request_prompt_version,'schema_version',prep.request_schema_version,
  'send_before_epoch',floor(extract(epoch from deadline))::bigint,'server_now_epoch',ceil(extract(epoch from clock_timestamp()))::bigint);
end $$;



CREATE FUNCTION public.ai_claim_alert() RETURNS TABLE(incident_id uuid, reason text, lease_token uuid, lease_expires_at timestamp with time zone, attempt integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare candidate uuid;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  perform 1 from public.ai_budget_control where singleton for share;
  if not found then raise exception 'budget control unavailable'; end if;
  select o.incident_id into candidate from public.ai_alert_outbox o
    where o.status in ('pending','retry_wait') and o.attempts < 3 and o.available_at <= clock_timestamp()
    order by o.available_at,o.incident_id for update skip locked limit 1;
  if candidate is null then return; end if;
  return query update public.ai_alert_outbox o set status='processing',attempts=o.attempts+1,
      lease_token=gen_random_uuid(),lease_expires_at=clock_timestamp()+interval '1 minute',updated_at=clock_timestamp()
    from public.ai_budget_incidents i where o.incident_id=candidate and i.id=o.incident_id
    returning o.incident_id,i.reason,o.lease_token,o.lease_expires_at,o.attempts;
end $$;



CREATE FUNCTION public.ai_confirm_checked_request(p_request uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare request_state text;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_request is null then raise exception 'request identity required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
  select state into request_state from public.ai_request_preparations where request_id=p_request;
  if request_state='checked' then return 'checked'; end if;
  return 'unresolved';
end $$;



CREATE FUNCTION public.ai_effective_monthly_cny_fx(p_day date) RETURNS TABLE(month_start date, fx_version integer, fx_review_id uuid, cny_per_usd_micros bigint, fx_valid_until timestamp with time zone, limit_fen bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.ai_monthly_cny_budgets%rowtype; r public.ai_monthly_cny_fx_reviews%rowtype;
  v integer; rid uuid; rate bigint; expires timestamptz;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  if p_day is null or p_day<>(clock_timestamp() at time zone 'UTC')::date then raise exception 'budget day changed'; end if;
  select mb.* into b from public.ai_monthly_cny_budgets mb
    where mb.month_start=date_trunc('month',p_day)::date for update;
  if b.month_start is null then raise exception 'reviewed monthly budget unavailable'; end if;
  select fr.* into r from public.ai_monthly_cny_fx_reviews fr
    where fr.month_start=b.month_start order by fr.version desc limit 1;
  if r.id is null then
    v:=0; rid:=null; rate:=b.cny_per_usd_micros; expires:=b.fx_valid_until;
  else
    v:=r.version; rid:=r.id; rate:=r.cny_per_usd_micros; expires:=r.valid_until;
    if r.valid_from>clock_timestamp() then raise exception 'latest monthly FX review not yet valid'; end if;
  end if;
  if expires<=clock_timestamp() or exists(select 1 from public.ai_monthly_cny_fx_withdrawals w
    where w.month_start=b.month_start and w.version=v) then raise exception 'latest monthly FX expired or withdrawn'; end if;
  if p_day<>(clock_timestamp() at time zone 'UTC')::date then raise exception 'budget day changed'; end if;
  return query select b.month_start,v,rid,rate,expires,b.limit_fen;
end $$;



CREATE FUNCTION public.ai_enter_derived_restore_quarantine() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  update public.ai_budget_control set stopped=true,restore_quarantine=true,updated_at=clock_timestamp() where singleton;
  if not found then raise exception 'AI budget control unavailable'; end if;
  update public.ai_claim_retention_control set restore_quarantine=true,last_sweep_at=null,last_removed=null where singleton;
  if not found then raise exception 'claim retention control unavailable'; end if;
  update public.ai_verified_fact_retention_control set restore_quarantine=true,last_sweep_at=null where singleton;
  if not found then raise exception 'verified fact retention control unavailable'; end if;
  update public.classification_retention_control set restore_quarantine=true,last_sweep_at=null where singleton;
  if not found then raise exception 'classification retention control unavailable'; end if;
  update public.summary_retention_control set restore_quarantine=true,last_sweep_at=null where singleton;
  if not found then raise exception 'summary retention control unavailable'; end if;
  update public.story_summary_retention_control set restore_quarantine=true,last_sweep_at=null where singleton;
  if not found then raise exception 'story summary retention control unavailable'; end if;
end $$;



CREATE FUNCTION public.ai_enter_verified_restore_quarantine() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  update public.ai_verified_fact_retention_control set restore_quarantine=true,last_sweep_at=null where singleton;
  if not found then raise exception 'retention control unavailable'; end if;
end $$;



CREATE FUNCTION public.ai_expire_alert_leases() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare changed integer;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  perform 1 from public.ai_budget_control where singleton for share;
  if not found then raise exception 'budget control unavailable'; end if;
  update public.ai_alert_outbox set status='unknown',lease_token=null,lease_expires_at=null,updated_at=clock_timestamp()
    where status='processing' and lease_expires_at<=clock_timestamp();
  get diagnostics changed=row_count;
  return changed;
end $$;



CREATE FUNCTION public.ai_finish_alert(p_incident uuid, p_token uuid, p_outcome text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result text;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_outcome is null or p_outcome not in ('delivered','not_sent','unknown') then raise exception 'invalid alert outcome'; end if;
  perform 1 from public.ai_budget_control where singleton for share;
  if not found then raise exception 'budget control unavailable'; end if;
  update public.ai_alert_outbox o set
    status=case when p_outcome='delivered' then 'delivered' when p_outcome='unknown' then 'unknown'
      when o.attempts < 3 then 'retry_wait' else 'failed' end,
    available_at=case when p_outcome='not_sent' and o.attempts < 3 then clock_timestamp()+interval '1 minute'*power(2,o.attempts-1) else o.available_at end,
    lease_token=null,lease_expires_at=null,updated_at=clock_timestamp()
    where o.incident_id=p_incident and o.status='processing' and o.lease_token=p_token and o.lease_expires_at>clock_timestamp()
    returning o.status into result;
  if result is null then raise exception 'alert lease unavailable'; end if;
  return result;
end $$;



CREATE FUNCTION public.ai_guard_cny_reconciled_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if tg_op='UPDATE' and old.state='reconciled_cny' and new is distinct from old then
 raise exception 'CNY reconciled reservation is immutable'; end if;
 if new.state='reconciled_cny' and not exists(select 1 from public.ai_cny_charge_reconciliations c
 where c.request_id=new.request_id and c.reserved_usd_nanos=new.reserved_nanos) then
 raise exception 'original currency reconciliation required'; end if;
 return new;
end $$;



CREATE FUNCTION public.ai_guard_execution_safety() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if tg_op='UPDATE' and old.state='prepared' and new.state='cancelled' then return new; end if;
 if not exists(select 1 from public.ai_execution_control where singleton and not stopped for share)
 then raise exception 'AI execution manually stopped'; end if;
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=new.request_id
   and not exists(select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id))
 then raise exception 'unresolved execution safety incident'; end if;
 return new;
end $$;



CREATE FUNCTION public.ai_legacy_prepare_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare reservation_job uuid; identity_job uuid;
begin
 select job_id into reservation_job from public.ai_budget_reservations where request_id=new.request_id;
 select job_id into identity_job from public.ai_request_identities where request_id=new.request_id;
 if identity_job is null then
  if reservation_job is null then raise exception 'AI request identity unavailable'; end if;
  perform public.ai_register_request_identity(new.request_id,reservation_job);
 elsif reservation_job is not null and identity_job is distinct from reservation_job then
  raise exception 'AI request identity conflict';
 end if;
 return new;
end $$;



CREATE FUNCTION public.ai_list_verified_deletion_receipts(p_after uuid, p_limit integer) RETURNS TABLE(fact_id uuid, request_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if p_limit is null or p_limit not between 1 and 500 then raise exception 'invalid receipt page size'; end if;
  return query select r.fact_id,r.request_id from public.ai_verified_fact_deletion_receipts r
    where p_after is null or r.fact_id>p_after order by r.fact_id limit p_limit;
end $$;



CREATE FUNCTION public.ai_lock_billing_bound_for_withdrawal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin perform 1 from public.ai_billing_bounds where id=new.bound_id for update; return new; end $$;



CREATE FUNCTION public.ai_lock_derived_claim_permissions(p_ids uuid[], p_provider text, p_region text, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare n integer;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  n:=coalesce(cardinality(p_ids),0);
  if n<1 or n>50 or (select count(distinct x) from unnest(p_ids) x)<>n or p_action is null or p_action not in ('store','editor_display')
    or p_provider is null or p_region is null then raise exception 'invalid derived permission scope'; end if;
  perform s.id from public.sources s where s.id in (select a.source_id from public.articles a where a.id=any(p_ids)) order by s.id for update;
  if (select count(*) from public.articles a join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) p on true
    where a.id=any(p_ids) and p.policy_status='approved' and p.reviewed_by is not null and p.reviewed_at is not null
      and p.policy_evidence<>'{}'::jsonb and (p.permission_expires_at is null or p.permission_expires_at>clock_timestamp())
      and exists(select 1 from public.ai_derived_claim_grants g where g.policy_id=p.id and g.provider=p_provider and g.processing_region=p_region
        and g.permitted_action=p_action and g.expires_at>clock_timestamp()
        and not exists(select 1 from public.ai_derived_claim_revocations r where r.grant_id=g.id)))<>n then
    raise exception 'derived claim permission unavailable'; end if;
end $$;



CREATE FUNCTION public.ai_lock_provider_title_inputs(p_ids uuid[], p_provider text, p_region text) RETURNS TABLE(article_id uuid, title text, policy_id uuid, policy_version integer, grant_id uuid, grant_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare n integer; source_ids uuid[]; provider_enabled boolean;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  n := coalesce(cardinality(p_ids),0);
  if n < 1 or n > 50 or (select count(distinct x) from unnest(p_ids) x) <> n
    or p_provider is null or p_provider !~ '^[a-z][a-z0-9_-]{0,63}$'
    or p_region is null or p_region !~ '^[a-z0-9-]{2,40}$' then raise exception 'invalid provider input scope'; end if;
  select enabled into provider_enabled from public.ai_provider_catalog where name=p_provider for share;
  if provider_enabled is distinct from true then raise exception 'AI provider unavailable'; end if;
  select array_agg(distinct a.source_id order by a.source_id) into source_ids from public.articles a where a.id=any(p_ids);
  perform s.id from public.sources s where s.id=any(source_ids) order by s.id for update;
  perform a.id from public.articles a where a.id=any(p_ids) order by a.id for share;
  if (select count(*) from public.articles a
      join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) p on true
      join public.ai_provider_title_grants g on g.policy_id=p.id and g.provider=p_provider and g.processing_region=p_region
      where a.id=any(p_ids) and a.source_id=any(source_ids) and a.title is not null and length(trim(a.title)) between 1 and 1000
        and p.policy_status='approved' and p.title_storage_allowed and p.ai_processing_allowed
        and p.reviewed_by is not null and p.reviewed_at is not null and jsonb_typeof(p.policy_evidence)='object' and p.policy_evidence <> '{}'::jsonb
        and (p.permission_expires_at is null or p.permission_expires_at>clock_timestamp())
        and (g.expires_at is null or g.expires_at>clock_timestamp())
        and not exists(select 1 from public.ai_provider_title_revocations r where r.grant_id=g.id)) <> n then
    raise exception 'current provider title permission unavailable';
  end if;
  return query select a.id,a.title,p.id,p.version,g.id,least(p.permission_expires_at,g.expires_at)
    from public.articles a join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) p on true
    join public.ai_provider_title_grants g on g.policy_id=p.id and g.provider=p_provider and g.processing_region=p_region
    where a.id=any(p_ids) order by a.id;
end $_$;



CREATE FUNCTION public.ai_lock_story_summary_request(p_request uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare req public.story_summary_requests%rowtype; prep public.ai_request_preparations%rowtype; ids uuid[]; n integer; deadline timestamptz;
begin
  select * into req from public.story_summary_requests where request_id=p_request;
  select * into prep from public.ai_request_preparations where request_id=p_request;
  if req.request_id is null or prep.request_id is null or exists(select 1 from public.story_summary_request_invalidations where request_id=p_request)
    then raise exception 'story summary request unavailable'; end if;
  select array_agg(fact_id order by fact_id),count(*) into ids,n from public.story_summary_request_facts where request_id=p_request;
  if n<>req.fact_count then raise exception 'story summary facts unavailable'; end if;
  select min(x.deadline) into deadline from public.ai_lock_summary_story_facts(req.story_id,ids,prep.processor,prep.processing_region) x;
  if deadline is null or deadline<=clock_timestamp() or exists(select 1 from public.story_summary_request_facts x
    join public.ai_verified_facts f on f.id=x.fact_id where x.request_id=p_request
    and x.fact_sha256<>encode(sha256(convert_to(f.fact_text,'UTF8')),'hex')) then raise exception 'story summary facts changed'; end if;
  if exists(select 1 from public.story_summary_request_facts x join public.ai_verified_facts f on f.id=x.fact_id
    join public.ai_request_preparation_inputs i on i.request_id=f.request_id
    left join public.story_summary_request_grants rg on rg.request_id=x.request_id and rg.fact_id=x.fact_id and rg.article_id=i.article_id
    left join public.summary_processing_grants g on g.id=rg.grant_id and g.policy_id=i.policy_id and g.provider=prep.processor and g.region=prep.processing_region
    where x.request_id=p_request and (g.id is null or g.expires_at<=clock_timestamp()
      or exists(select 1 from public.summary_processing_revocations rv where rv.grant_id=g.id)))
    or exists(select 1 from public.story_summary_request_grants rg where rg.request_id=p_request and not exists(
      select 1 from public.ai_verified_facts f join public.ai_request_preparation_inputs i on i.request_id=f.request_id
      where f.id=rg.fact_id and i.article_id=rg.article_id)) then raise exception 'story summary processing permission unavailable'; end if;
  select least(deadline,min(g.expires_at)) into deadline from public.story_summary_request_grants rg
    join public.summary_processing_grants g on g.id=rg.grant_id where rg.request_id=p_request;
  if deadline is null or deadline<=clock_timestamp() then raise exception 'story summary processing expired'; end if;
  return deadline;
end $$;



CREATE FUNCTION public.ai_lock_summary_story_facts(p_story uuid, p_facts uuid[], p_provider text, p_region text) RETURNS TABLE(fact_id uuid, fact_text text, deadline timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare n integer; matched integer; item uuid; scope_deadline timestamptz;
begin
  if current_setting('transaction_isolation')<>'read committed' or p_story is null or p_provider is null or p_region is null
    or p_facts is null or cardinality(p_facts) not between 2 and 10
    or (select count(distinct id) from unnest(p_facts) id)<>cardinality(p_facts)
    then raise exception 'invalid summary story facts'; end if;
  select cardinality(p_facts) into n;
  -- Keep locks until the caller commits; story membership must not change
  -- while the facts and source permissions are checked.
  perform 1 from public.stories where id=p_story for share;
  if not found then raise exception 'story unavailable'; end if;
  perform 1 from public.ai_verified_fact_retention_control where singleton and not restore_quarantine for share;
  if not found then raise exception 'verified fact unavailable'; end if;
  perform s.id from public.sources s where s.id in (
    select a.source_id from public.ai_verified_facts f
      join public.ai_request_preparation_inputs i on i.request_id=f.request_id
      join public.articles a on a.id=i.article_id where f.id=any(p_facts)) order by s.id for update;
  perform sa.article_id from public.story_articles sa where sa.story_id=p_story and sa.article_id in (
    select i.article_id from public.ai_verified_facts f join public.ai_request_preparation_inputs i on i.request_id=f.request_id
      where f.id=any(p_facts)) order by sa.article_id for share;
  select count(*) into matched from public.ai_verified_facts f
    join public.ai_request_identities r on r.request_id=f.request_id
    join public.ai_processing_jobs j on j.id=r.job_id and j.story_id=p_story
    where f.id=any(p_facts)
      and exists(select 1 from public.story_articles sa where sa.story_id=p_story and sa.article_id=f.article_id)
      and not exists(select 1 from public.ai_request_preparation_inputs i where i.request_id=f.request_id
        and not exists(select 1 from public.story_articles sa where sa.story_id=p_story and sa.article_id=i.article_id));
  if matched<>n then raise exception 'summary fact story membership unavailable'; end if;
  foreach item in array (select array_agg(id order by id) from unnest(p_facts) id) loop
    select min(x.deadline) into scope_deadline from public.lock_summary_processing(item,p_provider,p_region,null) x;
    if scope_deadline is null or scope_deadline<=clock_timestamp() then raise exception 'summary fact permission unavailable'; end if;
    return query select f.id,f.fact_text,scope_deadline from public.ai_verified_facts f where f.id=item;
  end loop;
end $$;



CREATE FUNCTION public.ai_lock_title_inputs(p_ids uuid[], p_processor text, p_region text) RETURNS TABLE(article_id uuid, title text, policy_id uuid, policy_version integer, permission_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if p_processor is distinct from 'openai' then raise exception 'invalid AI input scope'; end if;
  return query select i.article_id,i.title,i.policy_id,i.policy_version,i.grant_expires_at
    from public.ai_lock_provider_title_inputs(p_ids,'openai',p_region) i;
end $$;



CREATE FUNCTION public.ai_lock_translation_scope(p_revision uuid, p_provider text, p_region text, p_actions text[]) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare action_name text; deadline timestamptz;
begin
  if current_setting('transaction_isolation')<>'read committed' or p_revision is null or p_provider is null or p_region is null
    or p_actions is null or cardinality(p_actions) not between 1 and 3
    or (select count(distinct x) from unnest(p_actions) x)<>cardinality(p_actions)
    or exists(select 1 from unnest(p_actions) x where x is null or x not in ('process','store','editor_display'))
    then raise exception 'invalid translation scope'; end if;
  perform s.id from public.stories s join public.story_revisions r on r.story_id=s.id where r.id=p_revision and s.archived_at is null for update of s;
  if not found then raise exception 'translation revision unavailable'; end if;
  perform s.id from public.sources s where s.id in (
    select a.source_id from public.claims c join public.claim_evidence e on e.claim_id=c.id
      join public.articles a on a.id=e.article_id where c.revision_id=p_revision
  ) order by s.id for update;
  foreach action_name in array p_actions loop
    if not public.translation_revision_scope_available(p_revision,p_provider,p_region,action_name)
      then raise exception 'translation permission unavailable'; end if;
  end loop;
  select min(least(g.expires_at,coalesce(p.permission_expires_at,'infinity'::timestamptz))) into deadline
    from public.claims c join public.claim_evidence e on e.claim_id=c.id
    join public.articles a on a.id=e.article_id
    join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) p on true
    cross join (values ('title'),('summary'),('claims')) f(name)
    cross join unnest(p_actions) action(value)
    join lateral (select x.expires_at from public.translation_scope_grants x where x.policy_id=p.id and x.provider=p_provider
      and x.processing_region=p_region and x.field_name=f.name and x.permitted_action=action.value and x.expires_at>clock_timestamp()
      and not exists(select 1 from public.translation_scope_revocations r where r.grant_id=x.id)
      order by x.expires_at desc,x.id limit 1) g on true where c.revision_id=p_revision;
  if deadline is null or deadline<=clock_timestamp() then raise exception 'translation permission expired'; end if;
  return deadline;
end $$;



CREATE FUNCTION public.ai_lock_verified_fact_grants(p_ids uuid[], p_provider text, p_region text, p_action text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare n integer; matched integer; deadline timestamptz;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  n:=coalesce(cardinality(p_ids),0);
  if n<1 or n>50 or (select count(distinct x) from unnest(p_ids) x)<>n or p_provider is null or p_region is null
    or p_action is null or p_action not in ('verified_store','verified_display') then raise exception 'invalid verified fact scope'; end if;
  perform s.id from public.sources s where s.id in (select a.source_id from public.articles a where a.id=any(p_ids)) order by s.id for update;
  select count(*),min(least(g.expires_at,p.permission_expires_at)) into matched,deadline from public.articles a
    join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) p on true
    join lateral (select v.expires_at from public.ai_verified_fact_grants v where v.policy_id=p.id and v.provider=p_provider
      and v.processing_region=p_region and v.permitted_action=p_action and v.expires_at>clock_timestamp()
      and not exists(select 1 from public.ai_verified_fact_grant_revocations r where r.grant_id=v.id)
      order by v.expires_at desc limit 1) g on true
    where a.id=any(p_ids) and p.policy_status='approved' and p.reviewed_by is not null and p.reviewed_at is not null
      and p.policy_evidence<>'{}'::jsonb and (p.permission_expires_at is null or p.permission_expires_at>clock_timestamp());
  if matched<>n or deadline is null or deadline<=clock_timestamp() then raise exception 'verified fact permission unavailable'; end if;
  return deadline;
end $$;



CREATE FUNCTION public.ai_mark_budget_unknown(p_request uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  update public.ai_budget_reservations set state='unknown' where request_id=p_request and state='reserved';
  if not found and not exists (select 1 from public.ai_budget_reservations where request_id=p_request and state='unknown') then
    raise exception 'reservation cannot be marked unknown';
  end if;
end $$;



CREATE FUNCTION public.ai_prepare_article_body_request(p_request uuid, p_job uuid, p_snapshot uuid, p_claims uuid[], p_region text, p_bound uuid, p_output integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin raise exception 'explicit Flash summary then Pro draft stage required'; end $$;



CREATE FUNCTION public.ai_prepare_article_stage_request(p_request uuid, p_job uuid, p_snapshot uuid, p_claims uuid[], p_region text, p_bound uuid, p_output integer, p_stage text, p_summary uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare r public.article_body_receipts%rowtype; cfg public.article_stage_configs%rowtype; route public.ai_model_routes%rowtype;
 ids uuid[]; facts jsonb; sr public.article_body_summary_receipts%rowtype; n integer;
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 if current_setting('transaction_isolation')<>'read committed' or p_request is null or p_job is null or p_snapshot is null
  or p_bound is null or p_region is null or p_output is null or p_output not between 1 and 8192
  or p_stage is null or p_stage not in ('summary','draft') or (p_stage='summary' and p_summary is not null)
  or (p_stage='draft' and p_summary is null) then raise exception 'explicit stage and handoff required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists
  (select 1 from public.ai_execution_safety_resolutions s where s.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 if exists(select 1 from public.ai_request_preparations where request_id=p_request) then raise exception 'request already exists; reconcile rather than retry'; end if;
 select * into cfg from public.article_stage_configs where id=p_bound for share;
 select * into route from public.ai_model_routes where id=cfg.route_id for share;
 if cfg.id is null or cfg.stage is distinct from p_stage or cfg.expires_at<=clock_timestamp()
  or exists(select 1 from public.article_stage_config_revocations where config_id=cfg.id)
  or route.id is null or not route.enabled or route.provider<>'deepseek' or route.processing_region is distinct from p_region
  or route.purpose is distinct from (case when p_stage='summary' then 'article_summary.v1' else 'article_draft.v1' end)
  or route.model_id is distinct from (case when p_stage='summary' then 'deepseek-flash' else 'deepseek-v4-pro' end)
 then raise exception 'article stage configuration unavailable'; end if;
 select * into r from public.article_body_receipts where id=p_snapshot;
 ids:=public.article_body_scope(r.article_id,p_region,case when p_stage='summary' then array['process_summary_deepseek','store_summary','display_summary'] else array['process_deepseek','store_draft','display_draft'] end);
 if not public.article_body_available(p_snapshot) or r.region is distinct from p_region then raise exception 'snapshot unavailable'; end if;
 facts:=public.article_body_claims(p_snapshot,p_claims);
 if not exists(select 1 from public.ai_processing_jobs j join public.story_articles sa on sa.story_id=j.story_id and sa.article_id=j.article_id where j.id=p_job and j.article_id=r.article_id and j.task_type='full_article.v1') then raise exception 'full article job/story scope mismatch'; end if;
 if exists(select 1 from public.claims c join public.story_revisions rv on rv.id=c.revision_id where c.id=any(p_claims) and rv.story_id is distinct from (select story_id from public.ai_processing_jobs where id=p_job)) then raise exception 'claim/job story mismatch'; end if;
 if p_stage='draft' then
  select * into sr from public.article_body_summary_receipts where id=p_summary and snapshot_id=p_snapshot;
  if sr.id is null or not public.article_summary_available(sr.id) or not exists(select 1 from public.article_body_request_context c where c.request_id=sr.request_id and c.claims_sha256=encode(sha256(convert_to(facts::text,'UTF8')),'hex')) then raise exception 'current matching Flash summary required'; end if;
 end if;
 perform 1 from public.ai_lock_provider_title_inputs(array[r.article_id],'deepseek',p_region);
 perform public.ai_register_request_identity(p_request,p_job);
 insert into public.ai_request_preparations(request_id,processor,processing_region,requested_model,model_route_id,request_max_output_tokens,request_prompt_version,request_schema_version)
 values(p_request,'deepseek',p_region,route.model_id,route.id,p_output,case when p_stage='summary' then 'body_summary_context.v1' else 'full_article_context.v2' end,case when p_stage='summary' then 'summary_proposal.v1' else 'full_article.v1' end);
 insert into public.ai_request_preparation_inputs(request_id,article_id,policy_id,title_sha256,provider_grant_id)
 select p_request,i.article_id,i.policy_id,encode(sha256(convert_to(i.title,'UTF8')),'hex'),i.grant_id
 from public.ai_lock_provider_title_inputs(array[r.article_id],'deepseek',p_region) i;
 get diagnostics n=row_count; if n<>1 then raise exception 'article source input unavailable'; end if;
 insert into public.article_body_requests(request_id,snapshot_id,grant_ids) values(p_request,p_snapshot,ids);
 insert into public.article_body_request_context(request_id,stage_config_id,claim_ids,claims_sha256,body_sha256,stage,summary_id,summary_content_sha256)
 values(p_request,cfg.id,p_claims,encode(sha256(convert_to(facts::text,'UTF8')),'hex'),r.body_sha256,p_stage,p_summary,sr.content_sha256);
 return true;
end $$;



CREATE FUNCTION public.ai_prepare_bounded_request(p_request uuid, p_job uuid, p_ids uuid[], p_provider text, p_region text, p_bound uuid, p_output integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare route public.ai_model_routes%rowtype; prep public.ai_request_preparations%rowtype; ids uuid[]; existing_ids uuid[]; n integer;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null or p_job is null
  or p_provider is null or p_region is null or p_bound is null or p_output is null or p_output not between 1 and 8192
  or p_ids is null or cardinality(p_ids) not between 1 and 50
  or (select count(distinct x) from unnest(p_ids) x)<>cardinality(p_ids) then raise exception 'invalid AI request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists(
  select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into route from public.ai_model_routes where id=p_bound for share;
 if route.id is null or not route.enabled or route.provider is distinct from p_provider
  or route.processing_region is distinct from p_region or route.purpose<>'claim_extraction.v1'
 then raise exception 'explicit model route unavailable'; end if;
 select array_agg(x order by x) into ids from unnest(p_ids) x;
 perform 1 from public.ai_lock_provider_title_inputs(ids,p_provider,p_region);
 if not exists(select 1 from public.ai_processing_jobs where id=p_job) then raise exception 'AI job unavailable'; end if;
 select * into prep from public.ai_request_preparations where request_id=p_request;
 if found then
  select array_agg(article_id order by article_id) into existing_ids from public.ai_request_preparation_inputs where request_id=p_request;
  if prep.processor is distinct from p_provider or prep.processing_region is distinct from p_region
   or prep.model_route_id is distinct from route.id or prep.requested_model is distinct from route.model_id
   or prep.request_max_output_tokens is distinct from p_output or existing_ids is distinct from ids
   or not exists(select 1 from public.ai_request_identities where request_id=p_request and job_id=p_job)
  then raise exception 'AI request identity conflict'; end if;
  return false;
 end if;
 perform public.ai_register_request_identity(p_request,p_job);
 insert into public.ai_request_preparations(request_id,processor,processing_region,requested_model,model_route_id,
  request_max_output_tokens,request_prompt_version,request_schema_version)
 values(p_request,p_provider,p_region,route.model_id,route.id,p_output,'claim_extract_titles.v1','claim_extraction.v1');
 insert into public.ai_request_preparation_inputs(request_id,article_id,policy_id,title_sha256,provider_grant_id)
 select p_request,i.article_id,i.policy_id,encode(sha256(convert_to(i.title,'UTF8')),'hex'),i.grant_id
 from public.ai_lock_provider_title_inputs(ids,p_provider,p_region) i;
 get diagnostics n=row_count;
 if n<>cardinality(ids) then raise exception 'source input unavailable'; end if;
 return true;
end $$;



CREATE FUNCTION public.ai_prepare_classification_request(p_request uuid, p_job uuid, p_article uuid, p_categories uuid[], p_provider text, p_region text, p_bound uuid, p_output integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare route public.ai_model_routes%rowtype; prep public.ai_request_preparations%rowtype; ids uuid[]; old_ids uuid[]; n integer;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null or p_job is null or p_article is null
  or p_bound is null or p_output not between 1 and 8192 or p_output is null or p_categories is null
  or cardinality(p_categories) not between 1 and 50
  or (select count(distinct id) from unnest(p_categories) id)<>cardinality(p_categories)
 then raise exception 'invalid classification request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists
   (select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into route from public.ai_model_routes where id=p_bound for share;
 if route.id is null or not route.enabled or route.provider is distinct from p_provider
  or route.processing_region is distinct from p_region or route.purpose<>'classification.v1'
 then raise exception 'explicit classification model route unavailable'; end if;
 perform public.lock_classification_processing(p_article,p_provider,p_region);
 perform 1 from public.ai_lock_provider_title_inputs(array[p_article],p_provider,p_region);
 select array_agg(id order by id) into ids from unnest(p_categories) id;
 perform id from public.categories where id=any(ids) and active and length(trim(name)) between 1 and 100 order by id for share;
 select count(*) into n from public.categories where id=any(ids) and active and length(trim(name)) between 1 and 100;
 if n<>cardinality(ids) then raise exception 'classification categories unavailable'; end if;
 if not exists(select 1 from public.ai_processing_jobs where id=p_job) then raise exception 'AI job unavailable'; end if;
 select * into prep from public.ai_request_preparations where request_id=p_request;
 if found then
  select array_agg(category_id order by category_id) into old_ids from public.classification_request_categories where request_id=p_request;
  if prep.model_route_id is distinct from route.id or prep.requested_model is distinct from route.model_id
   or prep.processor is distinct from p_provider or prep.processing_region is distinct from p_region
   or prep.request_max_output_tokens is distinct from p_output or old_ids is distinct from ids
   or not exists(select 1 from public.ai_request_identities where request_id=p_request and job_id=p_job)
   or (select array_agg(article_id order by article_id) from public.ai_request_preparation_inputs where request_id=p_request) is distinct from array[p_article]
  then raise exception 'classification request identity conflict'; end if;
  return false;
 end if;
 perform public.ai_register_request_identity(p_request,p_job);
 insert into public.ai_request_preparations(request_id,processor,processing_region,requested_model,model_route_id,request_max_output_tokens,request_prompt_version,request_schema_version)
 values(p_request,p_provider,p_region,route.model_id,route.id,p_output,'classification_titles.v1','classification_proposal.v1');
 insert into public.ai_request_preparation_inputs(request_id,article_id,policy_id,title_sha256,provider_grant_id)
 select p_request,i.article_id,i.policy_id,encode(sha256(convert_to(i.title,'UTF8')),'hex'),i.grant_id
 from public.ai_lock_provider_title_inputs(array[p_article],p_provider,p_region) i;
 get diagnostics n=row_count;
 if n<>1 then raise exception 'classification input unavailable'; end if;
 insert into public.classification_request_categories(request_id,category_id,name_sha256)
 select p_request,id,encode(sha256(convert_to(name,'UTF8')),'hex') from public.categories where id=any(ids);
 return true;
end $$;



