CREATE FUNCTION public.ai_prepare_story_summary_request(p_request uuid, p_job uuid, p_story uuid, p_facts uuid[], p_provider text, p_region text, p_bound uuid, p_output integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare route public.ai_model_routes%rowtype; prep public.ai_request_preparations%rowtype;
 ids uuid[]; fact_ids uuid[]; old_ids uuid[]; n integer;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null or p_job is null or p_story is null
  or p_bound is null or p_output is null or p_output not between 1 and 8192 or p_facts is null
  or cardinality(p_facts) not between 2 and 10 or (select count(distinct id) from unnest(p_facts) id)<>cardinality(p_facts)
 then raise exception 'invalid story summary request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists
  (select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into route from public.ai_model_routes where id=p_bound for share;
 if route.id is null or not route.enabled or route.provider is distinct from p_provider
  or route.processing_region is distinct from p_region or route.purpose<>'summary_story.v1'
 then raise exception 'explicit story summary model route unavailable'; end if;
 if not exists(select 1 from public.ai_processing_jobs where id=p_job and story_id=p_story) then raise exception 'summary job story mismatch'; end if;
 select array_agg(id order by id) into fact_ids from unnest(p_facts) id;
 select * into prep from public.ai_request_preparations where request_id=p_request;
 if prep.request_id is null then
  select count(*) into n from public.ai_lock_summary_story_facts(p_story,fact_ids,p_provider,p_region);
  if n<>cardinality(fact_ids) then raise exception 'story summary facts unavailable'; end if;
 else
  perform public.ai_lock_story_summary_request(p_request);
  select array_agg(fact_id order by fact_id) into old_ids from public.story_summary_request_facts where request_id=p_request;
  if prep.model_route_id is distinct from route.id or prep.requested_model is distinct from route.model_id
   or prep.processor is distinct from p_provider or prep.processing_region is distinct from p_region
   or prep.request_max_output_tokens is distinct from p_output or old_ids is distinct from fact_ids
   or not exists(select 1 from public.ai_request_identities where request_id=p_request and job_id=p_job)
   or not exists(select 1 from public.story_summary_requests where request_id=p_request and story_id=p_story)
  then raise exception 'story summary request identity conflict'; end if;
 end if;
 select array_agg(distinct i.article_id order by i.article_id) into ids from public.ai_verified_facts f
  join public.ai_request_preparation_inputs i on i.request_id=f.request_id where f.id=any(fact_ids);
 if cardinality(ids) not between 1 and 50 then raise exception 'story summary inputs unavailable'; end if;
 perform 1 from public.ai_lock_provider_title_inputs(ids,p_provider,p_region);
 if prep.request_id is not null then
  select array_agg(article_id order by article_id) into old_ids from public.ai_request_preparation_inputs where request_id=p_request;
  if old_ids is distinct from ids then raise exception 'story summary request identity conflict'; end if;
  return false;
 end if;
 perform public.ai_register_request_identity(p_request,p_job);
 insert into public.ai_request_preparations(request_id,processor,processing_region,requested_model,model_route_id,request_max_output_tokens,request_prompt_version,request_schema_version)
 values(p_request,p_provider,p_region,route.model_id,route.id,p_output,'summary_story_facts.v1','summary_proposal.v1');
 insert into public.ai_request_preparation_inputs(request_id,article_id,policy_id,title_sha256,provider_grant_id)
 select p_request,i.article_id,i.policy_id,encode(sha256(convert_to(i.title,'UTF8')),'hex'),i.grant_id
 from public.ai_lock_provider_title_inputs(ids,p_provider,p_region) i;
 get diagnostics n=row_count;
 if n<>cardinality(ids) then raise exception 'story summary source input unavailable'; end if;
 insert into public.story_summary_requests(request_id,story_id,fact_count) values(p_request,p_story,cardinality(fact_ids));
 insert into public.story_summary_request_facts(request_id,fact_id,fact_sha256)
 select p_request,f.id,encode(sha256(convert_to(f.fact_text,'UTF8')),'hex') from public.ai_verified_facts f where f.id=any(fact_ids);
 insert into public.story_summary_request_grants(request_id,fact_id,article_id,grant_id)
 select p_request,f.id,i.article_id,g.id from public.ai_verified_facts f join public.ai_request_preparation_inputs i on i.request_id=f.request_id
 join lateral (select sg.id from public.summary_processing_grants sg where sg.policy_id=i.policy_id and sg.provider=p_provider and sg.region=p_region
  and sg.expires_at>clock_timestamp() and not exists(select 1 from public.summary_processing_revocations r where r.grant_id=sg.id)
  order by sg.expires_at desc,sg.id limit 1) g on true where f.id=any(fact_ids);
 perform public.ai_lock_story_summary_request(p_request);
 return true;
end $$;



CREATE FUNCTION public.ai_prepare_summary_request(p_request uuid, p_job uuid, p_fact uuid, p_provider text, p_region text, p_bound uuid, p_output integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare route public.ai_model_routes%rowtype; prep public.ai_request_preparations%rowtype;
 f public.ai_verified_facts%rowtype; ids uuid[]; old_ids uuid[]; n integer; fact_hash text;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null or p_job is null or p_fact is null
  or p_bound is null or p_output is null or p_output not between 1 and 8192 then raise exception 'invalid summary request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists
  (select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into route from public.ai_model_routes where id=p_bound for share;
 if route.id is null or not route.enabled or route.provider is distinct from p_provider
  or route.processing_region is distinct from p_region or route.purpose<>'summary_fact.v1'
 then raise exception 'explicit summary model route unavailable'; end if;
 select * into prep from public.ai_request_preparations where request_id=p_request;
 select count(*) into n from public.lock_summary_processing(p_fact,p_provider,p_region,case when prep.request_id is null then null else p_request end);
 if n not between 1 and 50 then raise exception 'summary inputs unavailable'; end if;
 select * into f from public.ai_verified_facts where id=p_fact;
 select array_agg(i.article_id order by i.article_id) into ids from public.ai_request_preparation_inputs i where i.request_id=f.request_id;
 if not exists(select 1 from public.ai_request_identities r join public.ai_processing_jobs original on original.id=r.job_id
  join public.ai_processing_jobs current_job on current_job.id=p_job and current_job.story_id=original.story_id where r.request_id=f.request_id)
 then raise exception 'summary job story mismatch'; end if;
 perform 1 from public.ai_lock_provider_title_inputs(ids,p_provider,p_region);
 fact_hash:=encode(sha256(convert_to(f.fact_text,'UTF8')),'hex');
 if prep.request_id is not null then
  select array_agg(article_id order by article_id) into old_ids from public.ai_request_preparation_inputs where request_id=p_request;
  if prep.model_route_id is distinct from route.id or prep.requested_model is distinct from route.model_id
   or prep.processor is distinct from p_provider or prep.processing_region is distinct from p_region
   or prep.request_max_output_tokens is distinct from p_output or old_ids is distinct from ids
   or not exists(select 1 from public.ai_request_identities where request_id=p_request and job_id=p_job)
   or not exists(select 1 from public.summary_request_facts where request_id=p_request and fact_id=p_fact and fact_sha256=fact_hash)
  then raise exception 'summary request identity conflict'; end if;
  return false;
 end if;
 perform public.ai_register_request_identity(p_request,p_job);
 insert into public.ai_request_preparations(request_id,processor,processing_region,requested_model,model_route_id,request_max_output_tokens,request_prompt_version,request_schema_version)
 values(p_request,p_provider,p_region,route.model_id,route.id,p_output,'summary_reviewed_fact.v1','summary_proposal.v1');
 insert into public.ai_request_preparation_inputs(request_id,article_id,policy_id,title_sha256,provider_grant_id)
 select p_request,i.article_id,i.policy_id,encode(sha256(convert_to(i.title,'UTF8')),'hex'),i.grant_id
 from public.ai_lock_provider_title_inputs(ids,p_provider,p_region) i;
 get diagnostics n=row_count;
 if n<>cardinality(ids) then raise exception 'summary source input unavailable'; end if;
 insert into public.summary_request_facts(request_id,fact_id,fact_sha256) values(p_request,p_fact,fact_hash);
 insert into public.summary_request_processing_grants(request_id,article_id,grant_id)
 select p_request,article_id,grant_id from public.lock_summary_processing(p_fact,p_provider,p_region,null);
 return true;
end $$;



