CREATE FUNCTION public.ai_prepare_translation_request(p_request uuid, p_job uuid, p_intent uuid, p_provider text, p_region text, p_bound uuid, p_output integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare intent public.translation_task_intents%rowtype; route public.ai_model_routes%rowtype;
 prep public.ai_request_preparations%rowtype; previous public.translation_requests%rowtype; ids uuid[]; old_ids uuid[]; h text; n integer;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null or p_job is null or p_intent is null
  or p_provider is null or p_region is null or p_bound is null or p_output is null or p_output not between 1 and 8192
 then raise exception 'invalid translation request'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if exists(select 1 from public.ai_execution_safety_incidents i where i.request_id=p_request and not exists
  (select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id))
  or exists(select 1 from public.ai_request_preparations p where p.request_id=p_request and p.state='checked'
   and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id))
 then raise exception 'unresolved execution requires reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into intent from public.translation_task_intents where id=p_intent;
 if not found or not exists(select 1 from public.ai_processing_jobs where id=p_job and story_id=intent.story_id and task_type='translation')
 then raise exception 'translation intent or job unavailable'; end if;
 select * into route from public.ai_model_routes where id=p_bound for share;
 if route.id is null or not route.enabled or route.provider is distinct from p_provider
  or route.processing_region is distinct from p_region or route.purpose<>'translation.v1'
 then raise exception 'explicit translation model route unavailable'; end if;
 perform public.ai_lock_translation_scope(intent.source_revision_id,p_provider,p_region,array['process','store','editor_display']);
 select array_agg(distinct e.article_id order by e.article_id) into ids from public.claims c join public.claim_evidence e on e.claim_id=c.id
  where c.revision_id=intent.source_revision_id;
 n:=coalesce(cardinality(ids),0); if n not between 1 and 50 then raise exception 'translation evidence unavailable'; end if;
 perform 1 from public.ai_lock_provider_title_inputs(ids,p_provider,p_region);
 h:=encode(sha256(convert_to(public.translation_source_payload(intent.source_revision_id)::text,'UTF8')),'hex');
 select * into prep from public.ai_request_preparations where request_id=p_request;
 if prep.request_id is not null then
  select * into previous from public.translation_requests where request_id=p_request;
  select array_agg(article_id order by article_id) into old_ids from public.ai_request_preparation_inputs where request_id=p_request;
  if previous.intent_id is distinct from p_intent or previous.draft_sha256 is distinct from h
   or prep.model_route_id is distinct from route.id or prep.requested_model is distinct from route.model_id
   or prep.processor is distinct from p_provider or prep.processing_region is distinct from p_region
   or prep.request_max_output_tokens is distinct from p_output or old_ids is distinct from ids
   or not exists(select 1 from public.ai_request_identities where request_id=p_request and job_id=p_job)
  then raise exception 'translation request identity conflict'; end if;
  -- Snapshot rechecks the originally bound grants; a replacement is not revival.
  if exists(select 1 from public.translation_request_grants rg join public.translation_scope_grants g on g.id=rg.grant_id
   where rg.request_id=p_request and (g.expires_at<=clock_timestamp()
    or exists(select 1 from public.translation_scope_revocations r where r.grant_id=g.id)))
  then raise exception 'translation request permissions changed'; end if;
  return false;
 end if;
 perform public.ai_register_request_identity(p_request,p_job);
 insert into public.ai_request_preparations(request_id,processor,processing_region,requested_model,model_route_id,request_max_output_tokens,request_prompt_version,request_schema_version)
 values(p_request,p_provider,p_region,route.model_id,route.id,p_output,'translation_context.v1','translation_proposal.v1');
 insert into public.ai_request_preparation_inputs(request_id,article_id,policy_id,title_sha256,provider_grant_id)
 select p_request,i.article_id,i.policy_id,encode(sha256(convert_to(i.title,'UTF8')),'hex'),i.grant_id
 from public.ai_lock_provider_title_inputs(ids,p_provider,p_region) i;
 get diagnostics n=row_count;
 if n<>cardinality(ids) then raise exception 'translation source input unavailable'; end if;
 insert into public.translation_requests(request_id,intent_id,draft_sha256) values(p_request,p_intent,h);
 insert into public.translation_request_grants(request_id,grant_id)
 select distinct p_request,g.id from public.claims c join public.claim_evidence e on e.claim_id=c.id
 join public.articles a on a.id=e.article_id
 join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) policy on true
 cross join (values ('title'),('summary'),('claims')) f(name)
 cross join (values ('process'),('store'),('editor_display')) action(name)
 join lateral (select x.id from public.translation_scope_grants x where x.policy_id=policy.id and x.provider=p_provider
  and x.processing_region=p_region and x.field_name=f.name and x.permitted_action=action.name and x.expires_at>clock_timestamp()
  and not exists(select 1 from public.translation_scope_revocations r where r.grant_id=x.id)
  order by x.expires_at desc,x.id limit 1) g on true where c.revision_id=intent.source_revision_id;
 return true;
end $$;



CREATE FUNCTION public.ai_purge_expired_claim_proposals() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare n integer;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  perform 1 from public.ai_claim_retention_control where singleton for update;
  delete from public.ai_claim_proposals where request_id in (
    select request_id from public.ai_claim_proposals where expires_at<=clock_timestamp() order by expires_at,request_id limit 500
  );
  get diagnostics n = row_count;
  update public.ai_claim_retention_control set last_sweep_at=clock_timestamp(),last_removed=n where singleton;
  return n;
end $$;



CREATE FUNCTION public.ai_queue_incident_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  begin
    insert into public.ai_alert_outbox(incident_id) values(new.id) on conflict do nothing;
  exception when others then
    -- Notification failure must not undo the safety halt or hide degradation.
    update public.ai_budget_control set alert_degraded=true,updated_at=clock_timestamp() where singleton;
  end;
  return new;
end $$;



CREATE FUNCTION public.ai_raise_budget_halt(p_request uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare incident uuid;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_reason is null or p_reason not in ('missing_usage','malformed_usage','model_mismatch','token_limit_exceeded','unknown_charge','other') then raise exception 'invalid budget incident'; end if;
  if p_request is not null then
    perform 1 from public.ai_budget_reservations where request_id=p_request for key share;
    if not found then raise exception 'reservation unavailable'; end if;
  end if;
  update public.ai_budget_control set stopped=true,generation=generation+1,updated_at=clock_timestamp() where singleton;
  if not found then raise exception 'budget control unavailable'; end if;
  insert into public.ai_budget_incidents(request_id,reason) values(p_request,p_reason) returning id into incident;
  return incident;
end $$;



CREATE FUNCTION public.ai_record_bounded_execution(p_request uuid, p_model text, p_input bigint, p_output bigint, p_cached bigint, p_total bigint, p_outcome text, p_latency integer) RETURNS TABLE(status text, triggered_halt boolean, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prep public.ai_request_preparations%rowtype; prior public.ai_execution_observations%rowtype; prior_usage public.ai_usage_observations%rowtype;
 expected text; prompt text; schema_name text; actual_outcome text; incident text; observed text;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null or p_outcome is null
  or p_outcome not in ('ok','refused','incomplete','invalid','http_error','invalid_response','unknown','not_sent_expired','integrity_error')
  or p_latency is null or p_latency not between 0 and 86400000 then raise exception 'invalid execution observation'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into prep from public.ai_request_preparations where request_id=p_request;
 if prep.request_id is null or prep.state<>'checked' then raise exception 'checked request required'; end if;
 select coalesce(prep.requested_model,r.model_id),coalesce(prep.request_prompt_version,b.prompt_version),
  coalesce(prep.request_schema_version,b.schema_version) into expected,prompt,schema_name
 from (select 1) x left join public.ai_budget_reservations r on r.request_id=p_request
 left join public.ai_request_billing_bounds b on b.request_id=p_request;
 if expected is null or prompt is null or schema_name is null then raise exception 'request model or version unavailable'; end if;
 if p_outcome in ('http_error','invalid_response','unknown','not_sent_expired','integrity_error') then
  incident:='uncertain_send'; actual_outcome:=p_outcome;
 elsif p_model is distinct from expected then incident:='model_mismatch'; actual_outcome:='integrity_error';
 else actual_outcome:=p_outcome; end if;
 if incident is not null then observed:='unknown'; p_input:=null; p_output:=null; p_cached:=null; p_total:=null;
 elsif p_input is null or p_output is null or p_input not between 0 and 100000000 or p_output not between 0 and 100000000
  or (p_cached is not null and (p_cached<0 or p_cached>p_input))
  or (p_total is not null and (p_total<0 or p_total::numeric<>p_input::numeric+p_output::numeric))
 then observed:='unavailable'; p_input:=null; p_output:=null; p_cached:=null; p_total:=null;
 else observed:='reported'; end if;
 select * into prior from public.ai_execution_observations where request_id=p_request;
 if found then
  select * into prior_usage from public.ai_usage_observations where request_id=p_request;
  if prior.outcome is distinct from actual_outcome or prior.observed_model is distinct from p_model
   or prior.latency_ms is distinct from p_latency or prior_usage.request_id is null
   or prior_usage.input_tokens is distinct from p_input or prior_usage.output_tokens is distinct from p_output
   or prior_usage.cached_input_tokens is distinct from p_cached or prior_usage.total_tokens is distinct from p_total
  then incident:='receipt_conflict'; end if;
  if incident is not null then
   insert into public.ai_execution_safety_incidents(request_id,reason) values(p_request,incident);
   return query select 'unknown'::text,true,false;
  else
   select u.status into observed from public.ai_usage_observations u where u.request_id=p_request;
   return query select coalesce(observed,'unavailable')::text,false,false;
  end if;
  return;
 end if;
 insert into public.ai_usage_observations(request_id,status,reason,input_tokens,output_tokens,cached_input_tokens,total_tokens)
 values(p_request,observed,case when observed='reported' then 'provider usage' when observed='unavailable' then 'usage unavailable' else incident end,
        p_input,p_output,p_cached,p_total);
 insert into public.ai_execution_observations(request_id,prompt_version,schema_version,outcome,latency_ms,estimated_nanos,observed_model)
 values(p_request,prompt,schema_name,actual_outcome,p_latency,null,p_model);
 if incident is not null then
  insert into public.ai_execution_safety_incidents(request_id,reason) values(p_request,incident);
 end if;
 return query select observed,incident is not null,true;
end $$;



CREATE FUNCTION public.ai_record_classification_result(p_request uuid, p_model text, p_input bigint, p_output bigint, p_cached bigint, p_total bigint, p_outcome text, p_latency integer, p_proposal uuid, p_content jsonb, p_expires timestamp with time zone) RETURNS TABLE(status text, triggered_halt boolean, inserted boolean, stored boolean, storage_failed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare obs record; bound public.ai_request_billing_bounds%rowtype; wrote boolean:=false; failed boolean:=false;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if not exists(select 1 from public.ai_request_preparations p left join public.ai_request_billing_bounds old on old.request_id=p.request_id
   where p.request_id=p_request and coalesce(p.request_prompt_version,old.prompt_version)='classification_titles.v1'
    and coalesce(p.request_schema_version,old.schema_version)='classification_proposal.v1')
    then raise exception 'classification request version unavailable'; end if;
  select * into obs from public.ai_record_bounded_execution(p_request,p_model,p_input,p_output,p_cached,p_total,p_outcome,p_latency);
  if obs.inserted and not obs.triggered_halt and p_outcome='ok' and p_content is not null then
    begin
      select public.ai_store_classification_response(p_request,p_proposal,p_content,p_expires) into wrote;
      if wrote is distinct from true then failed:=true; wrote:=false; end if;
    exception when others then
      -- Keep the usage observation; an invalid or unauthorized candidate is not stored.
      failed:=true; wrote:=false;
    end;
  end if;
  return query select obs.status::text,obs.triggered_halt::boolean,obs.inserted::boolean,wrote,failed;
end $$;



CREATE FUNCTION public.ai_record_story_summary_result(p_request uuid, p_model text, p_input bigint, p_output bigint, p_cached bigint, p_total bigint, p_outcome text, p_latency integer, p_proposal uuid, p_content jsonb, p_expires timestamp with time zone) RETURNS TABLE(status text, triggered_halt boolean, inserted boolean, stored boolean, storage_failed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare obs record; bound public.ai_request_billing_bounds%rowtype; wrote boolean:=false; failed boolean:=false;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if not exists(select 1 from public.ai_request_preparations p left join public.ai_request_billing_bounds old on old.request_id=p.request_id
   where p.request_id=p_request and coalesce(p.request_prompt_version,old.prompt_version)='summary_story_facts.v1'
    and coalesce(p.request_schema_version,old.schema_version)='summary_proposal.v1')
    then raise exception 'story summary request version unavailable'; end if;
  select * into obs from public.ai_record_bounded_execution(p_request,p_model,p_input,p_output,p_cached,p_total,p_outcome,p_latency);
  if obs.inserted and not obs.triggered_halt and p_outcome='ok' and p_content is not null then
    begin
      select public.ai_store_story_summary_response(p_request,p_proposal,p_content,p_expires) into wrote;
      if wrote is distinct from true then failed:=true; wrote:=false; end if;
    exception when others then failed:=true; wrote:=false;
    end;
  end if;
  return query select obs.status::text,obs.triggered_halt::boolean,obs.inserted::boolean,wrote,failed;
end $$;



CREATE FUNCTION public.ai_record_summary_result(p_request uuid, p_model text, p_input bigint, p_output bigint, p_cached bigint, p_total bigint, p_outcome text, p_latency integer, p_proposal uuid, p_content jsonb, p_expires timestamp with time zone) RETURNS TABLE(status text, triggered_halt boolean, inserted boolean, stored boolean, storage_failed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare obs record; bound public.ai_request_billing_bounds%rowtype; wrote boolean:=false; failed boolean:=false;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if not exists(select 1 from public.ai_request_preparations p left join public.ai_request_billing_bounds old on old.request_id=p.request_id
   where p.request_id=p_request and coalesce(p.request_prompt_version,old.prompt_version)='summary_reviewed_fact.v1'
    and coalesce(p.request_schema_version,old.schema_version)='summary_proposal.v1')
    then raise exception 'summary request version unavailable'; end if;
  select * into obs from public.ai_record_bounded_execution(p_request,p_model,p_input,p_output,p_cached,p_total,p_outcome,p_latency);
  if obs.inserted and not obs.triggered_halt and p_outcome='ok' and p_content is not null then
    begin
      select public.ai_store_summary_response(p_request,p_proposal,p_content,p_expires) into wrote;
      if wrote is distinct from true then failed:=true; wrote:=false; end if;
    exception when others then failed:=true; wrote:=false;
    end;
  end if;
  return query select obs.status::text,obs.triggered_halt::boolean,obs.inserted::boolean,wrote,failed;
end $$;



CREATE FUNCTION public.ai_record_translation_usage(p_request uuid, p_model text, p_input bigint, p_output bigint, p_cached bigint, p_total bigint, p_outcome text, p_latency integer) RETURNS TABLE(status text, triggered_halt boolean, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not exists(select 1 from public.translation_requests tr join public.ai_request_preparations p on p.request_id=tr.request_id
    left join public.ai_request_billing_bounds old on old.request_id=p.request_id
    where tr.request_id=p_request and coalesce(p.request_prompt_version,old.prompt_version)='translation_context.v1'
      and coalesce(p.request_schema_version,old.schema_version)='translation_proposal.v1')
    then raise exception 'translation request version unavailable'; end if;
  return query select x.status,x.triggered_halt,x.inserted
    from public.ai_record_bounded_execution(p_request,p_model,p_input,p_output,p_cached,p_total,p_outcome,p_latency) x;
end $$;



