CREATE FUNCTION public.ai_register_request_identity(p_request uuid, p_job uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare existing uuid;
begin
 if current_setting('transaction_isolation')<>'read committed' or p_request is null or p_job is null
  or not exists(select 1 from public.ai_processing_jobs where id=p_job)
 then raise exception 'valid AI request and job required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select job_id into existing from public.ai_request_identities where request_id=p_request;
 if found then
  if existing is distinct from p_job then raise exception 'AI request identity conflict'; end if;
  return false;
 end if;
 insert into public.ai_request_identities(request_id,job_id) values(p_request,p_job);
 return true;
end $$;



CREATE FUNCTION public.ai_replay_verified_fact_deletions(p_entries jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare item jsonb; fid uuid; rid uuid; existing_request uuid; n integer:=0; quarantined boolean;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  if jsonb_typeof(p_entries) is distinct from 'array' or jsonb_array_length(p_entries) not between 1 and 500 then raise exception 'invalid deletion replay'; end if;
  select restore_quarantine into quarantined from public.ai_verified_fact_retention_control where singleton for update;
  if quarantined is distinct from true then raise exception 'restore quarantine required'; end if;
  for item in select * from jsonb_array_elements(p_entries) loop
    if jsonb_typeof(item) is distinct from 'object' or item - array['fact_id','request_id'] <> '{}'::jsonb
      or item->>'fact_id' is null or item->>'fact_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or item->>'request_id' is null or item->>'request_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then raise exception 'invalid deletion replay entry'; end if;
    fid:=(item->>'fact_id')::uuid; rid:=(item->>'request_id')::uuid;
    select request_id into existing_request from public.ai_verified_facts where id=fid for update;
    if found and existing_request is distinct from rid then raise exception 'deletion replay identity conflict'; end if;
    select request_id into existing_request from public.ai_verified_fact_deletion_receipts where fact_id=fid;
    if found and existing_request is distinct from rid then raise exception 'deletion receipt identity conflict'; end if;
    delete from public.ai_verified_facts where id=fid;
    insert into public.ai_verified_fact_deletion_receipts(fact_id,request_id) values(fid,rid) on conflict do nothing;
    n:=n+1;
  end loop;
  return n;
end $_$;



