    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
 if tg_op='DELETE' or new.id is distinct from old.id or new.provider is distinct from old.provider
  or new.processing_region is distinct from old.processing_region or new.model_id is distinct from old.model_id
  or new.purpose is distinct from old.purpose or new.created_at is distinct from old.created_at
 then raise exception 'model route identity is immutable'; end if;
 return new;
end $$;



CREATE FUNCTION public.ai_settle_budget(p_request uuid, p_actual_nanos bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare r public.ai_budget_reservations%rowtype;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_actual_nanos is null or p_actual_nanos < 0 or p_actual_nanos > 1000000000000000 then raise exception 'invalid actual cost'; end if;
  select * into r from public.ai_budget_reservations where request_id=p_request;
  if not found then raise exception 'reservation unavailable'; end if;
  -- Same lock order as reservation; actual cost may exceed the estimate.
  perform 1 from public.ai_daily_budgets where budget_day=r.budget_day for update;
  perform 1 from public.ai_task_budgets where job_id=r.job_id for update;
  select * into r from public.ai_budget_reservations where request_id=p_request for update;
  if r.state='reconciled_cny' then raise exception 'CNY reconciliation cannot become USD settlement'; end if;
  if r.state = 'settled' then
    if r.actual_nanos <> p_actual_nanos then raise exception 'settlement conflict'; end if;
    return false;
  end if;
  update public.ai_budget_reservations set state='settled',actual_nanos=p_actual_nanos,settled_at=clock_timestamp() where request_id=p_request;
  return true;
end $$;



CREATE FUNCTION public.ai_store_claim_proposal(p_request uuid, p_content jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  perform 1 from public.ai_claim_retention_control where singleton and not restore_quarantine for update;
  if not found then raise exception 'claim restore quarantine active'; end if;
  return public.ai_store_claim_proposal_before_restore_gate(p_request,p_content);
end $$;



CREATE FUNCTION public.ai_store_claim_proposal_before_restore_gate(p_request uuid, p_content jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare last_sweep timestamptz;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  select last_sweep_at into last_sweep from public.ai_claim_retention_control where singleton for update;
  if last_sweep is null or last_sweep>clock_timestamp() or last_sweep<=clock_timestamp()-interval '5 minutes'
    or exists(select 1 from public.ai_claim_proposals where expires_at<=clock_timestamp()) then
    raise exception 'claim retention cleanup unavailable'; end if;
  return public.ai_store_claim_proposal_unchecked(p_request,p_content);
end $$;



CREATE FUNCTION public.ai_store_claim_proposal_unchecked(p_request uuid, p_content jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare prep public.ai_request_preparations%rowtype; ids uuid[]; n integer; matched integer; item jsonb; ev jsonb; title_value text;
  start_pos integer; end_pos integer; deadline timestamptz; digest text; prior_digest text;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_request is null or p_content is null or pg_column_size(p_content)>65536 or jsonb_typeof(p_content) is distinct from 'object'
    or p_content - array['schema_version','claims'] <> '{}'::jsonb or p_content->>'schema_version' is distinct from 'claim_extraction.v1'
    or jsonb_typeof(p_content->'claims') is distinct from 'array' or jsonb_array_length(p_content->'claims')>30 then raise exception 'invalid claim proposal'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
  select * into prep from public.ai_request_preparations where request_id=p_request;
  if not found or prep.state<>'checked' or not exists(select 1 from public.ai_execution_observations e
      where e.request_id=p_request and e.outcome='ok'
        and e.observed_model is not null
        and e.observed_model=coalesce(prep.requested_model,(select b.model_id from public.ai_budget_reservations b where b.request_id=p_request))
        and e.schema_version='claim_extraction.v1' and e.created_at>clock_timestamp()-interval '5 minutes') then raise exception 'successful execution unavailable'; end if;
  select array_agg(article_id order by article_id),count(*) into ids,n from public.ai_request_preparation_inputs where request_id=p_request;
  if n<1 or n>50 then raise exception 'request inputs unavailable'; end if;
  select count(*) into matched from public.ai_lock_provider_title_inputs(ids,prep.processor,prep.processing_region) i
    join public.ai_request_preparation_inputs x on x.request_id=p_request and x.article_id=i.article_id
      and x.policy_id=i.policy_id and x.provider_grant_id=i.grant_id and x.title_sha256=encode(sha256(convert_to(i.title,'UTF8')),'hex');
  if matched<>n then raise exception 'request inputs changed'; end if;
  perform public.ai_lock_derived_claim_permissions(ids,prep.processor,prep.processing_region,'store');
  for item in select * from jsonb_array_elements(p_content->'claims') loop
    if jsonb_typeof(item) is distinct from 'object' or item - array['text','kind','status','evidence'] <> '{}'::jsonb
      or jsonb_typeof(item->'text') is distinct from 'string' or length(item->>'text') not between 1 and 500 or item->>'text' !~ '[^[:space:]]'
      or item->>'kind' is null or item->>'kind' not in ('factual','opinion') or item->>'status' is distinct from 'unverified'
      or jsonb_typeof(item->'evidence') is distinct from 'array' or jsonb_array_length(item->'evidence') not between 1 and 5 then raise exception 'invalid claim'; end if;
    for ev in select * from jsonb_array_elements(item->'evidence') loop
      if jsonb_typeof(ev) is distinct from 'object' or ev - array['article_id','field','start','end'] <> '{}'::jsonb
        or ev->>'article_id' is null or ev->>'article_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        or ev->>'field' is distinct from 'title' or jsonb_typeof(ev->'start') is distinct from 'number'
        or jsonb_typeof(ev->'end') is distinct from 'number' or ev->>'start' !~ '^(0|[1-9][0-9]{0,3})$'
        or ev->>'end' !~ '^[1-9][0-9]{0,3}$' then raise exception 'invalid evidence'; end if;
      start_pos:=(ev->>'start')::integer; end_pos:=(ev->>'end')::integer;
      select title into title_value from public.articles where id=(ev->>'article_id')::uuid and id=any(ids);
      if title_value is null or start_pos>=end_pos or end_pos>length(title_value)
        or substring(title_value from start_pos+1 for end_pos-start_pos) !~ '[^[:space:]]' then raise exception 'invalid evidence span'; end if;
    end loop;
  end loop;
  select least(clock_timestamp()+interval '7 days',min(g.expires_at),min(p.permission_expires_at)) into deadline
    from public.articles a join public.source_policies p on p.source_id=a.source_id
    join public.ai_derived_claim_grants g on g.policy_id=p.id and g.provider=prep.processor and g.processing_region=prep.processing_region
      and g.permitted_action='store' and g.expires_at>clock_timestamp()
      and not exists(select 1 from public.ai_derived_claim_revocations r where r.grant_id=g.id)
    where a.id=any(ids) and p.id=(select sp.id from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1);
  if deadline is null or deadline<=clock_timestamp() then raise exception 'storage deadline unavailable'; end if;
  perform public.ai_lock_provider_title_inputs(ids,prep.processor,prep.processing_region);
  perform public.ai_lock_derived_claim_permissions(ids,prep.processor,prep.processing_region,'store');
  digest:=encode(sha256(convert_to(p_content::text,'UTF8')),'hex');
  select content_sha256 into prior_digest from public.ai_claim_proposal_receipts where request_id=p_request;
  if found then
    if prior_digest is distinct from digest then raise exception 'proposal identity conflict'; end if;
    return false;
  end if;
  insert into public.ai_claim_proposal_receipts(request_id,content_sha256) values(p_request,digest);
  insert into public.ai_claim_proposals(request_id,content,expires_at) values(p_request,p_content,deadline);
  return true;
end $_$;



CREATE FUNCTION public.ai_store_classification_response(p_request uuid, p_proposal uuid, p_content jsonb, p_expires timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare prep public.ai_request_preparations%rowtype; item jsonb; article uuid; category uuid; n integer; matched integer;
  digest text; prior public.classification_model_receipts%rowtype;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_request is null or p_proposal is null or p_content is null or jsonb_typeof(p_content) is distinct from 'object'
    or pg_column_size(p_content)>32768 or p_content - array['schema_version','categories'] <> '{}'::jsonb
    or p_content->>'schema_version' is distinct from 'classification_proposal.v1' or jsonb_typeof(p_content->'categories') is distinct from 'array'
    or jsonb_array_length(p_content->'categories')<>1 then raise exception 'invalid classification response'; end if;
  item:=p_content->'categories'->0;
  if jsonb_typeof(item) is distinct from 'object' or item - array['category_id','reason','article_ids'] <> '{}'::jsonb
    or jsonb_typeof(item->'category_id') is distinct from 'string' or item->>'category_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or jsonb_typeof(item->'reason') is distinct from 'string' or length(trim(item->>'reason')) not between 1 and 500
    or jsonb_typeof(item->'article_ids') is distinct from 'array' or jsonb_array_length(item->'article_ids')<>1 then raise exception 'invalid classification item'; end if;
  category:=(item->>'category_id')::uuid;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
  select * into prep from public.ai_request_preparations where request_id=p_request;
  if not found or prep.state<>'checked' or not exists(select 1 from public.ai_execution_observations e

    where e.request_id=p_request and e.outcome='ok' and e.observed_model is not null
      and e.observed_model=coalesce(prep.requested_model,(select old.model_id from public.ai_budget_reservations old where old.request_id=p_request)) and e.prompt_version='classification_titles.v1' and e.schema_version='classification_proposal.v1'
      and e.created_at>clock_timestamp()-interval '5 minutes' ) then raise exception 'successful classification execution unavailable'; end if;
  select count(*),min(article_id::text)::uuid into n,article from public.ai_request_preparation_inputs where request_id=p_request;
  if n<>1 or item->'article_ids'<>jsonb_build_array(article::text) then raise exception 'classification evidence unavailable'; end if;
  perform public.lock_classification_processing(article,prep.processor,prep.processing_region);
  select count(*) into matched from public.ai_lock_provider_title_inputs(array[article],prep.processor,prep.processing_region) i
    join public.ai_request_preparation_inputs x on x.request_id=p_request and x.article_id=i.article_id and x.policy_id=i.policy_id
      and x.provider_grant_id=i.grant_id and x.title_sha256=encode(sha256(convert_to(i.title,'UTF8')),'hex');
  if matched<>1 then raise exception 'classification input changed'; end if;
  perform c.id from public.categories c join public.classification_request_categories x on x.category_id=c.id where x.request_id=p_request order by c.id for share of c;
  if not exists(select 1 from public.classification_request_categories x join public.categories c on c.id=x.category_id
    where x.request_id=p_request and x.category_id=category and c.active and x.name_sha256=encode(sha256(convert_to(c.name,'UTF8')),'hex'))
    or exists(select 1 from public.classification_request_categories x join public.categories c on c.id=x.category_id
      where x.request_id=p_request and (not c.active or x.name_sha256<>encode(sha256(convert_to(c.name,'UTF8')),'hex'))) then raise exception 'classification category snapshot changed'; end if;
  digest:=encode(sha256(convert_to(p_content::text,'UTF8')),'hex');
  select * into prior from public.classification_model_receipts where request_id=p_request;
  if found then
    if prior.proposal_id is distinct from p_proposal or prior.content_sha256 is distinct from digest
      or not exists(select 1 from public.classification_proposals c where c.id=p_proposal and c.expires_at=p_expires and c.created_by=auth.uid())
      then raise exception 'classification response identity conflict'; end if;
    return false;
  end if;
  perform public.editor_import_classification(p_proposal,article,category,prep.processor,prep.processing_region,p_expires);
  insert into public.classification_model_receipts(request_id,proposal_id,content_sha256) values(p_request,p_proposal,digest);
  return true;
end $_$;



CREATE FUNCTION public.ai_store_story_summary_response(p_request uuid, p_proposal uuid, p_content jsonb, p_expires timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prep public.ai_request_preparations%rowtype; deadline timestamptz; prior public.story_summary_proposals%rowtype;
  fresh timestamptz; quarantined boolean; ids uuid[]; matched integer; digest text;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_request is null or p_proposal is null or p_expires is null or not public.story_summary_valid_content(p_content,p_request) then raise exception 'invalid story summary response'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
  select * into prep from public.ai_request_preparations where request_id=p_request;
  if not found or prep.state<>'checked' or not exists(select 1 from public.ai_execution_observations e

    where e.request_id=p_request and e.outcome='ok' and e.observed_model is not null
      and e.observed_model=coalesce(prep.requested_model,(select old.model_id from public.ai_budget_reservations old where old.request_id=p_request)) and e.prompt_version='summary_story_facts.v1' and e.schema_version='summary_proposal.v1'
      and e.created_at>clock_timestamp()-interval '5 minutes' )
    then raise exception 'successful story summary execution unavailable'; end if;
  select last_sweep_at,restore_quarantine into fresh,quarantined from public.story_summary_retention_control where singleton for update;
  if quarantined is distinct from false or fresh is null or fresh>clock_timestamp() or fresh<=clock_timestamp()-interval '5 minutes'
    or exists(select 1 from public.story_summary_proposals where expires_at<=clock_timestamp()) then raise exception 'story summary cleanup unavailable'; end if;
  deadline:=public.ai_lock_story_summary_request(p_request);
  if p_expires<=clock_timestamp() or p_expires>deadline then raise exception 'story summary permission unavailable'; end if;
  select array_agg(article_id order by article_id) into ids from public.ai_request_preparation_inputs where request_id=p_request;
  select count(*) into matched from public.ai_lock_provider_title_inputs(ids,prep.processor,prep.processing_region) i
    join public.ai_request_preparation_inputs x on x.request_id=p_request and x.article_id=i.article_id and x.policy_id=i.policy_id
      and x.provider_grant_id=i.grant_id and x.title_sha256=encode(sha256(convert_to(i.title,'UTF8')),'hex');
  if matched<>cardinality(ids) then raise exception 'story summary input changed'; end if;
  digest:=encode(sha256(convert_to(p_content::text,'UTF8')),'hex');
  select * into prior from public.story_summary_proposals where request_id=p_request;
  if found then
    if prior.id is distinct from p_proposal or prior.content_sha256 is distinct from digest or prior.expires_at is distinct from p_expires
      or prior.created_by is distinct from auth.uid() then raise exception 'story summary response identity conflict'; end if;
    return false;
  end if;
  if exists(select 1 from public.story_summary_receipts where id=p_proposal) then raise exception 'story summary cannot be restored'; end if;
  insert into public.story_summary_receipts(id,created_by) values(p_proposal,auth.uid());
  insert into public.story_summary_proposals(id,request_id,content,content_sha256,created_by,expires_at) values(p_proposal,p_request,p_content,digest,auth.uid(),p_expires);
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'record_story_summary','story_summary_proposal',p_proposal,'worker-reported model response; provenance unverified');
  return true;
end $$;



CREATE FUNCTION public.ai_store_summary_response(p_request uuid, p_proposal uuid, p_content jsonb, p_expires timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prep public.ai_request_preparations%rowtype; input public.summary_request_facts%rowtype;
  fact public.ai_verified_facts%rowtype; deadline timestamptz; prior public.summary_model_receipts%rowtype; digest text;
  ids uuid[]; matched integer;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_request is null or p_proposal is null or p_expires is null then raise exception 'invalid summary response'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
  select * into prep from public.ai_request_preparations where request_id=p_request;
  if not found or prep.state<>'checked' or not exists(select 1 from public.ai_execution_observations e

    where e.request_id=p_request and e.outcome='ok' and e.observed_model is not null
      and e.observed_model=coalesce(prep.requested_model,(select old.model_id from public.ai_budget_reservations old where old.request_id=p_request)) and e.prompt_version='summary_reviewed_fact.v1' and e.schema_version='summary_proposal.v1'
      and e.created_at>clock_timestamp()-interval '5 minutes' )
    then raise exception 'successful summary execution unavailable'; end if;
  select * into input from public.summary_request_facts where request_id=p_request;
  if not found or not public.summary_valid_content(p_content,input.fact_id) then raise exception 'invalid summary response'; end if;
  -- Match the existing summary import/review lock order: retention before sources.
  perform 1 from public.summary_retention_control where singleton for update;
  select min(x.deadline) into deadline from public.lock_summary_processing(input.fact_id,prep.processor,prep.processing_region,p_request) x;
  select * into fact from public.ai_verified_facts where id=input.fact_id;
  if fact.id is null or input.fact_sha256 is distinct from encode(sha256(convert_to(fact.fact_text,'UTF8')),'hex')
    or deadline is null or deadline<=clock_timestamp() or p_expires>deadline then raise exception 'summary fact snapshot or permission unavailable'; end if;
  select array_agg(article_id order by article_id) into ids from public.ai_request_preparation_inputs where request_id=p_request;
  select count(*) into matched from public.ai_lock_provider_title_inputs(ids,prep.processor,prep.processing_region) i
    join public.ai_request_preparation_inputs x on x.request_id=p_request and x.article_id=i.article_id and x.policy_id=i.policy_id
      and x.provider_grant_id=i.grant_id and x.title_sha256=encode(sha256(convert_to(i.title,'UTF8')),'hex');
  if matched<>cardinality(ids) then raise exception 'summary input changed'; end if;
  digest:=encode(sha256(convert_to(p_content::text,'UTF8')),'hex');
  select * into prior from public.summary_model_receipts where request_id=p_request;
  if found then
    if prior.proposal_id is distinct from p_proposal or prior.content_sha256 is distinct from digest
      or not exists(select 1 from public.summary_proposals c where c.id=p_proposal and c.expires_at=p_expires and c.created_by=auth.uid())
      then raise exception 'summary response identity conflict'; end if;
    return false;
  end if;
  perform public.editor_import_summary(p_proposal,input.fact_id,prep.processor,prep.processing_region,p_content,p_expires);
  insert into public.summary_model_receipts(request_id,proposal_id,content_sha256) values(p_request,p_proposal,digest);
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'record_model_summary','summary_proposal',p_proposal,'worker-reported model response; provenance unverified');
  return true;
end $$;



CREATE FUNCTION public.ai_store_translation_proposal(p_request uuid, p_id uuid, p_content jsonb, p_expires timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare intent public.translation_task_intents%rowtype; prep public.ai_request_preparations%rowtype; deadline timestamptz; digest text;
  prior public.translation_proposals%rowtype; fresh timestamptz; quarantined boolean;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_request is null or p_id is null or p_expires is null or not public.translation_valid_proposal(p_request,p_content) then raise exception 'invalid translation proposal'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
  select * into prep from public.ai_request_preparations where request_id=p_request;
  select t.* into intent from public.translation_requests r join public.translation_task_intents t on t.id=r.intent_id where r.request_id=p_request;
  if prep.request_id is null or intent.id is null or not exists(select 1 from public.ai_execution_observations e

    where e.request_id=p_request and e.outcome='ok' and e.observed_model is not null
      and e.observed_model=coalesce(prep.requested_model,(select old.model_id from public.ai_budget_reservations old where old.request_id=p_request)) and e.prompt_version='translation_context.v1' and e.schema_version='translation_proposal.v1'
    and e.created_at>clock_timestamp()-interval '5 minutes' )
    then raise exception 'successful translation execution unavailable'; end if;
  select last_sweep_at,restore_quarantine into fresh,quarantined from public.translation_retention_control where singleton for update;
  if quarantined is distinct from false or fresh is null or fresh>clock_timestamp() or fresh<=clock_timestamp()-interval '5 minutes'
    or exists(select 1 from public.translation_proposals where expires_at<=clock_timestamp()) then raise exception 'translation cleanup unavailable'; end if;
  deadline:=public.ai_lock_translation_scope(intent.source_revision_id,prep.processor,prep.processing_region,array['process','store','editor_display']);
  if not public.translation_request_accessible(p_request) or p_expires<=clock_timestamp() or p_expires>deadline
    or exists(select 1 from public.translation_request_grants x join public.translation_scope_grants g on g.id=x.grant_id
      where x.request_id=p_request and g.expires_at<p_expires) then raise exception 'translation permission unavailable'; end if;
  digest:=encode(sha256(convert_to(p_content::text,'UTF8')),'hex');
  select * into prior from public.translation_proposals where id=p_id;
  if found then
    if prior.content_sha256 is distinct from digest or prior.expires_at is distinct from p_expires
      or not exists(select 1 from public.translation_proposal_receipts where id=p_id and request_id=p_request)
      then raise exception 'translation proposal identity conflict'; end if;
    return false;
  end if;
  if exists(select 1 from public.translation_proposal_receipts where id=p_id or request_id=p_request)
    then raise exception 'translation proposal cannot be restored'; end if;
  insert into public.translation_proposal_receipts(id,request_id) values(p_id,p_request);
  insert into public.translation_proposals(id,content,content_sha256,expires_at) values(p_id,p_content,digest,p_expires);
  return true;
end $$;



CREATE FUNCTION public.ai_sweep_translation_proposals(p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare n integer; quarantined boolean;
begin
  if p_limit is null or p_limit not between 1 and 1000 then raise exception 'invalid cleanup limit'; end if;
  select restore_quarantine into quarantined from public.translation_retention_control where singleton for update;
  if quarantined is distinct from false then raise exception 'translation cleanup quarantined'; end if;
  delete from public.translation_proposals where id in (
    select p.id from public.translation_proposals p join public.translation_proposal_receipts r on r.id=p.id
    where p.expires_at<=clock_timestamp() or not public.translation_request_accessible(r.request_id)
    order by p.created_at,p.id limit p_limit);
  get diagnostics n=row_count;
  update public.translation_retention_control set last_sweep_at=clock_timestamp() where singleton;
  return n;
end $$;



CREATE FUNCTION public.ai_sweep_verified_facts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare n integer;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  perform 1 from public.ai_verified_fact_retention_control where singleton for update;
  delete from public.ai_verified_facts where id in(select id from public.ai_verified_facts where expires_at<=clock_timestamp() order by expires_at,id limit 500);
  get diagnostics n=row_count;
  update public.ai_verified_fact_retention_control set last_sweep_at=clock_timestamp() where singleton;
  return n;
end $$;



CREATE FUNCTION public.approve_retraction(p_notice uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if not exists(select 1 from public.retraction_notices where id = p_notice) then raise exception 'notice not found'; end if;
  insert into public.retraction_approvals(notice_id, approved_by) values (p_notice, auth.uid());
end $$;



CREATE FUNCTION public.article_auto_claim() RETURNS TABLE(job_id uuid, article_id uuid, region text, summary_config uuid, draft_config uuid, dispatch_id uuid, snapshot_id uuid, summary_request_id uuid, draft_request_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare task public.article_auto_tasks%rowtype;
begin
 if public.article_runtime_actor() is null or current_setting('transaction_isolation')<>'read committed' then raise exception 'authorized runtime actor required'; end if;
 if not exists(select 1 from public.ai_execution_control where singleton and not stopped) then raise exception 'AI execution manually stopped'; end if;
 select t.* into task from public.article_auto_tasks t join public.articles a on a.id=t.article_id where t.status='pending'
 order by (select count(*) from public.article_auto_tasks prior join public.articles pa on pa.id=prior.article_id
   where pa.source_id=a.source_id and prior.status in ('completed','failed','skipped') and prior.finished_at>clock_timestamp()-interval '24 hours'),t.created_at,t.job_id
 for update of t skip locked limit 1;
 if task.job_id is null then return; end if;
 update public.article_auto_tasks t set status='running',started_at=clock_timestamp() where t.job_id=task.job_id;
 update public.ai_processing_jobs j set status='processing' where j.id=task.job_id;
 return query select task.job_id,task.article_id,task.region,task.summary_config,task.draft_config,task.dispatch_id,task.snapshot_id,task.summary_request_id,task.draft_request_id;
end $$;



CREATE FUNCTION public.article_auto_finish(p_job uuid, p_draft uuid, p_failure text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare task public.article_auto_tasks%rowtype; skipped boolean;
begin
 if public.article_runtime_actor() is null or current_setting('transaction_isolation')<>'read committed' then raise exception 'authorized runtime actor required'; end if;
 if (p_draft is null)=(p_failure is null) or (p_failure is not null and p_failure not in ('processing_failed','result_unavailable','stale_or_undated','not_selected','selection_hold','editorial_hold')) then raise exception 'invalid automatic outcome'; end if;
 select * into task from public.article_auto_tasks where job_id=p_job for update;
 if task.job_id is null or task.status<>'running' then raise exception 'running automatic task required'; end if;
 if p_draft is not null and not exists(select 1 from public.article_full_review_queue q join public.article_full_drafts d on d.id=q.draft_id join public.ai_request_identities i on i.request_id=d.request_id where q.draft_id=p_draft and i.job_id=p_job and d.status='pending_human_review') then raise exception 'pending review draft required'; end if;
 skipped:=coalesce(p_failure in ('stale_or_undated','not_selected','selection_hold','editorial_hold'),false);
 update public.article_auto_tasks set status=case when skipped then 'skipped' when p_draft is null then 'failed' else 'completed' end,
  failure_code=p_failure,draft_id=p_draft,finished_at=clock_timestamp() where job_id=p_job;
 update public.ai_processing_jobs set status=case when skipped then 'cancelled' when p_draft is null then 'failed' else 'completed' end where id=p_job;
end $$;



CREATE FUNCTION public.article_auto_schedule(p_region text, p_summary uuid, p_draft uuid, p_summary_hash text, p_draft_hash text, p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare a record; sid uuid; jid uuid; created integer:=0; actor uuid;
begin
 actor:=public.article_runtime_actor();
 if actor is null or current_setting('transaction_isolation')<>'read committed' then raise exception 'authorized runtime actor required'; end if;
 if p_region is null or p_region !~ '^[a-z0-9-]{2,40}$' or p_limit is null or p_limit not between 1 and 5
  or p_summary_hash is null or p_summary_hash !~ '^[0-9a-f]{64}$' or p_draft_hash is null or p_draft_hash !~ '^[0-9a-f]{64}$'
 then raise exception 'invalid automatic task scope'; end if;
 if not exists(select 1 from public.ai_execution_control where singleton and not stopped) then raise exception 'AI execution manually stopped'; end if;
 if not exists(select 1 from public.article_stage_configs c join public.ai_model_routes r on r.id=c.route_id
   where c.id=p_summary and c.stage='summary' and c.expires_at>clock_timestamp() and r.enabled and r.provider='deepseek'
    and r.model_id='deepseek-flash' and r.purpose='article_summary.v1' and r.processing_region=p_region
    and not exists(select 1 from public.article_stage_config_revocations x where x.config_id=c.id))
 or not exists(select 1 from public.article_stage_configs c join public.ai_model_routes r on r.id=c.route_id
   where c.id=p_draft and c.stage='draft' and c.expires_at>clock_timestamp() and r.enabled and r.provider='deepseek'
    and r.model_id='deepseek-v4-pro' and r.purpose='article_draft.v1' and r.processing_region=p_region
    and not exists(select 1 from public.article_stage_config_revocations x where x.config_id=c.id))
 then raise exception 'explicit article model configuration unavailable'; end if;
 for a in select x.id from public.articles x
  where (x.canonical_url ~ '^https://www[.]example[.]invalid/news-events/news/[0-9]{4}/[0-9]{2}/[a-z0-9-]+/?$' or x.canonical_url ~ '^https://www[.]example[.]invalid/[a-zA-Z0-9][a-zA-Z0-9/_-]*/?$')

   and not exists(select 1 from public.article_auto_tasks t where t.article_id=x.id)
   and not exists(select 1 from public.story_articles sa where sa.article_id=x.id)
  order by (select count(*) from public.article_auto_tasks prior join public.articles pa on pa.id=prior.article_id where pa.source_id=x.source_id and prior.created_at>clock_timestamp()-interval '24 hours'),(exists(select 1 from public.signal_event_article_matches sm where sm.article_id=x.id)) desc,x.published_at desc nulls last,x.id limit 200
 loop
  perform pg_advisory_xact_lock(hashtextextended(a.id::text,881));
  if exists(select 1 from public.article_auto_tasks t where t.article_id=a.id)
   or exists(select 1 from public.story_articles sa where sa.article_id=a.id) then continue; end if;
  begin
   perform public.article_body_scope(a.id,p_region,array['fetch','store','editor_display','process_summary_deepseek','store_summary','display_summary','process_deepseek','store_draft','display_draft']);
   perform 1 from public.ai_lock_provider_title_inputs(array[a.id],'deepseek',p_region);
  exception when raise_exception then
   if sqlerrm not like 'body action not authorized:%' and sqlerrm<>'current provider title permission unavailable' then raise; end if;
   continue;
  end;
  sid:=gen_random_uuid(); jid:=gen_random_uuid();
  insert into public.stories(id,slug) values(sid,'auto-'||replace(sid::text,'-',''));
  insert into public.story_articles(story_id,article_id) values(sid,a.id);
  insert into public.ai_processing_jobs(id,story_id,article_id,task_type,idempotency_key)
   values(jid,sid,a.id,'full_article.v1','auto-article:'||a.id::text);
  insert into public.article_auto_tasks(job_id,article_id,region,summary_config,draft_config)
   values(jid,a.id,p_region,p_summary,p_draft);
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
   values(actor,'schedule_auto_article','story',sid,'Automated source candidate; requires editorial review');
  created:=created+1;
  exit when created>=p_limit;
 end loop;
 return created;
end $_$;



CREATE FUNCTION public.article_begin_body_fetch(p_dispatch uuid, p_article uuid, p_region text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare ids uuid[]; url text; target_host text; lock_name text;
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 select canonical_url into url from public.articles where id=p_article;
 if url ~ '^https://www[.]example[.]invalid/news-events/news/[0-9]{4}/[0-9]{2}/[a-z0-9-]+/?$'
 or url ~ '^https://www[.]example[.]invalid/[a-zA-Z0-9][a-zA-Z0-9/_-]*/?$' then
   target_host:=split_part(url,'/',3); lock_name:='article-body-'||target_host;
 else raise exception 'unsupported source URL';
 end if;
 ids:=public.article_body_scope(p_article,p_region,array['fetch','store','editor_display']);
 perform 1 from public.article_body_retention_control where singleton for update;
 -- Same host serialization. A recovery authorizes only its explicit successor once.
 perform pg_advisory_xact_lock(hashtextextended(lock_name,903514));
 if exists(select 1 from public.article_body_dispatches d join public.articles a on a.id=d.article_id
   where d.article_id=p_article and split_part(a.canonical_url,'/',3)=target_host and (d.outcome is distinct from 'stored' or d.finished_at is null)
   and not exists(select 1 from public.article_body_fetch_recoveries r where r.original_dispatch_id=d.id))
 or exists(select 1 from public.article_body_dispatches d join public.articles a on a.id=d.article_id
   where split_part(a.canonical_url,'/',3)=target_host and d.started_at>clock_timestamp()-interval '1 minute') then
 raise exception 'body dispatch held or rate limited'; end if;
 if exists(select 1 from public.article_body_fetch_recoveries r
   join public.article_body_dispatches original on original.id=r.original_dispatch_id
   join public.articles a on a.id=original.article_id
   where original.article_id=p_article and split_part(a.canonical_url,'/',3)=target_host and not exists(select 1 from public.article_body_dispatches d where d.id=r.successor_dispatch_id)
   and (r.successor_dispatch_id<>p_dispatch or clock_timestamp()<r.retry_not_before
     or clock_timestamp()>=r.retry_expires_at
     or not exists(select 1 from public.article_body_dispatches d where d.id=r.original_dispatch_id and d.article_id=p_article))) then
 raise exception 'explicit recovery successor or window required'; end if;
 -- A successor reserved for the other article/host cannot be repurposed.
 if exists(select 1 from public.article_body_fetch_recoveries r
   join public.article_body_dispatches d on d.id=r.original_dispatch_id
   where r.successor_dispatch_id=p_dispatch and d.article_id<>p_article) then
 raise exception 'recovery successor belongs to another article'; end if;
 insert into public.article_body_dispatches(id,article_id) values(p_dispatch,p_article);
 return jsonb_build_object('url',url,'deadline_epoch',extract(epoch from least(clock_timestamp()+interval '45 seconds',
 (select min(expires_at) from public.article_body_grants where id=any(ids)),
 (select retry_expires_at from public.article_body_fetch_recoveries where successor_dispatch_id=p_dispatch),
 (select expires_at from public.article_runtime_principals where role_name=session_user))),'server_epoch',extract(epoch from clock_timestamp()));
end $_$;



CREATE FUNCTION public.article_body_available(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select exists(select 1 from public.article_body_snapshots b join public.article_body_receipts r on r.id=b.id
 join public.article_body_retention_control c on c.singleton and not c.restore_quarantine
 where b.id=p_id and b.expires_at>statement_timestamp()
 and not exists(select 1 from unnest(r.grant_ids) gid where not public.article_body_grant_live(gid)))
$$;



CREATE FUNCTION public.article_body_claims(p_snapshot uuid, p_claims uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result jsonb;
begin
 if p_claims is null or cardinality(p_claims) not between 1 and 20 or (select count(distinct x) from unnest(p_claims) x)<>cardinality(p_claims) then raise exception 'invalid claims'; end if;
 select jsonb_agg(jsonb_build_object('claim_id',c.id,'text',c.claim_text,'quote',support.evidence_reference,
   'category',coalesce(x.category,'other'),'snapshot_id',support.snapshot_id,'source_family',support.source_id) order by c.id) into result
 from public.claims c left join public.claim_evidence_classifications x on x.claim_id=c.id
 join lateral (
   select e.evidence_reference,r.id as snapshot_id,a.source_id
   from public.claim_evidence e join public.article_body_receipts r on r.article_id=e.article_id
   join public.article_body_snapshots b on b.id=r.id join public.articles a on a.id=e.article_id
   where e.claim_id=c.id and r.id=p_snapshot and e.relation='supports'
     and length(trim(e.evidence_reference))>0 and position(e.evidence_reference in b.body)>0
   order by e.article_id limit 1
 ) support on true
 where c.id=any(p_claims) and c.status in ('unverified','verified')
   and not exists(select 1 from public.claim_evidence conflict where conflict.claim_id=c.id and conflict.relation='contradicts');
 if result is null or jsonb_array_length(result)<>cardinality(p_claims) then raise exception 'source-linked claim evidence unavailable'; end if;
 return result;
end $$;



CREATE FUNCTION public.article_body_grant_live(p_grant uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select coalesce((select p.policy_status='approved' and p.access_allowed
 and (g.action not in ('store','store_draft','store_summary') or p.fulltext_storage_allowed)
 and (g.action not in ('editor_display','display_draft','display_summary') or p.display_allowed)
 and (g.action not in ('process_deepseek','process_summary_deepseek') or p.ai_processing_allowed)
 and p.reviewed_by is not null and p.reviewed_at is not null and p.policy_evidence<>'{}'::jsonb
 and (p.permission_expires_at is null or p.permission_expires_at>statement_timestamp())
 and g.expires_at>statement_timestamp()
 and p.id=(select id from public.source_policies where source_id=p.source_id order by version desc limit 1)
 and not exists(select 1 from public.article_body_revocations where grant_id=g.id)
 and (g.source_rule_id is null or exists(select 1 from public.article_body_source_rules sr
  where sr.id=g.source_rule_id and sr.policy_id=g.policy_id and sr.action=g.action and sr.region=g.region
  and sr.expires_at>statement_timestamp() and not exists(select 1 from public.article_body_source_rule_revocations rv where rv.rule_id=sr.id)))
 from public.article_body_grants g join public.source_policies p on p.id=g.policy_id where g.id=p_grant),false)
$$;



CREATE FUNCTION public.article_body_scope(p_article uuid, p_region text, p_actions text[]) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare ids uuid[]; act text; gid uuid; sid uuid; rule public.article_body_source_rules%rowtype;
begin
 if current_setting('transaction_isolation')<>'read committed' or cardinality(p_actions) is null or cardinality(p_actions)<1 then raise exception 'invalid scope'; end if;
 select s.id into sid from public.sources s join public.articles a on a.source_id=s.id where a.id=p_article for update of s;
 if sid is null then raise exception 'article unavailable'; end if;
 foreach act in array p_actions loop
  select g.id into gid from public.article_body_grants g where g.article_id=p_article and g.region=p_region and g.action=act
   and public.article_body_grant_live(g.id) order by g.reviewed_at desc limit 1;
  if gid is null then
   -- An editor's explicit per-article revocation cannot be bypassed by a
   -- source-wide rule. A fresh explicit article grant can restore access.
   if exists(select 1 from public.article_body_grants g join public.article_body_revocations rv on rv.grant_id=g.id
      where g.article_id=p_article and g.region=p_region and g.action=act)
   then raise exception 'body action not authorized: %',act; end if;
   select r.* into rule from public.article_body_source_rules r join public.source_policies p on p.id=r.policy_id
    where p.source_id=sid and p.id=(select id from public.source_policies where source_id=sid order by version desc limit 1)
     and p.policy_status='approved' and p.access_allowed and p.reviewed_by is not null and p.reviewed_at is not null
     and p.policy_evidence<>'{}'::jsonb and (p.permission_expires_at is null or p.permission_expires_at>clock_timestamp())
     and r.action=act and r.region=p_region and r.expires_at>clock_timestamp()
     and not exists(select 1 from public.article_body_source_rule_revocations rv where rv.rule_id=r.id)
    order by r.created_at desc limit 1;
   if rule.id is null then raise exception 'body action not authorized: %',act; end if;
   insert into public.article_body_grants(policy_id,article_id,action,region,evidence,expires_at,reviewed_by,source_rule_id)
    values(rule.policy_id,p_article,rule.action,rule.region,rule.evidence,rule.expires_at,rule.reviewed_by,rule.id)
    on conflict(source_rule_id,article_id) where source_rule_id is not null do nothing returning id into gid;
   if gid is null then select g.id into gid from public.article_body_grants g where g.source_rule_id=rule.id and g.article_id=p_article; end if;
   if not public.article_body_grant_live(gid) then raise exception 'body action not authorized: %',act; end if;
  end if;
  ids:=array_append(ids,gid);
 end loop;
 return ids;
end $$;



CREATE FUNCTION public.article_claimset_current(p_snapshot uuid, p_claims uuid[], p_hash text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 return coalesce(encode(sha256(convert_to(public.article_body_claims(p_snapshot,p_claims)::text,'UTF8')),'hex')=p_hash,false);
exception when others then return false;
end $$;



CREATE FUNCTION public.article_editor_revision_live(p_revision uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select exists(select 1 from public.article_editor_revision_receipts er
 join public.article_editor_revision_content ec on ec.id=er.id join public.article_full_drafts d on d.id=er.draft_id
 where er.id=p_revision and ec.expires_at>statement_timestamp() and ec.expires_at<=d.expires_at and d.expires_at>statement_timestamp()
 and public.article_stage_accessible(d.request_id) and public.article_body_available(d.snapshot_id)
 and er.content_sha256=encode(sha256(convert_to(ec.content::text,'UTF8')),'hex')
 and not exists(select 1 from public.article_editor_revision_receipts newer where newer.draft_id=er.draft_id and newer.revision_number>er.revision_number))
$$;



CREATE FUNCTION public.article_finish_body_fetch(p_dispatch uuid, p_snapshot uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 update public.article_body_dispatches d set finished_at=clock_timestamp(),outcome=case when p_snapshot is null then 'held' else 'stored' end,snapshot_id=p_snapshot
 where d.id=p_dispatch and d.finished_at is null and (p_snapshot is null or exists(select 1 from public.article_body_receipts r where r.id=p_snapshot and r.article_id=d.article_id));
 if not found then raise exception 'dispatch unavailable'; end if;
end $$;



CREATE FUNCTION public.article_full_draft_valid(p_snapshot uuid, p_content jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare lang text; section text; row jsonb; cid text; article uuid; body_text text;
begin
 select r.article_id,b.body into article,body_text from public.article_body_receipts r join public.article_body_snapshots b on b.id=r.id where r.id=p_snapshot;
 if article is null or p_content is null or jsonb_typeof(p_content)<>'object' or octet_length(p_content::text)>65536
 or not (p_content ?& array['source_info','editorial_checks'])
 or jsonb_typeof(p_content->'source_info') is distinct from 'object' or jsonb_typeof(p_content->'editorial_checks') is distinct from 'object' or not p_content ?& array['schema_version','zh','en']
 or p_content->>'schema_version'<>'full_article.v1' then return false; end if;
 foreach lang in array array['zh','en'] loop
 if jsonb_typeof(p_content->lang)<>'object' or jsonb_typeof(p_content->lang->'seo') is distinct from 'object'
 or not (p_content->lang->'seo') ?& array['title','meta_description','slug','summary','keywords','tags']
 or not (p_content->lang) ?& array['title','what_happened','why_it_matters','what_we_know','what_we_dont_know','timeline','sources','corrections','single_source_label']
 or p_content->lang->>'single_source_label' is distinct from (case when lang='zh' then '单一来源、持续核验中' else 'Single source; verification ongoing' end) then return false; end if;
 foreach section in array array['title','what_happened','why_it_matters','what_we_know','what_we_dont_know','timeline','sources','corrections'] loop
 if jsonb_typeof(p_content->lang->section)<>'array' or jsonb_array_length(p_content->lang->section) not between 0 and 20
 or (section='what_happened' and jsonb_array_length(p_content->lang->section)=0)
 or (section='title' and jsonb_array_length(p_content->lang->section)<>1) then return false; end if;
 for row in select value from jsonb_array_elements(p_content->lang->section) loop
 if jsonb_typeof(row)<>'object' or (select count(*) from jsonb_object_keys(row))<>2
 or not row ?& array['text','claim_ids'] or jsonb_typeof(row->'text')<>'string' or length(trim(row->>'text')) not between 1 and 4000
 or jsonb_typeof(row->'claim_ids')<>'array' or jsonb_array_length(row->'claim_ids') not between 0 and 20 then return false; end if;
 for cid in select jsonb_array_elements_text(row->'claim_ids') loop
 -- A located quote is not factual verification; never update claim status.
 if not exists(select 1 from public.claims c join public.claim_evidence e on e.claim_id=c.id
 where c.id=cid::uuid and e.article_id=article and e.relation='supports'
 and length(trim(e.evidence_reference))>0 and position(e.evidence_reference in body_text)>0) then return false; end if;
 end loop;
 end loop;
 end loop;
 end loop;
 return true;
exception when others then return false;
end $$;



CREATE FUNCTION public.article_full_public_grant_live(p_grant bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select exists(select 1 from public.article_full_public_grants g
 join public.article_editor_revision_receipts er on er.id=g.revision_id
 join public.article_full_drafts d on d.id=er.draft_id join public.article_body_receipts br on br.id=d.snapshot_id
 join public.articles a on a.id=br.article_id
 join lateral (select * from public.source_policies where source_id=a.source_id order by version desc limit 1) policy on true
 where g.id=p_grant and g.allowed and g.expires_at>statement_timestamp() and g.policy_id=policy.id
 and public.article_editor_revision_live(er.id) and policy.policy_status='approved' and policy.access_allowed
 and policy.display_allowed and policy.story_publication_allowed and policy.source_display_allowed and policy.link_display_allowed
 and policy.fulltext_storage_allowed and policy.permitted_region='global'
 and policy.reviewed_by is not null and policy.reviewed_at is not null and length(trim(policy.attribution_requirements))>0
 and jsonb_typeof(policy.policy_evidence)='object' and policy.policy_evidence<>'{}'::jsonb
 and (policy.permission_expires_at is null or policy.permission_expires_at>statement_timestamp())
 and not exists(select 1 from public.article_full_public_grants newer where newer.revision_id=g.revision_id and newer.id>g.id))
$$;



CREATE FUNCTION public.article_get_robot_prompts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result jsonb;
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 select jsonb_object_agg(robot,jsonb_build_object('prompt',prompt,'version',version)) into result
 from (select distinct on (robot) robot,prompt,version from public.robot_prompt_versions order by robot,version desc) p;
 return result;
end $$;



CREATE FUNCTION public.article_prepare_candidate_evidence(p_snapshot uuid, p_job uuid, p_quotes text[]) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare receipt public.article_body_receipts%rowtype; body_text text; actor uuid; title_text text; quote text; story uuid;
 revision uuid; claim uuid; claim_ids uuid[]:='{}'; quote_hash text; old_batch public.article_candidate_evidence_batches%rowtype;
begin
 actor:=public.article_runtime_actor();
 if actor is null or current_setting('transaction_isolation')<>'read committed' then raise exception 'authorized runtime actor required'; end if;
 if p_snapshot is null or p_job is null or p_quotes is null or cardinality(p_quotes) not between 1 and 8
  or (select count(distinct q) from unnest(p_quotes) q)<>cardinality(p_quotes)
 then raise exception 'invalid candidate evidence'; end if;
 select * into receipt from public.article_body_receipts where id=p_snapshot;
 if receipt.id is null or not public.article_body_available(p_snapshot) then raise exception 'snapshot unavailable'; end if;
 select story_id into story from public.ai_processing_jobs where id=p_job and article_id=receipt.article_id and task_type='full_article.v1';
 if story is null then raise exception 'full article job/story scope mismatch'; end if;
 perform public.article_body_scope(receipt.article_id,receipt.region,array['store','editor_display']);
 perform 1 from public.stories where id=story and visibility='hidden' for update;
 if not found or not exists(select 1 from public.story_articles where story_id=story and article_id=receipt.article_id)
 then raise exception 'hidden story/article association required'; end if;
 select b.body,a.title into body_text,title_text from public.article_body_snapshots b
 join public.articles a on a.id=receipt.article_id where b.id=p_snapshot;
 if title_text is null or length(trim(title_text))=0 then raise exception 'source title unavailable'; end if;
 foreach quote in array p_quotes loop
  if quote is null or length(trim(quote)) not between 20 and 500 or quote<>trim(quote) or position(quote in body_text)=0
  then raise exception 'candidate evidence quote unavailable'; end if;
 end loop;
 quote_hash:=encode(sha256(convert_to(array_to_json(p_quotes)::text,'UTF8')),'hex');
 select * into old_batch from public.article_candidate_evidence_batches where snapshot_id=p_snapshot and story_id=story;
 if old_batch.snapshot_id is not null then
  if old_batch.quote_hash is distinct from quote_hash then raise exception 'candidate evidence batch conflict'; end if;
  return old_batch.claim_ids;
 end if;
 insert into public.story_revisions(story_id,revision_number,title,summary,created_by)
 values(story,(select coalesce(max(revision_number),0)+1 from public.story_revisions where story_id=story),
   left(title_text,1000),'Source-linked candidate evidence; not yet fact-checked.',actor) returning id into revision;
 foreach quote in array p_quotes loop
  insert into public.claims(revision_id,claim_text,status) values(revision,quote,'unverified') returning id into claim;
  insert into public.claim_evidence(claim_id,article_id,relation,evidence_reference) values(claim,receipt.article_id,'supports',quote);
  claim_ids:=array_append(claim_ids,claim);
 end loop;
 insert into public.article_candidate_evidence_batches(snapshot_id,story_id,revision_id,quote_hash,claim_ids)
 values(p_snapshot,story,revision,quote_hash,claim_ids);
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(actor,'create_candidate_evidence','story',story,'Automated source excerpts, unverified; editorial review required');
 return claim_ids;
end $$;



CREATE FUNCTION public.article_recent_published_titles() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 return coalesce((select array_agg(q.title order by q.published_at desc) from (
   select * from (
    select r.en_title title,max(e.created_at) published_at from public.manual_articles a
    join public.manual_article_revisions r on r.id=a.published_revision_id
    join public.manual_publication_events e on e.article_id=a.id and e.action in ('publish','update','correction')
    where a.status='published' and e.created_at>clock_timestamp()-interval '7 days' group by r.en_title
    union all
    select d.content->'en'->'title'->0->>'text',d.created_at from public.article_full_drafts d
    where d.expires_at>clock_timestamp() and not exists(select 1 from public.ai_article_publications p where p.draft_id=d.id)
   ) candidates where title is not null order by published_at desc limit 100) q),'{}'::text[]);
end $$;



CREATE FUNCTION public.article_record_execution(p_request uuid, p_model text, p_input bigint, p_output bigint, p_cached bigint, p_total bigint, p_outcome text, p_latency integer) RETURNS TABLE(status text, triggered_halt boolean, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if public.article_runtime_actor() is null or not exists(select 1 from public.article_body_requests where request_id=p_request) then raise exception 'body runtime request required'; end if;
 return query select * from public.ai_record_bounded_execution(p_request,p_model,p_input,p_output,p_cached,p_total,p_outcome,p_latency);
end $$;



CREATE FUNCTION public.article_record_selection(p_job uuid, p_provider text, p_model text, p_result jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare decision text; score integer; context jsonb;
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 context:=public.article_selection_context(p_job);
 decision:=p_result->>'decision'; score:=(p_result->>'score')::integer;
 if p_provider is distinct from 'deepseek' or p_model is distinct from 'deepseek-flash'
 or decision not in ('SELECT','REJECT','HOLD') or score not between 0 and 100
 or p_result->'source' is distinct from jsonb_build_object('name',context->>'name','title',context->>'title','url',context->>'url')
 then raise exception 'invalid selection result'; end if;
 insert into public.article_selection_decisions(job_id,provider,model,decision,score,result)
 values(p_job,p_provider,p_model,decision,score,p_result);
end $$;



CREATE FUNCTION public.article_revision_batch_matches(p_revision uuid, p_batch uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.story_bilingual_batches%rowtype; ctx public.article_body_request_context%rowtype;
 content jsonb; sid uuid; request uuid; locale text; rid uuid; claim uuid; title_text text;
begin
 if not public.article_editor_revision_live(p_revision) then return false; end if;
 select * into b from public.story_bilingual_batches where id=p_batch;
 select ec.content,q.story_id,d.request_id into content,sid,request
 from public.article_editor_revision_receipts er join public.article_editor_revision_content ec on ec.id=er.id
 join public.article_full_drafts d on d.id=er.draft_id join public.article_full_review_queue q on q.draft_id=d.id
 where er.id=p_revision;
 select * into ctx from public.article_body_request_context where request_id=request;
 if b.id is null or sid is distinct from b.story_id or not public.bilingual_batch_evidence_gate(b.id) then return false; end if;
 foreach locale in array array['zh','en'] loop
 rid:=(case when locale='zh' then b.zh_revision_id else b.en_revision_id end);
 select string_agg(value->>'text',E'\n' order by ord) into title_text from jsonb_array_elements(content->locale->'title') with ordinality t(value,ord);
 -- Existing public summaries are independently authored/reviewed metadata.
 -- Never copy full section B into a non-expiring legacy revision here.
 if not exists(select 1 from public.story_revisions where id=rid and title=title_text) then return false; end if;
 foreach claim in array ctx.claim_ids loop
 if not exists(select 1 from public.claims translated join public.claim_evidence te on te.claim_id=translated.id
 join public.claim_evidence original on original.article_id=te.article_id and original.evidence_reference=te.evidence_reference
 where translated.revision_id=rid and translated.status='verified' and original.claim_id=claim
 and te.relation='supports' and original.relation='supports' and te.verified_by is not null and te.verified_at is not null
 and original.verified_by is not null and original.verified_at is not null) then return false; end if;
 end loop;
 end loop;
 return true;
end $$;



CREATE FUNCTION public.article_runtime_actor() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
 select case when session_user='newsroom_article_worker' then
 (select p.actor_id from public.article_runtime_principals p join public.editors e on e.user_id=p.actor_id
 join auth.users u on u.id=e.user_id where p.role_name=session_user and p.expires_at>statement_timestamp()
 and e.active and u.deleted_at is null and (u.banned_until is null or u.banned_until<=statement_timestamp()))
 when session_user='authenticator' and public.is_active_editor() then auth.uid() else null end
$$;



CREATE FUNCTION public.article_selection_context(p_job uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare output jsonb;
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 select jsonb_build_object('name',s.name,'title',a.title,'url',a.canonical_url,
   'previous_titles',to_jsonb(public.article_recent_published_titles())) into output
 from public.article_auto_tasks t join public.articles a on a.id=t.article_id
 join public.sources s on s.id=a.source_id where t.job_id=p_job and t.status='running';
 if output is null then raise exception 'running task unavailable'; end if;
 return output;
end $$;



CREATE FUNCTION public.article_stage_accessible(p_request uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select exists(select 1 from public.article_body_requests r join public.article_body_request_context c on c.request_id=r.request_id
 where r.request_id=p_request and c.stage in ('summary','draft') and public.article_body_available(r.snapshot_id)
 and public.article_claimset_current(r.snapshot_id,c.claim_ids,c.claims_sha256)
 and not exists(select 1 from unnest(r.grant_ids) gid where not public.article_body_grant_live(gid))
 and (c.stage='summary' or (public.article_summary_available(c.summary_id) and exists(
 select 1 from public.article_body_summary_receipts sr join public.article_body_request_context sc on sc.request_id=sr.request_id
 where sr.id=c.summary_id and sr.snapshot_id=r.snapshot_id and sr.content_sha256=c.summary_content_sha256
 and sc.claims_sha256=c.claims_sha256))))
$$;



CREATE FUNCTION public.article_store_body(p_id uuid, p_article uuid, p_region text, p_url text, p_fetched timestamp with time zone, p_body text, p_expires timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare ids uuid[]; pid uuid;
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 ids:=public.article_body_scope(p_article,p_region,array['fetch','store','editor_display']);
 if p_id is null or p_body is null or length(trim(p_body))=0 or p_url is null or p_url !~ '^https://'
 or p_url is distinct from (select canonical_url from public.articles where id=p_article)
 or p_fetched is null or p_fetched<(select max(reviewed_at) from public.article_body_grants where id=any(ids)) or p_fetched>clock_timestamp() or p_fetched<clock_timestamp()-interval '5 minutes'
 or p_expires is null or p_expires<=clock_timestamp() or p_expires>clock_timestamp()+interval '7 days'
 or p_expires>(select min(expires_at) from public.article_body_grants where id=any(ids)) then raise exception 'invalid body snapshot'; end if;
 perform 1 from public.article_body_retention_control where singleton and not restore_quarantine
 for update;
 if not found then raise exception 'body retention unavailable'; end if;
 select policy_id into pid from public.article_body_grants where id=ids[1];
 insert into public.article_body_receipts(id,article_id,policy_id,grant_ids,region,fetched_at,original_url,body_sha256)
 values(p_id,p_article,pid,ids,p_region,p_fetched,p_url,encode(sha256(convert_to(p_body,'UTF8')),'hex'));
 insert into public.article_body_snapshots(id,body,expires_at) values(p_id,p_body,p_expires);
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(public.article_runtime_actor(),'store_article_body','article',p_article,'Authorized text-only snapshot; no source images');
 return p_id;
end $$;



CREATE FUNCTION public.article_store_body_summary(p_request uuid, p_snapshot uuid, p_content jsonb, p_expires timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare r public.article_body_receipts%rowtype; req public.article_body_requests%rowtype; ctx public.article_body_request_context%rowtype; result uuid; facts jsonb;
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 select * into r from public.article_body_receipts where id=p_snapshot;
 perform public.article_body_scope(r.article_id,r.region,array['process_summary_deepseek','store_summary','display_summary']);
 select * into req from public.article_body_requests where request_id=p_request and snapshot_id=p_snapshot;
 select * into ctx from public.article_body_request_context where request_id=p_request and stage='summary';
 if ctx.request_id is null or req.request_id is null or not public.article_stage_accessible(p_request)
 or not public.article_valid_body_summary(p_request,p_content) or p_expires is null or p_expires<=clock_timestamp()
 or p_expires>(select expires_at from public.article_body_snapshots where id=p_snapshot)
 or p_expires>(select min(expires_at) from public.article_body_grants where id=any(req.grant_ids)) then raise exception 'summary scope or retention unavailable'; end if;
 facts:=public.article_body_claims(p_snapshot,ctx.claim_ids);
 if encode(sha256(convert_to(facts::text,'UTF8')),'hex') is distinct from ctx.claims_sha256 then raise exception 'summary claims changed'; end if;
 if not exists(select 1 from public.ai_request_preparations p join public.ai_execution_observations e on e.request_id=p.request_id
 where p.request_id=p_request and p.processor='deepseek' and p.processing_region=r.region
 and e.observed_model='deepseek-flash'
 and coalesce(p.requested_model,(select b.model_id from public.ai_budget_reservations b where b.request_id=p_request))='deepseek-flash'
 and e.outcome='ok' and e.prompt_version='body_summary_context.v1' and e.schema_version='summary_proposal.v1'
 and e.created_at>clock_timestamp()-interval '5 minutes') then raise exception 'successful Flash execution unavailable'; end if;
 result:=gen_random_uuid();
 insert into public.article_body_summary_receipts(id,request_id,snapshot_id,content_sha256)
 values(result,p_request,p_snapshot,encode(sha256(convert_to(p_content::text,'UTF8')),'hex'));
 insert into public.article_body_summaries values(result,p_content,p_expires);
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(public.article_runtime_actor(),'store_flash_body_summary','article_body_summary',result,'Machine summary, not verified new facts or publication');
 return result;
end $$;



CREATE FUNCTION public.article_store_full_draft(p_request uuid, p_snapshot uuid, p_content jsonb, p_expires timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare ctx public.article_body_request_context%rowtype; facts jsonb; result uuid; sid uuid; lang text; section text; row jsonb; cid text;
begin
 select * into ctx from public.article_body_request_context where request_id=p_request;
 if ctx.request_id is null then raise exception 'body request unavailable'; end if;
 facts:=public.article_body_claims(p_snapshot,ctx.claim_ids);
 if encode(sha256(convert_to(facts::text,'UTF8')),'hex') is distinct from ctx.claims_sha256 then raise exception 'reviewed claims changed'; end if;
 if not public.article_full_draft_valid(p_snapshot,p_content) then raise exception 'invalid full draft'; end if;
 foreach lang in array array['zh','en'] loop
 foreach section in array array['title','what_happened','why_it_matters','what_we_know','what_we_dont_know','timeline','sources','corrections'] loop
 for row in select value from jsonb_array_elements(p_content->lang->section) loop
 for cid in select jsonb_array_elements_text(row->'claim_ids') loop
 if not cid::uuid=any(ctx.claim_ids) then raise exception 'claim outside checked request'; end if;
 end loop; end loop; end loop; end loop;
 select j.story_id into sid from public.ai_request_identities r join public.ai_processing_jobs j on j.id=r.job_id where r.request_id=p_request;
 if sid is null or not exists(select 1 from public.story_articles sa join public.article_body_receipts r on r.article_id=sa.article_id where sa.story_id=sid and r.id=p_snapshot) then raise exception 'draft story/article mismatch'; end if;
 result:=public.article_store_full_draft_before_context(p_request,p_snapshot,p_content,p_expires);
 insert into public.article_full_review_queue(draft_id,story_id,imported_by) values(result,sid,public.article_runtime_actor());
 return result;
end $$;



CREATE FUNCTION public.article_store_full_draft_before_context(p_request uuid, p_snapshot uuid, p_content jsonb, p_expires timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare r public.article_body_receipts%rowtype; ids uuid[]; bound_ids uuid[]; result uuid;
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 select * into r from public.article_body_receipts where id=p_snapshot;
 ids:=public.article_body_scope(r.article_id,r.region,array['process_deepseek','store_draft','display_draft']);
 select grant_ids into bound_ids from public.article_body_requests where request_id=p_request and snapshot_id=p_snapshot;
 if not public.article_stage_accessible(p_request) or not exists(select 1 from public.article_body_request_context where request_id=p_request and stage='draft') or bound_ids is null or exists(select 1 from unnest(bound_ids) gid where not public.article_body_grant_live(gid))
 or exists(select 1 from unnest(bound_ids) gid where not exists(select 1 from public.article_body_grants g where g.id=gid
   and g.article_id=r.article_id and g.region=r.region and g.action in ('process_deepseek','store_draft','display_draft')))
 or (select count(distinct action) from public.article_body_grants where id=any(bound_ids))<>3
 or not public.article_body_available(p_snapshot) or not public.article_full_draft_valid(p_snapshot,p_content)
 or p_expires is null or p_expires<=clock_timestamp()
 or p_expires>(select expires_at from public.article_body_snapshots where id=p_snapshot)
 or p_expires>(select min(expires_at) from public.article_body_grants where id=any(bound_ids))
 or p_expires>(select s.expires_at from public.article_body_request_context c join public.article_body_summaries s on s.id=c.summary_id where c.request_id=p_request)
 or p_expires>(select min(g.expires_at) from public.article_body_request_context c join public.article_body_summary_receipts sr on sr.id=c.summary_id join public.article_body_requests rq on rq.request_id=sr.request_id join public.article_body_grants g on g.id=any(rq.grant_ids) where c.request_id=p_request)
 or not exists(select 1 from public.ai_request_preparations p join public.ai_execution_observations e on e.request_id=p.request_id
 where p.request_id=p_request and p.processor='deepseek' and p.processing_region=r.region
 and e.observed_model='deepseek-v4-pro'
 and coalesce(p.requested_model,(select b.model_id from public.ai_budget_reservations b where b.request_id=p_request))='deepseek-v4-pro'
 and e.outcome='ok' and e.prompt_version='full_article_context.v2' and e.schema_version='full_article.v1'
 and e.created_at>clock_timestamp()-interval '5 minutes')
 then raise exception 'full draft provenance or permissions unavailable'; end if;
 result:=gen_random_uuid();
 insert into public.article_full_draft_receipts(id,request_id,snapshot_id) values(result,p_request,p_snapshot);
 insert into public.article_full_drafts(id,request_id,snapshot_id,content,expires_at) values(result,p_request,p_snapshot,p_content,p_expires);
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(public.article_runtime_actor(),'store_full_article_draft','article',r.article_id,'Bilingual A-H; pending factual, originality and language review; not published');
 return result;
end $$;



CREATE FUNCTION public.article_summary_available(p_summary uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select exists(select 1 from public.article_body_summaries s join public.article_body_summary_receipts sr on sr.id=s.id
 join public.article_body_requests r on r.request_id=sr.request_id
 join public.article_body_request_context c on c.request_id=r.request_id and c.stage='summary'
 where s.id=p_summary and s.expires_at>statement_timestamp() and public.article_body_available(sr.snapshot_id)
 and public.article_claimset_current(sr.snapshot_id,c.claim_ids,c.claims_sha256)
 and sr.content_sha256=encode(sha256(convert_to(s.content::text,'UTF8')),'hex')
 and not exists(select 1 from unnest(r.grant_ids) gid where not public.article_body_grant_live(gid)))
$$;



CREATE FUNCTION public.article_sweep_bodies(p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare n integer; m integer; k integer; revisions integer;
begin
 if public.article_runtime_actor() is null then raise exception 'authorized runtime actor required'; end if;
 if p_limit is null or p_limit not between 1 and 1000 then raise exception 'invalid limit'; end if;
 perform 1 from public.article_body_retention_control where singleton for update;
 -- Revisions share the existing p_limit draft-family cap; no extra deletion allowance.
 delete from public.article_editor_revision_content where id in (
 select c.id from public.article_editor_revision_content c join public.article_editor_revision_receipts er on er.id=c.id
 left join public.article_full_drafts d on d.id=er.draft_id
 where c.expires_at<=clock_timestamp() or d.id is null or d.expires_at<=clock_timestamp()
 or not public.article_stage_accessible(d.request_id) limit p_limit);
 get diagnostics revisions=row_count;
 -- During restore quarantine nothing is accessible. This conservative sweep
 -- deletes restored content rather than re-authorizing old grants or receipts.
 delete from public.article_full_drafts where id in (select d.id from public.article_full_drafts d
 join public.article_body_requests r on r.request_id=d.request_id where d.expires_at<=clock_timestamp()
 or not public.article_stage_accessible(d.request_id)
 or exists(select 1 from unnest(r.grant_ids) gid where not public.article_body_grant_live(gid)) limit greatest(p_limit-revisions,0));
 get diagnostics n=row_count;
 delete from public.article_body_summaries where id in (select id from public.article_body_summaries where not public.article_summary_available(id) limit p_limit);
 get diagnostics k=row_count;
 delete from public.article_body_snapshots where id in (select id from public.article_body_snapshots
 where not public.article_body_available(id) limit p_limit);
 get diagnostics m=row_count;
 update public.article_body_retention_control set last_sweep_at=clock_timestamp() where singleton;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(public.article_runtime_actor(),'sweep_article_bodies','retention',gen_random_uuid(),'Deleted expired/revoked/quarantined text and AI/editor drafts within shared draft cap; immutable receipts retained');
 return n+m+k+revisions;
end $$;



CREATE FUNCTION public.article_url_identity(p_url text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
declare parts text[]; authority text; host_parts text[]; host text; tail text; port_text text; port_clean text; port_value integer; path text; query_text text; closing integer;
begin
  if length(p_url) > 2048 or p_url ~ '[[:space:][:cntrl:]]' or position(chr(92) in p_url) > 0 then
    raise exception using errcode='22023', message='unsupported or invalid article URL';
  end if;
  parts := regexp_match(p_url, '^[Hh][Tt][Tt][Pp][Ss]://([^/?#]+)([^?#]*)([?][^#]*)?(#.*)?$');
  if parts is null then raise exception using errcode='22023', message='unsupported or invalid article URL'; end if;
  authority := parts[1];
  if left(authority,1) = '[' then
    closing := position(']' in authority);
    if closing < 3 then raise exception using errcode='22023', message='unsupported or invalid article URL'; end if;
    host := substring(authority from 2 for closing-2);
    tail := substring(authority from closing+1);
    if host !~ '^[0-9A-Fa-f:.]+$' or (tail <> '' and tail !~ '^:[0-9]*$') then
      raise exception using errcode='22023', message='unsupported or invalid article URL';
    end if;
    begin
      if family(host::inet) <> 6 then raise exception using errcode='22023', message='unsupported or invalid article URL'; end if;
    exception when invalid_text_representation then
      raise exception using errcode='22023', message='unsupported or invalid article URL';
    end;
    host := '[' || lower(host collate "C") || ']';
    port_text := substring(tail from 2);
  else
    host_parts := regexp_match(authority, '^([A-Za-z0-9.-]+)(:([0-9]*))?$');
    if host_parts is null or length(host_parts[1]) > 253 then raise exception using errcode='22023', message='unsupported or invalid article URL'; end if;
    host := lower(host_parts[1] collate "C");
    port_text := host_parts[3];
  end if;
  if coalesce(port_text, '') <> '' then
    port_clean := ltrim(port_text, '0');
    if port_clean = '' then port_clean := '0'; end if;
    if length(port_clean) > 5 then raise exception using errcode='22023', message='unsupported or invalid article URL'; end if;
    port_value := port_clean::integer;
    if port_value > 65535 then raise exception using errcode='22023', message='unsupported or invalid article URL'; end if;
    if port_value <> 443 then host := host || ':' || port_value::text; end if;
  end if;
  path := case when parts[2] = '' then '/' else parts[2] end;
  query_text := case when parts[3] is null or parts[3] = '?' then '' else parts[3] end;
  return 'https://' || host || path || query_text;
end $_$;



CREATE FUNCTION public.article_valid_body_summary(p_request uuid, p_content jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare item jsonb; items jsonb; cid text; ids uuid[];
begin
 select claim_ids into ids from public.article_body_request_context where request_id=p_request and stage='summary';
 if ids is null or p_content is null or jsonb_typeof(p_content)<>'object' or octet_length(p_content::text)>32768
 or not p_content ?& array['schema_version','headline','summary','why_it_matters'] or (select count(*) from jsonb_object_keys(p_content))<>4
 or p_content->>'schema_version'<>'summary_proposal.v1' or jsonb_typeof(p_content->'headline')<>'object'
 or jsonb_typeof(p_content->'summary')<>'array' or jsonb_typeof(p_content->'why_it_matters')<>'array'
 or jsonb_array_length(p_content->'summary') not between 1 and 4 or jsonb_array_length(p_content->'why_it_matters') not between 1 and 3 then return false; end if;
 items:=jsonb_build_array(p_content->'headline')||(p_content->'summary')||(p_content->'why_it_matters');
 for item in select value from jsonb_array_elements(items) loop
 if jsonb_typeof(item)<>'object' or not item ?& array['text','claim_ids'] or (select count(*) from jsonb_object_keys(item))<>2
 or jsonb_typeof(item->'text')<>'string' or length(trim(item->>'text')) not between 1 and 500
 or jsonb_typeof(item->'claim_ids')<>'array' or jsonb_array_length(item->'claim_ids') not between 1 and 5
 or (select count(distinct value) from jsonb_array_elements_text(item->'claim_ids'))<>jsonb_array_length(item->'claim_ids') then return false; end if;
 for cid in select jsonb_array_elements_text(item->'claim_ids') loop
 if not cid::uuid=any(ids) then return false; end if;
 end loop; end loop;
 return true;
exception when others then return false;
end $$;



CREATE FUNCTION public.article_validate_fetch_recovery() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare original public.article_body_dispatches%rowtype; checked_at timestamptz;
begin
 -- No callable recovery RPC or runtime grant: insertion requires administrator table access.
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
 perform 1 from public.article_body_retention_control where singleton for update;
 perform pg_advisory_xact_lock(hashtextextended('article-body-nist',903514));
 lock table public.article_body_dispatches,public.article_body_receipts,public.article_body_snapshots,
 public.article_body_summaries,public.article_full_drafts,public.article_body_requests,
 public.ai_request_preparations,public.ai_budget_reservations,public.ai_usage_observations
 in share row exclusive mode;
 select * into original from public.article_body_dispatches where id=new.original_dispatch_id;
 if original.id is null or original.snapshot_id is not null
 or original.outcome='stored' or (original.outcome is not null and original.outcome<>'held') then
 raise exception 'unresolved failed dispatch required'; end if;
 if exists(select 1 from public.article_body_dispatches where id=new.successor_dispatch_id)
 or exists(select 1 from public.article_body_dispatches where id<>original.id
   and (finished_at is null or outcome is distinct from 'stored')
   and not exists(select 1 from public.article_body_fetch_recoveries r where r.original_dispatch_id=article_body_dispatches.id)) then
 raise exception 'other unresolved dispatch or existing successor'; end if;
 if exists(select 1 from public.article_body_receipts)
 or exists(select 1 from public.article_body_snapshots)
 or exists(select 1 from public.article_body_summaries)
 or exists(select 1 from public.article_full_drafts)
 or exists(select 1 from public.article_body_requests)
 or exists(select 1 from public.ai_request_preparations)
 or exists(select 1 from public.ai_budget_reservations)
 or exists(select 1 from public.ai_usage_observations) then
 raise exception 'zero snapshot receipts and AI accounting required'; end if;
 checked_at:=clock_timestamp();
 if new.processes_ended_verified_at<original.started_at
 or new.processes_ended_verified_at>checked_at
 or new.retry_not_before<new.processes_ended_verified_at+interval '10 minutes'
 or new.retry_expires_at<=greatest(checked_at,new.retry_not_before)
 or new.retry_expires_at>greatest(checked_at,new.retry_not_before)+interval '1 hour' then
 raise exception 'verified termination and bounded ten-minute cooldown required'; end if;
 new.recorded_at:=checked_at;
 new.recorded_by:=session_user;
 -- Preserve unknown failure cause, original NULL fields, and all old receipts.
 -- This append-only row IS the administrator audit record. audit_logs.actor_id
 -- requires a real editor UUID; never fabricate an editor identity for an SQL operator.
 return new;
end $$;



CREATE FUNCTION public.bilingual_batch_evidence_gate(p_batch uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select coalesce((select public.revision_eligible_before_archive(b.story_id,b.zh_revision_id)
   and public.revision_eligible_before_archive(b.story_id,b.en_revision_id)
   and exists(select 1 from public.stories s where s.id=b.story_id and s.archived_at is null)
 from public.story_bilingual_batches b where b.id=p_batch),false)
$$;



CREATE FUNCTION public.bilingual_channel_publication_ready(p_batch uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select not public.editorial_channel_rollout_enabled() or coalesce((
    select r.decision='approved' and exists(select 1 from public.bilingual_review_channel_bindings x
      join public.bilingual_channel_assignments a on a.id=x.assignment_id
      where x.review_id=r.id and a.batch_id=r.batch_id)
    from public.bilingual_editorial_reviews r where r.batch_id=p_batch order by r.id desc limit 1),false)
$$;



CREATE FUNCTION public.bilingual_reviewed_primary_channel(p_batch uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select a.primary_channel from public.bilingual_editorial_reviews r
  join public.bilingual_review_channel_bindings x on x.review_id=r.id
  join public.bilingual_channel_assignments a on a.id=x.assignment_id and a.batch_id=r.batch_id
  where r.batch_id=p_batch and r.decision='approved'
    and r.id=(select max(last_review.id) from public.bilingual_editorial_reviews last_review where last_review.batch_id=p_batch)
$$;



CREATE FUNCTION public.bilingual_rollout_enabled() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce((select enabled from public.bilingual_rollout_settings where singleton),false)
$$;



CREATE FUNCTION public.bind_bilingual_review_channels() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare n integer; active boolean;
begin
  active:=public.lock_editorial_channel_rollout();
  insert into public.bilingual_review_channel_bindings(review_id,assignment_id)
    select new.id,a.id from public.bilingual_channel_assignments a where a.batch_id=new.batch_id order by a.id desc limit 1;
  get diagnostics n=row_count;
  if new.decision='approved' and active and n<>1 then raise exception 'primary editorial channel required'; end if;
  return new;
end $$;



CREATE FUNCTION public.candidate_title_allowed(p_article uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce((select a.title is not null and p.policy_status = 'approved' and p.title_storage_allowed and p.display_allowed
      and p.reviewed_by is not null and p.reviewed_at is not null and jsonb_typeof(p.policy_evidence) = 'object'
      and p.policy_evidence <> '{}'::jsonb and (p.permission_expires_at is null or p.permission_expires_at > clock_timestamp())
    from public.articles a join lateral (select * from public.source_policies sp where sp.source_id = a.source_id order by sp.version desc limit 1) p on true
    where a.id = p_article), false)
$$;



CREATE FUNCTION public.check_ai_review_input_expiry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if exists(select 1 from public.ai_request_preparation_inputs x join public.source_policies p on p.id=x.policy_id
    join public.ai_provider_title_grants g on g.id=x.provider_grant_id where x.request_id=new.request_id
    and ((p.permission_expires_at is not null and p.permission_expires_at<=clock_timestamp())
      or (g.expires_at is not null and g.expires_at<=clock_timestamp()))) then
    raise exception 'input permission expired during review'; end if;
  return new;
end $$;


SET default_tablespace = '';

SET default_table_access_method = heap;


CREATE TABLE public.classification_proposals (
    id uuid NOT NULL,
    article_id uuid NOT NULL,
    category_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    provider_grant_id uuid NOT NULL,
    provider text NOT NULL,
    region text NOT NULL,
    title_sha256 text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_by uuid NOT NULL,
    origin text DEFAULT 'manual_import_unverified'::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT classification_proposals_origin_check CHECK ((origin = 'manual_import_unverified'::text))
);



CREATE FUNCTION public.classification_visible(p public.classification_proposals) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select p.expires_at>statement_timestamp() and exists(select 1 from public.classification_retention_control where singleton and not restore_quarantine) and exists(
    select 1 from public.articles a join public.categories c on c.id=p.category_id and c.active
    join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) pol on true
    join public.ai_provider_title_grants tg on tg.id=p.provider_grant_id and tg.policy_id=pol.id and tg.provider=p.provider and tg.processing_region=p.region
    where a.id=p.article_id and pol.id=p.policy_id and pol.policy_status='approved' and pol.ai_processing_allowed and pol.title_storage_allowed
      and pol.reviewed_by is not null and pol.reviewed_at is not null and pol.policy_evidence<>'{}'::jsonb
      and (pol.permission_expires_at is null or pol.permission_expires_at>statement_timestamp())
      and (tg.expires_at is null or tg.expires_at>statement_timestamp())
      and not exists(select 1 from public.ai_provider_title_revocations tr where tr.grant_id=tg.id)
      and encode(sha256(convert_to(a.title,'UTF8')),'hex')=p.title_sha256
      and (select count(distinct g.action) from public.classification_grants g where g.policy_id=pol.id and g.provider=p.provider and g.region=p.region
        and g.action in ('store','editor_display') and g.expires_at>statement_timestamp()
        and not exists(select 1 from public.classification_grant_revocations r where r.grant_id=g.id))=2
      and (not exists(select 1 from public.classification_model_receipts r where r.proposal_id=p.id)
        or exists(select 1 from public.classification_model_receipts mr join public.classification_processing_grants g
          on g.policy_id=pol.id and g.provider=p.provider and g.region=p.region
          where mr.proposal_id=p.id and g.expires_at>statement_timestamp()
            and not exists(select 1 from public.classification_processing_revocations r where r.grant_id=g.id)
            and exists(select 1 from public.classification_request_categories x where x.request_id=mr.request_id and x.category_id=p.category_id)
            and not exists(select 1 from public.classification_request_categories x join public.categories cc on cc.id=x.category_id
              where x.request_id=mr.request_id and (not cc.active or x.name_sha256<>encode(sha256(convert_to(cc.name,'UTF8')),'hex')))))
  )
$$;



CREATE FUNCTION public.duty_editor_create_draft(p_bot text, p_request text, p_hash text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare owner_uuid uuid; aid uuid; rid uuid; old public.duty_editor_submissions%rowtype; s jsonb; z jsonb; e jsonb; ch text; tp text; src jsonb; t timestamptz;
begin
 if p_bot is null or p_bot !~ '^[a-z0-9][a-z0-9_-]{0,63}$' or p_request is null or p_request !~ '^[A-Za-z0-9._-]{1,128}$' or p_hash is null or p_hash !~ '^[0-9a-f]{64}$' or jsonb_typeof(p_payload)<>'object' then raise exception 'invalid submission'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_bot||':'||p_request,932));
 select * into old from public.duty_editor_submissions where bot_id=p_bot and request_id=p_request;
 if found then
  if old.payload_hash<>p_hash then raise exception 'idempotency conflict'; end if;
  return jsonb_build_object('article_id',old.article_id,'slug',(select slug from public.manual_articles where id=old.article_id),'status',(select status from public.manual_articles where id=old.article_id),'duplicate',true);
 end if;
 select o.user_id into owner_uuid from public.manual_editor_owners o join auth.users u on u.id=o.user_id where o.enabled and u.deleted_at is null;
 if owner_uuid is null then raise exception 'owner unavailable'; end if;
 z:=p_payload->'zh'; e:=p_payload->'en'; ch:=p_payload->>'channel'; tp:=p_payload->>'topic'; src:=p_payload->'sources';
 if p_payload->>'slug' is null or p_payload->>'slug' !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or length(p_payload->>'slug')>160
 or jsonb_typeof(z)<>'object' or jsonb_typeof(e)<>'object'
 or length(trim(coalesce(z->>'title',''))) not between 1 and 240 or length(trim(coalesce(e->>'title',''))) not between 1 and 240
 or length(trim(coalesce(z->>'summary',''))) not between 1 and 1000 or length(trim(coalesce(e->>'summary',''))) not between 1 and 1000
 or not public.manual_document_safe(z->'document') or not public.manual_document_safe(e->'document')
 or jsonb_path_exists(z->'document','$.** ? (@.type == "image" || @.type == "manualVideo" || @.type == "youtube")')
 or jsonb_path_exists(e->'document','$.** ? (@.type == "image" || @.type == "manualVideo" || @.type == "youtube")')
 or not exists(select 1 from public.manual_editor_topics where channel=ch and topic=tp)
 or jsonb_typeof(src)<>'array' or jsonb_array_length(src) not between 1 and 30 then raise exception 'invalid article'; end if;
 for s in select value from jsonb_array_elements(src) loop
  if coalesce(s->>'url','') !~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$' or length(coalesce(s->>'name','')) not between 1 and 300 then raise exception 'invalid source'; end if;
  begin t:=(s->>'published_at')::timestamptz; exception when others then raise exception 'invalid source timestamp'; end;

 end loop;
 insert into public.manual_articles(slug,owner_id) values(public.duty_editor_dated_slug(p_payload->>'slug',clock_timestamp()),owner_uuid) returning id into aid;
 insert into public.manual_article_revisions(article_id,revision_number,zh_title,en_title,zh_summary,en_summary,zh_document,en_document,primary_channel,related_channels,tags,source_links,created_by)
 values(aid,1,trim(z->>'title'),trim(e->>'title'),trim(z->>'summary'),trim(e->>'summary'),z->'document',e->'document',ch,'{}',array(select jsonb_array_elements_text(coalesce(p_payload->'tags','[]'::jsonb))),
 (select jsonb_agg(jsonb_build_object('url',x->>'url','label',x->>'name')) from jsonb_array_elements(src) x),owner_uuid) returning id into rid;
 insert into public.manual_revision_topics(revision_id,channel,topic) values(rid,ch,tp);
 update public.manual_articles set current_revision_id=rid where id=aid;
 insert into public.duty_editor_submissions(bot_id,request_id,payload_hash,article_id,source_publications) values(p_bot,p_request,p_hash,aid,src);
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(owner_uuid,'external_bot_draft','manual_article',aid,'Submitted by duty editor '||p_bot||'; awaiting owner review');
 return jsonb_build_object('article_id',aid,'slug',(select slug from public.manual_articles where id=aid),'revision_id',rid,'status','draft','duplicate',false);
end $_$;



CREATE FUNCTION public.duty_editor_dated_slug(p_slug text, p_created_at timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 select case
  when p_slug ~ '-[12][0-9]{3}(0[1-9]|1[0-2])(0[1-9]|[12][0-9]|3[01])$' then p_slug
  else rtrim(left(p_slug,151),'-') || '-' || to_char(p_created_at at time zone 'Asia/Shanghai','YYYYMMDD')
 end
$_$;



CREATE FUNCTION public.duty_editor_identify(p_hash text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
 select bot_id from public.duty_editor_identities where enabled and secret_hash=p_hash and p_hash ~ '^[0-9a-f]{64}$'
$_$;



CREATE FUNCTION public.duty_editor_submission_status(p_bot text, p_secret_hash text, p_request text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if not exists(select 1 from public.duty_editor_identities
               where bot_id=p_bot and secret_hash=p_secret_hash and enabled)
 then raise exception 'identity revoked'; end if;
 return (
   select jsonb_build_object(
     'request_id',s.request_id,'article_id',a.id,'revision_id',a.current_revision_id,
     'status',a.status,'slug',a.slug,'submitted_at',s.created_at)
   from public.duty_editor_submissions s
   join public.manual_articles a on a.id=s.article_id
   where s.bot_id=p_bot and s.request_id=p_request
 );
end $$;



CREATE FUNCTION public.duty_editor_submit(p_bot text, p_secret_hash text, p_request text, p_hash text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare outcome jsonb; grade integer; a public.manual_articles%rowtype; r public.manual_article_revisions%rowtype; why text;
begin
 perform 1 from public.duty_editor_identities where bot_id=p_bot and secret_hash=p_secret_hash and enabled for share;
 if not found then raise exception 'identity revoked'; end if;
 begin grade:=(p_payload->>'suggested_score')::integer; exception when others then raise exception 'invalid suggested score'; end;
 if grade is null or grade not between 0 and 100 or jsonb_typeof(p_payload->'suggested_score') is distinct from 'number' then raise exception 'invalid suggested score'; end if;
 outcome:=public.duty_editor_create_draft(p_bot,p_request,p_hash,p_payload);
 -- Replays report the current state, including retraction, without publishing again.
 if coalesce((outcome->>'duplicate')::boolean,false) then return outcome; end if;
 select * into a from public.manual_articles where id=(outcome->>'article_id')::uuid for update;
 select * into r from public.manual_article_revisions where id=a.current_revision_id and article_id=a.id;
 if a.status<>'draft' or r.id is null
  or not exists(select 1 from jsonb_path_query(r.zh_document,'$.** ? (@.type == "text")') n where length(trim(n->>'text'))>0)
  or not exists(select 1 from jsonb_path_query(r.en_document,'$.** ? (@.type == "text")') n where length(trim(n->>'text'))>0)
 then raise exception 'both language bodies required'; end if;
 update public.duty_editor_submissions set suggested_score=grade where article_id=a.id;
 why:='Automatically published submission from duty editor '||p_bot;
 insert into public.manual_publication_events(article_id,revision_id,final_score,action,reason,actor_id)
 values(a.id,r.id,grade,'publish',why,a.owner_id);
 update public.manual_articles set status='published',published_revision_id=r.id,updated_at=clock_timestamp() where id=a.id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(a.owner_id,'external_bot_publish','manual_article',a.id,why);
 return outcome || jsonb_build_object('status','published');
end $_$;



CREATE FUNCTION public.editor_ack_ai_incident(p_incident uuid, p_note text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare inserted_id uuid;
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI budget operator access required'; end if;
  if p_incident is null or p_note is null or length(trim(p_note)) not between 1 and 1000 then raise exception 'incident and note required'; end if;
  insert into public.ai_incident_acknowledgements(incident_id,acknowledged_by,note)
    values(p_incident,auth.uid(),trim(p_note)) on conflict (incident_id) do nothing returning incident_id into inserted_id;
  if inserted_id is null then return false; end if;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'acknowledge','ai_budget_incident',p_incident,trim(p_note));
  return true;
end $$;



CREATE FUNCTION public.editor_activate_ai_budget(p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare c public.ai_budget_control%rowtype; result uuid;
begin
 if session_user<>'authenticator' or public.editor_can_resume_ai_budget() is distinct from true then
   raise exception 'authenticated AI budget recovery access required'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
 if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'activation reason required'; end if;
 select * into c from public.ai_budget_control where singleton for update;
 if c.stopped is distinct from true or c.generation is distinct from 0 then raise exception 'initial activation unavailable'; end if;
 perform 1 from public.ai_claim_retention_control where singleton for update;
 if not found then raise exception 'claim retention control unavailable'; end if;
 lock table public.ai_budget_reservations, public.ai_request_preparations,
 public.ai_usage_observations, public.ai_budget_incidents, public.ai_budget_restarts,
 public.ai_claim_proposals in share row exclusive mode;
 if exists(select 1 from public.ai_budget_reservations)
 or exists(select 1 from public.ai_request_preparations)
 or exists(select 1 from public.ai_usage_observations)
 or exists(select 1 from public.ai_budget_incidents)
 or exists(select 1 from public.ai_budget_restarts)
 or exists(select 1 from public.ai_claim_proposals) then
   raise exception 'empty initial accounting and claim state required'; end if;
 -- Timestamp describes an actual locked empty-content check, not a fake sweep.
 update public.ai_claim_retention_control set restore_quarantine=false,
 last_sweep_at=clock_timestamp(),last_removed=0 where singleton;
 update public.ai_budget_control set restore_quarantine=false,updated_at=clock_timestamp() where singleton;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'verify_empty_initial_ai_state','ai_budget_control',gen_random_uuid(),
 'Locked empty accounting/claim check; zero content deleted; other restore gates unchanged. '||trim(p_reason));
 -- Preserve every original055 check: clean generation, alert health, daily and
 -- provider budgets, enabled provider, live reviewed price and billing bound.
 -- Any failure rolls back the empty-gate changes and audit above.
 result:=public.editor_activate_ai_budget_before_restore_gate(p_reason);
 return result;
end $$;



CREATE FUNCTION public.editor_activate_ai_budget_before_restore_gate(p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare c public.ai_budget_control%rowtype; restart_id uuid; today date;
begin
  if not public.editor_can_resume_ai_budget() then raise exception 'AI budget recovery access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'activation reason required'; end if;
  select * into c from public.ai_budget_control where singleton for update;
  if c.stopped is distinct from true or c.generation<>0 then raise exception 'initial activation unavailable'; end if;
  if c.alert_degraded is distinct from false or exists(select 1 from public.ai_budget_incidents)
    or exists(select 1 from public.ai_budget_reservations) or exists(select 1 from public.ai_budget_restarts) then
    raise exception 'initial activation requires clean state'; end if;
  today:=(clock_timestamp() at time zone 'UTC')::date;
  if not exists(select 1 from public.ai_daily_budgets where budget_day=today) then raise exception 'daily budget unavailable'; end if;
  if not exists(select 1 from public.ai_provider_catalog c0 join public.ai_provider_daily_budgets d on d.provider=c0.name and d.budget_day=today
    join public.ai_price_schedules s on s.provider=c0.name join public.ai_billing_bounds b on b.schedule_id=s.id
    where c0.enabled and s.covers_all_charges and s.valid_from<=clock_timestamp() and s.valid_until>clock_timestamp()
      and b.valid_from<=clock_timestamp() and b.valid_until>clock_timestamp()
      and not exists(select 1 from public.ai_price_withdrawals w where w.schedule_id=s.id)
      and not exists(select 1 from public.ai_billing_bound_withdrawals w where w.bound_id=b.id)) then
    raise exception 'enabled provider with reviewed bound and daily budget required'; end if;
  update public.ai_budget_control set stopped=false,generation=generation+1,updated_at=clock_timestamp() where singleton returning * into c;
  insert into public.ai_budget_restarts(generation,resumed_by,reason) values(c.generation,auth.uid(),trim(p_reason)) returning id into restart_id;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'activate','ai_budget_restart',restart_id,trim(p_reason));
  return restart_id;
end $$;



CREATE FUNCTION public.editor_activate_article_body_retention(p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare was_quarantined boolean; checked_at timestamptz;
begin
 if session_user<>'authenticator' or public.editor_can_review_provider_grants() is distinct from true
 or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then
   raise exception 'authenticated source reviewer and reason required';
 end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
 select restore_quarantine into was_quarantined from public.article_body_retention_control where singleton for update;
 if not found then raise exception 'body retention control unavailable'; end if;
 lock table public.article_full_drafts,public.article_body_summaries,
 public.article_body_snapshots,public.article_body_dispatches in share row exclusive mode;
 if exists(select 1 from public.article_full_drafts)
 or exists(select 1 from public.article_body_summaries)
 or exists(select 1 from public.article_body_snapshots) then
   raise exception 'empty private content required; separate confirmed maintenance needed';
 end if;
 -- Only explicitly reconciled originals are resolved; active/unknown successors still block.
 if exists(select 1 from public.article_body_dispatches d
   where (d.finished_at is null or d.outcome is distinct from 'stored')
   and not exists(select 1 from public.article_body_fetch_recoveries r where r.original_dispatch_id=d.id)) then
   raise exception 'unresolved body dispatch blocks empty retention refresh';
 end if;
 checked_at:=clock_timestamp();
 update public.article_body_retention_control set restore_quarantine=false,last_sweep_at=checked_at where singleton;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),(case when was_quarantined then 'activate_article_body_retention' else 'refresh_empty_article_retention' end),
 'retention',gen_random_uuid(),'Locked empty-content and resolved-dispatch verification; zero content deleted. '||trim(p_reason));
end $$;



CREATE FUNCTION public.editor_add_contradiction(p_story uuid, p_version integer, p_claim uuid, p_article uuid, p_reference text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare revision uuid; current_version integer;
begin
  if current_setting('transaction_isolation') <> 'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_reference is null or length(trim(p_reference)) not between 1 and 1000 or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reference and reason required'; end if;
  select version into current_version from public.stories where id=p_story for update;
  if current_version is null or current_version is distinct from p_version then raise exception 'story version conflict'; end if;
  select c.revision_id into revision from public.claims c join public.story_revisions r on r.id=c.revision_id where c.id=p_claim and r.story_id=p_story;
  if revision is null or revision is distinct from (select id from public.story_revisions where story_id=p_story order by revision_number desc limit 1) then raise exception 'claim not in latest revision'; end if;
  if exists(select 1 from public.editorial_reviews where revision_id=revision) then raise exception 'reviewed evidence is immutable'; end if;
  perform s.id from public.sources s join public.articles a on a.source_id=s.id where a.id=p_article for update of s;
  if not found or not public.candidate_title_allowed(p_article) or not exists(
    select 1 from public.articles a join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by version desc limit 1) p on true
    where a.id=p_article and p.story_publication_allowed
  ) then raise exception 'article permission unavailable'; end if;
  insert into public.story_articles(story_id,article_id) values(p_story,p_article) on conflict do nothing;
  insert into public.claim_evidence(claim_id,article_id,relation,evidence_reference,verified_by,verified_at)
    values(p_claim,p_article,'contradicts',trim(p_reference),auth.uid(),clock_timestamp());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'record_contradiction','claim',p_claim,trim(p_reason));
  if not public.candidate_title_allowed(p_article) then raise exception 'article permission unavailable'; end if;
end $$;



CREATE FUNCTION public.editor_add_provider_title_grant(p_source uuid, p_expected_version integer, p_provider text, p_region text, p_expires_at timestamp with time zone, p_evidence text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare p public.source_policies%rowtype; new_policy uuid; new_grant uuid;
begin
  if not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_source is null or p_expected_version is null or p_expected_version < 1
    or p_provider is null or p_provider !~ '^[a-z][a-z0-9_-]{0,63}$'
    or p_region is null or p_region !~ '^[a-z0-9-]{2,40}$'
    or p_evidence is null or length(trim(p_evidence)) not between 1 and 2000
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid provider grant review'; end if;
  if p_expires_at is not null and p_expires_at <= clock_timestamp() then raise exception 'grant already expired'; end if;
  if not exists(select 1 from public.ai_provider_catalog where name=p_provider) then raise exception 'provider not registered'; end if;
  perform 1 from public.sources where id=p_source for update;
  if not found then raise exception 'source not found'; end if;
  select * into p from public.source_policies where source_id=p_source order by version desc limit 1;
  if p.id is null or p.version <> p_expected_version then raise exception 'source policy version conflict'; end if;
  if p.policy_status <> 'approved' or not p.title_storage_allowed or p.reviewed_by is null or p.reviewed_at is null
    or jsonb_typeof(p.policy_evidence) <> 'object' or p.policy_evidence = '{}'::jsonb
    or (p.permission_expires_at is not null and p.permission_expires_at <= clock_timestamp()) then raise exception 'current approved title policy required'; end if;
  if p_expires_at is not null and p.permission_expires_at is not null and p_expires_at > p.permission_expires_at then
    raise exception 'grant outlasts source policy';
  end if;
  if exists(select 1 from public.ai_provider_title_grants g where g.policy_id=p.id and g.provider=p_provider and g.processing_region=p_region
    and (g.expires_at is null or g.expires_at > clock_timestamp())
    and not exists(select 1 from public.ai_provider_title_revocations r where r.grant_id=g.id)) then raise exception 'provider grant already active'; end if;
  -- This revision changes only the general AI flag; previous permissions are
  -- preserved exactly, never inferred across providers or new regions.
  insert into public.source_policies(source_id,version,policy_status,access_allowed,ai_processing_allowed,display_allowed,
    fulltext_storage_allowed,image_usage_allowed,policy_evidence,reviewed_by,reviewed_at,story_publication_allowed,permission_expires_at,
    access_method,title_storage_allowed,url_storage_allowed,source_display_allowed,link_display_allowed,terms_url,robots_url,
    attribution_requirements,permitted_region,title_ai_processing_allowed,ai_processor,ai_processing_region)
  values(p.source_id,p.version+1,p.policy_status,p.access_allowed,true,p.display_allowed,p.fulltext_storage_allowed,p.image_usage_allowed,
    p.policy_evidence,auth.uid(),clock_timestamp(),p.story_publication_allowed,p.permission_expires_at,p.access_method,p.title_storage_allowed,
    p.url_storage_allowed,p.source_display_allowed,p.link_display_allowed,p.terms_url,p.robots_url,p.attribution_requirements,p.permitted_region,
    p.title_ai_processing_allowed,p.ai_processor,p.ai_processing_region) returning id into new_policy;
  insert into public.ai_provider_title_grants(policy_id,provider,processing_region,evidence,reviewed_by,reviewed_at,expires_at,previous_grant_id)
    select new_policy,g.provider,g.processing_region,g.evidence,g.reviewed_by,g.reviewed_at,g.expires_at,g.id
    from public.ai_provider_title_grants g where g.policy_id=p.id
      and (g.expires_at is null or g.expires_at > clock_timestamp())
      and not exists(select 1 from public.ai_provider_title_revocations r where r.grant_id=g.id);
  insert into public.ai_provider_title_grants(policy_id,provider,processing_region,evidence,reviewed_by,expires_at)
    values(new_policy,p_provider,p_region,jsonb_build_object('basis',trim(p_evidence)),auth.uid(),p_expires_at) returning id into new_grant;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'grant_provider_title','ai_provider_title_grant',new_grant,trim(p_reason));
  return new_grant;
end $_$;



CREATE FUNCTION public.editor_add_verified_claim(p_revision uuid, p_article uuid, p_claim text, p_reference text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid; cid uuid; allowed boolean;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_claim is null or length(trim(p_claim)) = 0 or p_reference is null or length(trim(p_reference)) = 0 then raise exception 'claim and evidence reference required'; end if;
  if p_reason is null or length(trim(p_reason)) = 0 then raise exception 'reason required'; end if;
  select story_id into sid from public.story_revisions where id = p_revision;
  if sid is null then raise exception 'revision not found'; end if;
  perform 1 from public.stories where id = sid for update;
  if p_revision is distinct from (select id from public.story_revisions where story_id = sid order by revision_number desc limit 1) then raise exception 'revision is not latest'; end if;
  perform 1 from public.sources where id = (select source_id from public.articles where id = p_article) for update;
  if not found then raise exception 'article not found'; end if;
  select coalesce((select p.policy_status = 'approved' and p.display_allowed and p.story_publication_allowed
      and p.reviewed_by is not null and p.reviewed_at is not null and p.policy_evidence <> '{}'::jsonb
      and (p.permission_expires_at is null or p.permission_expires_at > now())
    from public.articles a join lateral (select * from public.source_policies sp where sp.source_id = a.source_id order by version desc limit 1) p on true
    where a.id = p_article), false) into allowed;
  if not allowed then raise exception 'article permission unavailable'; end if;
  insert into public.story_articles(story_id, article_id) values(sid, p_article) on conflict do nothing;
  insert into public.claims(revision_id, claim_text, status) values(p_revision, p_claim, 'verified') returning id into cid;
  insert into public.claim_evidence(claim_id, article_id, relation, evidence_reference, verified_by, verified_at)
    values(cid, p_article, 'supports', p_reference, auth.uid(), now());
  insert into public.audit_logs(actor_id, action, resource_type, resource_id, reason)
    values (auth.uid(), 'verify', 'claim', cid, p_reason);
  return cid;
end $$;



CREATE FUNCTION public.editor_ai_alert_health() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI budget operator access required'; end if;
  return jsonb_build_object(
    'degraded',coalesce((select alert_degraded from public.ai_budget_control where singleton),true),
    'pending',(select count(*) from public.ai_alert_outbox where status in ('pending','retry_wait','processing')),
    'unknown',(select count(*) from public.ai_alert_outbox where status='unknown'),
    'failed',(select count(*) from public.ai_alert_outbox where status='failed'),
    'issues',coalesce((select jsonb_agg(row_to_json(x) order by x.updated_at desc,x.incident_id desc) from (
      select o.incident_id,o.status,o.attempts,o.updated_at,i.reason from public.ai_alert_outbox o
      join public.ai_budget_incidents i on i.id=o.incident_id where o.status in ('unknown','failed')
      order by o.updated_at desc,o.incident_id desc limit 100
    ) x),'[]'::jsonb)
  );
end $$;



CREATE FUNCTION public.editor_ai_budget_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI budget operator access required'; end if;
  return public.editor_ai_budget_status_before_restore_gate() || jsonb_build_object('restore_quarantine',
    coalesce((select restore_quarantine from public.ai_budget_control where singleton),true));
end $$;



CREATE FUNCTION public.editor_ai_budget_status_base() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result jsonb;
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI budget operator access required'; end if;
  select jsonb_build_object(
    'stopped',coalesce((select stopped from public.ai_budget_control where singleton),true),
    'unknown_reservations',(select count(*) from public.ai_budget_reservations where state='unknown'),
    'unknown_requests',coalesce((select jsonb_agg(row_to_json(y) order by y.created_at desc,y.request_id desc) from (
      select request_id,model_id,reserved_nanos::text as reserved_nanos,created_at from public.ai_budget_reservations
      where state='unknown' order by created_at desc,request_id desc limit 100
    ) y),'[]'::jsonb),
    'total_incidents',(select count(*) from public.ai_budget_incidents),
    'incidents',coalesce((select jsonb_agg(row_to_json(x) order by x.created_at desc,x.id desc) from (
      select i.id,i.request_id,i.reason,i.created_at,a.acknowledged_at
      from public.ai_budget_incidents i left join public.ai_incident_acknowledgements a on a.incident_id=i.id
      order by i.created_at desc,i.id desc limit 100
    ) x),'[]'::jsonb)
  ) into result;
  return result;
end $$;



CREATE FUNCTION public.editor_ai_budget_status_before_restore_gate() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result jsonb;
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI budget operator access required'; end if;
  result:=public.editor_ai_budget_status_base();
  return result || jsonb_build_object(
    'reserved_count',(select count(*) from public.ai_budget_reservations where state='reserved'),
    'reserved_requests',coalesce((select jsonb_agg(row_to_json(x) order by x.created_at desc,x.request_id desc) from (
      select r.request_id,r.provider,r.model_id,r.reserved_nanos::text as reserved_nanos,r.created_at,
        coalesce(p.state,'unavailable') as preparation_state,coalesce(o.status,'not_recorded') as usage_status
      from public.ai_budget_reservations r left join public.ai_request_preparations p on p.request_id=r.request_id
        left join public.ai_usage_observations o on o.request_id=r.request_id
      where r.state='reserved' order by r.created_at desc,r.request_id desc limit 100
    ) x),'[]'::jsonb));
end $$;



CREATE FUNCTION public.editor_ai_claim_retention_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sweep timestamptz; removed integer; overdue bigint; quarantined boolean;
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI operator access required'; end if;
  select last_sweep_at,last_removed,restore_quarantine into sweep,removed,quarantined from public.ai_claim_retention_control where singleton;
  select count(*) into overdue from public.ai_claim_proposals where expires_at<=statement_timestamp();
  return jsonb_build_object('last_sweep_at',sweep,'last_removed',removed,'overdue',overdue,'quarantined',coalesce(quarantined,true),
    'healthy',coalesce(not quarantined and sweep<=statement_timestamp() and sweep>statement_timestamp()-interval '5 minutes' and overdue=0,false));
end $$;



CREATE FUNCTION public.editor_ai_cny_reconciliation_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if session_user<>'authenticator' or public.editor_can_monitor_ai() is distinct from true then raise exception 'authenticated budget reviewer required'; end if;
 return jsonb_build_object('currency','CNY','usd_budget_treatment','original reservation retained; not actual USD',
 'requests',coalesce((select jsonb_agg(to_jsonb(row_data)) from (
 select c.request_id,r.job_id,r.model_id,(c.actual_cny_nanos::numeric/1000000000)::text as actual_cny,
 c.reserved_usd_nanos::text,c.statement_sha256,c.evidence_reference,c.reconciled_at
 from public.ai_cny_charge_reconciliations c join public.ai_budget_reservations r using(request_id)
 order by c.reconciled_at desc limit 100) row_data),'[]'::jsonb));
end $$;



CREATE FUNCTION public.editor_ai_execution_history() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if not public.editor_can_monitor_ai() then raise exception 'AI operator access required'; end if;
 return coalesce((select jsonb_agg(row_to_json(x) order by x.created_at desc,x.request_id desc) from (
  select e.request_id,coalesce(r.provider,p.processor) as provider,r.model_id,r.state as reservation_state,
   e.prompt_version,e.schema_version,e.outcome,e.latency_ms,e.retry_count,e.estimated_nanos::text as estimated_nanos,
   e.created_at,u.status as usage_status,u.input_tokens,u.output_tokens,u.cached_input_tokens,u.total_tokens
  from public.ai_execution_observations e
  join public.ai_request_identities i on i.request_id=e.request_id
  left join public.ai_request_preparations p on p.request_id=e.request_id
  left join public.ai_budget_reservations r on r.request_id=e.request_id
  left join public.ai_usage_observations u on u.request_id=e.request_id
  order by e.created_at desc,e.request_id desc limit 100
 ) x),'[]'::jsonb);
end $$;



CREATE FUNCTION public.editor_ai_setup_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI budget operator access required'; end if;
  return jsonb_build_object(
    'providers',coalesce((select jsonb_agg(jsonb_build_object('name',name,'enabled',enabled) order by name) from public.ai_provider_catalog),'[]'::jsonb),
    'budgets',coalesce((select jsonb_agg(row_to_json(x) order by x.budget_day,x.scope,x.provider) from (
      select 'global'::text as scope,null::text as provider,d.budget_day,d.limit_nanos::text from public.ai_daily_budgets d
        where d.budget_day between (clock_timestamp() at time zone 'UTC')::date and (clock_timestamp() at time zone 'UTC')::date+1
      union all
      select 'provider'::text,d.provider,d.budget_day,d.limit_nanos::text from public.ai_provider_daily_budgets d
        where d.budget_day between (clock_timestamp() at time zone 'UTC')::date and (clock_timestamp() at time zone 'UTC')::date+1
    ) x),'[]'::jsonb));
end $$;



CREATE FUNCTION public.editor_approve_article_body_bound(p_bound uuid, p_bytes integer, p_prompt_sha256 text, p_evidence text, p_expires timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare b public.ai_billing_bounds%rowtype; result uuid;
begin
 if not public.editor_can_review_ai_billing() then raise exception 'billing reviewer required'; end if;
 select * into b from public.ai_billing_bounds where id=p_bound for update;
 if b.id is null or b.valid_from>clock_timestamp() or b.valid_until<=clock_timestamp()
 or exists(select 1 from public.ai_billing_bound_withdrawals where bound_id=b.id)
 or p_bytes is null or p_bytes+1024>b.max_billable_input_tokens
 or p_prompt_sha256 is null or p_prompt_sha256 !~ '^[0-9a-f]{64}$'
 or p_evidence is null or length(trim(p_evidence)) not between 1 and 4000
 or p_expires is null or p_expires<=clock_timestamp() or p_expires>b.valid_until then raise exception 'invalid full-body billing approval'; end if;
 insert into public.article_body_billing_approvals(bound_id,max_payload_bytes,prompt_sha256,evidence,expires_at,reviewed_by) values(p_bound,p_bytes,p_prompt_sha256,p_evidence,p_expires,auth.uid()) returning id into result;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'approve_full_body_billing','ai_billing_bound',p_bound,p_evidence);
 return result;
end $_$;



CREATE FUNCTION public.editor_approve_article_stage_bound(p_stage text, p_bound uuid, p_bytes integer, p_prompt_sha256 text, p_evidence text, p_expires timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare b public.ai_billing_bounds%rowtype; result uuid;
begin
 if not public.editor_can_review_ai_billing() then raise exception 'billing reviewer required'; end if;
 if p_stage is null or p_stage not in ('summary','draft') then raise exception 'explicit stage required'; end if;
 select * into b from public.ai_billing_bounds where id=p_bound for update;
 if not exists(select 1 from public.ai_price_schedules where id=b.schedule_id and provider='deepseek' and request_mode='standard' and model_id=(case when p_stage='summary' then 'deepseek-flash' else 'deepseek-v4-pro' end)) or b.id is null or b.valid_from>clock_timestamp() or b.valid_until<=clock_timestamp()
 or exists(select 1 from public.ai_billing_bound_withdrawals where bound_id=b.id)
 or p_bytes is null or p_bytes+1024>b.max_billable_input_tokens
 or p_prompt_sha256 is null or p_prompt_sha256 !~ '^[0-9a-f]{64}$'
 or p_evidence is null or length(trim(p_evidence)) not between 1 and 4000
 or p_expires is null or p_expires<=clock_timestamp() or p_expires>b.valid_until then raise exception 'invalid full-body billing approval'; end if;
 insert into public.article_body_billing_approvals(bound_id,max_payload_bytes,prompt_sha256,evidence,expires_at,reviewed_by,stage) values(p_bound,p_bytes,p_prompt_sha256,p_evidence,p_expires,auth.uid(),p_stage) returning id into result;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'approve_full_body_billing','ai_billing_bound',p_bound,p_evidence);
 return result;
end $_$;



CREATE FUNCTION public.editor_approve_bilingual_retraction(p_notice uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.bilingual_rollout_enabled() then raise exception 'bilingual rollout is disabled'; end if;
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if not exists(select 1 from public.bilingual_retraction_notices where notice_id=p_notice) then raise exception 'bilingual notice required'; end if;
  perform public.approve_retraction(p_notice);
end $$;



CREATE FUNCTION public.editor_approve_classification_bound(p_bound uuid, p_evidence text, p_expires timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.ai_billing_bounds%rowtype; result uuid;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.editor_can_review_ai_billing() then raise exception 'billing reviewer access required'; end if;
  if p_bound is null or p_evidence is null or length(trim(p_evidence)) not between 1 and 1000 or p_expires is null
    or p_expires<=clock_timestamp() or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid classification billing approval'; end if;
  select * into b from public.ai_billing_bounds where id=p_bound for update;
  if not found or b.valid_from>clock_timestamp() or b.valid_until<=clock_timestamp() or p_expires>b.valid_until
    or exists(select 1 from public.ai_billing_bound_withdrawals where bound_id=b.id) then raise exception 'reviewed billing bound unavailable'; end if;
  if exists(select 1 from public.classification_billing_approvals a where a.bound_id=p_bound and a.expires_at>clock_timestamp()
    and not exists(select 1 from public.classification_billing_revocations r where r.approval_id=a.id)) then raise exception 'billing approval already active'; end if;
  insert into public.classification_billing_approvals(bound_id,evidence,expires_at,reviewed_by) values(p_bound,trim(p_evidence),p_expires,auth.uid()) returning id into result;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'approve_classification_bound','ai_billing_bound',p_bound,trim(p_reason));
  return result;
end $$;



CREATE FUNCTION public.editor_approve_rss_validators(p_endpoint uuid, p_evidence text, p_expires timestamp with time zone, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare e public.rss_endpoint_reviews%rowtype; p public.source_policies%rowtype;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.is_active_editor() or not exists(select 1 from public.editors where user_id=auth.uid() and active and can_review_sources) then raise exception 'source reviewer access required'; end if;
  if p_evidence is null or length(trim(p_evidence)) not between 1 and 2000 or p_reason is null or length(trim(p_reason)) not between 1 and 1000
    or p_expires is null or p_expires<=clock_timestamp() then raise exception 'invalid validator review'; end if;
  select * into e from public.rss_endpoint_reviews where id=p_endpoint;
  select * into p from public.source_policies where id=e.policy_id;
  if p.id is null then raise exception 'endpoint not found'; end if;
  perform 1 from public.sources where id=p.source_id for update;
  if p.version is distinct from (select max(latest.version) from public.source_policies latest where latest.source_id=p.source_id)
    or p.policy_status<>'approved' or not p.access_allowed or e.expires_at<=clock_timestamp() or p_expires>e.expires_at
    or (p.permission_expires_at is not null and (p.permission_expires_at<=clock_timestamp() or p_expires>p.permission_expires_at)) then
    raise exception 'current endpoint permission unavailable'; end if;
  insert into public.rss_validator_permissions(endpoint_id,evidence,reviewed_by,expires_at)
    values(p_endpoint,trim(p_evidence),auth.uid(),p_expires) on conflict do nothing;
  if not found then raise exception 'validator review already exists'; end if;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'approve_rss_validators','rss_endpoint_review',p_endpoint,trim(p_reason));
  return true;
end $$;



