end $$;



CREATE FUNCTION public.editor_assign_bilingual_channels(p_request uuid, p_batch uuid, p_version integer, p_primary text, p_secondary text[], p_domains text[], p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.story_bilingual_batches%rowtype; old public.bilingual_channel_assignments%rowtype;
  v integer; secondary_sorted text[]; domains_sorted text[];
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_request is null or p_batch is null or p_version is null or p_primary is null
    or p_primary not in ('ai','robotics','industry','technology','internet','products')
    or p_secondary is null or cardinality(p_secondary)>5 or p_domains is null or cardinality(p_domains)>6
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000
    or exists(select 1 from unnest(p_secondary) x where x is null or x=p_primary or x not in ('ai','robotics','industry','technology','internet','products'))
    or exists(select 1 from unnest(p_domains) x where x is null or x not in ('robotics','bci','energy','chips-ai','space','biotech'))
    or (select count(distinct x) from unnest(p_secondary) x)<>cardinality(p_secondary)
    or (select count(distinct x) from unnest(p_domains) x)<>cardinality(p_domains)
    then raise exception 'invalid channel assignment'; end if;
  select coalesce(array_agg(x order by x),'{}'::text[]) into secondary_sorted from unnest(p_secondary) x;
  select coalesce(array_agg(x order by x),'{}'::text[]) into domains_sorted from unnest(p_domains) x;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,24142));
  select * into b from public.story_bilingual_batches where id=p_batch;
  if b.id is null then raise exception 'bilingual batch unavailable'; end if;
  select version into v from public.stories where id=b.story_id and archived_at is null for update;
  if v is null then raise exception 'story unavailable'; end if;
  select * into old from public.bilingual_channel_assignments where request_id=p_request;
  if found then
    if old.batch_id is distinct from p_batch or old.story_version is distinct from p_version or old.primary_channel is distinct from p_primary
      or old.secondary_channels is distinct from secondary_sorted or old.technical_domains is distinct from domains_sorted
      or old.actor_id is distinct from auth.uid() or old.reason is distinct from trim(p_reason) then raise exception 'channel request identity conflict'; end if;
    return false;
  end if;
  if v is distinct from p_version then raise exception 'story version conflict'; end if;
  if b.zh_revision_id is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id
      where l.story_id=b.story_id and l.locale='zh' order by r.revision_number desc limit 1)
    or b.en_revision_id is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id
      where l.story_id=b.story_id and l.locale='en' order by r.revision_number desc limit 1) then raise exception 'stale bilingual batch'; end if;
  if exists(select 1 from public.bilingual_editorial_reviews where batch_id=p_batch) then raise exception 'reviewed batch cannot be reclassified'; end if;
  perform public.lock_revision_sources(b.zh_revision_id);
  perform public.lock_revision_sources(b.en_revision_id);
  if not public.editor_revision_sources_available(b.zh_revision_id) or not public.editor_revision_sources_available(b.en_revision_id)
    then raise exception 'source permission unavailable'; end if;
  insert into public.bilingual_channel_assignments(request_id,batch_id,story_version,primary_channel,secondary_channels,technical_domains,actor_id,reason)
    values(p_request,p_batch,p_version,p_primary,secondary_sorted,domains_sorted,auth.uid(),trim(p_reason));
  update public.stories set version=version+1 where id=b.story_id;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'assign_bilingual_channels','story_bilingual_batch',p_batch,trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editor_authorize_full_article_publication(p_revision uuid, p_allowed boolean, p_expires timestamp with time zone, p_evidence text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result bigint; draft uuid; policy uuid; expiry timestamptz; policy_expiry timestamptz; src uuid;
begin
 if session_user<>'authenticator' or public.editor_can_review_provider_grants() is distinct from true then raise exception 'authenticated source reviewer required'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
 if p_allowed is null or p_expires is null or p_evidence is null or length(trim(p_evidence)) not between 1 and 1000 then raise exception 'invalid public authorization'; end if;
 select er.draft_id,ec.expires_at,a.source_id into draft,expiry,src from public.article_editor_revision_receipts er
 left join public.article_editor_revision_content ec on ec.id=er.id join public.article_full_draft_receipts d on d.id=er.draft_id
 join public.article_body_receipts br on br.id=d.snapshot_id join public.articles a on a.id=br.article_id where er.id=p_revision;
 perform pg_advisory_xact_lock(hashtextextended(draft::text,903515));
 perform 1 from public.sources where id=src for update;
 select id,permission_expires_at into policy,policy_expiry from public.source_policies where source_id=src order by version desc limit 1;
 if policy is null then raise exception 'source policy unavailable'; end if;
 if p_allowed and (not public.article_editor_revision_live(p_revision) or p_expires<=clock_timestamp() or p_expires>expiry or (policy_expiry is not null and p_expires>policy_expiry)) then raise exception 'public authorization exceeds current revision scope'; end if;
 insert into public.article_full_public_grants(revision_id,policy_id,allowed,expires_at,evidence_reference,reviewed_by)
 values(p_revision,policy,p_allowed,least(p_expires,expiry),trim(p_evidence),auth.uid()) returning id into result;
 if p_allowed and not public.article_full_public_grant_live(result) then raise exception 'explicit current source publication permissions required'; end if;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'authorize_full_article_publication','article_editor_revision',p_revision,(case when p_allowed then 'allow public_full_article' else 'revoke public_full_article' end));
 return result;
end $$;



CREATE FUNCTION public.editor_bilingual_rollout_status() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return public.bilingual_rollout_enabled();
end $$;



CREATE FUNCTION public.editor_bind_revision_locale(p_story uuid, p_revision uuid, p_locale text, p_version integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v integer;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_locale is null or p_locale not in ('zh','en') or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid locale or reason'; end if;
  select version into v from public.stories where id=p_story and archived_at is null for update;
  if v is null or v is distinct from p_version then raise exception 'story version conflict'; end if;
  if not exists(select 1 from public.story_revisions where id=p_revision and story_id=p_story) then raise exception 'revision unavailable'; end if;
  insert into public.story_revision_locales(story_id,revision_id,locale) values(p_story,p_revision,p_locale);
  update public.stories set version=version+1,bilingual_translation_status='pending' where id=p_story;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'bind_locale','story_revision',p_revision,trim(p_reason));
end $$;



CREATE FUNCTION public.editor_branch_retracted_story(p_id uuid, p_source uuid, p_version integer, p_slug text, p_articles uuid[], p_reason text) RETURNS TABLE(target_story_id uuid, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare s public.stories%rowtype; old public.story_retracted_branches%rowtype; ids uuid[]; old_ids uuid[]; target uuid;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_source is null or p_version is null or p_slug is null or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or length(p_slug)>120
    or p_articles is null or cardinality(p_articles) not between 1 and 100 or (select count(distinct id) from unnest(p_articles) id)<>cardinality(p_articles)
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid retracted branch'; end if;
  select array_agg(id order by id) into ids from unnest(p_articles) id;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,76131));
  select * into s from public.stories where id=p_source for update;
  if not found then raise exception 'story unavailable'; end if;
  select * into old from public.story_retracted_branches where id=p_id;
  if found then
    select array_agg(article_id order by article_id) into old_ids from public.story_retracted_branch_articles where branch_id=p_id;
    if old.source_story_id is distinct from p_source or old.source_version is distinct from p_version or old.target_slug is distinct from p_slug
      or old.actor_id is distinct from auth.uid() or old.reason is distinct from trim(p_reason) or old_ids is distinct from ids then raise exception 'branch identity conflict'; end if;
    perform src.id from public.sources src where src.id in(select a.source_id from public.articles a where a.id=any(ids)) order by src.id for update;
    if exists(select 1 from unnest(ids) id where not public.candidate_title_allowed(id)) then raise exception 'article permission unavailable'; end if;
    return query select old.target_story_id,false; return;
  end if;
  if s.version<>p_version then raise exception 'story version conflict'; end if;
  if s.visibility<>'retracted' or not exists(select 1 from public.retraction_notices n join public.retraction_approvals a on a.notice_id=n.id
    where n.id=s.public_retraction_id and n.story_id=s.id and n.revision_id=s.public_revision_id) then raise exception 'approved retraction required'; end if;
  perform src.id from public.sources src where src.id in(select a.source_id from public.articles a where a.id=any(ids)) order by src.id for update;
  if exists(select 1 from unnest(ids) id where not public.candidate_title_allowed(id)) then raise exception 'article permission unavailable'; end if;
  perform article_id from public.story_articles where story_id=p_source order by article_id for update;
  if (select count(*) from public.story_articles where story_id=p_source and article_id=any(ids))<>cardinality(ids) then raise exception 'articles not in source story'; end if;
  insert into public.stories(slug) values(p_slug) returning id into target;
  insert into public.story_retracted_branches(id,source_story_id,target_story_id,notice_id,source_version,target_slug,actor_id,reason)
    values(p_id,p_source,target,s.public_retraction_id,p_version,p_slug,auth.uid(),trim(p_reason));
  insert into public.story_retracted_branch_articles(branch_id,article_id,original_role,original_independence,original_syndicated_from)
    select p_id,article_id,reporting_role,independence,syndicated_from_article_id from public.story_articles where story_id=p_source and article_id=any(ids);
  insert into public.story_articles(story_id,article_id,reporting_role,independence) select target,id,'unknown','unknown' from unnest(ids) id;
  update public.stories set version=version+1 where id=p_source;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'branch_retracted_story','story',p_source,trim(p_reason));
  if exists(select 1 from unnest(ids) id where not public.candidate_title_allowed(id)) then raise exception 'article permission expired'; end if;
  return query select target,true;
end $_$;



