CREATE FUNCTION public.editor_cancel_prepared_ai_trial(p_request uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare changed boolean;
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null then raise exception 'AI operator access required'; end if;
 if p_request is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'request and reason required'; end if;
 changed:=public.ai_cancel_prepared_request(p_request);
 if changed then insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'cancel_ai_trial','ai_request',p_request,trim(p_reason)); end if;
 return changed;
end $$;



CREATE FUNCTION public.editor_classify_claim_evidence(p_claim uuid, p_category text, p_firsthand_article uuid, p_version integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid; rid uuid; v integer;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_category is null or p_category not in ('firsthand_statement','official_exclusive','own_test',
      'external_allegation','external_number','other') then raise exception 'invalid category'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reason required'; end if;
  select r.story_id,c.revision_id into sid,rid from public.claims c
    join public.story_revisions r on r.id=c.revision_id where c.id=p_claim;
  if sid is null then raise exception 'claim unavailable'; end if;
  select version into v from public.stories where id=sid and archived_at is null for update;
  if v is null or v is distinct from p_version then raise exception 'story version conflict'; end if;
  if exists(select 1 from public.editorial_reviews where revision_id=rid) then raise exception 'reviewed revision cannot be classified'; end if;
  perform public.lock_revision_sources(rid);
  if not public.editor_revision_sources_available(rid) then raise exception 'source permission unavailable'; end if;
  if p_category in ('firsthand_statement','official_exclusive','own_test') then
    if p_firsthand_article is null or not exists(
      select 1 from public.claim_evidence e join public.story_articles sa on sa.story_id=sid and sa.article_id=e.article_id
      where e.claim_id=p_claim and e.article_id=p_firsthand_article and e.relation='supports'
        and e.verified_by is not null and e.verified_at is not null and length(trim(e.evidence_reference))>0
        and sa.reporting_role<>'syndicated' and sa.syndicated_from_article_id is null and sa.independence<>'dependent')
      then raise exception 'verified firsthand basis required'; end if;
  elsif p_firsthand_article is not null then
    raise exception 'firsthand basis is not applicable';
  end if;
  insert into public.claim_evidence_classifications(claim_id,category,firsthand_article_id,reason,classified_by)
    values(p_claim,p_category,p_firsthand_article,trim(p_reason),auth.uid());
  update public.stories set version=version+1 where id=sid;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'classify_evidence','claim',p_claim,trim(p_reason));
end $$;



CREATE FUNCTION public.editor_configure_ai_daily_budget(p_scope text, p_provider text, p_day date, p_limit bigint, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare previous bigint; used numeric; change_id uuid; today date; inserted integer;
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI budget operator access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  today:=(clock_timestamp() at time zone 'UTC')::date;
  if p_scope not in ('global','provider') or p_scope is null or p_day is null or p_day not between today and today+1
    or p_limit is null or p_limit not between 1 and 1000000000000000 or p_reason is null or length(trim(p_reason)) not between 1 and 1000
    or (p_scope='global' and p_provider is not null) or (p_scope='provider' and p_provider is null) then raise exception 'invalid daily budget'; end if;
  if p_scope='global' then
    insert into public.ai_daily_budgets(budget_day,limit_nanos) values(p_day,p_limit) on conflict do nothing;
    get diagnostics inserted = row_count;
    select limit_nanos into previous from public.ai_daily_budgets where budget_day=p_day for update;
    if inserted=1 then previous:=null; end if;
    select coalesce(sum(case when state='settled' then actual_nanos else reserved_nanos end),0) into used from public.ai_budget_reservations where budget_day=p_day;
    if used>p_limit then raise exception 'budget below existing commitments'; end if;
    update public.ai_daily_budgets set limit_nanos=p_limit where budget_day=p_day;
  else
    insert into public.ai_provider_daily_budgets(provider,budget_day,limit_nanos) values(p_provider,p_day,p_limit) on conflict do nothing;
    get diagnostics inserted = row_count;
    select limit_nanos into previous from public.ai_provider_daily_budgets where provider=p_provider and budget_day=p_day for update;
    if inserted=1 then previous:=null; end if;
    select coalesce(sum(case when state='settled' then actual_nanos else reserved_nanos end),0) into used from public.ai_budget_reservations where provider=p_provider and budget_day=p_day;
    if used>p_limit then raise exception 'budget below existing commitments'; end if;
    update public.ai_provider_daily_budgets set limit_nanos=p_limit where provider=p_provider and budget_day=p_day;
  end if;
  insert into public.ai_budget_config_changes(scope,provider,budget_day,old_limit_nanos,new_limit_nanos,actor_id,reason)
    values(p_scope,p_provider,p_day,previous,p_limit,auth.uid(),trim(p_reason)) returning id into change_id;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'configure_budget','ai_budget_config_change',change_id,trim(p_reason));
  return change_id;
end $$;



CREATE FUNCTION public.editor_configure_article_task_budget(p_job uuid, p_expected_limit bigint, p_limit bigint, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare previous bigint; used numeric; result uuid;
begin
 if session_user<>'authenticator' or public.editor_can_monitor_ai() is distinct from true or public.editor_can_review_ai_billing() is distinct from true then raise exception 'authenticated budget and billing reviewer required'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
 if p_job is null or p_expected_limit is null or p_limit is null or p_limit not between 1 and 5000000000 or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid article task budget'; end if;
 if not exists(select 1 from public.ai_processing_jobs where id=p_job and task_type='full_article.v1') then raise exception 'full article job required'; end if;
 select limit_nanos into previous from public.ai_task_budgets where job_id=p_job for update;
 if previous is null or previous<>p_expected_limit then raise exception 'task budget version conflict'; end if;
 perform 1 from public.ai_budget_control where singleton and stopped for share;
 if not found then raise exception 'AI requests must be stopped'; end if;
 select coalesce(sum(case when state='settled' then actual_nanos else reserved_nanos end),0) into used from public.ai_budget_reservations where job_id=p_job;
 if used>p_limit then raise exception 'task budget below existing commitments'; end if;
 update public.ai_task_budgets set limit_nanos=p_limit where job_id=p_job;
 insert into public.ai_article_task_budget_changes(job_id,old_limit_nanos,new_limit_nanos,actor_id,reason)
 values(p_job,previous,p_limit,auth.uid(),trim(p_reason)) returning id into result;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'configure_article_task_budget','ai_processing_job',p_job,trim(p_reason));
 return result;
end $$;



CREATE FUNCTION public.editor_create_ai_bound(p_schedule uuid, p_region text, p_input integer, p_output integer, p_evidence text, p_valid_from timestamp with time zone, p_valid_until timestamp with time zone, p_confirm boolean, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare s public.ai_price_schedules%rowtype; id uuid;
begin
  if not public.editor_can_review_ai_billing() then raise exception 'AI billing reviewer access required'; end if;
  if p_confirm is distinct from true or p_reason is null or length(trim(p_reason)) not between 1 and 1000
    or p_evidence is null or length(trim(p_evidence)) not between 1 and 2000
    or p_valid_from is null or p_valid_until is null or p_valid_until<=clock_timestamp() then raise exception 'reviewed billing bound required'; end if;
  select * into s from public.ai_price_schedules where ai_price_schedules.id=p_schedule for update;
  if not found or not s.covers_all_charges or p_valid_from<s.valid_from or p_valid_until>s.valid_until
    or exists(select 1 from public.ai_price_withdrawals where schedule_id=s.id) then raise exception 'reviewed price unavailable'; end if;
  insert into public.ai_billing_bounds(schedule_id,processing_region,max_billable_input_tokens,max_output_tokens,evidence,reviewed_by,valid_from,valid_until)
    values(p_schedule,p_region,p_input,p_output,trim(p_evidence),auth.uid(),p_valid_from,p_valid_until) returning ai_billing_bounds.id into id;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'review_bound','ai_billing_bound',id,trim(p_reason));
  return id;
end $$;



CREATE FUNCTION public.editor_create_ai_model_route(p_provider text, p_region text, p_model text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare route_id uuid;
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null
  or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'AI operator and reason required'; end if;
 insert into public.ai_model_routes(provider,processing_region,model_id,purpose,enabled)
 values(p_provider,p_region,p_model,'claim_extraction.v1',true) returning id into route_id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'create_ai_model_route','ai_model_route',route_id,trim(p_reason));
 return route_id;
end $$;



CREATE FUNCTION public.editor_create_ai_model_route(p_provider text, p_region text, p_model text, p_purpose text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare route_id uuid;
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null or p_reason is null
  or length(trim(p_reason)) not between 1 and 1000 or p_purpose is null
  or p_purpose not in ('claim_extraction.v1','classification.v1','summary_fact.v1','summary_story.v1','translation.v1','article_summary.v1','article_draft.v1')
 then raise exception 'AI operator, purpose and reason required'; end if;
 insert into public.ai_model_routes(provider,processing_region,model_id,purpose,enabled)
 values(p_provider,p_region,p_model,p_purpose,true) returning id into route_id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'create_ai_model_route','ai_model_route',route_id,trim(p_reason));
 return route_id;
end $$;



CREATE FUNCTION public.editor_create_ai_price(p_provider text, p_model text, p_version text, p_input bigint, p_output bigint, p_fixed bigint, p_evidence text, p_valid_from timestamp with time zone, p_valid_until timestamp with time zone, p_complete boolean, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare id uuid;
begin
  if not public.editor_can_review_ai_billing() then raise exception 'AI billing reviewer access required'; end if;
  if p_complete is distinct from true or p_reason is null or length(trim(p_reason)) not between 1 and 1000
    or p_evidence is null or length(trim(p_evidence)) not between 1 and 2000
    or p_model is null or p_version is null or p_valid_from is null or p_valid_until is null
    or p_valid_until<=clock_timestamp() or p_valid_until<=p_valid_from then raise exception 'complete reviewed pricing required'; end if;
  insert into public.ai_price_schedules(provider,model_id,price_version,request_mode,input_nanos_per_million,output_nanos_per_million,
    fixed_request_nanos,covers_all_charges,evidence,reviewed_by,valid_from,valid_until)
  values(p_provider,trim(p_model),trim(p_version),'standard',p_input,p_output,p_fixed,true,trim(p_evidence),auth.uid(),p_valid_from,p_valid_until)
  returning ai_price_schedules.id into id;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'review_price','ai_price_schedule',id,trim(p_reason));
  return id;
end $$;



CREATE FUNCTION public.editor_create_article(p_source uuid, p_title text, p_url text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare p public.source_policies%rowtype; aid uuid;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_title is null or length(trim(p_title)) = 0 or length(p_title) > 1000 then raise exception 'invalid title'; end if;
  if p_url is null or length(p_url) > 2048 or p_url !~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$' then raise exception 'invalid https url'; end if;
  if p_reason is null or length(trim(p_reason)) = 0 then raise exception 'reason required'; end if;
  perform 1 from public.sources where id = p_source for update;
  if not found then raise exception 'source not found'; end if;
  select * into p from public.source_policies where source_id = p_source order by version desc limit 1;
  if p.id is null or p.policy_status <> 'approved' or not p.title_storage_allowed or not p.url_storage_allowed
    or (p.permission_expires_at is not null and p.permission_expires_at <= now()) then raise exception 'metadata permission unavailable'; end if;
  insert into public.articles(source_id, title, canonical_url) values(p_source, trim(p_title), p_url) returning id into aid;
  insert into public.audit_logs(actor_id, action, resource_type, resource_id, reason)
    values(auth.uid(), 'create', 'article', aid, p_reason);
  return aid;
end $_$;



CREATE FUNCTION public.editor_create_article_body_job(p_story uuid, p_article uuid, p_task_budget bigint, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result uuid;
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null then raise exception 'AI operator required'; end if;
 if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reason required'; end if;
 perform 1 from public.stories where id=p_story and visibility='hidden' for update;
 if not found or not exists(select 1 from public.story_articles where story_id=p_story and article_id=p_article) then raise exception 'hidden story/article association required'; end if;
 result:=gen_random_uuid();
 insert into public.ai_processing_jobs(id,story_id,article_id,task_type,idempotency_key) values(result,p_story,p_article,'full_article.v1','full-article:'||result::text);
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'create_full_article_job','ai_processing_job',result,trim(p_reason));
 return result;
end $$;



CREATE FUNCTION public.editor_create_article_stage_config(p_route uuid, p_stage text, p_bytes integer, p_prompt_sha256 text, p_expires timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare route public.ai_model_routes%rowtype; result uuid;
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000
  or p_stage not in ('summary','draft') or p_stage is null or p_prompt_sha256 is null or p_prompt_sha256 !~ '^[0-9a-f]{64}$'
  or p_bytes is null or p_bytes not between 1024 and 200000 or p_expires is null or p_expires<=clock_timestamp()
 then raise exception 'invalid article stage configuration'; end if;
 select * into route from public.ai_model_routes where id=p_route for share;
 if route.id is null or not route.enabled or route.provider<>'deepseek'
  or route.purpose is distinct from (case when p_stage='summary' then 'article_summary.v1' else 'article_draft.v1' end)
  or route.model_id is distinct from (case when p_stage='summary' then 'deepseek-flash' else 'deepseek-v4-pro' end)
 then raise exception 'article stage route unavailable'; end if;
 insert into public.article_stage_configs(route_id,stage,prompt_sha256,max_payload_bytes,expires_at,created_by)
 values(p_route,p_stage,p_prompt_sha256,p_bytes,p_expires,auth.uid()) returning id into result;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'create_article_stage_config','article_stage_config',result,trim(p_reason));
 return result;
end $_$;



CREATE FUNCTION public.editor_create_bilingual_batch(p_story uuid, p_zh uuid, p_en uuid, p_version integer, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v integer; bid uuid;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reason required'; end if;
  select version into v from public.stories where id=p_story and archived_at is null for update;
  if v is null or v is distinct from p_version then raise exception 'story version conflict'; end if;
  if p_zh is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id
      where l.story_id=p_story and l.locale='zh' order by r.revision_number desc limit 1)
    or p_en is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id
      where l.story_id=p_story and l.locale='en' order by r.revision_number desc limit 1)
    or p_zh is null or p_en is null then raise exception 'latest paired revisions required'; end if;
  insert into public.story_bilingual_batches(story_id,zh_revision_id,en_revision_id,created_by) values(p_story,p_zh,p_en,auth.uid()) returning id into bid;
  update public.stories set version=version+1,bilingual_translation_status='needs_review' where id=p_story;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'create_bilingual_batch','story_bilingual_batch',bid,trim(p_reason));
  return bid;
end $$;



CREATE FUNCTION public.editor_create_revision(p_story uuid, p_expected_version integer, p_title text, p_summary text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare ver integer; next_revision integer; rid uuid;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_title is null or length(trim(p_title)) = 0 or p_summary is null or length(trim(p_summary)) = 0 then raise exception 'title and summary required'; end if;
  if p_reason is null or length(trim(p_reason)) = 0 then raise exception 'reason required'; end if;
  select version into ver from public.stories where id = p_story for update;
  if ver is null or ver <> p_expected_version then raise exception 'story version conflict'; end if;
  select coalesce(max(revision_number), 0) + 1 into next_revision from public.story_revisions where story_id = p_story;
  insert into public.story_revisions(story_id, revision_number, title, summary, created_by)
    values (p_story, next_revision, p_title, p_summary, auth.uid()) returning id into rid;
  update public.stories set version = version + 1, workflow_status = 'developing' where id = p_story;
  insert into public.audit_logs(actor_id, action, resource_type, resource_id, reason)
    values (auth.uid(), 'create', 'story_revision', rid, p_reason);
  return rid;
end $$;



CREATE FUNCTION public.editor_create_score_input(p_id uuid, p_story uuid, p_revision uuid, p_version integer, p_technical integer, p_impact integer, p_novelty integer, p_attention integer, p_unexpected integer, p_reasons jsonb, p_attention_evidence text, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prior public.editorial_score_inputs%rowtype; actual_version integer; key text;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_story is null or p_revision is null or p_version is null or p_version<1
    or p_technical is null or p_technical not between 0 and 100 or p_impact is null or p_impact not between 0 and 100
    or p_novelty is null or p_novelty not between 0 and 100 or p_unexpected is null or p_unexpected not between 0 and 100
    or (p_attention is not null and p_attention not between 0 and 100)
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid score input'; end if;
  if (p_attention is null and p_attention_evidence is not null)
    or (p_attention is not null and (p_attention_evidence is null or length(trim(p_attention_evidence)) not between 1 and 1000)) then
    raise exception 'attention evidence required'; end if;
  if jsonb_typeof(p_reasons) is distinct from 'object'
    or not (p_reasons ?& array['technical_breakthrough','future_impact','novelty','attention','unexpectedness'])
    or p_reasons - array['technical_breakthrough','future_impact','novelty','attention','unexpectedness'] <> '{}'::jsonb then
    raise exception 'invalid score reasons'; end if;
  foreach key in array array['technical_breakthrough','future_impact','novelty','unexpectedness'] loop
    if jsonb_typeof(p_reasons->key) is distinct from 'string' or length(trim(p_reasons->>key)) not between 1 and 1000 then
      raise exception 'invalid score reasons'; end if;
  end loop;
  if (p_attention is null and p_reasons->'attention' is distinct from 'null'::jsonb)
    or (p_attention is not null and (jsonb_typeof(p_reasons->'attention') is distinct from 'string'
      or length(trim(p_reasons->>'attention')) not between 1 and 1000)) then raise exception 'invalid attention reason'; end if;
  select version into actual_version from public.stories where id=p_story for update;
  if actual_version is null then raise exception 'story not found'; end if;
  select * into prior from public.editorial_score_inputs where id=p_id;
  if prior.id is not null then
    if prior.story_id is distinct from p_story or prior.revision_id is distinct from p_revision or prior.story_version is distinct from p_version
      or prior.technical_breakthrough is distinct from p_technical or prior.future_impact is distinct from p_impact
      or prior.novelty is distinct from p_novelty or prior.attention is distinct from p_attention or prior.unexpectedness is distinct from p_unexpected
      or prior.reasons is distinct from p_reasons or prior.attention_evidence is distinct from p_attention_evidence
      or prior.editorial_reason is distinct from p_reason or prior.created_by is distinct from auth.uid() then raise exception 'score input identity conflict'; end if;
    return false;
  end if;
  if actual_version<>p_version then raise exception 'story version conflict'; end if;
  if p_revision is distinct from (select id from public.story_revisions where story_id=p_story order by revision_number desc limit 1) then
    raise exception 'revision is not latest'; end if;
  if exists(select 1 from public.editorial_reviews where revision_id=p_revision) then raise exception 'reviewed revision is immutable'; end if;
  insert into public.editorial_score_inputs(id,story_id,revision_id,story_version,technical_breakthrough,future_impact,novelty,attention,unexpectedness,reasons,attention_evidence,editorial_reason,created_by)
    values(p_id,p_story,p_revision,p_version,p_technical,p_impact,p_novelty,p_attention,p_unexpected,p_reasons,p_attention_evidence,p_reason,auth.uid());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'record_score_input','story_revision',p_revision,trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editor_create_source(p_name text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_name is null or length(trim(p_name)) = 0 or length(p_name) > 200 then raise exception 'invalid source name'; end if;
  if p_reason is null or length(trim(p_reason)) = 0 then raise exception 'reason required'; end if;
  insert into public.sources(name) values (trim(p_name)) returning id into sid;
  insert into public.audit_logs(actor_id, action, resource_type, resource_id, reason)
    values (auth.uid(), 'create', 'source', sid, p_reason);
  return sid;
end $$;



CREATE FUNCTION public.editor_create_story(p_slug text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare sid uuid;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_slug is null or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'invalid slug'; end if;
  if p_reason is null or length(trim(p_reason)) = 0 then raise exception 'reason required'; end if;
  insert into public.stories(slug) values (p_slug) returning id into sid;
  insert into public.audit_logs(actor_id, action, resource_type, resource_id, reason)
    values (auth.uid(), 'create', 'story', sid, p_reason);
  return sid;
end $_$;



CREATE FUNCTION public.editor_decide_candidate(p_candidate uuid, p_expected_version integer, p_decision text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare c public.editor_candidate_pairs%rowtype;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_decision is null or p_decision not in ('same_event', 'different_event', 'needs_evidence') then raise exception 'invalid decision'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reason required'; end if;
  select * into c from public.editor_candidate_pairs where id = p_candidate for update;
  if c.id is null or p_expected_version is null or c.version <> p_expected_version then raise exception 'candidate version conflict'; end if;
  perform public.lock_candidate_sources(c.first_article_id, c.second_article_id);
  insert into public.editor_candidate_decisions(candidate_id, candidate_version, decision, reason, reviewer_id)
    values (c.id, c.version, p_decision, trim(p_reason), auth.uid());
  update public.editor_candidate_pairs set version = version + 1 where id = c.id;
  insert into public.audit_logs(actor_id, action, resource_type, resource_id, reason)
    values (auth.uid(), 'decide', 'candidate_pair', c.id, trim(p_reason));
end $$;



CREATE FUNCTION public.editor_disable_ai_model_route(p_route uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null or p_route is null
  or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'AI operator and reason required'; end if;
 update public.ai_model_routes set enabled=false where id=p_route and enabled;
 if not found then return false; end if;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'disable_ai_model_route','ai_model_route',p_route,trim(p_reason));
 return true;
end $$;



CREATE FUNCTION public.editor_execution_safety_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null then raise exception 'AI operator required'; end if;
 return jsonb_build_object('stopped',(select stopped from public.ai_execution_control where singleton),
  'unresolved',coalesce((select jsonb_agg(jsonb_build_object('request_id',i.request_id,'reason',i.reason,'created_at',i.created_at) order by i.created_at)
   from public.ai_execution_safety_incidents i where not exists(select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id)),'[]'::jsonb),
  'unobserved',coalesce((select jsonb_agg(jsonb_build_object('request_id',p.request_id,'checked_at',p.state_changed_at) order by p.state_changed_at)
   from public.ai_request_preparations p where p.state='checked' and not exists(select 1 from public.ai_execution_observations e where e.request_id=p.request_id)),'[]'::jsonb));
end $$;



CREATE FUNCTION public.editor_flag_checked_ai_unknown(p_request uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare obs record;
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null then raise exception 'AI operator access required'; end if;
 if current_setting('transaction_isolation')<>'read committed' or p_request is null or p_reason is null
  or length(trim(p_reason)) not between 1 and 1000 then raise exception 'request and reason required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 if not exists(select 1 from public.ai_request_preparations where request_id=p_request and state='checked') then raise exception 'checked request required'; end if;
 if exists(select 1 from public.ai_execution_observations where request_id=p_request and outcome='unknown') then return false; end if;
 if exists(select 1 from public.ai_execution_observations where request_id=p_request) then raise exception 'execution already recorded'; end if;
 select * into obs from public.ai_record_bounded_execution(p_request,null,null,null,null,null,'unknown',0);
 if obs.status is distinct from 'unknown' or obs.triggered_halt is distinct from true or obs.inserted is distinct from true
 then raise exception 'uncertain execution could not be recorded'; end if;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'flag_unknown_execution','ai_request',p_request,trim(p_reason));
 return true;
end $$;



CREATE FUNCTION public.editor_get_article_body(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if not public.is_active_editor() then raise exception 'editor required'; end if;
 if not public.article_body_available(p_id) then return null; end if;
 return (select jsonb_build_object('snapshot_id',b.id,'body',b.body,'sha256',r.body_sha256,'original_url',r.original_url,'fetched_at',r.fetched_at)
 from public.article_body_snapshots b join public.article_body_receipts r on r.id=b.id where b.id=p_id);
end $$;



CREATE FUNCTION public.editor_get_article_selection(p_draft uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result jsonb;
begin
 if not public.is_active_editor() then raise exception 'editor required'; end if;
 if public.editor_get_full_article_draft(p_draft) is null then return null; end if;
 select s.result into result from public.article_full_drafts d
 join public.ai_request_identities i on i.request_id=d.request_id
 join public.article_selection_decisions s on s.job_id=i.job_id
 where d.id=p_draft and s.decision='SELECT';
 return result;
end $$;



CREATE FUNCTION public.editor_get_bilingual_channels(p_batch uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.story_bilingual_batches%rowtype; result jsonb;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  select * into b from public.story_bilingual_batches where id=p_batch;
  if b.id is null then raise exception 'bilingual batch unavailable'; end if;
  if not public.editor_revision_sources_available(b.zh_revision_id) or not public.editor_revision_sources_available(b.en_revision_id)
    then raise exception 'source permission unavailable'; end if;
  select jsonb_build_object('assignment_id',a.id,'primary',a.primary_channel,'secondary',a.secondary_channels,'domains',a.technical_domains,
    'actor_id',a.actor_id,'created_at',a.created_at) into result from public.bilingual_channel_assignments a where a.batch_id=p_batch order by a.id desc limit 1;
  return result;
end $$;



CREATE FUNCTION public.editor_get_bilingual_state(p_story uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result jsonb;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  select jsonb_build_object(
    'status',s.bilingual_translation_status,
    'locales',coalesce((select jsonb_agg(jsonb_build_object('revision_id',l.revision_id,'locale',l.locale)
      order by r.revision_number desc) from public.story_revision_locales l
      join public.story_revisions r on r.id=l.revision_id where l.story_id=s.id),'[]'::jsonb),
    'batches',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'zh_revision_id',b.zh_revision_id,
      'en_revision_id',b.en_revision_id,'created_at',b.created_at) order by b.created_at desc,b.id desc)
      from public.story_bilingual_batches b where b.story_id=s.id),'[]'::jsonb))
    into result from public.stories s where s.id=p_story;
  return result;
end $$;



CREATE FUNCTION public.editor_get_bilingual_uncertainty(p_batch uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.story_bilingual_batches%rowtype; result jsonb;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  select * into b from public.story_bilingual_batches where id=p_batch;
  if b.id is null then raise exception 'batch unavailable'; end if;
  if not public.editor_revision_sources_available(b.zh_revision_id) or not public.editor_revision_sources_available(b.en_revision_id)
    then raise exception 'source permission unavailable'; end if;
  select jsonb_build_object('zh',n.zh,'en',n.en) into result from public.bilingual_uncertainty_notes n where n.batch_id=b.id;
  return result;
end $$;



CREATE FUNCTION public.editor_get_full_article_draft(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if not public.is_active_editor() then raise exception 'editor required'; end if;
 return (select jsonb_build_object('id',d.id,'status',d.status,'content',d.content,'snapshot_id',d.snapshot_id,'summary',(select jsonb_build_object('summary_id',sr.id,'request_id',sr.request_id,'content',ss.content,'content_sha256',sr.content_sha256) from public.article_body_request_context c join public.article_body_summary_receipts sr on sr.id=c.summary_id join public.article_body_summaries ss on ss.id=sr.id where c.request_id=d.request_id))
 from public.article_full_drafts d join public.article_body_requests r on r.request_id=d.request_id
 where public.article_stage_accessible(d.request_id) and d.id=p_id and d.expires_at>statement_timestamp() and public.article_body_available(d.snapshot_id)
 and not exists(select 1 from unnest(r.grant_ids) gid where not public.article_body_grant_live(gid)));
end $$;



CREATE FUNCTION public.editor_get_revision_discovery(p_revision uuid) RETURNS TABLE(category text, score_id uuid, created_at timestamp with time zone, actor_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select d.category,d.score_id,d.created_at,d.actor_id from public.revision_discovery d where d.revision_id=p_revision;
end $$;



CREATE FUNCTION public.editor_get_story(p_story uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result jsonb;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  select jsonb_build_object('id',s.id,'slug',s.slug,'version',s.version,'visibility',s.visibility,
    'workflow_status',s.workflow_status,'public_revision_id',s.public_revision_id,
    'revisions',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'number',r.revision_number,
      'source_access_restricted',not gate.available,
      'title',case when gate.available then r.title else '[Unavailable: source permission or story association]' end,
      'summary',case when gate.available then r.summary else '[Unavailable: source permission or story association]' end,
      'claims',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,
        'text',case when gate.available then c.claim_text else '[Unavailable: source permission or story association]' end,'status',c.status,
        'evidence',case when gate.available then coalesce((select jsonb_agg(jsonb_build_object('article_id',e.article_id,'relation',e.relation,
          'reference',e.evidence_reference,'verified_by',e.verified_by)) from public.claim_evidence e where e.claim_id=c.id),'[]'::jsonb) else '[]'::jsonb end))
        from public.claims c where c.revision_id=r.id),'[]'::jsonb),
      'reviews',coalesce((select jsonb_agg(jsonb_build_object('reviewer_id',er.reviewer_id,'decision',er.decision,
        'reviewed_at',er.reviewed_at,'notes',case when gate.available then er.notes else null end) order by er.review_order)
        from public.editorial_reviews er where er.revision_id=r.id),'[]'::jsonb)) order by r.revision_number desc)
      from public.story_revisions r cross join lateral (select public.editor_revision_sources_available(r.id) available) gate where r.story_id=s.id),'[]'::jsonb))
    into result from public.stories s where s.id=p_story;
  return result;
end $$;



CREATE FUNCTION public.editor_get_translation_proposal(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result jsonb;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  select p.content into result from public.translation_proposals p join public.translation_proposal_receipts r on r.id=p.id
    join public.translation_retention_control ctl on ctl.singleton and not ctl.restore_quarantine
    where p.id=p_id and p.expires_at>statement_timestamp() and public.translation_request_accessible(r.request_id);
  return result;
end $$;



CREATE FUNCTION public.editor_grant_article_body(p_article uuid, p_version integer, p_action text, p_region text, p_evidence text, p_expires timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid; p public.source_policies%rowtype; result uuid;
begin
 if not public.editor_can_review_provider_grants() or current_setting('transaction_isolation')<>'read committed' then raise exception 'source reviewer required'; end if;
 select source_id into sid from public.articles where id=p_article;
 perform 1 from public.sources where id=sid for update;
 select * into p from public.source_policies where source_id=sid order by version desc limit 1;
 if p.id is null or p.version is distinct from p_version or p.policy_status<>'approved' or not p.access_allowed
 or p.reviewed_by is null or p.reviewed_at is null or p.policy_evidence='{}'::jsonb
 or (p.permission_expires_at is not null and p.permission_expires_at<=clock_timestamp())
 or (p_action in ('store','store_draft','store_summary') and not p.fulltext_storage_allowed)
 or (p_action in ('editor_display','display_draft','display_summary') and not p.display_allowed)
 or (p_action in ('process_deepseek','process_summary_deepseek') and not p.ai_processing_allowed)
 or p_expires is null or p_expires<=clock_timestamp() or p_expires>clock_timestamp()+interval '30 days'
 or (p.permission_expires_at is not null and p_expires>p.permission_expires_at) then raise exception 'invalid current body policy'; end if;
 -- Article/action/region grants narrow existing source-wide permission flags.
 insert into public.article_body_grants(policy_id,article_id,action,region,evidence,expires_at,reviewed_by)
 values(p.id,p_article,p_action,p_region,p_evidence,p_expires,auth.uid()) returning id into result;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'grant_article_body','article',p_article,p_evidence);
 return result;
end $$;



CREATE FUNCTION public.editor_grant_classification(p_source uuid, p_version integer, p_provider text, p_region text, p_action text, p_evidence text, p_expires timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare p public.source_policies%rowtype; result uuid;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  if p_source is null or p_version is null or p_provider is null or p_region is null or p_region !~ '^[a-z0-9-]{2,40}$'
    or p_action is null or p_action not in ('store','editor_display') or p_evidence is null or length(trim(p_evidence)) not between 1 and 1000
    or p_expires is null or p_expires<=clock_timestamp() or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid classification permission'; end if;
  perform 1 from public.sources where id=p_source for update;
  select * into p from public.source_policies where source_id=p_source order by version desc limit 1;
  if p.id is null or p.version<>p_version or p.policy_status<>'approved' or p.reviewed_by is null or p.reviewed_at is null
    or p.policy_evidence='{}'::jsonb or (p.permission_expires_at is not null and p.permission_expires_at<=clock_timestamp()) then raise exception 'source policy unavailable'; end if;
  if not exists(select 1 from public.ai_provider_catalog where name=p_provider) then raise exception 'provider unavailable'; end if;
  if exists(select 1 from public.classification_grants g where g.policy_id=p.id and g.provider=p_provider and g.region=p_region and g.action=p_action
    and g.expires_at>clock_timestamp() and not exists(select 1 from public.classification_grant_revocations r where r.grant_id=g.id)) then raise exception 'permission already active'; end if;
  insert into public.classification_grants(policy_id,provider,region,action,evidence,expires_at,reviewed_by)
    values(p.id,p_provider,p_region,p_action,trim(p_evidence),p_expires,auth.uid()) returning id into result;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'grant_classification','source',p_source,trim(p_reason));
