CREATE FUNCTION public.editor_grant_derived_claim(p_source uuid, p_version integer, p_provider text, p_region text, p_action text, p_evidence text, p_expires timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare p public.source_policies%rowtype; result uuid;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  if p_source is null or p_version is null or p_provider is null or p_region is null or p_region !~ '^[a-z0-9-]{2,40}$'
    or p_action is null or p_action not in ('store','editor_display') or p_evidence is null or length(trim(p_evidence)) not between 1 and 1000
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 or p_expires is null or p_expires<=clock_timestamp()
    then raise exception 'invalid derived claim permission'; end if;
  perform 1 from public.sources where id=p_source for update;
  if not found then raise exception 'source unavailable'; end if;
  select * into p from public.source_policies where source_id=p_source order by version desc limit 1;
  if p.version is distinct from p_version then raise exception 'source policy version conflict'; end if;
  if p.policy_status<>'approved' or p.reviewed_by is null or p.reviewed_at is null or p.policy_evidence='{}'::jsonb
    or (p.permission_expires_at is not null and p.permission_expires_at<=clock_timestamp())
    then raise exception 'source policy unavailable'; end if;
  if not exists(select 1 from public.ai_provider_catalog where name=p_provider) then raise exception 'provider not registered'; end if;
  if exists(select 1 from public.ai_derived_claim_grants g where g.policy_id=p.id and g.provider=p_provider
    and g.processing_region=p_region and g.permitted_action=p_action and g.expires_at>clock_timestamp()
    and not exists(select 1 from public.ai_derived_claim_revocations r where r.grant_id=g.id)) then
    raise exception 'permission already active'; end if;
  insert into public.ai_derived_claim_grants(policy_id,provider,processing_region,permitted_action,evidence,expires_at,reviewed_by)
    values(p.id,p_provider,p_region,p_action,trim(p_evidence),p_expires,auth.uid()) returning id into result;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'grant_ai_derived_claim','source',p_source,trim(p_reason));
  return result;
end $_$;



CREATE FUNCTION public.editor_grant_source_body_rule(p_source uuid, p_version integer, p_action text, p_region text, p_evidence text, p_expires timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare p public.source_policies%rowtype; result uuid;
begin
 if public.editor_can_review_provider_grants() is distinct from true or auth.uid() is null
  or current_setting('transaction_isolation')<>'read committed' then raise exception 'source reviewer required'; end if;
 if p_action is null or p_action not in ('fetch','store','editor_display','process_summary_deepseek','store_summary','display_summary','process_deepseek','store_draft','display_draft')
  or p_region is null or p_region !~ '^[a-z0-9-]{2,40}$' or p_evidence is null or length(trim(p_evidence)) not between 1 and 4000
  or p_expires is null or p_expires<=clock_timestamp() or p_expires>clock_timestamp()+interval '30 days'
 then raise exception 'invalid source body rule'; end if;
 perform 1 from public.sources where id=p_source for update;
 select * into p from public.source_policies where source_id=p_source order by version desc limit 1;
 if p.id is null or p.version is distinct from p_version or p.policy_status<>'approved' or not p.access_allowed
  or p.reviewed_by is null or p.reviewed_at is null or p.policy_evidence='{}'::jsonb
  or (p.permission_expires_at is not null and (p.permission_expires_at<=clock_timestamp() or p_expires>p.permission_expires_at))
  or (p_action in ('store','store_summary','store_draft') and not p.fulltext_storage_allowed)
  or (p_action in ('editor_display','display_summary','display_draft') and not p.display_allowed)
  or (p_action in ('process_deepseek','process_summary_deepseek') and not p.ai_processing_allowed)
 then raise exception 'current source body permission unavailable'; end if;
 insert into public.article_body_source_rules(policy_id,action,region,evidence,expires_at,reviewed_by)
 values(p.id,p_action,p_region,trim(p_evidence),p_expires,auth.uid()) returning id into result;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'grant_source_body_rule','source_policy',p.id,trim(p_evidence));
 return result;
end $_$;



