CREATE FUNCTION public.editor_grant_translation_scope(p_source uuid, p_version integer, p_provider text, p_region text, p_field text, p_action text, p_evidence text, p_expires timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare p public.source_policies%rowtype; result uuid;
begin
  if current_setting('transaction_isolation') <> 'read committed' or not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  if p_source is null or p_version is null or p_provider is null or p_region is null or p_region !~ '^[a-z0-9-]{2,40}$'
    or p_field is null or p_field not in ('title','summary','claims') or p_action is null or p_action not in ('process','store','editor_display')
    or p_evidence is null or length(trim(p_evidence)) not between 1 and 1000 or p_expires is null or p_expires<=clock_timestamp()
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid translation permission'; end if;
  perform 1 from public.sources where id=p_source for update;
