  if p.id is null or p.version<>p_version or p.policy_status<>'approved' or p.reviewed_by is null or p.reviewed_at is null
    or jsonb_typeof(p.policy_evidence)<>'object' or p.policy_evidence='{}'::jsonb
    or (p.permission_expires_at is not null and p.permission_expires_at<=clock_timestamp()) then raise exception 'source policy unavailable'; end if;
  if not exists(select 1 from public.ai_provider_catalog where name=p_provider) then raise exception 'provider unavailable'; end if;
  if exists(select 1 from public.translation_scope_grants g where g.policy_id=p.id and g.provider=p_provider and g.processing_region=p_region
    and g.field_name=p_field and g.permitted_action=p_action and g.expires_at>clock_timestamp()
    and not exists(select 1 from public.translation_scope_revocations r where r.grant_id=g.id)) then raise exception 'permission already active'; end if;
  insert into public.translation_scope_grants(policy_id,provider,processing_region,field_name,permitted_action,evidence,expires_at,reviewed_by)
    values(p.id,p_provider,p_region,p_field,p_action,trim(p_evidence),p_expires,auth.uid()) returning id into result;
