CREATE FUNCTION public.editor_import_classification(p_id uuid, p_article uuid, p_category uuid, p_provider text, p_region text, p_expires timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prior public.classification_proposals%rowtype; s record; fresh timestamptz; quarantined boolean;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_article is null or p_category is null or p_provider is null or p_region is null or p_expires is null or p_expires<=clock_timestamp() then raise exception 'invalid proposal'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7742));
  select last_sweep_at,restore_quarantine into fresh,quarantined from public.classification_retention_control where singleton for update;
  if quarantined is distinct from false or fresh is null or fresh>clock_timestamp() or fresh<=clock_timestamp()-interval '5 minutes'
     or exists(select 1 from public.classification_proposals where expires_at<=clock_timestamp()) then raise exception 'classification cleanup unavailable'; end if;
  select * into s from public.lock_classification_scope(p_article,p_provider,p_region,'store');
  perform 1 from public.categories where id=p_category and active for share;
  if not found or p_expires>s.deadline or p_expires<=clock_timestamp() then raise exception 'classification category or expiry unavailable'; end if;
  select * into prior from public.classification_proposals where id=p_id;
  if found then
    if prior.article_id<>p_article or prior.category_id<>p_category or prior.provider<>p_provider or prior.region<>p_region
       or prior.expires_at<>p_expires or prior.created_by<>auth.uid() or prior.policy_id<>s.policy_id
       or prior.provider_grant_id<>s.provider_grant_id or prior.title_sha256<>s.title_sha256 then raise exception 'proposal identity conflict'; end if;
    return false;
  end if;
  if exists(select 1 from public.classification_receipts where id=p_id) then raise exception 'proposal cannot be restored'; end if;
  insert into public.classification_receipts(id,created_by) values(p_id,auth.uid());
  insert into public.classification_proposals(id,article_id,category_id,policy_id,provider_grant_id,provider,region,title_sha256,expires_at,created_by)
    values(p_id,p_article,p_category,s.policy_id,s.provider_grant_id,p_provider,p_region,s.title_sha256,p_expires,auth.uid());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'import_classification','classification_proposal',p_id,'manual import; provenance unverified');
  return true;
end $$;



CREATE FUNCTION public.editor_import_summary(p_id uuid, p_fact uuid, p_provider text, p_region text, p_content jsonb, p_expires timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prior public.summary_proposals%rowtype; fresh timestamptz; quarantined boolean; deadline timestamptz;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_fact is null or p_provider is null or p_region is null or p_expires is null or p_expires<=clock_timestamp()
    or not public.summary_valid_content(p_content,p_fact) then raise exception 'invalid summary proposal'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7731));
  select last_sweep_at,restore_quarantine into fresh,quarantined from public.summary_retention_control where singleton for update;
  if quarantined is distinct from false or fresh is null or fresh>clock_timestamp() or fresh<=clock_timestamp()-interval '5 minutes'
     or exists(select 1 from public.summary_proposals where expires_at<=clock_timestamp()) then raise exception 'summary cleanup unavailable'; end if;
  perform public.lock_summary_fact(p_fact);
  deadline:=public.summary_scope_deadline(p_fact,p_provider,p_region,'store');
  if deadline is null or deadline<=clock_timestamp() or p_expires>deadline or p_expires<=clock_timestamp() then raise exception 'summary permission unavailable'; end if;
  select * into prior from public.summary_proposals where id=p_id;
  if found then
    if prior.fact_id<>p_fact or prior.provider<>p_provider or prior.region<>p_region or prior.content<>p_content
       or prior.expires_at<>p_expires or prior.created_by<>auth.uid() then raise exception 'summary identity conflict'; end if;
    return false;
  end if;
  if exists(select 1 from public.summary_receipts where id=p_id) then raise exception 'summary cannot be restored'; end if;
  insert into public.summary_receipts(id,created_by) values(p_id,auth.uid());
  insert into public.summary_proposals(id,fact_id,provider,region,content,expires_at,created_by) values(p_id,p_fact,p_provider,p_region,p_content,p_expires,auth.uid());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'import_summary','summary_proposal',p_id,'manual import; provenance unverified');
  return true;
end $$;



CREATE FUNCTION public.editor_import_translation(p_proposal uuid, p_version integer, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare rec record; content jsonb; new_revision uuid; new_claim uuid; source_claim record; segment jsonb;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_proposal is null or p_version is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid import'; end if;
  select t.*,r.request_id,prep.processor,prep.processing_region into rec from public.translation_proposal_receipts r
    join public.translation_requests req on req.request_id=r.request_id join public.translation_task_intents t on t.id=req.intent_id
    join public.ai_request_preparations prep on prep.request_id=req.request_id where r.id=p_proposal;
  if rec.request_id is null then raise exception 'translation proposal unavailable'; end if;
  perform public.ai_lock_translation_scope(rec.source_revision_id,rec.processor,rec.processing_region,array['process','store','editor_display']);
  content:=public.editor_get_translation_proposal(p_proposal);
  if content is null or not public.translation_valid_proposal(rec.request_id,content) then raise exception 'translation proposal unavailable'; end if;
  if exists(select 1 from public.translation_revision_imports where proposal_id=p_proposal or request_id=rec.request_id)
    then raise exception 'translation already imported'; end if;
  if rec.source_revision_id is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id
    where l.story_id=rec.story_id and l.locale=rec.source_locale order by r.revision_number desc limit 1) then raise exception 'source revision stale'; end if;
  new_revision:=public.editor_create_revision(rec.story_id,p_version,content->>'headline',content->'segments'->0->>'text',p_reason);
  insert into public.translation_revision_imports(target_revision_id,proposal_id,request_id,source_revision_id,imported_by)
    values(new_revision,p_proposal,rec.request_id,rec.source_revision_id,auth.uid());
  for source_claim in select c.id from public.claims c where c.revision_id=rec.source_revision_id order by c.id loop
    select x into segment from jsonb_array_elements(content->'segments') x where x->>'segment_id'=source_claim.id::text;
    insert into public.claims(revision_id,claim_text,status) values(new_revision,segment->>'text','unverified') returning id into new_claim;
    insert into public.translation_claim_imports(target_claim_id,source_claim_id,target_revision_id) values(new_claim,source_claim.id,new_revision);
    insert into public.claim_evidence(claim_id,article_id,relation,evidence_reference)
      select new_claim,article_id,relation,evidence_reference from public.claim_evidence where claim_id=source_claim.id;
  end loop;
  perform public.editor_bind_revision_locale(rec.story_id,new_revision,rec.target_locale,p_version+1,p_reason);
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'import_translation','story_revision',new_revision,trim(p_reason));
  return new_revision;
end $$;



CREATE FUNCTION public.editor_latest_review(p_revision uuid) RETURNS TABLE(id uuid, decision text, reviewed_at timestamp with time zone, reviewer_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select r.id,r.decision,r.reviewed_at,r.reviewer_id from public.editorial_reviews r where r.revision_id=p_revision order by r.review_order desc limit 1;
end $$;



CREATE FUNCTION public.editor_link_retracted_duplicate(p_id uuid, p_source uuid, p_source_version integer, p_target uuid, p_target_version integer, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare s public.stories%rowtype; t public.stories%rowtype; old public.story_duplicate_links%rowtype;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_source is null or p_target is null or p_source=p_target or p_source_version is null or p_target_version is null
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid duplicate link'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,76130));
  perform id from public.stories where id in(p_source,p_target) order by id for update;
  select * into s from public.stories where id=p_source;
  select * into t from public.stories where id=p_target;
  if s.id is null or t.id is null then raise exception 'story unavailable'; end if;
  select * into old from public.story_duplicate_links where id=p_id;
  if found then
    if old.source_story_id is distinct from p_source or old.target_story_id is distinct from p_target or old.source_version is distinct from p_source_version
      or old.target_version is distinct from p_target_version or old.actor_id is distinct from auth.uid() or old.reason is distinct from trim(p_reason)
      then raise exception 'duplicate link identity conflict'; end if;
    return false;
  end if;
  if s.version<>p_source_version or t.version<>p_target_version then raise exception 'story version conflict'; end if;
  if exists(select 1 from public.story_duplicate_links d where d.source_story_id=p_source and not exists(select 1 from public.story_duplicate_link_revocations r where r.link_id=d.id)) then raise exception 'active duplicate link exists'; end if;
  if s.visibility<>'retracted' or not exists(select 1 from public.retraction_notices n join public.retraction_approvals a on a.notice_id=n.id
      where n.id=s.public_retraction_id and n.story_id=s.id and n.revision_id=s.public_revision_id) then raise exception 'approved retraction required'; end if;
  if t.visibility<>'public' or t.archived_at is not null then raise exception 'public target required'; end if;
  perform public.lock_revision_sources(t.public_revision_id);
  if not public.revision_is_eligible(t.id,t.public_revision_id) then raise exception 'target not eligible'; end if;
  insert into public.story_duplicate_links(id,source_story_id,target_story_id,notice_id,source_version,target_version,actor_id,reason)
    values(p_id,p_source,p_target,s.public_retraction_id,p_source_version,p_target_version,auth.uid(),trim(p_reason));
  update public.stories set version=version+1 where id=p_source;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'link_retracted_duplicate','story',p_source,trim(p_reason));
  if not public.revision_is_eligible(t.id,t.public_revision_id) then raise exception 'target permission expired'; end if;
  return true;
end $$;



CREATE FUNCTION public.editor_list_ai_billing() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.editor_can_review_ai_billing() then raise exception 'AI billing reviewer access required'; end if;
  return jsonb_build_object(
    'prices',coalesce((select jsonb_agg(row_to_json(x) order by x.valid_until desc,x.id) from (
      select s.id,s.provider,s.model_id,s.price_version,s.input_nanos_per_million::text,s.output_nanos_per_million::text,
        s.fixed_request_nanos::text,s.valid_from,s.valid_until,s.evidence,exists(select 1 from public.ai_price_withdrawals w where w.schedule_id=s.id) as withdrawn
      from public.ai_price_schedules s order by s.valid_until desc,s.id limit 100) x),'[]'::jsonb),
    'bounds',coalesce((select jsonb_agg(row_to_json(x) order by x.valid_until desc,x.id) from (
      select b.id,b.schedule_id,b.processing_region,b.max_billable_input_tokens,b.max_output_tokens,b.valid_from,b.valid_until,b.evidence,
        exists(select 1 from public.ai_billing_bound_withdrawals w where w.bound_id=b.id) as withdrawn
      from public.ai_billing_bounds b order by b.valid_until desc,b.id limit 100) x),'[]'::jsonb));
end $$;



CREATE FUNCTION public.editor_list_ai_claim_proposals(p_article uuid) RETURNS TABLE(request_id uuid, provider text, processing_region text, content jsonb, expires_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if not exists(select 1 from public.ai_claim_retention_control where singleton and not restore_quarantine) then raise exception 'claim restore quarantine active'; end if;
  return query select * from public.editor_list_ai_claim_proposals_before_restore_gate(p_article);
end $$;



CREATE FUNCTION public.editor_list_ai_claim_proposals_before_restore_gate(p_article uuid) RETURNS TABLE(request_id uuid, provider text, processing_region text, content jsonb, expires_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select c.request_id,prep.processor,prep.processing_region,c.content,c.expires_at,c.created_at
    from public.ai_claim_proposals c join public.ai_request_preparations prep on prep.request_id=c.request_id
    where c.expires_at>statement_timestamp() and exists(select 1 from public.ai_request_preparation_inputs x where x.request_id=c.request_id and x.article_id=p_article)
      and not exists(select 1 from public.ai_request_preparation_inputs x join public.articles a on a.id=x.article_id
        left join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) p on true
        left join public.ai_provider_title_grants tg on tg.id=x.provider_grant_id
        where x.request_id=c.request_id and (p.id is distinct from x.policy_id or p.policy_status is distinct from 'approved'
          or p.reviewed_by is null or p.reviewed_at is null or p.policy_evidence='{}'::jsonb or not p.title_storage_allowed or not p.ai_processing_allowed
          or (p.permission_expires_at is not null and p.permission_expires_at<=statement_timestamp())
          or x.title_sha256 is distinct from encode(sha256(convert_to(a.title,'UTF8')),'hex')
          or tg.id is null or tg.policy_id is distinct from p.id or tg.provider is distinct from prep.processor or tg.processing_region is distinct from prep.processing_region
          or (tg.expires_at is not null and tg.expires_at<=statement_timestamp())
          or exists(select 1 from public.ai_provider_title_revocations tr where tr.grant_id=tg.id)
          or not exists(select 1 from public.ai_derived_claim_grants g where g.policy_id=p.id and g.provider=prep.processor
            and g.processing_region=prep.processing_region and g.permitted_action='store' and g.expires_at>statement_timestamp()
            and not exists(select 1 from public.ai_derived_claim_revocations r where r.grant_id=g.id))
          or not exists(select 1 from public.ai_derived_claim_grants g where g.policy_id=p.id and g.provider=prep.processor
            and g.processing_region=prep.processing_region and g.permitted_action='editor_display' and g.expires_at>statement_timestamp()
            and not exists(select 1 from public.ai_derived_claim_revocations r where r.grant_id=g.id))))
    order by c.created_at desc,c.request_id limit 20;
end $$;



CREATE FUNCTION public.editor_list_ai_claim_reviews(p_article uuid) RETURNS TABLE(request_id uuid, proposal_index integer, article_id uuid, decision text, reviewer_id uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select r.request_id,r.proposal_index,r.article_id,r.decision,r.reviewer_id,r.created_at
    from public.ai_claim_editor_reviews r join public.editor_list_ai_claim_proposals(p_article) p on p.request_id=r.request_id
    order by r.created_at desc,r.id limit 200;
end $$;



CREATE FUNCTION public.editor_list_ai_claim_reviews_v2(p_article uuid) RETURNS TABLE(review_id uuid, request_id uuid, proposal_index integer, article_id uuid, decision text, reviewer_id uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select r.id,r.request_id,r.proposal_index,r.article_id,r.decision,r.reviewer_id,r.created_at
    from public.ai_claim_editor_reviews r join public.editor_list_ai_claim_proposals(p_article) p on p.request_id=r.request_id
    order by r.created_at desc,r.id limit 200;
end $$;



CREATE FUNCTION public.editor_list_article_summaries(p_article uuid) RETURNS TABLE(proposal_id uuid, fact_id uuid, provider text, region text, content jsonb, origin text, expires_at timestamp with time zone, reviews jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select p.id,p.fact_id,p.provider,p.region,p.content,case when mr.request_id is null then p.origin else 'model_response_unverified' end,p.expires_at,
    coalesce((select jsonb_agg(jsonb_build_object('review_id',r.id,'decision',r.decision,'reviewer_id',r.reviewer_id,'created_at',r.created_at) order by r.created_at desc,r.id)
      from (select * from public.summary_reviews sr where sr.proposal_id=p.id order by sr.created_at desc,sr.id limit 100) r),'[]'::jsonb)
    from public.summary_proposals p join public.ai_verified_facts f on f.id=p.fact_id
    left join public.summary_model_receipts mr on mr.proposal_id=p.id
    where f.article_id=p_article and public.summary_visible(p) order by p.created_at desc,p.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_articles() RETURNS TABLE(id uuid, source_id uuid, title text, canonical_url text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select a.id, a.source_id, a.title,
    case when p.url_storage_allowed and p.link_display_allowed then a.canonical_url else null end
  from public.articles a join lateral (select * from public.source_policies sp where sp.source_id = a.source_id order by sp.version desc limit 1) p on true
  where public.candidate_title_allowed(a.id) order by a.created_at desc limit 100;
end $$;



CREATE FUNCTION public.editor_list_auto_article_tasks() RETURNS TABLE(job_id uuid, title text, status text, failure_code text, draft_id uuid, created_at timestamp with time zone, started_at timestamp with time zone, finished_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if public.is_active_editor() is distinct from true then raise exception 'editor access required'; end if;
 return query select t.job_id,case when public.candidate_title_allowed(a.id) then a.title else null end,
  t.status,t.failure_code,t.draft_id,t.created_at,t.started_at,t.finished_at
 from public.article_auto_tasks t join public.articles a on a.id=t.article_id order by t.created_at desc,t.job_id limit 100;
end $$;



CREATE FUNCTION public.editor_list_bilingual_retraction_notices(p_story uuid) RETURNS TABLE(id uuid, revision_id uuid, zh text, en text, approved_by uuid, approved_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select n.id,n.revision_id,bn.zh,n.notice,a.approved_by,a.approved_at
    from public.retraction_notices n join public.bilingual_retraction_notices bn on bn.notice_id=n.id
    left join public.retraction_approvals a on a.notice_id=n.id
    where n.story_id=p_story order by n.created_at desc,n.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_candidates() RETURNS TABLE(id uuid, version integer, first_title text, second_title text, decision text, decisions jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select c.id, c.version, a.title, b.title,
    (select d.decision from public.editor_candidate_decisions d where d.candidate_id = c.id order by d.candidate_version desc limit 1),
    coalesce((select jsonb_agg(jsonb_build_object('version', d.candidate_version, 'decision', d.decision,
      'reason', d.reason, 'reviewer_id', d.reviewer_id, 'created_at', d.created_at) order by d.candidate_version desc)
      from public.editor_candidate_decisions d where d.candidate_id = c.id), '[]'::jsonb)
  from public.editor_candidate_pairs c join public.articles a on a.id = c.first_article_id join public.articles b on b.id = c.second_article_id
  where public.candidate_title_allowed(a.id) and public.candidate_title_allowed(b.id)
  order by c.created_at desc, c.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_candidates_with_origin() RETURNS TABLE(id uuid, version integer, first_title text, second_title text, decision text, decisions jsonb, origin text, rule_version text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select c.id,c.version,c.first_title,c.second_title,c.decision,c.decisions,p.origin,p.rule_version
    from public.editor_list_candidates() c join public.editor_candidate_pairs p on p.id=c.id;
end $$;



CREATE FUNCTION public.editor_list_claim_evidence_classifications(p_revision uuid) RETURNS TABLE(claim_id uuid, category text, firsthand_article_id uuid, classified_by uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if not public.editor_revision_sources_available(p_revision) then raise exception 'source permission unavailable'; end if;
  return query select x.claim_id,x.category,x.firsthand_article_id,x.classified_by,x.created_at
    from public.claim_evidence_classifications x join public.claims c on c.id=x.claim_id
    where c.revision_id=p_revision order by x.claim_id;
end $$;



CREATE FUNCTION public.editor_list_classification_grants() RETURNS TABLE(grant_id uuid, source_id uuid, policy_version integer, provider text, region text, action text, evidence text, expires_at timestamp with time zone, revoked boolean, current_policy boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  return query select g.id,p.source_id,p.version,g.provider,g.region,g.action,g.evidence,g.expires_at,
    exists(select 1 from public.classification_grant_revocations r where r.grant_id=g.id),
    p.id=(select sp.id from public.source_policies sp where sp.source_id=p.source_id order by version desc limit 1)
    from public.classification_grants g join public.source_policies p on p.id=g.policy_id order by g.reviewed_at desc,g.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_classification_reviews(p_proposal uuid) RETURNS TABLE(review_id uuid, decision text, reviewer_id uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select r.id,r.decision,r.reviewer_id,r.created_at from public.classification_reviews r
    join public.classification_proposals p on p.id=r.proposal_id where p.id=p_proposal and public.classification_visible(p)
    order by r.created_at desc,r.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_classifications(p_article uuid) RETURNS TABLE(proposal_id uuid, article_id uuid, category_id uuid, category_name text, provider text, region text, origin text, expires_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select p.id,p.article_id,p.category_id,c.name,p.provider,p.region,
    case when r.request_id is null then p.origin else 'model_response_unverified' end,p.expires_at
    from public.classification_proposals p join public.categories c on c.id=p.category_id
    left join public.classification_model_receipts r on r.proposal_id=p.id
    where p.article_id=p_article and public.classification_visible(p)
      and (r.request_id is null or exists(select 1 from public.classification_processing_grants g
        where g.policy_id=p.policy_id and g.provider=p.provider and g.region=p.region and g.expires_at>statement_timestamp()
          and not exists(select 1 from public.classification_processing_revocations x where x.grant_id=g.id)))
    order by p.created_at desc,p.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_classifications_v2(p_article uuid) RETURNS TABLE(proposal_id uuid, article_id uuid, category_id uuid, category_name text, provider text, region text, origin text, expires_at timestamp with time zone, request_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select p.proposal_id,p.article_id,p.category_id,p.category_name,p.provider,p.region,p.origin,p.expires_at,r.request_id
    from public.editor_list_classifications(p_article) p left join public.classification_model_receipts r on r.proposal_id=p.proposal_id;
end $$;



CREATE FUNCTION public.editor_list_daily() RETURNS TABLE(selection_id uuid, story_id uuid, revision_id uuid, selection_day date, created_at timestamp with time zone, eligible boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select d.id,d.story_id,d.revision_id,d.selection_day,d.created_at,
    coalesce(s.visibility='public' and s.public_revision_id=d.revision_id and public.revision_is_eligible(s.id,d.revision_id),false)
    from public.daily_editorial_selections d join public.stories s on s.id=d.story_id
    where d.selection_day=(statement_timestamp() at time zone 'UTC')::date
      and not exists(select 1 from public.daily_selection_revocations v where v.selection_id=d.id)
    order by d.created_at,d.id limit 10;
end $$;



CREATE FUNCTION public.editor_list_derived_claim_grants() RETURNS TABLE(grant_id uuid, source_id uuid, policy_version integer, provider text, processing_region text, permitted_action text, evidence text, expires_at timestamp with time zone, revoked boolean, current_policy boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  return query select g.id,p.source_id,p.version,g.provider,g.processing_region,g.permitted_action,g.evidence,g.expires_at,
    exists(select 1 from public.ai_derived_claim_revocations r where r.grant_id=g.id),
    p.id=(select sp.id from public.source_policies sp where sp.source_id=p.source_id order by sp.version desc limit 1)
    from public.ai_derived_claim_grants g join public.source_policies p on p.id=g.policy_id order by g.reviewed_at desc,g.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_full_article_queue() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if not public.is_active_editor() then raise exception 'editor required'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('draft_id',q.draft_id,'story_id',q.story_id,'created_at',q.imported_at,
 'proposal',public.editor_get_full_article_draft(q.draft_id),'source',jsonb_build_object('url',r.original_url,'fetched_at',r.fetched_at,'sha256',r.body_sha256),
 'reviews',(select coalesce(jsonb_agg(jsonb_build_object('decision',v.decision,'reason',v.reason,'created_at',v.created_at) order by v.created_at),'[]'::jsonb) from public.article_full_reviews v where v.draft_id=q.draft_id)) order by q.imported_at desc)
 from (select * from public.article_full_review_queue order by imported_at desc limit 50) q
 join public.article_full_drafts d on d.id=q.draft_id join public.article_body_receipts r on r.id=d.snapshot_id
 where public.editor_get_full_article_draft(q.draft_id) is not null and not exists(select 1 from public.ai_article_publications published where published.draft_id=q.draft_id)),'[]'::jsonb);
end $$;



CREATE FUNCTION public.editor_list_full_article_revisions(p_draft uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if session_user<>'authenticator' or public.is_active_editor() is distinct from true then raise exception 'authenticated editor required'; end if;
 if public.editor_get_full_article_draft(p_draft) is null then raise exception 'original draft expired or unavailable'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'parent_revision_id',r.parent_revision_id,
 'revision_number',r.revision_number,'created_by',r.created_by,'created_at',r.created_at,'reason_code',r.reason_code,'content_sha256',r.content_sha256,
 'origin','editor_revision','content',c.content,'expires_at',c.expires_at,'status',c.status,
 'reviews',(select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'batch_id',v.batch_id,'decision',v.decision,'facts_checked',v.facts_checked,'originality_checked',v.originality_checked,'bilingual_checked',v.bilingual_checked,'created_at',v.created_at) order by v.id),'[]'::jsonb) from public.article_editor_revision_reviews v where v.revision_id=r.id),
 'public_authorization',(select jsonb_build_object('allowed',g.allowed,'expires_at',g.expires_at,'live',public.article_full_public_grant_live(g.id)) from public.article_full_public_grants g where g.revision_id=r.id order by g.id desc limit 1),
 'facts_checked',c.facts_checked,'originality_checked',c.originality_checked,'bilingual_checked',c.bilingual_checked) order by r.revision_number)
 from public.article_editor_revision_receipts r join public.article_editor_revision_content c on c.id=r.id
 join public.article_full_drafts d on d.id=r.draft_id
 where r.draft_id=p_draft and c.expires_at>statement_timestamp() and c.expires_at<=d.expires_at
 and r.content_sha256=encode(sha256(convert_to(c.content::text,'UTF8')),'hex')),'[]'::jsonb);
end $$;



CREATE FUNCTION public.editor_list_ingestion_dispatches() RETURNS TABLE(dispatch_id uuid, job_id uuid, source_id uuid, hostname text, checked_at timestamp with time zone, lease_expired boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() or not exists(select 1 from public.editors where user_id=auth.uid() and active and can_review_sources) then
    raise exception 'source reviewer access required';
  end if;
  return query select d.id,d.job_id,j.source_id,d.hostname,d.created_at,
    (j.lease_expires_at is null or j.lease_expires_at <= clock_timestamp())
    from public.ingestion_dispatches d join public.ingestion_jobs j on j.id=d.job_id
    where d.state='checked' order by d.created_at desc,d.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_ingestion_holds() RETURNS TABLE(hold_id uuid, source_id uuid, job_id uuid, reason text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() or not exists (select 1 from public.editors where user_id=auth.uid() and active and can_review_sources) then
    raise exception 'source reviewer access required';
  end if;
  return query select h.id,h.source_id,h.job_id,h.reason,h.created_at from public.ingestion_source_holds h
    where not exists (select 1 from public.ingestion_hold_releases r where r.hold_id=h.id)
    order by h.created_at desc,h.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_provider_title_grants() RETURNS TABLE(grant_id uuid, source_id uuid, policy_version integer, provider text, processing_region text, expires_at timestamp with time zone, revoked boolean, provider_enabled boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  return query select g.id,p.source_id,p.version,g.provider,g.processing_region,g.expires_at,r.grant_id is not null,c.enabled
    from public.sources s join lateral (select * from public.source_policies x where x.source_id=s.id order by x.version desc limit 1) p on true
    join public.ai_provider_title_grants g on g.policy_id=p.id join public.ai_provider_catalog c on c.name=g.provider
    left join public.ai_provider_title_revocations r on r.grant_id=g.id
    order by g.reviewed_at desc,g.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_public_reorganizations(p_story uuid) RETURNS TABLE(kind text, event_id uuid, source_story_id uuid, target_story_id uuid, actor_id uuid, reason text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select x.kind,x.event_id,x.source_story_id,x.target_story_id,x.actor_id,
    case when public.editor_story_sources_available(x.source_story_id) and public.editor_story_sources_available(x.target_story_id)
      and not exists(select 1 from public.story_retracted_branch_articles a where a.branch_id=x.event_id and not public.candidate_title_allowed(a.article_id))
      then x.reason else null end,x.created_at
    from public.editor_list_public_reorganizations_before_source_gate(p_story) x;
end $$;



CREATE FUNCTION public.editor_list_public_reorganizations_before_source_gate(p_story uuid) RETURNS TABLE(kind text, event_id uuid, source_story_id uuid, target_story_id uuid, actor_id uuid, reason text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select e.kind,e.event_id,e.source_story_id,e.target_story_id,e.actor_id,e.reason,e.created_at from (
    select case when exists(select 1 from public.story_duplicate_link_revocations r where r.link_id=d.id) then 'duplicate_revoked' else 'duplicate' end::text kind,d.id event_id,d.source_story_id,d.target_story_id,d.actor_id,d.reason,d.created_at from public.story_duplicate_links d
    union all
    select 'branch',b.id,b.source_story_id,b.target_story_id,b.actor_id,b.reason,b.created_at from public.story_retracted_branches b
  ) e where e.source_story_id=p_story or e.target_story_id=p_story order by e.created_at desc,e.event_id limit 100;
end $$;



CREATE FUNCTION public.editor_list_retraction_notices(p_story uuid) RETURNS TABLE(id uuid, revision_id uuid, notice text, created_by uuid, created_at timestamp with time zone, approved_by uuid, approved_at timestamp with time zone, is_current boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select n.id,n.revision_id,n.notice,n.created_by,n.created_at,a.approved_by,a.approved_at,
    coalesce(s.public_retraction_id=n.id and s.visibility='retracted',false)
    from public.retraction_notices n join public.stories s on s.id=n.story_id
    left join public.retraction_approvals a on a.notice_id=n.id
    where n.story_id=p_story order by n.created_at desc,n.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_rss_endpoints() RETURNS TABLE(endpoint_id uuid, source_id uuid, policy_version integer, feed_url text, min_interval_seconds integer, expires_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() or not exists(select 1 from public.editors where user_id=auth.uid() and active and can_review_sources) then
    raise exception 'source reviewer access required';
  end if;
  return query select e.id,p.source_id,p.version,e.feed_url,e.min_interval_seconds,e.expires_at
    from public.rss_endpoint_reviews e join public.source_policies p on p.id=e.policy_id
    where p.version=(select max(latest.version) from public.source_policies latest where latest.source_id=p.source_id)
    order by e.reviewed_at desc,e.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_rss_validator_permissions() RETURNS TABLE(endpoint_id uuid, evidence text, expires_at timestamp with time zone, revoked boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() or not exists(select 1 from public.editors where user_id=auth.uid() and active and can_review_sources) then raise exception 'source reviewer access required'; end if;
  return query select v.endpoint_id,v.evidence,v.expires_at,exists(select 1 from public.rss_validator_revocations r where r.endpoint_id=v.endpoint_id)
    from public.rss_validator_permissions v order by v.reviewed_at desc,v.endpoint_id limit 100;
end $$;



CREATE FUNCTION public.editor_list_score_inputs(p_revision uuid) RETURNS TABLE(input_id uuid, story_id uuid, story_version integer, technical_breakthrough integer, future_impact integer, novelty integer, attention integer, unexpectedness integer, reasons jsonb, attention_evidence text, score_id uuid, score integer, created_by uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if not public.editor_revision_sources_available(p_revision) then raise exception 'source display permission unavailable'; end if;
  return query select * from public.editor_list_score_inputs_before_source_gate(p_revision);
end $$;



CREATE FUNCTION public.editor_list_score_inputs_before_source_gate(p_revision uuid) RETURNS TABLE(input_id uuid, story_id uuid, story_version integer, technical_breakthrough integer, future_impact integer, novelty integer, attention integer, unexpectedness integer, reasons jsonb, attention_evidence text, score_id uuid, score integer, created_by uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select i.id,i.story_id,i.story_version,i.technical_breakthrough,i.future_impact,i.novelty,i.attention,
    i.unexpectedness,i.reasons,i.attention_evidence,s.id,s.holy_shit_score,i.created_by,i.created_at
    from public.editorial_score_inputs i left join public.story_scores s on s.assessment_id=i.id
    where i.revision_id=p_revision order by i.created_at desc,i.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_sources() RETURNS TABLE(id uuid, name text, policy_status text, policy_version integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select s.id, s.name, coalesce(p.policy_status, 'unreviewed'), p.version
    from public.sources s left join lateral (select sp.policy_status, sp.version from public.source_policies sp where sp.source_id = s.id order by sp.version desc limit 1) p on true
    order by s.created_at desc limit 100;
end $$;



CREATE FUNCTION public.editor_list_sources_with_ai_scope() RETURNS TABLE(id uuid, name text, policy_status text, policy_version integer, title_ai_processing_allowed boolean, ai_processing_region text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select s.id,s.name,coalesce(p.policy_status,'unreviewed'),p.version,
      coalesce(p.title_ai_processing_allowed,false),p.ai_processing_region
    from public.sources s left join lateral
      (select * from public.source_policies sp where sp.source_id=s.id order by sp.version desc limit 1) p on true
    order by s.created_at desc limit 100;
end $$;



CREATE FUNCTION public.editor_list_stories() RETURNS TABLE(id uuid, slug text, version integer, visibility text, workflow_status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select s.id, s.slug, s.version, s.visibility, s.workflow_status from public.stories s order by s.created_at desc limit 100;
end $$;



CREATE FUNCTION public.editor_list_story_merges(p_story uuid) RETURNS TABLE(event_id uuid, source_story_id uuid, target_story_id uuid, source_version integer, target_version integer, target_revision_number integer, article_count bigint, actor_id uuid, reason text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select x.event_id,x.source_story_id,x.target_story_id,x.source_version,x.target_version,x.target_revision_number,x.article_count,x.actor_id,
    case when x.article_count is not null and public.editor_story_sources_available(x.source_story_id) and public.editor_story_sources_available(x.target_story_id) then x.reason else null end,x.created_at
    from public.editor_list_story_merges_before_source_gate(p_story) x;
end $$;



CREATE FUNCTION public.editor_list_story_merges_before_source_gate(p_story uuid) RETURNS TABLE(event_id uuid, source_story_id uuid, target_story_id uuid, source_version integer, target_version integer, target_revision_number integer, article_count bigint, actor_id uuid, reason text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select e.id,e.source_story_id,e.target_story_id,e.source_version,e.target_version,e.target_revision_number,
    case when exists(select 1 from public.story_merge_articles m where m.event_id=e.id and not public.candidate_title_allowed(m.article_id))
      then null else (select count(*) from public.story_merge_articles m where m.event_id=e.id) end,e.actor_id,e.reason,e.created_at
    from public.story_merge_events e where e.source_story_id=p_story or e.target_story_id=p_story order by e.created_at desc,e.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_story_splits(p_story uuid) RETURNS TABLE(event_id uuid, source_story_id uuid, target_story_id uuid, source_version integer, source_revision_number integer, article_ids uuid[], original_relations jsonb, actor_id uuid, reason text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select x.event_id,x.source_story_id,x.target_story_id,x.source_version,x.source_revision_number,x.article_ids,x.original_relations,x.actor_id,
    case when x.article_ids is not null and public.editor_story_sources_available(x.source_story_id) and public.editor_story_sources_available(x.target_story_id) then x.reason else null end,x.created_at
    from public.editor_list_story_splits_before_source_gate(p_story) x;
end $$;



CREATE FUNCTION public.editor_list_story_splits_before_source_gate(p_story uuid) RETURNS TABLE(event_id uuid, source_story_id uuid, target_story_id uuid, source_version integer, source_revision_number integer, article_ids uuid[], original_relations jsonb, actor_id uuid, reason text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_story is null then raise exception 'story required'; end if;
  return query select e.id,e.source_story_id,e.target_story_id,e.source_version,e.source_revision_number,
    case when not exists(select 1 from public.story_split_articles a where a.event_id=e.id and not public.candidate_title_allowed(a.article_id))
      then (select array_agg(a.article_id order by a.article_id) from public.story_split_articles a where a.event_id=e.id) else null end,
    case when not exists(select 1 from public.story_split_articles a where a.event_id=e.id and not public.candidate_title_allowed(a.article_id))
      then (select jsonb_agg(jsonb_build_object('article_id',a.article_id,'reporting_role',a.reporting_role,'independence',a.independence,
        'syndicated_from_article_id',a.syndicated_from_article_id) order by a.article_id) from public.story_split_articles a where a.event_id=e.id) else null end,
    e.actor_id,e.reason,e.created_at from public.story_split_events e
    where e.source_story_id=p_story or e.target_story_id=p_story order by e.created_at desc,e.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_story_summaries(p_article uuid) RETURNS TABLE(proposal_id uuid, story_id uuid, provider text, region text, content jsonb, facts jsonb, expires_at timestamp with time zone, reviews jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select p.id,req.story_id,prep.processor,prep.processing_region,p.content,
    (select jsonb_agg(jsonb_build_object('fact_id',f.id,'text',f.fact_text,'article_id',a.id,
      'source_name',case when pol.source_display_allowed then s.name else null end,'evidence_reference',f.evidence_reference) order by f.id)
      from public.story_summary_request_facts rf join public.ai_verified_facts f on f.id=rf.fact_id
      join public.articles a on a.id=f.article_id join public.sources s on s.id=a.source_id
      join lateral (select * from public.source_policies sp where sp.source_id=s.id order by sp.version desc limit 1) pol on true
      where rf.request_id=p.request_id),p.expires_at,
    coalesce((select jsonb_agg(jsonb_build_object('review_id',r.id,'decision',r.decision,'reviewer_id',r.reviewer_id,'created_at',r.created_at) order by r.created_at desc,r.id)
      from (select * from public.story_summary_reviews sr where sr.proposal_id=p.id order by sr.created_at desc,sr.id limit 100) r),'[]'::jsonb)
    from public.story_summary_proposals p join public.story_summary_requests req on req.request_id=p.request_id
    join public.ai_request_preparations prep on prep.request_id=p.request_id
    where exists(select 1 from public.story_summary_request_facts rf join public.ai_verified_facts f on f.id=rf.fact_id
      where rf.request_id=p.request_id and f.article_id=p_article) and public.story_summary_visible(p)
    order by p.created_at desc,p.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_submissions() RETURNS TABLE(id uuid, url text, title text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select s.id,s.url,s.title,s.created_at from public.candidate_submissions s order by s.created_at desc,s.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_summaries(p_fact uuid) RETURNS TABLE(proposal_id uuid, fact_id uuid, provider text, region text, content jsonb, origin text, expires_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select p.id,p.fact_id,p.provider,p.region,p.content,
    case when mr.request_id is null then p.origin else 'model_response_unverified' end,p.expires_at
    from public.summary_proposals p left join public.summary_model_receipts mr on mr.proposal_id=p.id
    where p.fact_id=p_fact and public.summary_visible(p) order by p.created_at desc,p.id limit 50;
end $$;



CREATE FUNCTION public.editor_list_summary_grants() RETURNS TABLE(grant_id uuid, source_id uuid, policy_version integer, provider text, region text, action text, evidence text, expires_at timestamp with time zone, revoked boolean, current_policy boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  return query select g.id,p.source_id,p.version,g.provider,g.region,g.action,g.evidence,g.expires_at,
    exists(select 1 from public.summary_grant_revocations r where r.grant_id=g.id),
    p.id=(select sp.id from public.source_policies sp where sp.source_id=p.source_id order by version desc limit 1)
    from public.summary_grants g join public.source_policies p on p.id=g.policy_id order by g.reviewed_at desc,g.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_summary_reviews(p_proposal uuid) RETURNS TABLE(review_id uuid, decision text, reviewer_id uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select r.id,r.decision,r.reviewer_id,r.created_at from public.summary_reviews r
    join public.summary_proposals p on p.id=r.proposal_id where p.id=p_proposal and public.summary_visible(p)
    order by r.created_at desc,r.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_translation_claims(p_revision uuid) RETURNS TABLE(claim_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if not public.editor_revision_sources_available(p_revision) then raise exception 'source permission unavailable'; end if;
  return query select c.target_claim_id from public.translation_claim_imports c where c.target_revision_id=p_revision order by c.target_claim_id;
end $$;



CREATE FUNCTION public.editor_list_translation_intents(p_story uuid) RETURNS TABLE(id uuid, source_revision_id uuid, source_locale text, target_locale text, glossary_version text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select t.id,t.source_revision_id,t.source_locale,t.target_locale,t.glossary_version,t.created_at
    from public.translation_task_intents t where t.story_id=p_story order by t.created_at desc,t.id desc limit 100;
end $$;



CREATE FUNCTION public.editor_list_translation_proposals(p_story uuid) RETURNS TABLE(proposal_id uuid, source_revision_id uuid, target_locale text, content jsonb, expires_at timestamp with time zone, imported boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select p.id,t.source_revision_id,t.target_locale,public.editor_get_translation_proposal(p.id),p.expires_at,
    exists(select 1 from public.translation_revision_imports i where i.proposal_id=p.id)
    from public.translation_proposals p join public.translation_proposal_receipts r on r.id=p.id
    join public.translation_requests req on req.request_id=r.request_id join public.translation_task_intents t on t.id=req.intent_id
    where t.story_id=p_story and public.editor_get_translation_proposal(p.id) is not null order by p.created_at desc,p.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_verified_ai_facts(p_article uuid) RETURNS TABLE(id uuid, review_id uuid, request_id uuid, fact_text text, evidence_reference text, recorded_by uuid, expires_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query select f.id,f.review_id,f.request_id,f.fact_text,f.evidence_reference,f.recorded_by,f.expires_at
    from public.ai_verified_facts f join public.ai_request_preparations prep on prep.request_id=f.request_id
    where f.article_id=p_article and f.expires_at>statement_timestamp()
      and exists(select 1 from public.ai_verified_fact_retention_control control where control.singleton and not control.restore_quarantine)
      and not exists(
      select 1 from public.ai_request_preparation_inputs i join public.articles a on a.id=i.article_id
        left join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) p on true
        where i.request_id=f.request_id and (p.id is distinct from i.policy_id or p.policy_status is distinct from 'approved'
          or p.reviewed_by is null or p.reviewed_at is null or p.policy_evidence='{}'::jsonb
          or (p.permission_expires_at is not null and p.permission_expires_at<=statement_timestamp())
          or not exists(select 1 from public.ai_verified_fact_grants g where g.policy_id=p.id and g.provider=prep.processor
            and g.processing_region=prep.processing_region and g.permitted_action='verified_store' and g.expires_at>statement_timestamp()
            and not exists(select 1 from public.ai_verified_fact_grant_revocations r where r.grant_id=g.id))
          or not exists(select 1 from public.ai_verified_fact_grants g where g.policy_id=p.id and g.provider=prep.processor
            and g.processing_region=prep.processing_region and g.permitted_action='verified_display' and g.expires_at>statement_timestamp()
            and not exists(select 1 from public.ai_verified_fact_grant_revocations r where r.grant_id=g.id))))
    order by f.created_at desc,f.id limit 100;
end $$;



CREATE FUNCTION public.editor_list_verified_fact_grants() RETURNS TABLE(grant_id uuid, source_id uuid, policy_version integer, provider text, processing_region text, permitted_action text, evidence text, expires_at timestamp with time zone, revoked boolean, current_policy boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  return query select g.id,p.source_id,p.version,g.provider,g.processing_region,g.permitted_action,g.evidence,g.expires_at,
    exists(select 1 from public.ai_verified_fact_grant_revocations r where r.grant_id=g.id),
    p.id=(select sp.id from public.source_policies sp where sp.source_id=p.source_id order by sp.version desc limit 1)
    from public.ai_verified_fact_grants g join public.source_policies p on p.id=g.policy_id order by g.reviewed_at desc,g.id limit 100;
end $$;



CREATE FUNCTION public.editor_merge_draft_stories(p_id uuid, p_source uuid, p_source_version integer, p_target uuid, p_target_version integer, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare src public.stories%rowtype; dst public.stories%rowtype; prior public.story_merge_events%rowtype; n integer; rev integer;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_source is null or p_target is null or p_source=p_target or p_source_version is null or p_source_version<1
    or p_target_version is null or p_target_version<1 or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid story merge'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,76129));
  perform id from public.stories where id in(p_source,p_target) order by id for update;
  select * into src from public.stories where id=p_source;
  select * into dst from public.stories where id=p_target;
  if src.id is null or dst.id is null then raise exception 'story unavailable'; end if;
  select * into prior from public.story_merge_events where id=p_id;
  if found then
    if prior.source_story_id is distinct from p_source or prior.target_story_id is distinct from p_target
      or prior.source_version is distinct from p_source_version or prior.target_version is distinct from p_target_version
      or prior.actor_id is distinct from auth.uid() or prior.reason is distinct from trim(p_reason) then raise exception 'story merge identity conflict'; end if;
    perform id from public.sources where id in(select a.source_id from public.story_merge_articles m join public.articles a on a.id=m.article_id where m.event_id=p_id) order by id for update;
    if exists(select 1 from public.story_merge_articles m where m.event_id=p_id and not public.candidate_title_allowed(m.article_id)) then raise exception 'article permission unavailable'; end if;
    return false;
  end if;
  if src.version<>p_source_version or dst.version<>p_target_version then raise exception 'story version conflict'; end if;
  if src.visibility<>'hidden' or dst.visibility<>'hidden' or src.public_revision_id is not null or dst.public_revision_id is not null
    or exists(select 1 from public.publication_events where story_id in(p_source,p_target)) then raise exception 'only never-published hidden stories can be merged'; end if;
  if exists(select 1 from public.story_merge_events where source_story_id in(p_source,p_target)) then raise exception 'merged source cannot be reused'; end if;
  select count(*) into n from public.story_articles where story_id=p_source;
  if n not between 1 and 100 then raise exception 'source article count out of range'; end if;
  perform id from public.sources where id in(select a.source_id from public.articles a join public.story_articles sa on sa.article_id=a.id where sa.story_id=p_source) order by id for update;
  perform sa.article_id from public.story_articles sa where sa.story_id in(p_source,p_target) order by sa.story_id,sa.article_id for update;
  if exists(select 1 from public.story_articles sa where sa.story_id=p_source and not public.candidate_title_allowed(sa.article_id)) then raise exception 'article permission unavailable'; end if;
  -- Never infer syndication from a copied relationship; preserve it only in history.
  select coalesce(max(revision_number),0) into rev from public.story_revisions where story_id=p_target;
  insert into public.story_merge_events(id,source_story_id,target_story_id,source_version,target_version,target_revision_number,actor_id,reason)
    values(p_id,p_source,p_target,p_source_version,p_target_version,rev,auth.uid(),trim(p_reason));
  insert into public.story_merge_articles(event_id,article_id,was_on_target,source_role,source_independence,source_syndicated_from)
    select p_id,sa.article_id,exists(select 1 from public.story_articles other where other.story_id=p_target and other.article_id=sa.article_id),sa.reporting_role,sa.independence,sa.syndicated_from_article_id
    from public.story_articles sa where sa.story_id=p_source;
  insert into public.story_articles(story_id,article_id,reporting_role,independence)
    select p_target,article_id,'unknown','unknown' from public.story_articles where story_id=p_source
    on conflict(story_id,article_id) do nothing;
  update public.stories set version=version+1,workflow_status='developing' where id in(p_source,p_target);
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'merge_draft_story','story',p_target,trim(p_reason));
  if exists(select 1 from public.story_merge_articles m where m.event_id=p_id and not public.candidate_title_allowed(m.article_id)) then raise exception 'article permission expired'; end if;
  return true;
end $$;



CREATE FUNCTION public.editor_monthly_cny_fx_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare m date;
begin
  if session_user<>'authenticator' or public.editor_can_review_ai_billing() is distinct from true then
    raise exception 'authenticated billing reviewer required';
  end if;
  m:=date_trunc('month',statement_timestamp() at time zone 'UTC')::date;
  return jsonb_build_object('month_start',m,
    'original_budget',(select to_jsonb(b) from public.ai_monthly_cny_budgets b where b.month_start=m),
    'latest_version',(select coalesce(max(version),0) from public.ai_monthly_cny_fx_reviews where month_start=m),
    'reviews',coalesce((select jsonb_agg(to_jsonb(r) order by r.version) from public.ai_monthly_cny_fx_reviews r where r.month_start=m),'[]'::jsonb),
    'withdrawals',coalesce((select jsonb_agg(to_jsonb(w) order by w.version) from public.ai_monthly_cny_fx_withdrawals w where w.month_start=m),'[]'::jsonb),
    'committed_usd_nanos',(select coalesce(sum(case when state='settled' then actual_nanos else reserved_nanos end),0)::text
      from public.ai_budget_reservations where budget_day>=m and budget_day<(m+interval '1 month')::date));
end $$;



CREATE FUNCTION public.editor_prepare_ai_trial(p_request uuid, p_provider text, p_region text, p_bound uuid, p_article uuid, p_output integer, p_task_budget bigint, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare job uuid; existing_article uuid; created boolean;
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null then raise exception 'AI operator access required'; end if;
 if p_request is null or p_article is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid AI trial'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select j.id,j.article_id into job,existing_article from public.ai_processing_jobs j
  where j.idempotency_key='ai-trial:'||p_request::text for update;
 if found then
  if existing_article is distinct from p_article then raise exception 'trial identity conflict'; end if;
  created:=public.ai_prepare_bounded_request(p_request,job,array[p_article],p_provider,p_region,p_bound,p_output);
  if created then raise exception 'trial preparation identity mismatch'; end if;
  return p_request;
 end if;
 insert into public.ai_processing_jobs(article_id,task_type,idempotency_key)
  values(p_article,'claim_extraction.v1','ai-trial:'||p_request::text) returning id into job;
 created:=public.ai_prepare_bounded_request(p_request,job,array[p_article],p_provider,p_region,p_bound,p_output);
 if created is distinct from true then raise exception 'trial preparation identity mismatch'; end if;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
  values(auth.uid(),'prepare_ai_trial','ai_processing_job',job,trim(p_reason));
 return p_request;
end $$;



CREATE FUNCTION public.editor_prepare_bilingual_retraction(p_story uuid, p_version integer, p_zh text, p_en text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.bilingual_rollout_enabled() then raise exception 'bilingual rollout is disabled'; end if;
  return public.prepare_bilingual_retraction_internal(p_story,p_version,p_zh,p_en);
end $$;



CREATE FUNCTION public.editor_propose_candidate(p_first uuid, p_second uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare cid uuid;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reason required'; end if;
  perform public.lock_candidate_sources(p_first, p_second);
  insert into public.editor_candidate_pairs(first_article_id, second_article_id, created_by)
    values (least(p_first, p_second), greatest(p_first, p_second), auth.uid()) returning id into cid;
  insert into public.audit_logs(actor_id, action, resource_type, resource_id, reason)
    values (auth.uid(), 'propose', 'candidate_pair', cid, trim(p_reason));
  return cid;
end $$;



CREATE FUNCTION public.editor_publish_ai_draft(p_draft uuid, p_expected_revision uuid, p_channel text, p_topic text, p_score integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare d public.article_full_drafts%rowtype; source_url text; source_name text; policy public.source_policies%rowtype;
 doc_zh jsonb;doc_en jsonb;lang text;section text;row jsonb;nodes jsonb;title_zh text;title_en text;
 summary_zh text;summary_en text;result jsonb;v_slug text;linked uuid; content jsonb; latest_revision uuid;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed required'; end if;
 if p_draft is null or p_score not between 0 and 100 or p_score is null or p_channel is null or p_topic is null then raise exception 'channel topic and score required'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_draft::text,903515));
 select article_id into linked from public.ai_article_publications where draft_id=p_draft;
 if linked is not null then
  select a.slug into v_slug from public.manual_articles a where a.id=linked;
  return jsonb_build_object('article_id',linked,'slug',v_slug,'status','already_published');
 end if;
 select * into d from public.article_full_drafts where id=p_draft;
 if d.id is null or public.editor_get_full_article_draft(p_draft) is null then raise exception 'draft expired or unavailable'; end if;
 select er.id,ec.content into latest_revision,content from public.article_editor_revision_receipts er join public.article_editor_revision_content ec on ec.id=er.id where er.draft_id=p_draft and public.article_editor_revision_live(er.id) order by er.revision_number desc limit 1;
 if latest_revision is distinct from p_expected_revision then raise exception 'draft changed; refresh and review again'; end if;
 content:=coalesce(content,d.content);
 select r.original_url,s.name into source_url,source_name from public.article_body_receipts r join public.articles a on a.id=r.article_id join public.sources s on s.id=a.source_id where r.id=d.snapshot_id;
 select sp.* into policy from public.article_body_receipts r join public.articles a on a.id=r.article_id join public.source_policies sp on sp.source_id=a.source_id where r.id=d.snapshot_id order by sp.version desc limit 1;
 if policy.policy_status is distinct from 'approved' or not coalesce(policy.story_publication_allowed,false)
 or not coalesce(policy.source_display_allowed,false) or not coalesce(policy.link_display_allowed,false)
 or (policy.permission_expires_at is not null and policy.permission_expires_at<=clock_timestamp()) then raise exception 'source publication permission unavailable'; end if;
 if source_url is null or source_url !~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$' then raise exception 'source link unavailable'; end if;
 foreach lang in array array['zh','en'] loop
  nodes:='[]'::jsonb;
  foreach section in array array['what_happened','why_it_matters','what_we_know','what_we_dont_know','timeline'] loop
   for row in select value from jsonb_array_elements(content->lang->section) loop
    if length(trim(coalesce(row->>'text','')))>0 then nodes:=nodes||jsonb_build_array(jsonb_build_object('type','paragraph','content',jsonb_build_array(jsonb_build_object('type','text','text',row->>'text')))); end if;
   end loop;
  end loop;
  if jsonb_array_length(nodes)=0 then raise exception 'both language bodies required'; end if;
  if lang='zh' then doc_zh:=jsonb_build_object('type','doc','content',nodes); else doc_en:=jsonb_build_object('type','doc','content',nodes); end if;
 end loop;
 title_zh:=content->'zh'->'title'->0->>'text';title_en:=content->'en'->'title'->0->>'text';
 summary_zh:=content->'zh'->'seo'->>'summary';summary_en:=content->'en'->'seo'->>'summary';
 if length(trim(coalesce(title_zh,''))) not between 1 and 240 or length(trim(coalesce(title_en,''))) not between 1 and 240 or length(trim(coalesce(summary_zh,''))) not between 1 and 1000 or length(trim(coalesce(summary_en,''))) not between 1 and 1000 then raise exception 'title or summary unavailable'; end if;
 v_slug:=lower(trim(coalesce(content->'en'->'seo'->>'slug','')));
 if v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or length(v_slug)>120 or exists(select 1 from public.manual_articles where manual_articles.slug=v_slug)
 then v_slug:='ai-'||replace(p_draft::text,'-',''); end if;
 result:=public.manual_save_article_with_topics(null,null,v_slug,title_zh,title_en,summary_zh,summary_en,doc_zh,doc_en,p_channel,'{}'::text[],'{}'::text[],jsonb_build_array(jsonb_build_object('url',source_url,'label',source_name)),array[p_topic]);
 insert into public.ai_article_publications(draft_id,article_id,approved_by,zh_seo,en_seo)
 values(p_draft,(result->>'article_id')::uuid,auth.uid(),content->'zh'->'seo',content->'en'->'seo');
 perform public.manual_publish_article((result->>'article_id')::uuid,(result->>'revision_id')::uuid,p_score,'publish','Owner reviewed and approved bilingual AI draft');
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'publish_reviewed_ai_draft','manual_article',(result->>'article_id')::uuid,'Owner approved source-linked bilingual AI draft');
 return jsonb_build_object('article_id',result->>'article_id','slug',v_slug,'status','published');
end $_$;



CREATE FUNCTION public.editor_publish_bilingual(p_batch uuid, p_version integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.bilingual_rollout_enabled() then raise exception 'bilingual rollout is disabled'; end if;
  perform public.lock_editorial_channel_rollout();
  if not public.bilingual_channel_publication_ready(p_batch) then raise exception 'reviewed primary editorial channel required'; end if;
  perform public.publish_bilingual_first_internal(p_batch,p_version,p_reason);
end $$;



CREATE FUNCTION public.editor_publish_full_article_revision(p_revision uuid, p_batch uuid, p_version integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare review public.article_editor_revision_reviews%rowtype; grant_id bigint; draft uuid;
begin
 if session_user<>'authenticator' or public.is_active_editor() is distinct from true then raise exception 'authenticated editor required'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
 perform public.lock_editorial_channel_rollout();
 select draft_id into draft from public.article_editor_revision_receipts where id=p_revision;
 perform pg_advisory_xact_lock(hashtextextended(draft::text,903515));
 select * into review from public.article_editor_revision_reviews where revision_id=p_revision order by id desc limit 1;
 select id into grant_id from public.article_full_public_grants where revision_id=p_revision order by id desc limit 1;
 if review.id is null or review.decision<>'approved' or review.batch_id<>p_batch or not public.article_full_public_grant_live(grant_id)
 or not public.article_revision_batch_matches(p_revision,p_batch) then raise exception 'reviewed revision and explicit public authorization required'; end if;
 -- Existing first-publication RPC checks version, hidden state, complete pair,
 -- facts, source permissions, channel, rollout and audit. Never replace it.
 perform public.editor_publish_bilingual(p_batch,p_version,p_reason);
 if not public.article_full_public_grant_live(grant_id) or not public.article_revision_batch_matches(p_revision,p_batch)
 or not exists(select 1 from public.article_full_public_grants g
 join public.article_editor_revision_content ec on ec.id=g.revision_id
 join public.source_policies policy on policy.id=g.policy_id
 where g.id=grant_id and g.expires_at>clock_timestamp() and ec.expires_at>clock_timestamp()
 and (policy.permission_expires_at is null or policy.permission_expires_at>clock_timestamp()))
 then raise exception 'publication dependencies changed'; end if;
 insert into public.article_full_publications(batch_id,revision_id,review_id,public_grant_id,published_by)
 values(p_batch,p_revision,review.id,grant_id,auth.uid());
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'publish_full_article_revision','article_editor_revision',p_revision,'Explicit first publication through existing bilingual gates');
end $$;



CREATE FUNCTION public.editor_publish_selected_ai_draft(p_draft uuid, p_expected_revision uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare selection jsonb; existing record;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 select p.article_id,a.slug into existing from public.ai_article_publications p join public.manual_articles a on a.id=p.article_id where p.draft_id=p_draft;
 if existing.article_id is not null then return jsonb_build_object('article_id',existing.article_id,'slug',existing.slug,'status','already_published'); end if;
 selection:=public.editor_get_article_selection(p_draft);
 if selection is null then raise exception 'selection metadata unavailable'; end if;
 return public.editor_publish_ai_draft(p_draft,p_expected_revision,selection->>'channel',selection->>'subcategory',(selection->>'score')::integer);
end $$;



CREATE FUNCTION public.editor_recent_ingestion_events() RETURNS TABLE(job_id uuid, source_id uuid, previous_status text, status text, error_code text, attempts integer, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() or not exists(select 1 from public.editors where user_id=auth.uid() and active and can_review_sources) then
    raise exception 'source reviewer access required';
  end if;
  return query select e.job_id,e.source_id,e.previous_status,e.status,e.error_code,e.attempts,e.created_at
    from public.ingestion_job_events e order by e.id desc limit 100;
end $$;



CREATE FUNCTION public.editor_reconcile_ai_charge(p_request uuid, p_nanos bigint, p_evidence text, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare r public.ai_budget_reservations%rowtype; prior public.ai_charge_reconciliations%rowtype; stopped boolean;
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI budget operator access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_request is null or p_nanos is null or p_nanos not between 0 and 1000000000000000
    or p_evidence is null or length(trim(p_evidence)) not between 1 and 1000
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid reconciliation'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
  select * into prior from public.ai_charge_reconciliations where request_id=p_request;
  if found then
    if prior.confirmed_nanos is distinct from p_nanos or prior.evidence_reference is distinct from trim(p_evidence) then
      raise exception 'reconciliation conflict';
    end if;
    return false;
  end if;
  select * into r from public.ai_budget_reservations where request_id=p_request;
  if not found then raise exception 'reservation unavailable'; end if;
  perform 1 from public.ai_daily_budgets where budget_day=r.budget_day for update;
  perform 1 from public.ai_task_budgets where job_id=r.job_id for update;
  select * into r from public.ai_budget_reservations where request_id=p_request for update;
  select c.stopped into stopped from public.ai_budget_control c where singleton for share;
  if stopped is distinct from true then raise exception 'AI requests must be stopped'; end if;
  if r.state <> 'unknown' or not exists(select 1 from public.ai_request_preparations where request_id=p_request and state='checked') then
    raise exception 'unknown checked request required';
  end if;
  perform public.ai_settle_budget(p_request,p_nanos);
  insert into public.ai_charge_reconciliations(request_id,confirmed_nanos,evidence_reference,reconciled_by)
    values(p_request,p_nanos,trim(p_evidence),auth.uid());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'reconcile_charge','ai_budget_reservation',p_request,trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editor_reconcile_ai_cny_charge(p_request uuid, p_cny_nanos bigint, p_statement_sha256 text, p_evidence text, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare reservation public.ai_budget_reservations%rowtype; prior public.ai_cny_charge_reconciliations%rowtype; fx public.ai_request_monthly_cny_fx_checks%rowtype;
begin
 if session_user<>'authenticator' or public.editor_can_monitor_ai() is distinct from true or public.editor_can_review_ai_billing() is distinct from true then raise exception 'authenticated budget and billing reviewer required'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
 if p_request is null or p_cny_nanos is null or p_cny_nanos not between 0 and 1000000000000000
 or p_statement_sha256 is null or p_statement_sha256 !~ '^[0-9a-f]{64}$'
 or p_evidence is null or length(trim(p_evidence)) not between 1 and 2000
 or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid CNY reconciliation'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,629854231));
 select * into prior from public.ai_cny_charge_reconciliations where request_id=p_request;
 if found then
 if prior.actual_cny_nanos is distinct from p_cny_nanos or prior.statement_sha256 is distinct from p_statement_sha256 or prior.evidence_reference is distinct from trim(p_evidence) then raise exception 'CNY reconciliation conflict'; end if;
 return false; end if;
 select * into reservation from public.ai_budget_reservations where request_id=p_request;
 if not found then raise exception 'reservation unavailable'; end if;
 perform 1 from public.ai_daily_budgets where budget_day=reservation.budget_day for update;
 perform 1 from public.ai_task_budgets where job_id=reservation.job_id for update;
 select * into reservation from public.ai_budget_reservations where request_id=p_request for update;
 perform 1 from public.ai_budget_control where singleton and stopped for share;
 if not found then raise exception 'AI requests must be stopped'; end if;
 if reservation.provider<>'deepseek' or reservation.state not in ('reserved','unknown')
 or not exists(select 1 from public.ai_request_preparations where request_id=p_request and state='checked')
 or not exists(select 1 from public.ai_usage_observations where request_id=p_request)
 or not exists(select 1 from public.ai_execution_observations where request_id=p_request)
 or exists(select 1 from public.ai_charge_reconciliations where request_id=p_request) then raise exception 'observed checked DeepSeek request required'; end if;
 select * into fx from public.ai_request_monthly_cny_fx_checks where request_id=p_request;
 if fx.request_id is null or p_cny_nanos::numeric>reservation.reserved_nanos::numeric*fx.cny_per_usd_micros/1000000 then raise exception 'CNY charge exceeds retained conservative coverage'; end if;
 insert into public.ai_cny_charge_reconciliations(request_id,actual_cny_nanos,statement_sha256,evidence_reference,reserved_usd_nanos,fx_micros,prior_state,reconciled_by)
 values(p_request,p_cny_nanos,p_statement_sha256,trim(p_evidence),reservation.reserved_nanos,fx.cny_per_usd_micros,reservation.state,auth.uid());
 update public.ai_budget_reservations set state='reconciled_cny',settled_at=clock_timestamp() where request_id=p_request;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'reconcile_cny_keep_usd_reservation','ai_budget_reservation',p_request,trim(p_reason));
 return true;
end $_$;



CREATE FUNCTION public.editor_record_bilingual_uncertainty(p_batch uuid, p_version integer, p_zh text, p_en text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.story_bilingual_batches%rowtype; v integer;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_zh is null or length(trim(p_zh)) not between 1 and 4000 or p_en is null or length(trim(p_en)) not between 1 and 4000
     or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'both languages and reason required'; end if;
  select * into b from public.story_bilingual_batches where id=p_batch;
  if b.id is null then raise exception 'batch unavailable'; end if;
  select version into v from public.stories where id=b.story_id and archived_at is null for update;
  if v is null or v is distinct from p_version then raise exception 'story version conflict'; end if;
  if b.zh_revision_id is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id
      where l.story_id=b.story_id and l.locale='zh' order by r.revision_number desc limit 1)
    or b.en_revision_id is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id
      where l.story_id=b.story_id and l.locale='en' order by r.revision_number desc limit 1)
    then raise exception 'stale bilingual batch'; end if;
  if exists(select 1 from public.bilingual_editorial_reviews where batch_id=b.id) then raise exception 'batch already reviewed'; end if;
  perform s.id from public.sources s where exists(
    select 1 from public.articles a join public.claim_evidence e on e.article_id=a.id join public.claims c on c.id=e.claim_id
    where a.source_id=s.id and c.revision_id in (b.zh_revision_id,b.en_revision_id)) order by s.id for update;
  if not public.editor_revision_sources_available(b.zh_revision_id) or not public.editor_revision_sources_available(b.en_revision_id)
    then raise exception 'source permission unavailable'; end if;
  insert into public.bilingual_uncertainty_notes(batch_id,zh,en,recorded_by) values(b.id,trim(p_zh),trim(p_en),auth.uid());
  update public.stories set version=version+1 where id=b.story_id;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'record_uncertainty','story_bilingual_batch',b.id,trim(p_reason));
end $$;



CREATE FUNCTION public.editor_record_review(p_request uuid, p_story uuid, p_revision uuid, p_version integer, p_decision text, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prior public.review_requests%rowtype; current_version integer; rid uuid;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_request is null or p_story is null or p_revision is null or p_version is null or p_decision is null
    or p_decision not in ('approved','rejected','needs_changes','needs_evidence') or p_reason is null
    or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid review'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,1033));
  select version into current_version from public.stories where id=p_story for update;
  if current_version is null then raise exception 'story unavailable'; end if;
  select * into prior from public.review_requests where request_id=p_request;
  if found then
    if prior.story_id is distinct from p_story or prior.revision_id is distinct from p_revision or prior.story_version is distinct from p_version
      or prior.decision is distinct from p_decision or prior.reason is distinct from trim(p_reason) or prior.actor_id is distinct from auth.uid()
      then raise exception 'review identity conflict'; end if;
    return false;
  end if;
  if current_version<>p_version or p_revision is distinct from (select id from public.story_revisions where story_id=p_story order by revision_number desc limit 1)
    then raise exception 'story version conflict'; end if;
  if exists(select 1 from public.stories where id=p_story and public_revision_id=p_revision and visibility='public')
    then raise exception 'published revision requires separate hide or correction'; end if;
  insert into public.editorial_reviews(revision_id,reviewer_id,decision,notes)
    values(p_revision,auth.uid(),p_decision,trim(p_reason)) returning id into rid;
  insert into public.review_requests(request_id,story_id,story_version,revision_id,decision,reason,review_id,actor_id)
    values(p_request,p_story,p_version,p_revision,p_decision,trim(p_reason),rid,auth.uid());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'record_review','story_revision',p_revision,trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editor_record_source_policy(p_source uuid, p_status text, p_basis text, p_region text, p_attribution text, p_title_allowed boolean, p_url_allowed boolean, p_display_allowed boolean, p_story_allowed boolean, p_source_display boolean, p_link_display boolean, p_expires_at timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare next_version integer; policy_id uuid;
begin
  if not public.is_active_editor() or not exists(select 1 from public.editors where user_id = auth.uid() and active and can_review_sources) then
    raise exception 'source reviewer access required';
  end if;
  if p_status is null or p_status not in ('approved', 'paused', 'rejected') then raise exception 'invalid policy status'; end if;
  if p_basis is null or length(trim(p_basis)) = 0 or p_region is null or length(trim(p_region)) = 0 then raise exception 'policy basis and region required'; end if;
  if p_attribution is null or length(trim(p_attribution)) = 0 or p_reason is null or length(trim(p_reason)) = 0 then raise exception 'attribution and reason required'; end if;
  if p_status = 'approved' and p_expires_at is not null and p_expires_at <= now() then raise exception 'permission already expired'; end if;
  if p_status = 'approved' and coalesce(p_story_allowed, false) and trim(p_region) <> 'global' then raise exception 'global publication requires global permission'; end if;
  perform 1 from public.sources where id = p_source for update;
  if not found then raise exception 'source not found'; end if;
  select coalesce(max(version), 0) + 1 into next_version from public.source_policies where source_id = p_source;
  insert into public.source_policies(source_id, version, policy_status, access_method, access_allowed,
    title_storage_allowed, url_storage_allowed, display_allowed, story_publication_allowed, source_display_allowed, link_display_allowed,
    policy_evidence, permitted_region, attribution_requirements, permission_expires_at, reviewed_by, reviewed_at)
  values(p_source, next_version, p_status, 'manual', false,
    case when p_status = 'approved' then coalesce(p_title_allowed, false) else false end,
    case when p_status = 'approved' then coalesce(p_url_allowed, false) else false end,
    case when p_status = 'approved' then coalesce(p_display_allowed, false) else false end,
    case when p_status = 'approved' then coalesce(p_story_allowed, false) else false end,
    case when p_status = 'approved' then coalesce(p_source_display, false) else false end,
    case when p_status = 'approved' then coalesce(p_link_display, false) else false end,
    jsonb_build_object('basis', trim(p_basis)), trim(p_region), trim(p_attribution), p_expires_at, auth.uid(), now())
  returning id into policy_id;
  insert into public.audit_logs(actor_id, action, resource_type, resource_id, reason)
    values(auth.uid(), 'record_policy', 'source_policy', policy_id, p_reason);
  return policy_id;
end $$;



CREATE FUNCTION public.editor_record_verified_ai_fact(p_id uuid, p_review uuid, p_text text, p_reference text, p_expires timestamp with time zone, p_attested boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  perform 1 from public.ai_claim_retention_control where singleton and not restore_quarantine for share;
  if not found then raise exception 'claim restore quarantine active'; end if;
  return public.editor_record_verified_ai_fact_before_claim_restore_gate(p_id,p_review,p_text,p_reference,p_expires,p_attested);
end $$;



CREATE FUNCTION public.editor_record_verified_ai_fact_before_claim_restore_gate(p_id uuid, p_review uuid, p_text text, p_reference text, p_expires timestamp with time zone, p_attested boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare rev public.ai_claim_editor_reviews%rowtype; prep public.ai_request_preparations%rowtype; prior public.ai_verified_facts%rowtype;
  ids uuid[]; n integer; matched integer; deadline timestamptz; sweep timestamptz; quarantined boolean;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_review is null or p_attested is distinct from true or p_text is null or length(trim(p_text)) not between 1 and 1000
    or p_reference is null or length(trim(p_reference)) not between 1 and 1000 or p_expires is null
    or p_expires<=clock_timestamp() or p_expires>clock_timestamp()+interval '365 days' then raise exception 'invalid verified fact'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,741095));
  select * into prior from public.ai_verified_facts where id=p_id;
  if found then
    if prior.review_id is distinct from p_review or prior.fact_text is distinct from trim(p_text) or prior.evidence_reference is distinct from trim(p_reference)
      or prior.recorded_by is distinct from auth.uid() or prior.expires_at is distinct from p_expires then raise exception 'verified fact identity conflict'; end if;
    return false;
  end if;
  if exists(select 1 from public.ai_verified_fact_deletion_receipts where fact_id=p_id) then raise exception 'deleted fact cannot be restored'; end if;
  select last_sweep_at,restore_quarantine into sweep,quarantined from public.ai_verified_fact_retention_control where singleton for update;
  if quarantined is distinct from false or sweep is null or sweep>clock_timestamp() or sweep<=clock_timestamp()-interval '5 minutes'
    or exists(select 1 from public.ai_verified_facts where expires_at<=clock_timestamp()) then raise exception 'verified fact retention unavailable'; end if;
  select * into rev from public.ai_claim_editor_reviews where id=p_review;
  if not found or rev.decision<>'supported' then raise exception 'supported editorial review required'; end if;
  select * into prep from public.ai_request_preparations where request_id=rev.request_id;
  select array_agg(article_id order by article_id),count(*) into ids,n from public.ai_request_preparation_inputs where request_id=rev.request_id;
  if n<1 or n>50 or not (rev.article_id=any(ids)) then raise exception 'candidate inputs unavailable'; end if;
  deadline:=public.ai_lock_verified_fact_grants(ids,prep.processor,prep.processing_region,'verified_store');
  if p_expires>deadline then raise exception 'verified fact exceeds permission'; end if;
  perform public.ai_lock_derived_claim_permissions(ids,prep.processor,prep.processing_region,'store');
  perform public.ai_lock_derived_claim_permissions(ids,prep.processor,prep.processing_region,'editor_display');
  perform a.id from public.articles a where a.id=any(ids) order by a.id for share;
  select count(*) into matched from public.ai_request_preparation_inputs x join public.articles a on a.id=x.article_id
    join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) p on true
    join public.ai_provider_title_grants g on g.id=x.provider_grant_id where x.request_id=rev.request_id and x.policy_id=p.id
      and p.policy_status='approved' and p.title_storage_allowed and p.ai_processing_allowed and p.reviewed_by is not null and p.reviewed_at is not null
      and p.policy_evidence<>'{}'::jsonb and (p.permission_expires_at is null or p.permission_expires_at>clock_timestamp())
      and g.policy_id=p.id and g.provider=prep.processor and g.processing_region=prep.processing_region
      and (g.expires_at is null or g.expires_at>clock_timestamp())
      and not exists(select 1 from public.ai_provider_title_revocations r where r.grant_id=g.id)
      and x.title_sha256=encode(sha256(convert_to(a.title,'UTF8')),'hex');
  if matched<>n then raise exception 'candidate inputs changed'; end if;
  if p_review is distinct from (select id from public.ai_claim_editor_reviews where request_id=rev.request_id and proposal_index=rev.proposal_index
      order by created_at desc,id desc limit 1) then raise exception 'editorial review superseded'; end if;
  perform 1 from public.ai_claim_proposals c where c.request_id=rev.request_id and c.expires_at>clock_timestamp()
    and exists(select 1 from jsonb_array_elements(c.content->'claims'->rev.proposal_index->'evidence') e where e->>'article_id'=rev.article_id::text) for share;
  if not found then raise exception 'candidate unavailable'; end if;
  if p_expires>public.ai_lock_verified_fact_grants(ids,prep.processor,prep.processing_region,'verified_store') then raise exception 'verified fact exceeds permission'; end if;
  perform public.ai_lock_derived_claim_permissions(ids,prep.processor,prep.processing_region,'store');
  perform public.ai_lock_derived_claim_permissions(ids,prep.processor,prep.processing_region,'editor_display');
  if p_expires<=clock_timestamp() or not exists(select 1 from public.ai_claim_proposals where request_id=rev.request_id and expires_at>clock_timestamp())
    or exists(select 1 from public.ai_request_preparation_inputs x join public.source_policies p on p.id=x.policy_id
      join public.ai_provider_title_grants g on g.id=x.provider_grant_id where x.request_id=rev.request_id
        and ((p.permission_expires_at is not null and p.permission_expires_at<=clock_timestamp())
          or (g.expires_at is not null and g.expires_at<=clock_timestamp()))) then raise exception 'candidate permission expired'; end if;
  insert into public.ai_verified_facts(id,review_id,request_id,article_id,fact_text,evidence_reference,recorded_by,expires_at)
    values(p_id,p_review,rev.request_id,rev.article_id,trim(p_text),trim(p_reference),auth.uid(),p_expires);
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'record_verified_ai_fact','ai_verified_fact',p_id,'editor attested');
  return true;
end $$;



CREATE FUNCTION public.editor_release_ingestion_hold(p_hold uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.is_active_editor() or not exists (select 1 from public.editors where user_id=auth.uid() and active and can_review_sources) then
    raise exception 'source reviewer access required';
  end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reason required'; end if;
  select source_id into sid from public.ingestion_source_holds where id=p_hold;
  if sid is null then raise exception 'hold not found'; end if;
  perform 1 from public.sources where id=sid for update;
  insert into public.ingestion_hold_releases(hold_id,reviewed_by,reason) values(p_hold,auth.uid(),trim(p_reason)) on conflict do nothing;
  return found;
end $$;



CREATE FUNCTION public.editor_request_translation(p_id uuid, p_story uuid, p_revision uuid, p_target text, p_version integer, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v integer; source_lang text; previous public.translation_task_intents%rowtype;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_story is null or p_revision is null or p_target is null or p_target not in ('zh','en')
    or p_version is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then
    raise exception 'invalid translation intent';
  end if;
  select version into v from public.stories where id=p_story and archived_at is null for update;
  if v is null or v is distinct from p_version then raise exception 'story version conflict'; end if;
  select locale into source_lang from public.story_revision_locales where story_id=p_story and revision_id=p_revision;
  if source_lang is null or source_lang=p_target then raise exception 'source revision or language unavailable'; end if;
  select * into previous from public.translation_task_intents where id=p_id;
  if found then
    if previous.story_id is distinct from p_story or previous.source_revision_id is distinct from p_revision
      or previous.target_locale is distinct from p_target or previous.created_by is distinct from auth.uid()
      then raise exception 'translation intent identity conflict'; end if;
    return false;
  end if;
  insert into public.translation_task_intents(id,story_id,source_revision_id,source_locale,target_locale,glossary_version,created_by)
    values(p_id,p_story,p_revision,source_lang,p_target,'glossary.v1',auth.uid());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'request_translation','story_revision',p_revision,trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editor_resolve_execution_safety(p_request uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare n integer;
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null or p_request is null
  or p_reason is null or length(trim(p_reason)) not between 1 and 1000
 then raise exception 'operator and reconciliation evidence required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 if not exists(select 1 from public.ai_execution_safety_incidents where request_id=p_request)
 then raise exception 'execution safety incident unavailable'; end if;
 insert into public.ai_execution_safety_resolutions(incident_id,resolved_by,reason)
 select i.id,auth.uid(),trim(p_reason) from public.ai_execution_safety_incidents i
 where i.request_id=p_request and not exists
  (select 1 from public.ai_execution_safety_resolutions r where r.incident_id=i.id);
 get diagnostics n=row_count;
 if n>0 then insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
  values(auth.uid(),'resolve_execution_safety','ai_request',p_request,trim(p_reason)); end if;
 return n>0;
end $$;



CREATE FUNCTION public.editor_resolve_ingestion_dispatch(p_dispatch uuid, p_terminated boolean, p_evidence text, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare d public.ingestion_dispatches%rowtype; h public.ingestion_host_limits%rowtype; j public.ingestion_jobs%rowtype;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.is_active_editor() or not exists(select 1 from public.editors where user_id=auth.uid() and active and can_review_sources) then
    raise exception 'source reviewer access required';
  end if;
  if p_terminated is distinct from true or p_evidence is null or length(trim(p_evidence)) not between 20 and 2000
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'termination evidence and reason required'; end if;
  select * into d from public.ingestion_dispatches where id=p_dispatch;
  if d.id is null then raise exception 'dispatch not found'; end if;
  -- Same host-first lock order as ingestion_close_dispatch.
  select * into h from public.ingestion_host_limits where hostname=d.hostname for update;
  select * into d from public.ingestion_dispatches where id=p_dispatch for update;
  if d.state='closed' then return false; end if;
  select * into j from public.ingestion_jobs where id=d.job_id;
  if h.active_dispatch_id is distinct from d.id or d.created_at > clock_timestamp()-interval '2 minutes'
    or (j.status='processing' and j.lease_expires_at > clock_timestamp()) then raise exception 'dispatch is not eligible for review'; end if;
  insert into public.ingestion_dispatch_reviews(dispatch_id,reviewed_by,evidence,reason)
    values(d.id,auth.uid(),trim(p_evidence),trim(p_reason));
  update public.ingestion_dispatches set state='closed',closed_at=clock_timestamp() where id=d.id;
  update public.ingestion_host_limits set active_dispatch_id=null,
    next_allowed_at=greatest(next_allowed_at,clock_timestamp()+make_interval(secs=>d.interval_seconds)) where hostname=d.hostname;
  return true;
end $$;



CREATE FUNCTION public.editor_resume_ai_budget(p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.editor_can_resume_ai_budget() then raise exception 'AI budget recovery access required'; end if;
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  perform 1 from public.ai_budget_control where singleton and not restore_quarantine for update;
  if not found then raise exception 'AI restore quarantine active'; end if;
  perform 1 from public.ai_claim_retention_control where singleton and not restore_quarantine for share;
  if not found then raise exception 'claim restore quarantine active'; end if;
  return public.editor_resume_ai_budget_before_restore_gate(p_reason);
end $$;



CREATE FUNCTION public.editor_resume_ai_budget_alert_unchecked(p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare ctrl public.ai_budget_control%rowtype; restart_id uuid;
begin
  if not public.editor_can_resume_ai_budget() then raise exception 'AI budget recovery access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'recovery reason required'; end if;
  select * into ctrl from public.ai_budget_control where singleton for update;
  if ctrl.stopped is distinct from true then raise exception 'AI budget is not stopped'; end if;
  if not exists(select 1 from public.ai_budget_incidents) then raise exception 'recovery requires a recorded incident'; end if;
  if exists(select 1 from public.ai_budget_incidents i left join public.ai_incident_acknowledgements a on a.incident_id=i.id where a.incident_id is null) then
    raise exception 'unacknowledged AI incident';
  end if;
  if exists(select 1 from public.ai_budget_reservations where state in ('reserved','unknown')) then raise exception 'unresolved AI reservations'; end if;
  if not exists(select 1 from public.ai_daily_budgets where budget_day=(clock_timestamp() at time zone 'UTC')::date) then raise exception 'daily budget unavailable'; end if;
  if not exists(select 1 from public.ai_price_schedules p where p.covers_all_charges and p.valid_from <= clock_timestamp() and p.valid_until > clock_timestamp()
      and not exists(select 1 from public.ai_price_withdrawals w where w.schedule_id=p.id)) then raise exception 'current reviewed price unavailable'; end if;
  update public.ai_budget_control set stopped=false,generation=generation+1,updated_at=clock_timestamp() where singleton returning generation into ctrl.generation;
  insert into public.ai_budget_restarts(generation,resumed_by,reason) values(ctrl.generation,auth.uid(),trim(p_reason)) returning id into restart_id;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'resume','ai_budget_control',restart_id,trim(p_reason));
  return restart_id;
end $$;



CREATE FUNCTION public.editor_resume_ai_budget_before_restore_gate(p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare degraded boolean;
begin
  if not public.editor_can_resume_ai_budget() then raise exception 'AI budget recovery access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  select alert_degraded into degraded from public.ai_budget_control where singleton for update;
  if degraded is distinct from false then raise exception 'AI alert queue degraded'; end if;
  if exists(select 1 from public.ai_alert_outbox where status in ('processing','unknown','failed')) then
    raise exception 'alert deliveries require review';
  end if;
  return public.editor_resume_ai_budget_alert_unchecked(p_reason);
end $$;



CREATE FUNCTION public.editor_retract_bilingual(p_story uuid, p_notice uuid, p_version integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.bilingual_rollout_enabled() then raise exception 'bilingual rollout is disabled'; end if;
  perform public.retract_bilingual_story_internal(p_story,p_notice,p_version,p_reason);
end $$;



CREATE FUNCTION public.editor_review_ai_alert(p_incident uuid, p_decision text, p_evidence text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare old_status text; review_id uuid;
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI budget operator access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_incident is null or p_decision is null or p_decision not in ('confirmed_delivered','confirmed_not_delivered')
    or p_evidence is null or length(trim(p_evidence)) not between 1 and 1000
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid alert review'; end if;
  perform 1 from public.ai_budget_control where singleton for share;
  if not found then raise exception 'budget control unavailable'; end if;
  select status into old_status from public.ai_alert_outbox where incident_id=p_incident for update;
  if old_status is null or old_status not in ('unknown','failed') then raise exception 'alert is not awaiting review'; end if;
  insert into public.ai_alert_reviews(incident_id,prior_status,decision,evidence_reference,reviewed_by)
    values(p_incident,old_status,p_decision,trim(p_evidence),auth.uid()) returning id into review_id;
  update public.ai_alert_outbox set status=case when p_decision='confirmed_delivered' then 'delivered' else 'pending' end,
    attempts=case when p_decision='confirmed_not_delivered' then 0 else attempts end,
    available_at=clock_timestamp(),updated_at=clock_timestamp() where incident_id=p_incident;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'review_alert','ai_budget_incident',p_incident,trim(p_reason));
  return review_id;
end $$;



CREATE FUNCTION public.editor_review_ai_claim(p_review uuid, p_request uuid, p_index integer, p_article uuid, p_decision text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  perform 1 from public.ai_claim_retention_control where singleton and not restore_quarantine for share;
  if not found then raise exception 'claim restore quarantine active'; end if;
  return public.editor_review_ai_claim_before_restore_gate(p_review,p_request,p_index,p_article,p_decision);
end $$;



CREATE FUNCTION public.editor_review_ai_claim_before_restore_gate(p_review uuid, p_request uuid, p_index integer, p_article uuid, p_decision text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prior public.ai_claim_editor_reviews%rowtype; prep public.ai_request_preparations%rowtype;
  ids uuid[]; n integer; matched integer; proposal jsonb;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_review is null or p_request is null or p_article is null or p_index is null or p_index not between 0 and 29
    or p_decision is null or p_decision not in ('supported','rejected','needs_evidence') then raise exception 'invalid editorial review'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_review::text,456731));
  select * into prior from public.ai_claim_editor_reviews where id=p_review;
  if found then
    if prior.request_id is distinct from p_request or prior.proposal_index is distinct from p_index
      or prior.article_id is distinct from p_article or prior.reviewer_id is distinct from auth.uid() or prior.decision is distinct from p_decision then
      raise exception 'editorial review identity conflict'; end if;
    return false;
  end if;
  select * into prep from public.ai_request_preparations where request_id=p_request;
  if not found then raise exception 'proposal unavailable'; end if;
  select array_agg(article_id order by article_id),count(*) into ids,n from public.ai_request_preparation_inputs where request_id=p_request;
  if n<1 or n>50 or not (p_article=any(ids)) then raise exception 'proposal inputs unavailable'; end if;
  perform public.ai_lock_derived_claim_permissions(ids,prep.processor,prep.processing_region,'store');
  perform public.ai_lock_derived_claim_permissions(ids,prep.processor,prep.processing_region,'editor_display');
  perform a.id from public.articles a where a.id=any(ids) order by a.id for share;
  select count(*) into matched from public.ai_request_preparation_inputs x join public.articles a on a.id=x.article_id
    join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) p on true
    join public.ai_provider_title_grants g on g.id=x.provider_grant_id
    where x.request_id=p_request and x.policy_id=p.id and p.policy_status='approved' and p.title_storage_allowed and p.ai_processing_allowed
      and p.reviewed_by is not null and p.reviewed_at is not null and p.policy_evidence<>'{}'::jsonb
      and (p.permission_expires_at is null or p.permission_expires_at>clock_timestamp())
      and g.policy_id=p.id and g.provider=prep.processor and g.processing_region=prep.processing_region
      and (g.expires_at is null or g.expires_at>clock_timestamp())
      and not exists(select 1 from public.ai_provider_title_revocations r where r.grant_id=g.id)
      and x.title_sha256=encode(sha256(convert_to(a.title,'UTF8')),'hex');
  if matched<>n then raise exception 'proposal inputs changed'; end if;
  select content->'claims'->p_index into proposal from public.ai_claim_proposals
    where request_id=p_request and expires_at>clock_timestamp() for share;
  if proposal is null or not exists(select 1 from jsonb_array_elements(proposal->'evidence') e where e->>'article_id'=p_article::text) then
    raise exception 'proposal or selected evidence unavailable'; end if;
  perform public.ai_lock_derived_claim_permissions(ids,prep.processor,prep.processing_region,'store');
  perform public.ai_lock_derived_claim_permissions(ids,prep.processor,prep.processing_region,'editor_display');
  if not exists(select 1 from public.ai_claim_proposals where request_id=p_request and expires_at>clock_timestamp()) then
    raise exception 'proposal expired during review'; end if;
  insert into public.ai_claim_editor_reviews(id,request_id,proposal_index,article_id,decision,reviewer_id)
    values(p_review,p_request,p_index,p_article,p_decision,auth.uid());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'review_ai_claim','ai_claim_review',p_review,p_decision);
  return true;
end $$;



CREATE FUNCTION public.editor_review_bilingual_batch(p_batch uuid, p_version integer, p_decision text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  perform public.lock_editorial_channel_rollout();
  perform public.editor_review_bilingual_batch_before_evidence_gate(p_batch,p_version,p_decision,p_reason);
  if p_decision='approved' and not public.bilingual_batch_evidence_gate(p_batch) then
    raise exception 'bilingual evidence tier requirements not met';
  end if;
end $$;



CREATE FUNCTION public.editor_review_bilingual_batch_before_evidence_gate(p_batch uuid, p_version integer, p_decision text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.story_bilingual_batches%rowtype; v integer;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_decision is null or p_decision not in ('approved','rejected','needs_changes','needs_evidence') or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid review'; end if;
  select * into b from public.story_bilingual_batches where id=p_batch;
  if b.id is null then raise exception 'batch unavailable'; end if;
  select version into v from public.stories where id=b.story_id and archived_at is null for update;
  if v is null or v is distinct from p_version then raise exception 'story version conflict'; end if;
  if b.zh_revision_id is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id where l.story_id=b.story_id and l.locale='zh' order by r.revision_number desc limit 1)
    or b.en_revision_id is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id where l.story_id=b.story_id and l.locale='en' order by r.revision_number desc limit 1)
    then raise exception 'stale bilingual batch'; end if;
  perform s.id from public.sources s where exists(
    select 1 from public.articles a join public.claim_evidence e on e.article_id=a.id join public.claims c on c.id=e.claim_id
    where a.source_id=s.id and c.revision_id in (b.zh_revision_id,b.en_revision_id)) order by s.id for update;
  insert into public.editorial_reviews(revision_id,reviewer_id,decision,notes)
    values(b.zh_revision_id,auth.uid(),p_decision,trim(p_reason)),(b.en_revision_id,auth.uid(),p_decision,trim(p_reason));
  if p_decision='approved' and (not public.revision_is_eligible(b.story_id,b.zh_revision_id) or not public.revision_is_eligible(b.story_id,b.en_revision_id)) then
    raise exception 'both versions require current permissions and verified evidence';
  end if;
  insert into public.bilingual_editorial_reviews(batch_id,reviewer_id,decision,reason) values(b.id,auth.uid(),p_decision,trim(p_reason));
  update public.stories set version=version+1,bilingual_translation_status=case when p_decision='approved' then 'ready' else 'needs_review' end where id=b.story_id;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'review_bilingual_batch','story_bilingual_batch',b.id,trim(p_reason));
end $$;



CREATE FUNCTION public.editor_review_body_policy(p_source uuid, p_version integer, p_store boolean, p_process boolean, p_display boolean, p_basis text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare p public.source_policies%rowtype; result uuid;
begin
 if not public.editor_can_review_provider_grants() or current_setting('transaction_isolation')<>'read committed' then raise exception 'source reviewer required'; end if;
 if p_store is null or p_process is null or p_display is null or p_basis is null or length(trim(p_basis)) not between 1 and 4000 or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'review evidence required'; end if;
 perform 1 from public.sources where id=p_source for update;
 select * into p from public.source_policies where source_id=p_source order by version desc limit 1;
 if p.id is null or p.version is distinct from p_version or p.policy_status<>'approved' or not p.access_allowed
 or (p.permission_expires_at is not null and p.permission_expires_at<=clock_timestamp()) then raise exception 'current approved policy required'; end if;
 if not p_process and p.title_ai_processing_allowed then raise exception 'withdraw title processing before global processing'; end if;
 insert into public.source_policies(source_id,version,policy_status,access_allowed,ai_processing_allowed,display_allowed,
 fulltext_storage_allowed,image_usage_allowed,policy_evidence,reviewed_by,reviewed_at,story_publication_allowed,permission_expires_at,
 access_method,title_storage_allowed,url_storage_allowed,source_display_allowed,link_display_allowed,terms_url,robots_url,
 attribution_requirements,permitted_region,title_ai_processing_allowed,ai_processor,ai_processing_region)
 values(p.source_id,p.version+1,p.policy_status,p.access_allowed,p_process,p_display,p_store,p.image_usage_allowed,
 p.policy_evidence||jsonb_build_object('body_basis',trim(p_basis)),auth.uid(),clock_timestamp(),p.story_publication_allowed,p.permission_expires_at,
 p.access_method,p.title_storage_allowed,p.url_storage_allowed,p.source_display_allowed,p.link_display_allowed,p.terms_url,p.robots_url,
 p.attribution_requirements,p.permitted_region,p.title_ai_processing_allowed,p.ai_processor,p.ai_processing_region) returning id into result;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'review_body_policy','source_policy',result,p_reason);
 return result;
end $$;



CREATE FUNCTION public.editor_review_classification(p_id uuid, p_proposal uuid, p_decision text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare candidate public.classification_proposals%rowtype; prior public.classification_reviews%rowtype; s record; d record;
  model_request uuid; process_deadline timestamptz;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_proposal is null or p_decision is null or p_decision not in ('accept','reject','needs_evidence') then raise exception 'invalid review'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7743));
  perform 1 from public.classification_retention_control where singleton and not restore_quarantine for share;
  if not found then raise exception 'classification unavailable'; end if;
  select * into candidate from public.classification_proposals where id=p_proposal;
  if not found then raise exception 'classification unavailable'; end if;
  select * into s from public.lock_classification_scope(candidate.article_id,candidate.provider,candidate.region,'store');
  select * into d from public.lock_classification_scope(candidate.article_id,candidate.provider,candidate.region,'editor_display');
  select request_id into model_request from public.classification_model_receipts where proposal_id=p_proposal;
  if model_request is not null then
    process_deadline:=public.lock_classification_processing(candidate.article_id,candidate.provider,candidate.region);
    perform c.id from public.categories c join public.classification_request_categories x on x.category_id=c.id where x.request_id=model_request order by c.id for share of c;
  end if;
  perform 1 from public.categories where id=candidate.category_id and active for share;
  if not found then raise exception 'classification unavailable'; end if;
  perform 1 from public.classification_proposals where id=p_proposal for share;
  if not found or not public.classification_visible(candidate) or candidate.policy_id<>s.policy_id or candidate.provider_grant_id<>s.provider_grant_id
    or candidate.title_sha256<>s.title_sha256 or candidate.expires_at<=clock_timestamp() or s.deadline<=clock_timestamp() or d.deadline<=clock_timestamp()
    or (model_request is not null and (process_deadline is null or process_deadline<=clock_timestamp())) then raise exception 'classification unavailable'; end if;
  select * into prior from public.classification_reviews where id=p_id;
  if found then
    if prior.proposal_id<>p_proposal or prior.decision<>p_decision or prior.reviewer_id<>auth.uid() then raise exception 'review identity conflict'; end if;
    return false;
  end if;
  insert into public.classification_reviews(id,proposal_id,decision,reviewer_id) values(p_id,p_proposal,p_decision,auth.uid());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'review_classification','classification_proposal',p_proposal,p_decision);
  return true;
end $$;



CREATE FUNCTION public.editor_review_full_article(p_draft uuid, p_decision text, p_facts boolean, p_originality boolean, p_bilingual boolean, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result uuid; rid uuid;
begin
 if not public.is_active_editor() or current_setting('transaction_isolation')<>'read committed' then raise exception 'editor required'; end if;
 select snapshot_id into rid from public.article_full_drafts where id=p_draft;
 perform public.article_body_scope(r.article_id,r.region,array['display_draft']) from public.article_body_receipts r where r.id=rid;
 if public.editor_get_full_article_draft(p_draft) is null then raise exception 'proposal expired or unavailable'; end if;
 insert into public.article_full_reviews(draft_id,decision,facts_checked,originality_checked,bilingual_checked,reason,reviewed_by)
 values(p_draft,p_decision,p_facts,p_originality,p_bilingual,p_reason,auth.uid()) returning id into result;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'review_full_article','full_article_draft',p_draft,p_reason);
 return result;
end $$;



CREATE FUNCTION public.editor_review_full_article_revision(p_revision uuid, p_batch uuid, p_decision text, p_facts boolean, p_originality boolean, p_bilingual boolean) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result bigint; d uuid; sid uuid; hash text;
begin
 if session_user<>'authenticator' or public.is_active_editor() is distinct from true then raise exception 'authenticated editor required'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
 if p_decision is null or p_decision not in ('approved','needs_changes','needs_evidence') or p_facts is null or p_originality is null or p_bilingual is null then raise exception 'invalid revision review'; end if;
 perform public.lock_editorial_channel_rollout();
 select er.draft_id,er.content_sha256,q.story_id into d,hash,sid from public.article_editor_revision_receipts er join public.article_full_review_queue q on q.draft_id=er.draft_id where er.id=p_revision;
 perform pg_advisory_xact_lock(hashtextextended(d::text,903515));
 perform 1 from public.stories where id=sid for update;
 perform public.article_body_scope(r.article_id,r.region,array['display_draft']) from public.article_full_drafts f join public.article_body_receipts r on r.id=f.snapshot_id where f.id=d;
 if not public.article_editor_revision_live(p_revision) then raise exception 'revision expired stale or unavailable'; end if;
 if not exists(select 1 from public.story_bilingual_batches where id=p_batch and story_id=sid) then raise exception 'revision batch mismatch'; end if;
 if p_decision='approved' and (not (p_facts and p_originality and p_bilingual) or not public.article_revision_batch_matches(p_revision,p_batch) or not public.bilingual_channel_publication_ready(p_batch)) then raise exception 'complete checks and matching evidence-reviewed batch required'; end if;
 insert into public.article_editor_revision_reviews(revision_id,batch_id,content_sha256,decision,facts_checked,originality_checked,bilingual_checked,reviewed_by)
 values(p_revision,p_batch,hash,p_decision,p_facts,p_originality,p_bilingual,auth.uid()) returning id into result;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'review_editor_revision','article_editor_revision',p_revision,p_decision);
 return result;
end $$;



CREATE FUNCTION public.editor_review_monthly_cny_fx(p_month date, p_expected_version integer, p_fx_micros bigint, p_evidence text, p_valid_until timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.ai_monthly_cny_budgets%rowtype; v integer; highest bigint; total numeric; result uuid; current_month date;
begin
  -- Existing trusted Supabase/PostgREST authentication only. A direct admin or
  -- runtime connection setting JWT claims must not masquerade as this reviewer.
  if session_user<>'authenticator' or public.editor_can_review_ai_billing() is distinct from true then
    raise exception 'authenticated billing reviewer required';
  end if;
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  current_month:=date_trunc('month',clock_timestamp() at time zone 'UTC')::date;
  if p_month is null or p_month<>current_month or p_expected_version is null or p_expected_version<0
    or p_fx_micros is null or p_fx_micros not between 1000000 and 100000000
    or p_evidence is null or length(trim(p_evidence)) not between 1 and 2000
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000
    or p_valid_until is null or p_valid_until<=clock_timestamp()
    or p_valid_until>((p_month+interval '1 month')::timestamp at time zone 'UTC') then raise exception 'invalid monthly FX review'; end if;
  select * into b from public.ai_monthly_cny_budgets where month_start=p_month for update;
  if b.month_start is null then raise exception 'approved monthly cap must already exist'; end if;
  select coalesce(max(version),0),greatest(b.cny_per_usd_micros,coalesce(max(cny_per_usd_micros),b.cny_per_usd_micros))
    into v,highest from public.ai_monthly_cny_fx_reviews where month_start=p_month;
  if v<>p_expected_version then raise exception 'monthly FX version conflict'; end if;
  -- Even a withdrawn/expired prior high ceiling is not silently relaxed. A
  -- lower accounting rate needs a separately reviewed design, not this RPC.
  if p_fx_micros<highest then raise exception 'monthly FX ceiling cannot decrease'; end if;
  select coalesce(sum(case when state='settled' then actual_nanos else reserved_nanos end),0)
    into total from public.ai_budget_reservations where budget_day>=p_month and budget_day<(p_month+interval '1 month')::date;
  if ceil(total*p_fx_micros/10000000000000::numeric)>b.limit_fen then raise exception 'existing commitments exceed monthly cap at reviewed FX'; end if;
  if p_valid_until<=clock_timestamp() or p_month<>date_trunc('month',clock_timestamp() at time zone 'UTC')::date then
    raise exception 'monthly FX review expired or month changed';
  end if;
  insert into public.ai_monthly_cny_fx_reviews(month_start,version,cny_per_usd_micros,evidence,valid_from,valid_until,reviewed_by)
    values(p_month,v+1,p_fx_micros,trim(p_evidence),clock_timestamp(),p_valid_until,auth.uid()) returning id into result;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'review_monthly_cny_fx','ai_monthly_cny_fx_review',result,trim(p_reason));
  return result;
end $$;



CREATE FUNCTION public.editor_review_rss_endpoint(p_source uuid, p_expected_version integer, p_url text, p_interval integer, p_access_evidence text, p_robots_evidence text, p_expires timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare p public.source_policies%rowtype; new_policy_id uuid; endpoint_id uuid; host text;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.is_active_editor() or not exists(select 1 from public.editors where user_id=auth.uid() and active and can_review_sources) then
    raise exception 'source reviewer access required';
  end if;
  -- Lowercase ASCII hostname, HTTPS/443, no query, fragment, credentials or IP
  -- literals. The Python fetch validator performs additional strict checks.
  if p_url is null or length(p_url) > 2048 or p_url !~ '^https://[a-z0-9]([a-z0-9.-]*[a-z0-9])?/[A-Za-z0-9._~/%+-]*$'
    or p_url ~ '^https://[0-9.]+/' or p_url ~ '^https://[^/]*\.\.' then raise exception 'invalid RSS endpoint'; end if;
  host := substring(p_url from '^https://([^/]+)/');
  if host !~ '^[a-z0-9-]+(\.[a-z0-9-]+)+$' or host ~ '(^|\.)(localhost|local|internal)$' then raise exception 'invalid RSS hostname'; end if;
  if p_interval is null or p_interval not between 60 and 86400
    or p_access_evidence is null or length(trim(p_access_evidence)) not between 1 and 2000
    or p_robots_evidence is null or length(trim(p_robots_evidence)) not between 1 and 2000
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000
    or p_expires is null or p_expires <= clock_timestamp() then raise exception 'invalid RSS review'; end if;
  perform 1 from public.sources where id=p_source for update;
  if not found then raise exception 'source not found'; end if;
  select * into p from public.source_policies where source_id=p_source order by version desc limit 1;
  if p.id is null or p.version is distinct from p_expected_version then raise exception 'source policy version conflict'; end if;
  if p.policy_status <> 'approved' or not p.title_storage_allowed or not p.url_storage_allowed
    or p.reviewed_by is null or p.reviewed_at is null or jsonb_typeof(p.policy_evidence) <> 'object' or p.policy_evidence = '{}'::jsonb
    or (p.permission_expires_at is not null and (p.permission_expires_at <= clock_timestamp() or p_expires > p.permission_expires_at)) then
    raise exception 'current metadata permission unavailable';
  end if;
  insert into public.source_policies(source_id,version,policy_status,access_allowed,ai_processing_allowed,display_allowed,
    fulltext_storage_allowed,image_usage_allowed,policy_evidence,reviewed_by,reviewed_at,story_publication_allowed,permission_expires_at,
    access_method,title_storage_allowed,url_storage_allowed,source_display_allowed,link_display_allowed,terms_url,robots_url,
    attribution_requirements,permitted_region,title_ai_processing_allowed,ai_processor,ai_processing_region)
  values(p.source_id,p.version+1,p.policy_status,true,p.ai_processing_allowed,p.display_allowed,p.fulltext_storage_allowed,p.image_usage_allowed,
    p.policy_evidence,auth.uid(),clock_timestamp(),p.story_publication_allowed,p.permission_expires_at,'rss',p.title_storage_allowed,
    p.url_storage_allowed,p.source_display_allowed,p.link_display_allowed,p.terms_url,p.robots_url,p.attribution_requirements,p.permitted_region,
    p.title_ai_processing_allowed,p.ai_processor,p.ai_processing_region) returning id into new_policy_id;
  insert into public.ai_provider_title_grants(policy_id,provider,processing_region,evidence,reviewed_by,reviewed_at,expires_at,previous_grant_id)
    select new_policy_id,g.provider,g.processing_region,g.evidence,g.reviewed_by,g.reviewed_at,g.expires_at,g.id
    from public.ai_provider_title_grants g where g.policy_id=p.id
      and (g.expires_at is null or g.expires_at > clock_timestamp())
      and not exists(select 1 from public.ai_provider_title_revocations r where r.grant_id=g.id);
  insert into public.rss_endpoint_reviews(policy_id,feed_url,hostname,min_interval_seconds,access_evidence,robots_evidence,expires_at,reviewed_by)
    values(new_policy_id,p_url,host,p_interval,trim(p_access_evidence),trim(p_robots_evidence),p_expires,auth.uid()) returning id into endpoint_id;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'review_rss_endpoint','rss_endpoint_review',endpoint_id,trim(p_reason));
  return endpoint_id;
end $_$;



CREATE FUNCTION public.editor_review_story_summary(p_id uuid, p_proposal uuid, p_decision text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare candidate public.story_summary_proposals%rowtype; prior public.story_summary_reviews%rowtype; deadline timestamptz;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_proposal is null or p_decision is null or p_decision not in ('accept','reject','needs_evidence') then raise exception 'invalid review'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7732));
  perform 1 from public.story_summary_retention_control where singleton and not restore_quarantine for share;
  if not found then raise exception 'story summary unavailable'; end if;
  select * into candidate from public.story_summary_proposals where id=p_proposal;
  if not found then raise exception 'story summary unavailable'; end if;
  deadline:=public.ai_lock_story_summary_request(candidate.request_id);
  perform 1 from public.story_summary_proposals where id=p_proposal for share;
  if not found or deadline<=clock_timestamp() or not public.story_summary_visible(candidate) then raise exception 'story summary unavailable'; end if;
  select * into prior from public.story_summary_reviews where id=p_id;
  if found then
    if prior.proposal_id<>p_proposal or prior.decision<>p_decision or prior.reviewer_id<>auth.uid() then raise exception 'review identity conflict'; end if;
    return false;
  end if;
  insert into public.story_summary_reviews(id,proposal_id,decision,reviewer_id) values(p_id,p_proposal,p_decision,auth.uid());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'review_story_summary','story_summary_proposal',p_proposal,p_decision);
  return true;
end $$;



CREATE FUNCTION public.editor_review_summary(p_id uuid, p_proposal uuid, p_decision text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare candidate public.summary_proposals%rowtype; prior public.summary_reviews%rowtype; store_deadline timestamptz; display_deadline timestamptz; model_request uuid; process_deadline timestamptz;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_proposal is null or p_decision is null or p_decision not in ('accept','reject','needs_evidence') then raise exception 'invalid review'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7732));
  perform 1 from public.summary_retention_control where singleton and not restore_quarantine for share;
  if not found then raise exception 'summary unavailable'; end if;
  select * into candidate from public.summary_proposals where id=p_proposal;
  if not found then raise exception 'summary unavailable'; end if;
  perform public.lock_summary_fact(candidate.fact_id);
  store_deadline:=public.summary_scope_deadline(candidate.fact_id,candidate.provider,candidate.region,'store');
  display_deadline:=public.summary_scope_deadline(candidate.fact_id,candidate.provider,candidate.region,'editor_display');
  select request_id into model_request from public.summary_model_receipts where proposal_id=p_proposal;
  if model_request is not null then
    select min(x.deadline) into process_deadline from public.lock_summary_processing(candidate.fact_id,candidate.provider,candidate.region,model_request) x;
  end if;
  perform 1 from public.summary_proposals where id=p_proposal for share;
  if not found or not public.summary_visible(candidate) or (model_request is not null and (process_deadline is null or process_deadline<=clock_timestamp())) or candidate.expires_at<=clock_timestamp() or store_deadline is null or store_deadline<=clock_timestamp()
     or display_deadline is null or display_deadline<=clock_timestamp() then raise exception 'summary unavailable'; end if;
  select * into prior from public.summary_reviews where id=p_id;
  if found then
    if prior.proposal_id<>p_proposal or prior.decision<>p_decision or prior.reviewer_id<>auth.uid() then raise exception 'review identity conflict'; end if;
    return false;
  end if;
  insert into public.summary_reviews(id,proposal_id,decision,reviewer_id) values(p_id,p_proposal,p_decision,auth.uid());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'review_summary','summary_proposal',p_proposal,p_decision);
  return true;
end $$;



CREATE FUNCTION public.editor_review_title_ai_permission(p_source uuid, p_expected_version integer, p_allow boolean, p_region text, p_basis text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare p public.source_policies%rowtype; policy_id uuid;
begin
  if not public.is_active_editor() or not exists(select 1 from public.editors where user_id=auth.uid() and active and can_review_sources) then
    raise exception 'source reviewer access required';
  end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_source is null or p_expected_version is null or p_expected_version < 1 or p_allow is null
    or p_basis is null or length(trim(p_basis)) not between 1 and 2000
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid AI permission review'; end if;
  if p_allow and (p_region is null or p_region !~ '^[a-z0-9-]{2,40}$') then raise exception 'invalid AI processing region'; end if;
  if not p_allow and p_region is not null then raise exception 'region must be empty when withdrawing permission'; end if;
  perform 1 from public.sources where id=p_source for update;
  if not found then raise exception 'source not found'; end if;
  select * into p from public.source_policies where source_id=p_source order by version desc limit 1;
  if p.id is null or p.version <> p_expected_version then raise exception 'source policy version conflict'; end if;
  if p.policy_status <> 'approved' or not p.title_storage_allowed
    or p.reviewed_by is null or p.reviewed_at is null or jsonb_typeof(p.policy_evidence) <> 'object' or p.policy_evidence = '{}'::jsonb
    or (p.permission_expires_at is not null and p.permission_expires_at <= clock_timestamp()) then
    raise exception 'current approved title policy required';
  end if;
  insert into public.source_policies(source_id,version,policy_status,access_allowed,ai_processing_allowed,display_allowed,
    fulltext_storage_allowed,image_usage_allowed,policy_evidence,reviewed_by,reviewed_at,story_publication_allowed,permission_expires_at,
    access_method,title_storage_allowed,url_storage_allowed,source_display_allowed,link_display_allowed,terms_url,robots_url,
    attribution_requirements,permitted_region,title_ai_processing_allowed,ai_processor,ai_processing_region)
  values(p.source_id,p.version+1,p.policy_status,p.access_allowed,case when p_allow then true else p.ai_processing_allowed end,p.display_allowed,
    p.fulltext_storage_allowed,p.image_usage_allowed,p.policy_evidence || jsonb_build_object('ai_title_basis',trim(p_basis)),auth.uid(),clock_timestamp(),
    p.story_publication_allowed,p.permission_expires_at,p.access_method,p.title_storage_allowed,p.url_storage_allowed,p.source_display_allowed,
    p.link_display_allowed,p.terms_url,p.robots_url,p.attribution_requirements,p.permitted_region,p_allow,
    case when p_allow then 'openai' else null end,case when p_allow then p_region else null end)
  returning id into policy_id;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'review_title_ai_permission','source_policy',policy_id,trim(p_reason));
  return policy_id;
end $_$;



CREATE FUNCTION public.editor_revision_evidence_triage(p_revision uuid) RETURNS TABLE(claim_id uuid, status text, verified_supporting_articles bigint, independent_supporting_sources bigint, pending_evidence bigint, requires_conflict_review boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_revision is null or not exists(select 1 from public.story_revisions where id=p_revision) then raise exception 'revision unavailable'; end if;
  return query with evidence as (
    select c.id,c.status as claim_status,e.article_id,e.relation,a.source_id,sa.independence,sa.reporting_role,sa.syndicated_from_article_id,
      coalesce(e.verified_by is not null and e.verified_at is not null and length(trim(e.evidence_reference))>0,false) as reviewed,
      coalesce(sa.article_id is not null and p.policy_status='approved' and p.display_allowed and p.story_publication_allowed
        and p.reviewed_by is not null and p.reviewed_at is not null and p.policy_evidence<>'{}'::jsonb
        and (p.permission_expires_at is null or p.permission_expires_at>statement_timestamp()),false) as permitted
    from public.claims c join public.story_revisions r on r.id=c.revision_id
    left join public.claim_evidence e on e.claim_id=c.id left join public.articles a on a.id=e.article_id
    left join public.story_articles sa on sa.story_id=r.story_id and sa.article_id=e.article_id
    left join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by version desc limit 1) p on true
    where c.revision_id=p_revision
  ), aggregated as (
    select e.id,coalesce(bool_or(e.claim_status='disputed' or e.relation='contradicts'),false) as conflict,
      count(distinct e.article_id) filter(where e.relation='supports' and e.reviewed and e.permitted) as supporting,
      count(distinct e.source_id) filter(where e.relation='supports' and e.reviewed and e.permitted and e.independence='independent'
        and e.reporting_role<>'syndicated' and e.syndicated_from_article_id is null) as independent,
      count(distinct e.article_id) filter(where e.article_id is not null and (not e.reviewed or not e.permitted)) as pending
    from evidence e group by e.id
  )
  select a.id,case when a.conflict then 'conflict_review' when a.supporting=0 or a.pending>0 then 'needs_evidence' else 'editor_review' end,
    a.supporting,a.independent,a.pending,a.conflict from aggregated a order by a.id;
end $$;



CREATE FUNCTION public.editor_revision_sources_available(p_revision uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(select 1 from public.story_revisions where id=p_revision)
    and not exists(select 1 from public.translation_revision_imports i where i.target_revision_id=p_revision
      and not public.translation_request_accessible(i.request_id))
    and not exists (
      select 1 from public.claims c join public.claim_evidence e on e.claim_id=c.id
      join public.story_revisions r on r.id=c.revision_id
      left join public.articles a on a.id=e.article_id
      left join public.story_articles sa on sa.story_id=r.story_id and sa.article_id=e.article_id
      left join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by version desc limit 1) p on true
      where c.revision_id=p_revision and not coalesce(
        sa.article_id is not null and p.policy_status='approved' and p.display_allowed and p.story_publication_allowed
        and p.reviewed_by is not null and p.reviewed_at is not null and jsonb_typeof(p.policy_evidence)='object'
        and p.policy_evidence<>'{}'::jsonb and (p.permission_expires_at is null or p.permission_expires_at>clock_timestamp()),false))
$$;



CREATE FUNCTION public.editor_revoke_article_body(p_grant uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid;
begin
 if not public.editor_can_review_provider_grants() or current_setting('transaction_isolation')<>'read committed' then raise exception 'source reviewer required'; end if;
 if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reason required'; end if;
 select p.source_id into sid from public.article_body_grants g join public.source_policies p on p.id=g.policy_id where g.id=p_grant;
 perform 1 from public.sources where id=sid for update;
 if not found then raise exception 'grant unavailable'; end if;
 insert into public.article_body_revocations(grant_id,reason,revoked_by) values(p_grant,p_reason,auth.uid()) on conflict do nothing;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'revoke_article_body','source',sid,p_reason);
end $$;



CREATE FUNCTION public.editor_revoke_article_body_bound(p_approval uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if not public.editor_can_review_ai_billing() or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'billing reviewer and reason required'; end if;
 perform b.id from public.ai_billing_bounds b join public.article_body_billing_approvals a on a.bound_id=b.id where a.id=p_approval for update of b;
 if not found then raise exception 'approval unavailable'; end if;
 insert into public.article_body_billing_revocations values(p_approval,auth.uid(),p_reason) on conflict do nothing;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'revoke_full_body_billing','billing_approval',p_approval,p_reason);
end $$;



CREATE FUNCTION public.editor_revoke_article_stage_config(p_config uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000
 then raise exception 'AI operator and reason required'; end if;
 perform 1 from public.article_stage_configs where id=p_config for update;
 if not found then raise exception 'article stage configuration unavailable'; end if;
 insert into public.article_stage_config_revocations(config_id,revoked_by,reason) values(p_config,auth.uid(),trim(p_reason)) on conflict do nothing;
 if not found then return false; end if;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'revoke_article_stage_config','article_stage_config',p_config,trim(p_reason));
 return true;
end $$;



CREATE FUNCTION public.editor_revoke_classification(p_grant uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare g public.classification_grants%rowtype; sid uuid; n integer;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  if p_grant is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid revocation'; end if;
  select * into g from public.classification_grants where id=p_grant;
  select source_id into sid from public.source_policies where id=g.policy_id;
  if sid is null then raise exception 'permission unavailable'; end if;
  perform 1 from public.sources where id=sid for update;
  insert into public.classification_grant_revocations(grant_id,revoked_by,reason) values(p_grant,auth.uid(),trim(p_reason)) on conflict do nothing;
  get diagnostics n=row_count;
  if n=1 then
    if g.action='store' then delete from public.classification_proposals p where p.policy_id=g.policy_id and p.provider=g.provider and p.region=g.region; end if;
    insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'revoke_classification','source',sid,trim(p_reason));
  end if;
  return n=1;
end $$;



CREATE FUNCTION public.editor_revoke_classification_bound(p_approval uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare bid uuid; n integer;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.editor_can_review_ai_billing() then raise exception 'billing reviewer access required'; end if;
  if p_approval is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid billing withdrawal'; end if;
  select bound_id into bid from public.classification_billing_approvals where id=p_approval;
  if bid is null then raise exception 'billing approval unavailable'; end if;
  perform 1 from public.ai_billing_bounds where id=bid for update;
  insert into public.classification_billing_revocations(approval_id,revoked_by,reason) values(p_approval,auth.uid(),trim(p_reason)) on conflict do nothing;
  get diagnostics n=row_count;
  if n=1 then insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'revoke_classification_bound','ai_billing_bound',bid,trim(p_reason)); end if;
  return n=1;
end $$;



CREATE FUNCTION public.editor_revoke_classification_processing(p_grant uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid; n integer;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  if p_grant is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid revocation'; end if;
  select p.source_id into sid from public.classification_processing_grants g join public.source_policies p on p.id=g.policy_id where g.id=p_grant;
  if sid is null then raise exception 'permission unavailable'; end if;
  perform 1 from public.sources where id=sid for update;
  insert into public.classification_processing_revocations(grant_id,revoked_by,reason) values(p_grant,auth.uid(),trim(p_reason)) on conflict do nothing;
  get diagnostics n=row_count;
  if n=1 then insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'revoke_classification_processing','source',sid,trim(p_reason)); end if;
  return n=1;
end $$;



CREATE FUNCTION public.editor_revoke_daily(p_selection uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare entry public.daily_editorial_selections%rowtype;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reason required'; end if;
  select * into entry from public.daily_editorial_selections where id=p_selection;
  if not found then raise exception 'selection unavailable'; end if;
  perform pg_advisory_xact_lock(hashtextextended(entry.selection_day::text,76132));
  insert into public.daily_selection_revocations(selection_id,actor_id,reason) values(p_selection,auth.uid(),trim(p_reason));
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'revoke_daily','story',entry.story_id,trim(p_reason));
end $$;



CREATE FUNCTION public.editor_revoke_derived_claim(p_grant uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid; inserted integer;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  if p_grant is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid revocation'; end if;
  select p.source_id into sid from public.ai_derived_claim_grants g join public.source_policies p on p.id=g.policy_id where g.id=p_grant;
  if sid is null then raise exception 'permission unavailable'; end if;
  perform 1 from public.sources where id=sid for update;
  insert into public.ai_derived_claim_revocations(grant_id,reason,revoked_by) values(p_grant,trim(p_reason),auth.uid()) on conflict do nothing;
  get diagnostics inserted = row_count;
  if inserted=1 then insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'revoke_ai_derived_claim','source',sid,trim(p_reason)); end if;
  return inserted=1;
end $$;



CREATE FUNCTION public.editor_revoke_duplicate_link(p_story uuid, p_version integer, p_link uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare s public.stories%rowtype;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reason required'; end if;
  select * into s from public.stories where id=p_story for update;
  if s.id is null or s.version is distinct from p_version then raise exception 'story version conflict'; end if;
  if not exists(select 1 from public.story_duplicate_links where id=p_link and source_story_id=p_story) then raise exception 'duplicate link unavailable'; end if;
  insert into public.story_duplicate_link_revocations(link_id,actor_id,reason) values(p_link,auth.uid(),trim(p_reason));
  update public.stories set version=version+1 where id=p_story;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'revoke_duplicate_link','story',p_story,trim(p_reason));
end $$;



CREATE FUNCTION public.editor_revoke_provider_title_grant(p_source uuid, p_expected_version integer, p_grant uuid, p_evidence text, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare p public.source_policies%rowtype; inserted_id uuid;
begin
  if not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_source is null or p_expected_version is null or p_expected_version<1 or p_grant is null
    or p_evidence is null or length(trim(p_evidence)) not between 1 and 2000
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid provider revocation'; end if;
  perform 1 from public.sources where id=p_source for update;
  if not found then raise exception 'source not found'; end if;
  select * into p from public.source_policies where source_id=p_source order by version desc limit 1;
  if p.id is null or p.version <> p_expected_version then raise exception 'source policy version conflict'; end if;
  if not exists(select 1 from public.ai_provider_title_grants where id=p_grant and policy_id=p.id) then raise exception 'current provider grant unavailable'; end if;
  insert into public.ai_provider_title_revocations(grant_id,reason,revoked_by,evidence)
    values(p_grant,trim(p_reason),auth.uid(),jsonb_build_object('basis',trim(p_evidence)))
    on conflict(grant_id) do nothing returning grant_id into inserted_id;
  if inserted_id is null then return false; end if;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'revoke_provider_title','ai_provider_title_grant',p_grant,trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editor_revoke_review(p_request uuid, p_revision uuid, p_review uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid; current_review public.editorial_reviews%rowtype; prior public.review_revocations%rowtype; replacement uuid;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_request is null or p_revision is null or p_review is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid revocation'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,1032));
  select story_id into sid from public.story_revisions where id=p_revision;
  if sid is null then raise exception 'revision unavailable'; end if;
  perform 1 from public.stories where id=sid for update;
  select * into prior from public.review_revocations where request_id=p_request;
  if found then
    if prior.revision_id is distinct from p_revision or prior.review_id is distinct from p_review or prior.actor_id is distinct from auth.uid()
      or prior.reason is distinct from trim(p_reason) then raise exception 'revocation identity conflict'; end if;
    return false;
  end if;
  if exists(select 1 from public.stories where id=sid and public_revision_id=p_revision and visibility='public')
    then raise exception 'published revision requires separate hide or correction'; end if;
  select * into current_review from public.editorial_reviews where revision_id=p_revision order by review_order desc limit 1;
  if current_review.id is distinct from p_review or current_review.decision not in ('approved','rejected') then raise exception 'review is no longer revocable'; end if;
  insert into public.editorial_reviews(revision_id,reviewer_id,decision,notes)
    values(p_revision,auth.uid(),'needs_changes','Review revoked: '||trim(p_reason)) returning id into replacement;
  insert into public.review_revocations values(p_request,p_revision,p_review,replacement,auth.uid(),trim(p_reason),clock_timestamp());
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'revoke_review','story_revision',p_revision,trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editor_revoke_rss_validators(p_endpoint uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid; inserted boolean;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.is_active_editor() or not exists(select 1 from public.editors where user_id=auth.uid() and active and can_review_sources) then raise exception 'source reviewer access required'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reason required'; end if;
  select p.source_id into sid from public.rss_endpoint_reviews e join public.source_policies p on p.id=e.policy_id where e.id=p_endpoint;
  if sid is null then raise exception 'endpoint not found'; end if;
  perform 1 from public.sources where id=sid for update;
  insert into public.rss_validator_revocations(endpoint_id,reviewed_by,reason)
    values(p_endpoint,auth.uid(),trim(p_reason)) on conflict do nothing;
  inserted := found;
  delete from public.rss_endpoint_validators where endpoint_id=p_endpoint;
  update public.ingestion_dispatches set if_none_match=null,if_modified_since=null
    where endpoint_id=p_endpoint and (if_none_match is not null or if_modified_since is not null);
  return inserted;
end $$;



CREATE FUNCTION public.editor_revoke_source_body_rule(p_rule uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid;
begin
 if public.editor_can_review_provider_grants() is distinct from true or auth.uid() is null
  or current_setting('transaction_isolation')<>'read committed' or p_reason is null or length(trim(p_reason)) not between 1 and 1000
 then raise exception 'source reviewer and reason required'; end if;
 select p.source_id into sid from public.article_body_source_rules r join public.source_policies p on p.id=r.policy_id where r.id=p_rule;
 if sid is null then raise exception 'source body rule unavailable'; end if;
 perform 1 from public.sources where id=sid for update;
 insert into public.article_body_source_rule_revocations(rule_id,revoked_by,reason) values(p_rule,auth.uid(),trim(p_reason)) on conflict do nothing;
 if not found then return false; end if;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'revoke_source_body_rule','source',sid,trim(p_reason));
 return true;
end $$;



CREATE FUNCTION public.editor_revoke_story_summary_bound(p_approval uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare bid uuid; n integer;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.editor_can_review_ai_billing() then raise exception 'billing reviewer access required'; end if;
  if p_approval is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid billing withdrawal'; end if;
  select bound_id into bid from public.story_summary_billing_approvals where id=p_approval;
  if bid is null then raise exception 'billing approval unavailable'; end if;
