  return n=1;
end $$;



CREATE FUNCTION public.editor_revoke_summary(p_grant uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare g public.summary_grants%rowtype; sid uuid; n integer;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  if p_grant is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid revocation'; end if;
  select * into g from public.summary_grants where id=p_grant;
  select source_id into sid from public.source_policies where id=g.policy_id;
  if sid is null then raise exception 'permission unavailable'; end if;
  perform 1 from public.sources where id=sid for update;
  insert into public.summary_grant_revocations(grant_id,revoked_by,reason) values(p_grant,auth.uid(),trim(p_reason)) on conflict do nothing;
  get diagnostics n=row_count;
  if n=1 then
    if g.action='store' then delete from public.summary_proposals p using public.ai_verified_facts f
      where f.id=p.fact_id and p.provider=g.provider and p.region=g.region and exists(select 1 from public.ai_request_preparation_inputs i
        where i.request_id=f.request_id and i.policy_id=g.policy_id); end if;
    insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'revoke_summary','source',sid,trim(p_reason));
  end if;
  return n=1;
end $$;



