CREATE FUNCTION public.editor_revoke_verified_fact(p_grant uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare g public.ai_verified_fact_grants%rowtype; sid uuid; inserted integer;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.editor_can_review_provider_grants() then raise exception 'source reviewer access required'; end if;
  if p_grant is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid revocation'; end if;
  select * into g from public.ai_verified_fact_grants where id=p_grant;
  select source_id into sid from public.source_policies where id=g.policy_id;
  if sid is null then raise exception 'permission unavailable'; end if;
  perform 1 from public.sources where id=sid for update;
  insert into public.ai_verified_fact_grant_revocations(grant_id,revoked_by,reason) values(p_grant,auth.uid(),trim(p_reason)) on conflict do nothing;
  get diagnostics inserted=row_count;
  if inserted=1 then
    if g.permitted_action='verified_store' then
      delete from public.ai_verified_facts f using public.ai_request_preparations p where p.request_id=f.request_id
        and p.processor=g.provider and p.processing_region=g.processing_region and exists(
          select 1 from public.ai_request_preparation_inputs i join public.articles a on a.id=i.article_id where i.request_id=f.request_id and a.source_id=sid);
    end if;
    insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'revoke_verified_fact','source',sid,trim(p_reason));
  end if;
  return inserted=1;
end $$;



CREATE FUNCTION public.editor_save_full_article_revision(p_draft uuid, p_parent uuid, p_content jsonb, p_reason_code text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare draft public.article_full_drafts%rowtype; ctx public.article_body_request_context%rowtype;
 latest uuid; latest_number integer; result uuid; expiry timestamptz; lang text; section text; segment jsonb; cid text;
begin
 if session_user<>'authenticator' or public.is_active_editor() is distinct from true then raise exception 'authenticated editor required'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
 if p_draft is null or p_reason_code is null or p_reason_code not in ('factual_correction','bilingual_correction','clarity_correction') then raise exception 'invalid revision request'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_draft::text,903515));
 select * into draft from public.article_full_drafts where id=p_draft;
 if draft.id is null or public.editor_get_full_article_draft(p_draft) is null then raise exception 'original draft expired or unavailable'; end if;
 perform public.article_body_scope(r.article_id,r.region,array['store_draft','display_draft']) from public.article_body_receipts r where r.id=draft.snapshot_id;
 perform 1 from public.article_body_retention_control where singleton and not restore_quarantine for update;
 if not found then raise exception 'body retention unavailable'; end if;
 select receipt.id,receipt.revision_number into latest,latest_number from public.article_editor_revision_receipts receipt
 where receipt.draft_id=p_draft order by receipt.revision_number desc limit 1;
 if latest is distinct from p_parent then raise exception 'revision parent conflict'; end if;
 expiry:=draft.expires_at;
 if p_parent is not null then
 select least(expiry,c.expires_at) into expiry from public.article_editor_revision_content c
 join public.article_editor_revision_receipts r on r.id=c.id where c.id=p_parent and r.draft_id=p_draft;
 if expiry is null then raise exception 'parent revision unavailable'; end if;
 end if;
 if expiry<=clock_timestamp() or public.editor_get_full_article_draft(p_draft) is null then raise exception 'original draft expired or unavailable'; end if;
 if not public.article_full_draft_valid(draft.snapshot_id,p_content) then raise exception 'invalid bilingual revision'; end if;
 select * into ctx from public.article_body_request_context where request_id=draft.request_id;
 if ctx.request_id is null then raise exception 'original claim context unavailable'; end if;
 foreach lang in array array['zh','en'] loop
 foreach section in array array['title','what_happened','why_it_matters','what_we_know','what_we_dont_know','timeline','sources','corrections'] loop
 for segment in select value from jsonb_array_elements(p_content->lang->section) loop
 for cid in select jsonb_array_elements_text(segment->'claim_ids') loop
 if not cid::uuid=any(ctx.claim_ids) then raise exception 'claim outside original draft context'; end if;
 end loop; end loop; end loop; end loop;
 insert into public.article_editor_revision_receipts(draft_id,revision_number,parent_revision_id,content_sha256,created_by,reason_code)
 values(p_draft,coalesce(latest_number,0)+1,p_parent,encode(sha256(convert_to(p_content::text,'UTF8')),'hex'),auth.uid(),p_reason_code) returning id into result;
 insert into public.article_editor_revision_content(id,content,expires_at) values(result,p_content,expiry);
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'save_private_editor_revision','article_editor_revision',result,p_reason_code);
 return result;
end $$;



CREATE FUNCTION public.editor_select_daily(p_id uuid, p_story uuid, p_version integer, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare s public.stories%rowtype; old public.daily_editorial_selections%rowtype; today date := (statement_timestamp() at time zone 'UTC')::date;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_story is null or p_version is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid selection'; end if;
  perform pg_advisory_xact_lock(hashtextextended(today::text,76132));
  select * into s from public.stories where id=p_story for update;
  if not found then raise exception 'story unavailable'; end if;
  select * into old from public.daily_editorial_selections where id=p_id;
  if found then
    if old.story_id is distinct from p_story or old.story_version is distinct from p_version or old.actor_id is distinct from auth.uid()
      or old.reason is distinct from trim(p_reason) then raise exception 'selection identity conflict'; end if;
    return false;
  end if;
  if s.version<>p_version then raise exception 'story version conflict'; end if;
  if s.visibility<>'public' or s.public_revision_id is null then raise exception 'public story required'; end if;
  perform public.lock_revision_sources(s.public_revision_id);
  if not public.revision_is_eligible(s.id,s.public_revision_id) then raise exception 'story not eligible'; end if;
  if exists(select 1 from public.daily_editorial_selections d where d.selection_day=today and d.story_id=p_story
    and not exists(select 1 from public.daily_selection_revocations v where v.selection_id=d.id)) then raise exception 'story already selected'; end if;
  if (select count(*) from public.daily_editorial_selections d where d.selection_day=today
    and not exists(select 1 from public.daily_selection_revocations v where v.selection_id=d.id))>=10 then raise exception 'daily selection limit reached'; end if;
  insert into public.daily_editorial_selections(id,selection_day,story_id,story_version,revision_id,actor_id,reason)
    values(p_id,today,p_story,p_version,s.public_revision_id,auth.uid(),trim(p_reason));
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'select_daily','story',p_story,trim(p_reason));
  if not public.revision_is_eligible(s.id,s.public_revision_id) then raise exception 'story permission expired'; end if;
  return true;
end $$;



CREATE FUNCTION public.editor_set_ai_provider(p_provider text, p_enabled boolean, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare was_enabled boolean; change_id uuid;
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null then raise exception 'AI operator access required'; end if;
 if p_provider is null or p_enabled is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'provider and reason required'; end if;
 select enabled into was_enabled from public.ai_provider_catalog where name=p_provider for update;
 if not found then raise exception 'provider unavailable'; end if;
 if was_enabled=p_enabled then return false; end if;
 if p_enabled and not exists(select 1 from public.ai_model_routes where provider=p_provider and enabled)
 then raise exception 'explicit model route required'; end if;
 update public.ai_provider_catalog set enabled=p_enabled where name=p_provider;
 insert into public.ai_provider_config_changes(provider,enabled,actor_id,reason) values(p_provider,p_enabled,auth.uid(),trim(p_reason)) returning id into change_id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),case when p_enabled then 'enable_provider' else 'disable_provider' end,'ai_provider_config_change',change_id,trim(p_reason));
 return true;
end $$;



CREATE FUNCTION public.editor_set_archived(p_story uuid, p_version integer, p_archived boolean, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare s public.stories%rowtype;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_archived is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'archive state and reason required'; end if;
  select * into s from public.stories where id=p_story for update;
  if s.id is null or s.version is distinct from p_version then raise exception 'story version conflict'; end if;
  if s.visibility<>'hidden' then raise exception 'only hidden stories can be archived or restored'; end if;
  if (s.archived_at is not null)=p_archived then raise exception 'archive state unchanged'; end if;
  update public.stories set archived_at=case when p_archived then clock_timestamp() else null end,version=version+1 where id=p_story;
  insert into public.story_archive_events(story_id,archived,actor_id,reason) values(p_story,p_archived,auth.uid(),trim(p_reason));
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),case when p_archived then 'archive' else 'restore_archive' end,'story',p_story,trim(p_reason));
end $$;



CREATE FUNCTION public.editor_set_execution_stop(p_stopped boolean, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare previous boolean;
begin
 if public.editor_can_monitor_ai() is distinct from true or auth.uid() is null or p_stopped is null
  or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'AI operator and reason required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('bounded-ai-single-flight',903514));
 select stopped into previous from public.ai_execution_control where singleton for update;
 if previous is null then raise exception 'execution control unavailable'; end if;
 if previous=p_stopped then return false; end if;
 update public.ai_execution_control set stopped=p_stopped,updated_at=clock_timestamp() where singleton;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),case when p_stopped then 'stop_ai_execution' else 'resume_ai_execution' end,'ai_execution_control',gen_random_uuid(),trim(p_reason));
 return true;
end $$;



CREATE FUNCTION public.editor_set_revision_discovery(p_request uuid, p_story uuid, p_revision uuid, p_version integer, p_category text, p_score uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare prior public.revision_discovery%rowtype; actual integer;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_request is null or p_story is null or p_revision is null or p_version is null or p_category is null
    or p_category not in ('robotics','bci','energy','chips-ai','space','biotech')
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid discovery metadata'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,1031));
  select version into actual from public.stories where id=p_story for update;
  if actual is null then raise exception 'story unavailable'; end if;
  select * into prior from public.revision_discovery where request_id=p_request;
  if found then
    if prior.revision_id is distinct from p_revision or prior.category is distinct from p_category or prior.score_id is distinct from p_score
      or prior.actor_id is distinct from auth.uid() or prior.reason is distinct from trim(p_reason) or prior.story_version is distinct from p_version
      or not exists(select 1 from public.story_revisions where id=p_revision and story_id=p_story)
      then raise exception 'discovery request identity conflict'; end if;
    return false;
  end if;
  if actual<>p_version or p_revision is distinct from (select id from public.story_revisions where story_id=p_story order by revision_number desc limit 1)
    then raise exception 'story version conflict'; end if;
  if exists(select 1 from public.editorial_reviews where revision_id=p_revision) then raise exception 'reviewed revision is immutable'; end if;
  if p_score is not null and not exists(select 1 from public.story_scores where id=p_score and story_id=p_story and revision_id=p_revision and assessment_id is not null)
    then raise exception 'score does not belong to revision'; end if;
  insert into public.revision_discovery(revision_id,request_id,story_version,category,score_id,actor_id,reason)
    values(p_revision,p_request,p_version,p_category,p_score,auth.uid(),trim(p_reason));
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'set_revision_discovery','story_revision',p_revision,trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editor_split_draft_story(p_id uuid, p_source uuid, p_version integer, p_slug text, p_articles uuid[], p_reason text) RETURNS TABLE(target_story_id uuid, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare s public.stories%rowtype; prior public.story_split_events%rowtype; ids uuid[]; old_ids uuid[];
  target uuid; total integer; matched integer; rev_number integer;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_id is null or p_source is null or p_version is null or p_version<1 or p_slug is null or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
    or length(p_slug)>120 or p_articles is null or cardinality(p_articles) not between 1 and 100
    or (select count(distinct id) from unnest(p_articles) id)<>cardinality(p_articles)
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid story split'; end if;
  select array_agg(id order by id) into ids from unnest(p_articles) id;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,76128));
  select * into s from public.stories where id=p_source for update;
  if not found then raise exception 'story unavailable'; end if;
  select * into prior from public.story_split_events where id=p_id;
  if found then
    select array_agg(article_id order by article_id) into old_ids from public.story_split_articles where event_id=p_id;
    if prior.source_story_id is distinct from p_source or prior.source_version is distinct from p_version or prior.target_slug is distinct from p_slug
      or prior.actor_id is distinct from auth.uid() or prior.reason is distinct from trim(p_reason) or old_ids is distinct from ids
      then raise exception 'story split identity conflict'; end if;
    perform src.id from public.sources src where src.id in(select a.source_id from public.articles a where a.id=any(ids)) order by src.id for update;
    if exists(select 1 from unnest(ids) id where not public.candidate_title_allowed(id)) then raise exception 'article permission unavailable'; end if;
    return query select prior.target_story_id,false;
    return;
  end if;
  if s.version<>p_version then raise exception 'story version conflict'; end if;
  if s.visibility<>'hidden' or s.public_revision_id is not null or exists(select 1 from public.publication_events where story_id=p_source)
    then raise exception 'only never-published hidden stories can be split'; end if;
  perform id from public.sources where id in(select source_id from public.articles where id=any(ids)) order by id for update;
  if exists(select 1 from unnest(ids) id where not public.candidate_title_allowed(id)) then raise exception 'article permission unavailable'; end if;
  perform article_id from public.story_articles where story_id=p_source order by article_id for update;
  select count(*),count(*) filter(where article_id=any(ids)) into total,matched from public.story_articles where story_id=p_source;
  if matched<>cardinality(ids) or total<=matched then raise exception 'split requires selected and remaining story articles'; end if;
  if exists(select 1 from public.story_articles sa where sa.story_id=p_source and sa.syndicated_from_article_id is not null
    and ((sa.article_id=any(ids)) is distinct from (sa.syndicated_from_article_id=any(ids)))) then raise exception 'syndication crosses split boundary'; end if;
  if exists(select 1 from public.ai_processing_jobs j where j.story_id=p_source and j.article_id=any(ids))
    then raise exception 'story article has dependent AI job'; end if;
  -- Unlinking would purge a multi-fact summary and its editorial decisions.
  -- Require an explicit future workflow rather than silently deleting them.
  if exists(select 1 from public.story_summary_proposals p join public.story_summary_requests r on r.request_id=p.request_id
    join public.ai_request_preparation_inputs i on i.request_id=r.request_id
    where r.story_id=p_source and i.article_id=any(ids)) then raise exception 'story article has dependent summary'; end if;
  select coalesce(max(revision_number),0) into rev_number from public.story_revisions where story_id=p_source;
  insert into public.stories(slug) values(p_slug) returning id into target;
  insert into public.story_split_events(id,source_story_id,target_story_id,source_version,source_revision_number,target_slug,actor_id,reason)
    values(p_id,p_source,target,p_version,rev_number,p_slug,auth.uid(),trim(p_reason));
  insert into public.story_split_articles(event_id,article_id,reporting_role,independence,syndicated_from_article_id)
    select p_id,article_id,reporting_role,independence,syndicated_from_article_id from public.story_articles where story_id=p_source and article_id=any(ids);
  -- Relationship role and independence require fresh editorial assessment in
  -- the new event; the pre-split values remain in the audit record.
  insert into public.story_articles(story_id,article_id,reporting_role,independence,syndicated_from_article_id)
    select target,article_id,'unknown','unknown',syndicated_from_article_id from public.story_articles where story_id=p_source and article_id=any(ids);
  delete from public.story_articles where story_id=p_source and article_id=any(ids);
  update public.stories set version=version+1,workflow_status='developing' where id=p_source;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'split_draft_story','story',p_source,trim(p_reason));
  if exists(select 1 from unnest(ids) id where not public.candidate_title_allowed(id)) then raise exception 'article permission expired'; end if;
  return query select target,true;
end $_$;



CREATE FUNCTION public.editor_stop_ai_budget(p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare stopped boolean; incident uuid;
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI budget operator access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'stop reason required'; end if;
  select c.stopped into stopped from public.ai_budget_control c where singleton for update;
  if not found then raise exception 'budget control unavailable'; end if;
  if stopped then return false; end if;
  incident := public.ai_raise_budget_halt(null,'other');
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'stop','ai_budget_incident',incident,trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editor_story_history(p_story uuid) RETURNS TABLE(kind text, event_id bigint, action text, resource_type text, resource_id uuid, actor_id uuid, reason text, public_notice text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare available boolean;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  select not exists(select 1 from public.story_revisions r where r.story_id=p_story and not public.editor_revision_sources_available(r.id)) into available;
  return query select h.kind,h.event_id,h.action,h.resource_type,h.resource_id,h.actor_id,
    case when available then h.reason else null end,case when available then h.public_notice else null end,h.created_at
    from public.editor_story_history_before_source_gate(p_story) h;
end $$;



CREATE FUNCTION public.editor_story_history_before_source_gate(p_story uuid) RETURNS TABLE(kind text, event_id bigint, action text, resource_type text, resource_id uuid, actor_id uuid, reason text, public_notice text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  return query
    select h.kind,h.event_id,h.action,h.resource_type,h.resource_id,h.actor_id,h.reason,h.public_notice,h.created_at from (
      select 'audit'::text kind,a.id event_id,a.action,a.resource_type,a.resource_id,a.actor_id,a.reason,null::text public_notice,a.created_at
      from public.audit_logs a where (a.resource_type='story' and a.resource_id=p_story)
        or (a.resource_type='story_revision' and a.resource_id in(select r.id from public.story_revisions r where r.story_id=p_story))
        or (a.resource_type='claim' and a.resource_id in(select c.id from public.claims c join public.story_revisions r on r.id=c.revision_id where r.story_id=p_story))
      union all
      select 'publication',e.id,e.action,'story',e.story_id,e.actor_id,e.reason,e.public_notice,e.created_at
      from public.publication_events e where e.story_id=p_story
    ) h order by h.created_at desc,h.kind,h.event_id desc limit 100;
end $$;



CREATE FUNCTION public.editor_story_sources_available(p_story uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(select 1 from public.stories where id=p_story)
    and not exists(select 1 from public.story_revisions r where r.story_id=p_story and not public.editor_revision_sources_available(r.id))
$$;



CREATE FUNCTION public.editor_update_bilingual(p_batch uuid, p_version integer, p_kind text, p_zh text, p_en text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.bilingual_rollout_enabled() then raise exception 'bilingual rollout is disabled'; end if;
  perform public.lock_editorial_channel_rollout();
  if not public.bilingual_channel_publication_ready(p_batch) then raise exception 'reviewed primary editorial channel required'; end if;
  perform public.publish_bilingual_update_internal(p_batch,p_version,p_kind,p_zh,p_en,p_reason);
end $$;



CREATE FUNCTION public.editor_verified_fact_retention_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sweep timestamptz; quarantined boolean; overdue bigint;
begin
  if not public.editor_can_monitor_ai() then raise exception 'AI operator access required'; end if;
  select last_sweep_at,restore_quarantine into sweep,quarantined from public.ai_verified_fact_retention_control where singleton;
  select count(*) into overdue from public.ai_verified_facts where expires_at<=statement_timestamp();
  return jsonb_build_object('last_sweep_at',sweep,'quarantined',quarantined,'overdue',overdue,
    'ready',coalesce(not quarantined and sweep<=statement_timestamp() and sweep>statement_timestamp()-interval '5 minutes' and overdue=0,false));
end $$;



CREATE FUNCTION public.editor_verify_translation_claim(p_claim uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare rec record;
begin
  if current_setting('transaction_isolation')<>'read committed' or not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_claim is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid verification'; end if;
  select i.*,t.story_id,prep.processor,prep.processing_region into rec from public.translation_claim_imports m
    join public.translation_revision_imports i on i.target_revision_id=m.target_revision_id
    join public.translation_requests req on req.request_id=i.request_id join public.translation_task_intents t on t.id=req.intent_id
    join public.ai_request_preparations prep on prep.request_id=req.request_id where m.target_claim_id=p_claim;
  if rec.request_id is null then raise exception 'translated claim unavailable'; end if;
  perform public.ai_lock_translation_scope(rec.source_revision_id,rec.processor,rec.processing_region,array['process','store','editor_display']);
  if not public.translation_request_accessible(rec.request_id) or not public.editor_revision_sources_available(rec.target_revision_id)
    or rec.target_revision_id is distinct from (select id from public.story_revisions where story_id=rec.story_id order by revision_number desc limit 1)
    or exists(select 1 from public.editorial_reviews where revision_id=rec.target_revision_id)
    then raise exception 'translation verification unavailable'; end if;
  update public.claims set status='verified' where id=p_claim and revision_id=rec.target_revision_id and status='unverified';
  if not found then raise exception 'translated claim is not unverified'; end if;
  update public.claim_evidence set verified_by=auth.uid(),verified_at=clock_timestamp() where claim_id=p_claim and relation='supports';
  if not found then raise exception 'supporting evidence unavailable'; end if;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'verify_translated_claim','claim',p_claim,trim(p_reason));
end $$;



CREATE FUNCTION public.editor_withdraw_ai_bound(p_bound uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare inserted uuid;
begin
  if not public.editor_can_review_ai_billing() then raise exception 'AI billing reviewer access required'; end if;
  if p_bound is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'withdrawal reason required'; end if;
  insert into public.ai_billing_bound_withdrawals(bound_id,reason) values(p_bound,trim(p_reason)) on conflict do nothing returning bound_id into inserted;
  if inserted is null then return false; end if;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'withdraw_bound','ai_billing_bound',p_bound,trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editor_withdraw_ai_price(p_schedule uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare inserted uuid;
begin
  if not public.editor_can_review_ai_billing() then raise exception 'AI billing reviewer access required'; end if;
  if p_schedule is null or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'withdrawal reason required'; end if;
  insert into public.ai_price_withdrawals(schedule_id,reason) values(p_schedule,trim(p_reason)) on conflict do nothing returning schedule_id into inserted;
  if inserted is null then return false; end if;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'withdraw_price','ai_price_schedule',p_schedule,trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editor_withdraw_monthly_cny_fx(p_month date, p_expected_version integer, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare r public.ai_monthly_cny_fx_reviews%rowtype; v integer; inserted integer;
begin
  if session_user<>'authenticator' or public.editor_can_review_ai_billing() is distinct from true then
    raise exception 'authenticated billing reviewer required';
  end if;
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  if p_month is null or p_month<>date_trunc('month',clock_timestamp() at time zone 'UTC')::date
    or p_expected_version is null or p_expected_version<0
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid monthly FX withdrawal'; end if;
  perform 1 from public.ai_monthly_cny_budgets where month_start=p_month for update;
  if not found then raise exception 'monthly budget unavailable'; end if;
  select * into r from public.ai_monthly_cny_fx_reviews where month_start=p_month order by version desc limit 1;
  v:=coalesce(r.version,0);
  if v<>p_expected_version then raise exception 'monthly FX version conflict'; end if;
  if p_month<>date_trunc('month',clock_timestamp() at time zone 'UTC')::date then raise exception 'budget month changed'; end if;
  insert into public.ai_monthly_cny_fx_withdrawals(month_start,version,review_id,reason,withdrawn_by)
    values(p_month,v,r.id,trim(p_reason),auth.uid()) on conflict(month_start,version) do nothing;
  get diagnostics inserted=row_count;
  if inserted=0 then return false; end if;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
    values(auth.uid(),'withdraw_monthly_cny_fx','ai_monthly_cny_fx_review',coalesce(r.id,gen_random_uuid()),
      'Month '||p_month::text||', FX version '||v::text||': '||trim(p_reason));
  return true;
end $$;



CREATE FUNCTION public.editorial_channel_rollout_enabled() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce((select enabled from public.editorial_channel_rollout_settings where singleton),true)
$$;



CREATE FUNCTION public.enqueue_hot_event_publication() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if tg_table_name='manual_publication_events' then
  if new.action='retract' then
   update public.hot_events set status='hidden',updated_at=now() where id=(select hot_event_id from public.manual_articles where id=new.article_id);
   insert into public.hot_event_jobs(job_type,manual_article_id)
    select 'match_manual',a.id from public.manual_articles a where a.hot_event_id=(select hot_event_id from public.manual_articles where id=new.article_id)
     and a.id<>new.article_id and a.status='published' limit 1 on conflict do nothing;
   insert into public.hot_event_jobs(job_type,story_id)
    select 'match_story',s.id from public.stories s where s.hot_event_id=(select hot_event_id from public.manual_articles where id=new.article_id)
     and s.visibility='public' limit 1 on conflict do nothing;
  end if;
  insert into public.hot_event_jobs(job_type,manual_article_id) values('match_manual',new.article_id) on conflict do nothing;
 else
  if new.action in ('retract','hide') then
   update public.hot_events set status='hidden',updated_at=now() where id=(select hot_event_id from public.stories where id=new.story_id);
   insert into public.hot_event_jobs(job_type,manual_article_id)
    select 'match_manual',a.id from public.manual_articles a where a.hot_event_id=(select hot_event_id from public.stories where id=new.story_id)
     and a.status='published' limit 1 on conflict do nothing;
   insert into public.hot_event_jobs(job_type,story_id)
    select 'match_story',s.id from public.stories s where s.hot_event_id=(select hot_event_id from public.stories where id=new.story_id)
     and s.id<>new.story_id and s.visibility='public' limit 1 on conflict do nothing;
  end if;
  insert into public.hot_event_jobs(job_type,story_id) values('match_story',new.story_id) on conflict do nothing;
 end if;
 return new;
end $$;



CREATE FUNCTION public.enqueue_hot_event_score_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if new.total/10-new.dislikes/10-new.shit/3 is not distinct from old.total/10-old.dislikes/10-old.shit/3 then return new; end if;
 if new.content_type='manual' then
  insert into public.hot_event_jobs(job_type,manual_article_id) select 'match_manual',id from public.manual_articles where slug=new.slug and status='published' on conflict do nothing;
 else
  insert into public.hot_event_jobs(job_type,story_id) select 'match_story',id from public.stories where slug=new.slug and visibility='public' on conflict do nothing;
 end if;
 return new;
end $$;



