$$;



CREATE FUNCTION public.get_homepage_picks(p_locale text, p_bilingual boolean) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone, content_type text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select a.slug,a.title,a.summary,a.category,a.score,a.published_at,a.content_type from public.get_homepage_section('picks',p_locale,p_bilingual) a
$$;



CREATE FUNCTION public.get_homepage_picks_recent(p_locale text, p_bilingual boolean) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone, content_type text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select a.slug,a.title,a.summary,a.category,a.score,a.published_at,a.content_type from public.get_homepage_section('picks_recent',p_locale,p_bilingual) a
$$;



CREATE FUNCTION public.get_homepage_section(p_section text, p_locale text, p_bilingual boolean) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone, content_type text, views bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare current_bucket bigint; saved_bucket bigint; chosen jsonb;
begin
 if p_section is null or p_section not in ('headline','picks','picks_recent','trending') or p_locale is null or p_locale not in ('zh','en') or p_bilingual is null then raise exception 'invalid homepage section'; end if;
 current_bucket:=floor(extract(epoch from statement_timestamp())/case when p_section='trending' then 7200 else 1800 end)::bigint;
 if p_section<>'trending' then
  perform pg_advisory_xact_lock(hashtextextended('homepage:featured:'||p_bilingual::text,0));
  if (select count(*) from public.homepage_section_snapshots s where s.section in ('headline','picks','picks_recent') and s.bilingual=p_bilingual and s.bucket=current_bucket)<>3
   or exists (
    select 1 from public.homepage_section_snapshots s
    cross join lateral jsonb_array_elements(s.items) x(item)
    left join public.homepage_public_articles('en',p_bilingual) a on a.slug=x.item->>'slug' and a.content_type=x.item->>'type'
    left join public.homepage_article_controls c on c.slug=a.slug and c.content_type=a.content_type
    where s.section in ('headline','picks','picks_recent') and s.bilingual=p_bilingual
     and (a.slug is null or c.mode='exclude' or not public.homepage_pick_is_today(a.published_at,statement_timestamp()))
   ) then
   insert into public.homepage_section_snapshots(section,bilingual,bucket,items)
   select s.section,p_bilingual,current_bucket,
    coalesce(jsonb_agg(jsonb_build_object('slug',f.slug,'type',f.content_type) order by f.pos) filter(where f.slug is not null),'[]'::jsonb)
   from unnest(array['headline','picks','picks_recent']) s(section)
   left join public.homepage_featured_for_bucket(p_bilingual,current_bucket) f on f.section=s.section
   group by s.section
   on conflict(section,bilingual) do update set bucket=excluded.bucket,items=excluded.items;
  end if;
  select s.items into chosen from public.homepage_section_snapshots s where s.section=p_section and s.bilingual=p_bilingual;
 else
  perform pg_advisory_xact_lock(hashtextextended('homepage:trending:'||p_bilingual::text,0));
  select s.bucket,s.items into saved_bucket,chosen from public.homepage_section_snapshots s where s.section='trending' and s.bilingual=p_bilingual;
  if saved_bucket is distinct from current_bucket then
   select coalesce(jsonb_agg(jsonb_build_object('slug',q.slug,'type',q.content_type,'views',q.views) order by q.pos),'[]'::jsonb) into chosen
   from (select t.*,row_number() over() pos from public.get_homepage_trending('en',p_bilingual) t) q;
   insert into public.homepage_section_snapshots(section,bilingual,bucket,items) values('trending',p_bilingual,current_bucket,chosen)
   on conflict(section,bilingual) do update set bucket=excluded.bucket,items=excluded.items;
  end if;
 end if;
 return query
 select a.slug,a.title,
  case when a.content_type='manual' then public.latest_discovery_excerpt(a.summary,
   case p_locale when 'zh' then mr.zh_document else mr.en_document end,p_locale) else a.summary end,
  a.category,a.score,a.published_at,a.content_type,
  case when p_section='trending' then (x.item->>'views')::bigint else null::bigint end
 from jsonb_array_elements(chosen) with ordinality x(item,pos)
 join public.homepage_public_articles(p_locale,p_bilingual) a on a.slug=x.item->>'slug' and a.content_type=x.item->>'type'
 left join public.homepage_article_controls c on c.slug=a.slug and c.content_type=a.content_type
 left join public.manual_articles ma on a.content_type='manual' and ma.slug=a.slug and ma.status='published'
 left join public.manual_article_revisions mr on mr.id=ma.published_revision_id and mr.article_id=ma.id
 where (p_section='trending' or c.mode is distinct from 'exclude')
  and (p_section='trending' or public.homepage_pick_is_today(a.published_at,statement_timestamp()))
 order by x.pos limit case when p_section='headline' then 1 when p_section='trending' then 6 else 4 end;
end $$;



CREATE FUNCTION public.get_homepage_trending(p_locale text, p_bilingual boolean) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone, content_type text, views bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 with views as (select x.content_type,x.slug,count(*)::bigint n from public.homepage_article_views x where x.view_day >= (statement_timestamp() at time zone 'UTC')::date-6 group by x.content_type,x.slug),
 clicks as (select d.content_type,d.slug,sum(d.clicks)::bigint n from public.article_index_daily d where d.click_day >= (statement_timestamp() at time zone 'UTC')::date-6 group by d.content_type,d.slug)
 select a.*,coalesce(v.n,0) from public.homepage_public_articles(p_locale,p_bilingual) a
 left join views v on v.slug=a.slug and v.content_type=a.content_type left join clicks c on c.slug=a.slug and c.content_type=a.content_type
 where coalesce(v.n,0)+coalesce(c.n,0)>0 order by (coalesce(v.n,0)+coalesce(c.n,0)) desc,a.published_at desc,a.slug limit 6
$$;



CREATE FUNCTION public.get_hot_event_articles(p_event uuid, p_locale text) RETURNS TABLE(slug text, title text, summary text, score integer, published_at timestamp with time zone, content_type text, progress_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select a.slug,case p_locale when 'zh' then r.zh_title else r.en_title end,
  case p_locale when 'zh' then r.zh_summary else r.en_summary end,
  public.index_score('manual',a.slug,e.final_score),first_pub.published_at,'manual'::text,e.created_at
 from public.manual_articles a
 join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
 join lateral (select ev.* from public.manual_publication_events ev where ev.article_id=a.id order by ev.event_order desc limit 1) e on e.revision_id=r.id and e.action in ('publish','update','correction')
 join lateral (select min(ev.created_at) published_at from public.manual_publication_events ev where ev.article_id=a.id and ev.action='publish') first_pub on first_pub.published_at is not null
 where a.hot_event_id=p_event and a.status='published' and p_locale in ('zh','en') and (select enabled from public.manual_public_rollout where singleton)
 union all
 select s.slug,r.title,r.summary,public.index_score('story',s.slug,sc.holy_shit_score),p.published_at,'story'::text,
  coalesce((select max(ev.created_at) from public.publication_events ev where ev.story_id=s.id and ev.action in ('publish','update','correction')),p.published_at)
 from public.stories s
 join public.story_bilingual_batches b on b.id=s.published_bilingual_batch_id and b.story_id=s.id
 join public.story_revisions r on r.id=case p_locale when 'zh' then b.zh_revision_id else b.en_revision_id end
 join lateral (select min(ev.created_at) published_at from public.publication_events ev where ev.story_id=s.id and ev.action='publish') p on p.published_at is not null
 left join public.revision_discovery d on d.revision_id=s.public_revision_id
 left join public.story_scores sc on sc.id=d.score_id and sc.story_id=s.id and sc.revision_id=s.public_revision_id
 where s.hot_event_id=p_event and s.visibility='public' and p_locale in ('zh','en') and public.revision_is_eligible(s.id,s.public_revision_id) and public.bilingual_batch_evidence_gate(b.id)
$$;



CREATE FUNCTION public.get_hot_event_sitemap(p_after text DEFAULT ''::text) RETURNS TABLE(slug text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select h.slug from public.hot_events h where h.status='published' and h.slug>coalesce(p_after,'')
 and exists(select 1 from public.get_hot_event_articles(h.id,'en')) order by h.slug limit 500
$$;



CREATE FUNCTION public.get_public_bilingual_browse(p_locale text, p_query text DEFAULT ''::text, p_category text DEFAULT NULL::text, p_period text DEFAULT 'all'::text, p_sort text DEFAULT 'latest'::text, p_offset integer DEFAULT 0) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if p_locale is null or p_locale not in ('zh','en') or p_query is null or length(p_query)>100
    or p_category is not null and p_category not in ('robotics','bci','energy','chips-ai','space','biotech')
    or p_period is null or p_period not in ('all','day','week','month') or p_sort is null or p_sort not in ('latest','score')
    or p_offset is null or p_offset<0 or p_offset>10000 then raise exception 'invalid browse query'; end if;
  return query select s.slug,r.title,r.summary,d.category,sc.holy_shit_score,p.published_at
    from public.stories s join public.story_bilingual_batches b on b.id=s.published_bilingual_batch_id and b.story_id=s.id
    join public.story_revisions r on r.id=case p_locale when 'zh' then b.zh_revision_id else b.en_revision_id end
    join lateral (select min(e.created_at) published_at from public.publication_events e where e.story_id=s.id and e.action='publish') p on p.published_at is not null
    left join public.revision_discovery d on d.revision_id=s.public_revision_id
    left join public.story_scores sc on sc.id=d.score_id and sc.story_id=s.id and sc.revision_id=s.public_revision_id
    where s.visibility='public' and public.revision_is_eligible(s.id,s.public_revision_id) and public.bilingual_batch_evidence_gate(b.id)
      and (trim(p_query)='' or strpos(lower(r.title),lower(trim(p_query)))>0)
      and (p_category is null or d.category=p_category)
      and (p_period='all' or p.published_at >= statement_timestamp() - case p_period when 'day' then interval '1 day' when 'week' then interval '7 days' else interval '30 days' end)
    order by case when p_sort='score' then sc.holy_shit_score end desc nulls last,p.published_at desc,s.id desc limit 21 offset p_offset;
end $$;



CREATE FUNCTION public.get_public_bilingual_corrections(p_locale text) RETURNS TABLE(slug text, kind text, notice text, published_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select item.slug,item.kind,item.notice,item.published_at from (
    select s.slug,'correction'::text kind,case p_locale when 'zh' then n.zh else n.en end notice,e.created_at published_at,e.id event_id
      from public.stories s join public.publication_events e on e.story_id=s.id and e.action='correction'
      join public.bilingual_publication_notices n on n.event_id=e.id
      where s.visibility='public' and s.published_bilingual_batch_id is not null and public.revision_is_eligible(s.id,s.public_revision_id)
    union all
    select s.slug,'retraction'::text,case p_locale when 'zh' then bn.zh else n.notice end,e.created_at,e.id
      from public.stories s join public.retraction_notices n on n.id=s.public_retraction_id and n.story_id=s.id and n.revision_id=s.public_revision_id
      join public.bilingual_retraction_notices bn on bn.notice_id=n.id join public.retraction_approvals a on a.notice_id=n.id
      join lateral (select id,created_at from public.publication_events where story_id=s.id and action='retract' order by id desc limit 1) e on true
      where s.visibility='retracted' and s.published_bilingual_batch_id is not null
  ) item where p_locale in ('zh','en') order by item.published_at desc,item.event_id desc limit 100
$$;



CREATE FUNCTION public.get_public_bilingual_daily(p_locale text) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone, source_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  select f.slug,r.title,r.summary,f.category,f.score,f.published_at,
    (select count(distinct a.canonical_url)::integer from public.claims c
      join public.claim_evidence e on e.claim_id=c.id and e.relation='supports'
      join public.articles a on a.id=e.article_id join public.story_articles sa on sa.story_id=s.id and sa.article_id=a.id
      join lateral (select * from public.source_policies p where p.source_id=a.source_id order by p.version desc limit 1) p on true
      where c.revision_id=r.id and e.verified_by is not null and e.verified_at is not null and length(trim(e.evidence_reference))>0
        and p.policy_status='approved' and p.display_allowed and p.story_publication_allowed and p.source_display_allowed
        and p.link_display_allowed and p.permitted_region='global' and length(trim(p.attribution_requirements))>0
        and a.canonical_url ~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$' and p.reviewed_by is not null and p.reviewed_at is not null
        and jsonb_typeof(p.policy_evidence)='object' and p.policy_evidence<>'{}'::jsonb
        and (p.permission_expires_at is null or p.permission_expires_at>statement_timestamp()))
  from public.get_public_daily() with ordinality f(slug,title,summary,category,score,published_at,source_count,ordinality)
  join public.stories s on s.slug=f.slug join public.story_bilingual_batches b on b.id=s.published_bilingual_batch_id and b.story_id=s.id
  join public.story_revisions r on r.id=case p_locale when 'zh' then b.zh_revision_id when 'en' then b.en_revision_id end
  where p_locale in ('zh','en') and public.bilingual_batch_evidence_gate(b.id) order by f.ordinality
$_$;



CREATE FUNCTION public.get_public_bilingual_discovery(p_locale text) RETURNS TABLE(slug text, title text, summary text, category text, score integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select f.slug,r.title,r.summary,f.category,f.score from public.get_public_discovery() with ordinality f(slug,title,summary,category,score,ordinality)
  join public.stories s on s.slug=f.slug join public.story_bilingual_batches b on b.id=s.published_bilingual_batch_id and b.story_id=s.id
  join public.story_revisions r on r.id=case p_locale when 'zh' then b.zh_revision_id when 'en' then b.en_revision_id end
  where p_locale in ('zh','en') and public.bilingual_batch_evidence_gate(b.id) order by f.ordinality
$$;



CREATE FUNCTION public.get_public_bilingual_notices(p_slug text, p_locale text) RETURNS TABLE(kind text, notice text, published_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select e.action,case p_locale when 'zh' then n.zh else n.en end,e.created_at
  from public.stories s join public.story_bilingual_batches b on b.story_id=s.id and b.id=s.published_bilingual_batch_id
  join public.publication_events e on e.story_id=s.id and e.action in ('update','correction')
  join public.bilingual_publication_notices n on n.event_id=e.id
  where p_locale in ('zh','en') and s.slug=p_slug and s.visibility='public' and public.bilingual_batch_evidence_gate(b.id)
    and coalesce((select decision='approved' from public.bilingual_editorial_reviews r where r.batch_id=b.id order by r.id desc limit 1),false)
  order by e.id desc limit 100
$$;



CREATE FUNCTION public.get_public_bilingual_ranking(p_locale text) RETURNS TABLE(slug text, title text, score integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select f.slug,r.title,f.score from public.get_public_discovery_ranking() f
  join public.stories s on s.slug=f.slug join public.story_bilingual_batches b on b.id=s.published_bilingual_batch_id and b.story_id=s.id
  join public.story_revisions r on r.id=case p_locale when 'zh' then b.zh_revision_id when 'en' then b.en_revision_id end
  where p_locale in ('zh','en') and public.bilingual_batch_evidence_gate(b.id) order by f.score desc,f.slug
$$;



CREATE FUNCTION public.get_public_bilingual_retraction(p_slug text, p_locale text) RETURNS TABLE(slug text, notice text, retracted_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select s.slug,case p_locale when 'zh' then bn.zh else n.notice end,e.created_at
  from public.stories s join public.retraction_notices n on n.id=s.public_retraction_id and n.story_id=s.id and n.revision_id=s.public_revision_id
  join public.bilingual_retraction_notices bn on bn.notice_id=n.id
  join public.retraction_approvals a on a.notice_id=n.id
  join lateral (select created_at from public.publication_events where story_id=s.id and action='retract' order by id desc limit 1) e on true
  where p_locale in ('zh','en') and s.slug=p_slug and s.visibility='retracted' and s.published_bilingual_batch_id is not null
$$;



CREATE FUNCTION public.get_public_bilingual_story(p_slug text, p_locale text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select public.get_public_bilingual_story_internal(p_slug,p_locale)
$$;



CREATE FUNCTION public.get_public_bilingual_story_internal(p_slug text, p_locale text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  select jsonb_build_object(
    'slug',s.slug,'locale',p_locale,'title',r.title,'summary',r.summary,
    'single_source',exists(
      select 1 from public.claims c join public.claim_evidence_classifications x on x.claim_id=c.id
      where c.revision_id in (b.zh_revision_id,b.en_revision_id)
        and x.category in ('firsthand_statement','official_exclusive','own_test')
        and (select count(distinct a.source_id) from public.claim_evidence e
          join public.articles a on a.id=e.article_id
          join public.story_articles sa on sa.story_id=s.id and sa.article_id=a.id
          join lateral (select * from public.source_policies p where p.source_id=a.source_id order by version desc limit 1) p on true
          where e.claim_id=c.id and e.relation='supports' and e.verified_by is not null and e.verified_at is not null
            and length(trim(e.evidence_reference))>0 and sa.independence='independent' and sa.reporting_role<>'syndicated'
            and sa.syndicated_from_article_id is null and p.policy_status='approved' and p.display_allowed
            and p.story_publication_allowed and p.source_display_allowed and p.link_display_allowed and p.permitted_region='global'
            and length(trim(p.attribution_requirements))>0 and a.canonical_url ~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$'
            and p.reviewed_by is not null and p.reviewed_at is not null and jsonb_typeof(p.policy_evidence)='object'
            and p.policy_evidence<>'{}'::jsonb and (p.permission_expires_at is null or p.permission_expires_at>statement_timestamp()))<2),
    'what_we_dont_know',case when p_locale='zh' then n.zh else n.en end,
    'claims',coalesce((select jsonb_agg(jsonb_build_object('text',c.claim_text,'sources',
      coalesce((select jsonb_agg(distinct jsonb_build_object('name',src.name,'url',a.canonical_url,'attribution',p.attribution_requirements))
        from public.claim_evidence e join public.articles a on a.id=e.article_id
        join public.story_articles sa on sa.story_id=s.id and sa.article_id=a.id
        join public.sources src on src.id=a.source_id
        join lateral (select * from public.source_policies sp where sp.source_id=src.id order by version desc limit 1) p on true
        where e.claim_id=c.id and e.relation='supports' and e.verified_by is not null and e.verified_at is not null
          and length(trim(e.evidence_reference))>0 and p.policy_status='approved' and p.display_allowed
          and p.story_publication_allowed and p.source_display_allowed and p.link_display_allowed and p.permitted_region='global'
          and length(trim(p.attribution_requirements))>0 and a.canonical_url ~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$'
          and p.reviewed_by is not null and p.reviewed_at is not null and jsonb_typeof(p.policy_evidence)='object'
          and p.policy_evidence<>'{}'::jsonb and (p.permission_expires_at is null or p.permission_expires_at>statement_timestamp())), '[]'::jsonb))
      order by c.id) from public.claims c where c.revision_id=r.id),'[]'::jsonb))
  from public.stories s join public.story_bilingual_batches b on b.story_id=s.id and b.id=s.published_bilingual_batch_id
  join public.story_revisions r on r.id=case p_locale when 'zh' then b.zh_revision_id when 'en' then b.en_revision_id end and r.story_id=s.id
  left join public.bilingual_uncertainty_notes n on n.batch_id=b.id
  where p_locale in ('zh','en') and s.slug=p_slug and s.visibility='public' and public.bilingual_batch_evidence_gate(b.id)
    and coalesce((select decision='approved' from public.bilingual_editorial_reviews where batch_id=b.id order by id desc limit 1),false)
$_$;



CREATE FUNCTION public.get_public_browse(p_query text DEFAULT ''::text, p_category text DEFAULT NULL::text, p_period text DEFAULT 'all'::text, p_sort text DEFAULT 'latest'::text, p_offset integer DEFAULT 0) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if p_query is null or length(p_query)>100 or p_category is not null and p_category not in ('robotics','bci','energy','chips-ai','space','biotech')
    or p_period is null or p_period not in ('all','day','week','month') or p_sort is null or p_sort not in ('latest','score')
    or p_offset is null or p_offset<0 or p_offset>10000 then raise exception 'invalid browse query'; end if;
  return query select s.slug,r.title,r.summary,d.category,sc.holy_shit_score,p.published_at
    from public.stories s join public.story_revisions r on r.id=s.public_revision_id and r.story_id=s.id
    join lateral (select min(e.created_at) published_at from public.publication_events e where e.story_id=s.id and e.action='publish') p on p.published_at is not null
    left join public.revision_discovery d on d.revision_id=r.id
    left join public.story_scores sc on sc.id=d.score_id and sc.story_id=s.id and sc.revision_id=r.id
    where s.visibility='public' and public.revision_is_eligible(s.id,r.id)
      and (trim(p_query)='' or strpos(lower(r.title),lower(trim(p_query)))>0)
      and (p_category is null or d.category=p_category)
      and (p_period='all' or p.published_at >= statement_timestamp() - case p_period when 'day' then interval '1 day' when 'week' then interval '7 days' else interval '30 days' end)
    order by case when p_sort='score' then sc.holy_shit_score end desc nulls last,p.published_at desc,s.id desc
    limit 21 offset p_offset;
end $$;



CREATE FUNCTION public.get_public_browse_count(p_locale text, p_bilingual boolean, p_query text, p_channel text, p_period text) RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if p_locale is null or p_locale not in ('zh','en') or p_bilingual is null or p_query is null or length(p_query)>100
 or p_period is null or p_period not in ('all','day','week','month') then raise exception 'invalid browse query'; end if;
 return (with normal as (
  select s.slug,r.title,r.summary,coalesce(case when p_bilingual then public.bilingual_reviewed_primary_channel(b.id) end,d.category) as category,
   public.index_score('story',s.slug,sc.holy_shit_score) as score,p.published_at,'story'::text as kind,array[]::text[] as related
  from public.stories s
  left join public.story_bilingual_batches b on p_bilingual and b.id=s.published_bilingual_batch_id and b.story_id=s.id
  join public.story_revisions r on r.id=case when p_bilingual then case p_locale when 'zh' then b.zh_revision_id else b.en_revision_id end else s.public_revision_id end
  join lateral (select min(ev.created_at) published_at from public.publication_events ev where ev.story_id=s.id and ev.action='publish') p on p.published_at is not null
  left join public.revision_discovery d on d.revision_id=s.public_revision_id
  left join public.story_scores sc on sc.id=d.score_id and sc.story_id=s.id and sc.revision_id=s.public_revision_id
  where s.visibility='public' and public.revision_is_eligible(s.id,s.public_revision_id)
   and (not p_bilingual or b.id is not null and public.bilingual_batch_evidence_gate(b.id))
 ), manual as (
  select a.slug,case p_locale when 'zh' then r.zh_title else r.en_title end as title,case p_locale when 'zh' then r.zh_summary else r.en_summary end as summary,
   r.primary_channel as category,public.index_score('manual',a.slug,e.final_score) as score,first_pub.published_at,'manual'::text as kind,r.related_channels as related
  from public.manual_articles a join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
  join lateral (select ev.* from public.manual_publication_events ev where ev.article_id=a.id order by ev.event_order desc limit 1) e on e.revision_id=r.id and e.action in ('publish','update','correction')
  join lateral (select min(ev.created_at) published_at from public.manual_publication_events ev where ev.article_id=a.id and ev.action='publish') first_pub on first_pub.published_at is not null
  where a.status='published' and (select enabled from public.manual_public_rollout where singleton)
 ), combined as (select * from normal union all select * from manual)
 select count(*) from combined c
 where (trim(p_query)='' or strpos(lower(c.title),lower(trim(p_query)))>0)
  and (p_channel is null or c.category=p_channel or p_channel=any(c.related))
  and (p_period='all' or c.published_at>=statement_timestamp()-case p_period when 'day' then interval '1 day' when 'week' then interval '7 days' else interval '30 days' end));
end $$;



CREATE FUNCTION public.get_public_channel_browse(p_locale text, p_query text DEFAULT ''::text, p_channel text DEFAULT NULL::text, p_period text DEFAULT 'all'::text, p_sort text DEFAULT 'latest'::text, p_offset integer DEFAULT 0) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if p_locale is null or p_locale not in ('zh','en') or p_query is null or length(p_query)>100
    or p_channel is not null and p_channel not in ('ai','robotics','industry','technology','internet','products')
    or p_period is null or p_period not in ('all','day','week','month') or p_sort is null or p_sort not in ('latest','score')
    or p_offset is null or p_offset<0 or p_offset>10000 then raise exception 'invalid channel browse query'; end if;
  return query select s.slug,r.title,r.summary,ch.primary_channel,sc.holy_shit_score,p.published_at
    from public.stories s join public.story_bilingual_batches b on b.id=s.published_bilingual_batch_id and b.story_id=s.id
    join public.story_revisions r on r.id=case p_locale when 'zh' then b.zh_revision_id else b.en_revision_id end
    join lateral (select min(e.created_at) published_at from public.publication_events e where e.story_id=s.id and e.action='publish') p on p.published_at is not null
    cross join lateral (select public.bilingual_reviewed_primary_channel(b.id) primary_channel) ch
    left join public.revision_discovery d on d.revision_id=s.public_revision_id
    left join public.story_scores sc on sc.id=d.score_id and sc.story_id=s.id and sc.revision_id=s.public_revision_id
    where s.visibility='public' and public.revision_is_eligible(s.id,s.public_revision_id) and public.bilingual_batch_evidence_gate(b.id)
      and (trim(p_query)='' or strpos(lower(r.title),lower(trim(p_query)))>0)
      and (p_channel is null or ch.primary_channel=p_channel)
      and (p_period='all' or p.published_at >= statement_timestamp() - case p_period when 'day' then interval '1 day' when 'week' then interval '7 days' else interval '30 days' end)
    order by case when p_sort='score' then sc.holy_shit_score end desc nulls last,p.published_at desc,s.id desc limit 21 offset p_offset;
end $$;



CREATE FUNCTION public.get_public_channel_counts() RETURNS TABLE(channel text, story_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select channel.value,count(s.id) from (values ('ai'),('robotics'),('industry'),('technology'),('internet'),('products')) channel(value)
  left join public.stories s on s.visibility='public' and s.published_bilingual_batch_id is not null
    and public.revision_is_eligible(s.id,s.public_revision_id) and public.bilingual_batch_evidence_gate(s.published_bilingual_batch_id)
    and public.bilingual_reviewed_primary_channel(s.published_bilingual_batch_id)=channel.value
  group by channel.value order by channel.value
$$;



CREATE FUNCTION public.get_public_channel_daily(p_locale text) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone, source_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select f.slug,f.title,f.summary,public.bilingual_reviewed_primary_channel(s.published_bilingual_batch_id),f.score,f.published_at,f.source_count
  from public.get_public_bilingual_daily(p_locale) with ordinality f(slug,title,summary,legacy_category,score,published_at,source_count,ordinality)
  join public.stories s on s.slug=f.slug order by f.ordinality
$$;



CREATE FUNCTION public.get_public_channel_discovery(p_locale text) RETURNS TABLE(slug text, title text, summary text, category text, score integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select f.slug,f.title,f.summary,public.bilingual_reviewed_primary_channel(s.published_bilingual_batch_id),f.score
  from public.get_public_bilingual_discovery(p_locale) with ordinality f(slug,title,summary,legacy_category,score,ordinality)
  join public.stories s on s.slug=f.slug order by f.ordinality
$$;



CREATE FUNCTION public.get_public_corrections() RETURNS TABLE(slug text, kind text, notice text, published_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select item.slug,item.kind,item.notice,item.published_at from (
    select s.slug, 'correction'::text as kind, e.public_notice as notice, e.created_at as published_at, e.id as event_id
      from public.stories s join public.publication_events e on e.story_id=s.id and e.action='correction'
      where s.visibility='public' and public.revision_is_eligible(s.id,s.public_revision_id)
    union all
    select s.slug, 'retraction'::text, n.notice, e.created_at, e.id
      from public.stories s
      join public.retraction_notices n on n.id=s.public_retraction_id and n.story_id=s.id and n.revision_id=s.public_revision_id
      join public.retraction_approvals a on a.notice_id=n.id
      join lateral (select id,created_at from public.publication_events where story_id=s.id and action='retract' order by id desc limit 1) e on true
      where s.visibility='retracted'
  ) item order by item.published_at desc,item.event_id desc limit 100
$$;



CREATE FUNCTION public.get_public_daily() RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone, source_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select s.slug,r.title,r.summary,d.category,sc.holy_shit_score,p.published_at,jsonb_array_length(src.sources)
    from public.daily_editorial_selections e join public.stories s on s.id=e.story_id and s.public_revision_id=e.revision_id
    join public.story_revisions r on r.id=e.revision_id and r.story_id=s.id
    join lateral public.get_public_story(s.slug) src on true
    join lateral (select min(created_at) published_at from public.publication_events where story_id=s.id and action='publish') p on p.published_at is not null
    left join public.revision_discovery d on d.revision_id=r.id
    left join public.story_scores sc on sc.id=d.score_id and sc.story_id=s.id and sc.revision_id=r.id
    where e.selection_day=(statement_timestamp() at time zone 'UTC')::date and s.visibility='public'
      and public.revision_is_eligible(s.id,r.id) and not exists(select 1 from public.daily_selection_revocations v where v.selection_id=e.id)
    order by e.created_at,e.id limit 10
$$;



CREATE FUNCTION public.get_public_discovery() RETURNS TABLE(slug text, title text, summary text, category text, score integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select feed.slug,feed.title,feed.summary,d.category,sc.holy_shit_score
  from public.get_public_stories() feed
  join public.stories s on s.slug=feed.slug
  left join public.revision_discovery d on d.revision_id=s.public_revision_id
  left join public.story_scores sc on sc.id=d.score_id and sc.story_id=s.id and sc.revision_id=s.public_revision_id
  where s.visibility='public' and public.revision_is_eligible(s.id,s.public_revision_id)
  order by (select max(e.id) from public.publication_events e where e.story_id=s.id and e.action='publish') desc nulls last,s.id
$$;



CREATE FUNCTION public.get_public_discovery_ranking() RETURNS TABLE(slug text, title text, score integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select s.slug,r.title,sc.holy_shit_score from public.stories s
  join public.story_revisions r on r.id=s.public_revision_id and r.story_id=s.id
  join public.revision_discovery d on d.revision_id=r.id
  join public.story_scores sc on sc.id=d.score_id and sc.story_id=s.id and sc.revision_id=r.id
  where s.visibility='public' and sc.holy_shit_score is not null and public.revision_is_eligible(s.id,r.id)
  order by sc.holy_shit_score desc,s.slug limit 5
$$;



CREATE FUNCTION public.get_public_duplicate_target(p_slug text) RETURNS TABLE(target_slug text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select t.slug from public.stories s join public.story_duplicate_links d on d.source_story_id=s.id and d.notice_id=s.public_retraction_id
  join public.retraction_notices n on n.id=d.notice_id and n.story_id=s.id and n.revision_id=s.public_revision_id
  join public.retraction_approvals a on a.notice_id=n.id join public.stories t on t.id=d.target_story_id
  where s.slug=p_slug and s.visibility='retracted' and t.visibility='public' and public.revision_is_eligible(t.id,t.public_revision_id)
    and not exists(select 1 from public.story_duplicate_link_revocations r where r.link_id=d.id)
$$;



CREATE FUNCTION public.get_public_full_article(p_slug text, p_locale text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select jsonb_build_object('revision_id',er.id,'locale',p_locale,'content',ec.content->p_locale,'expires_at',least(ec.expires_at,g.expires_at))
 from public.stories s join public.article_full_publications pub on pub.batch_id=s.published_bilingual_batch_id
 join public.article_editor_revision_receipts er on er.id=pub.revision_id join public.article_editor_revision_content ec on ec.id=er.id
 join public.article_editor_revision_reviews review on review.id=pub.review_id
 join public.article_full_public_grants g on g.id=pub.public_grant_id
 where p_locale in ('zh','en') and s.slug=p_slug and s.visibility='public' and s.archived_at is null
 and public.bilingual_rollout_enabled() and public.bilingual_channel_publication_ready(pub.batch_id)
 and public.get_public_bilingual_story(p_slug,p_locale) is not null
 and public.article_revision_batch_matches(er.id,pub.batch_id) and public.article_full_public_grant_live(g.id)
 and review.decision='approved' and review.content_sha256=er.content_sha256
 and not exists(select 1 from public.article_editor_revision_reviews newer where newer.revision_id=er.id and newer.id>review.id)
$$;



CREATE FUNCTION public.get_public_hot_event_for_article(p_locale text, p_type text, p_slug text) RETURNS TABLE(slug text, title text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select h.slug,case p_locale when 'zh' then h.zh_title else h.en_title end
 from public.hot_events h
 where h.status='published' and p_locale in ('zh','en') and p_type in ('story','manual')
  and exists(select 1 from public.get_hot_event_articles(h.id,p_locale) a where a.content_type=p_type and a.slug=p_slug)
 limit 1
$$;



CREATE FUNCTION public.get_public_hot_events(p_locale text, p_slug text DEFAULT NULL::text, p_recent boolean DEFAULT false, p_offset integer DEFAULT 0) RETURNS TABLE(slug text, title text, summary text, article_count bigint, max_index integer, last_progress_at timestamp with time zone, articles jsonb, age_hours integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select h.slug,case p_locale when 'zh' then h.zh_title else h.en_title end,
  case p_locale when 'zh' then h.zh_summary else h.en_summary end,
  count(a.slug),max(a.score),h.last_progress_at,
  jsonb_agg(jsonb_build_object('slug',a.slug,'title',a.title,'summary',a.summary,'score',a.score,'published_at',a.published_at,'content_type',a.content_type,'progress_at',a.progress_at) order by a.published_at desc),
  greatest(0,floor(extract(epoch from (statement_timestamp()-h.last_progress_at))/3600)::integer)
 from public.hot_events h
 cross join lateral public.get_hot_event_articles(h.id,p_locale) a
 where h.status='published' and p_locale in ('zh','en') and (p_slug is null or h.slug=p_slug)
  and (not p_recent or h.last_progress_at>=statement_timestamp()-interval '72 hours')
 group by h.id order by h.last_progress_at desc,h.id
 limit case when p_recent then 2 when p_slug is not null then 1 else 51 end
 offset case when p_slug is null and not p_recent then greatest(0,coalesce(p_offset,0)) else 0 end
$$;



CREATE FUNCTION public.get_public_latest_discoveries(p_locale text, p_bilingual boolean, p_sort text) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone, content_type text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 with picked as materialized (
  select q.* from (
   select a.slug,a.title,a.summary,a.category,a.score,a.published_at,a.content_type,a.ord position
   from public.get_public_unified_browse(p_locale,p_bilingual,'',null,'day',p_sort,0)
    with ordinality a(slug,title,summary,category,score,published_at,content_type,ord)
   union all
   select b.slug,b.title,b.summary,b.category,b.score,b.published_at,b.content_type,b.ord+21 position
   from public.get_public_unified_browse(p_locale,p_bilingual,'',null,'day',p_sort,21)
    with ordinality b(slug,title,summary,category,score,published_at,content_type,ord)
  ) q order by q.position limit 24
 )
 select q.slug,q.title,
  case when q.content_type='manual' then public.latest_discovery_excerpt(q.summary,
   case p_locale when 'zh' then r.zh_document else r.en_document end,p_locale)
   else q.summary end,
  q.category,q.score,q.published_at,q.content_type
 from picked q
 left join public.manual_articles a on q.content_type='manual' and a.slug=q.slug and a.status='published'
 left join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
 order by q.position
$$;



CREATE FUNCTION public.get_public_manual_article(p_slug text, p_locale text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select base.doc
   || case when ap.draft_id is not null then jsonb_build_object('origin','ai_reviewed','seo',case p_locale when 'zh' then ap.zh_seo else ap.en_seo end) else jsonb_build_object('origin','manual') end
   || jsonb_build_object('score',public.index_score('manual',a.slug,(base.doc->>'score')::integer))
   || jsonb_build_object('topics',coalesce((select jsonb_agg(t.topic order by t.topic) from public.manual_revision_topics t where t.revision_id=a.published_revision_id and t.channel=base.doc->>'channel'),'[]'::jsonb))
 from (select public.get_public_manual_article_base(p_slug,p_locale) doc) base
 left join public.manual_articles a on a.slug=p_slug
 left join public.ai_article_publications ap on ap.article_id=a.id
 where base.doc is not null
$$;



CREATE FUNCTION public.get_public_manual_article_base(p_slug text, p_locale text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select jsonb_build_object('slug',a.slug,'locale',p_locale,'title',case p_locale when 'zh' then r.zh_title else r.en_title end,
 'summary',case p_locale when 'zh' then r.zh_summary else r.en_summary end,'document',case p_locale when 'zh' then r.zh_document else r.en_document end,
 'channel',r.primary_channel,'related_channels',r.related_channels,'tags',r.tags,'sources',r.source_links,'score',e.final_score,'published_at',e.created_at)
 from public.manual_articles a join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
 join lateral (select * from public.manual_publication_events ev where ev.article_id=a.id order by ev.event_order desc limit 1) e on e.revision_id=r.id and e.action in ('publish','update','correction')
 where p_locale in ('zh','en') and a.slug=p_slug and a.status='published' and (select enabled from public.manual_public_rollout where singleton)
$$;



CREATE FUNCTION public.get_public_manual_feed(p_locale text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select coalesce(jsonb_agg(jsonb_build_object('slug',a.slug,'title',case p_locale when 'zh' then r.zh_title else r.en_title end,'summary',case p_locale when 'zh' then r.zh_summary else r.en_summary end,'category',r.primary_channel,'score',e.final_score,'published_at',e.created_at) order by e.event_order desc),'[]'::jsonb)
 from public.manual_articles a join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
 join lateral (select * from public.manual_publication_events ev where ev.article_id=a.id order by ev.event_order desc limit 1) e on e.revision_id=r.id and e.action in ('publish','update','correction')
 where p_locale in ('zh','en') and a.status='published' and (select enabled from public.manual_public_rollout where singleton)
$$;



CREATE FUNCTION public.get_public_manual_media(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
 select jsonb_build_object('path',m.object_path,'mime',m.mime_type,'bytes',m.byte_size) from public.manual_media_assets m
 where m.id=p_id and (select enabled from public.manual_public_rollout where singleton) and exists(
  select 1 from public.manual_articles a join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
  where a.status='published' and a.owner_id=m.owner_id and
  (jsonb_path_exists(r.zh_document,'$.** ? (@.attrs.src == $src)',jsonb_build_object('src','/api/manual-media/'||m.id::text))
   or jsonb_path_exists(r.en_document,'$.** ? (@.attrs.src == $src)',jsonb_build_object('src','/api/manual-media/'||m.id::text)))
 )
$_$;



CREATE FUNCTION public.get_public_manual_topic_browse(p_locale text, p_channel text, p_topic text, p_offset integer) RETURNS TABLE(slug text, title text, summary text, score integer, published_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if p_locale is null or p_locale not in ('zh','en') or p_offset is null or p_offset<0 or p_offset>10000
 or not exists(select 1 from public.manual_editor_topics t where t.channel=p_channel and t.topic=p_topic) then raise exception 'invalid topic query'; end if;
 return query select a.slug,case p_locale when 'zh' then r.zh_title else r.en_title end,case p_locale when 'zh' then r.zh_summary else r.en_summary end,public.index_score('manual',a.slug,e.final_score),first_pub.published_at
 from public.manual_articles a join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
 join public.manual_revision_topics t on t.revision_id=r.id and t.channel=p_channel and t.topic=p_topic
 join lateral (select ev.* from public.manual_publication_events ev where ev.article_id=a.id order by ev.event_order desc limit 1) e on e.revision_id=r.id and e.action in ('publish','update','correction')
 join lateral (select min(ev.created_at) published_at from public.manual_publication_events ev where ev.article_id=a.id and ev.action='publish') first_pub on first_pub.published_at is not null
 where a.status='published' and (select enabled from public.manual_public_rollout where singleton)
 order by first_pub.published_at desc,a.slug limit 21 offset p_offset;
end $$;



CREATE FUNCTION public.get_public_retraction(p_slug text) RETURNS TABLE(slug text, notice text, retracted_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select s.slug, n.notice, e.created_at from public.stories s
  join public.retraction_notices n on n.id = s.public_retraction_id and n.story_id = s.id and n.revision_id = s.public_revision_id
  join public.retraction_approvals a on a.notice_id = n.id
  join lateral (select created_at from public.publication_events where story_id = s.id and action = 'retract' order by id desc limit 1) e on true
  where s.slug = p_slug and s.visibility = 'retracted'
$$;



CREATE FUNCTION public.get_public_sitemap(p_after text, p_limit integer) RETURNS TABLE(slug text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
begin
  if p_limit is null or p_limit not between 1 and 500 or (p_after is not null and
    (length(p_after)>200 or p_after !~ '^[a-z0-9]+(-[a-z0-9]+)*$')) then raise exception 'invalid sitemap cursor'; end if;
  return query select s.slug from public.stories s
    join public.story_revisions r on r.id=s.public_revision_id and r.story_id=s.id
    where s.visibility='public' and length(s.slug) between 1 and 200 and s.slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
      and (p_after is null or s.slug collate "C">p_after collate "C") and public.revision_is_eligible(s.id,r.id)
    order by s.slug collate "C" limit p_limit;
end $_$;



CREATE FUNCTION public.get_public_stories() RETURNS TABLE(slug text, title text, summary text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select s.slug, r.title, r.summary from public.stories s
  join public.story_revisions r on r.id = s.public_revision_id and r.story_id = s.id
  join lateral (select max(e.id) as latest_event from public.publication_events e where e.story_id = s.id and e.action = 'publish') p on true
  where s.visibility = 'public' and public.revision_is_eligible(s.id, r.id)
  order by p.latest_event desc nulls last, s.id limit 50
$$;



CREATE FUNCTION public.get_public_story(p_slug text) RETURNS TABLE(slug text, title text, summary text, sources jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  select s.slug, r.title, r.summary, (
    select coalesce(jsonb_agg(distinct jsonb_build_object('name', src.name, 'url', a.canonical_url, 'attribution', p.attribution_requirements)), '[]'::jsonb)
    from public.claims c join public.claim_evidence e on e.claim_id = c.id and e.relation = 'supports'
    join public.articles a on a.id = e.article_id
    join public.story_articles sa on sa.story_id = s.id and sa.article_id = a.id
    join public.sources src on src.id = a.source_id
    join lateral (select * from public.source_policies sp where sp.source_id = src.id order by version desc limit 1) p on true
    where c.revision_id = r.id and e.verified_by is not null and e.verified_at is not null and length(trim(e.evidence_reference)) > 0
      and p.policy_status = 'approved' and p.display_allowed and p.story_publication_allowed
      and p.source_display_allowed and p.link_display_allowed and p.permitted_region = 'global'
      and length(trim(p.attribution_requirements)) > 0 and p.policy_evidence <> '{}'::jsonb
      and p.reviewed_by is not null and p.reviewed_at is not null
      and (p.permission_expires_at is null or p.permission_expires_at > now())
      and a.canonical_url ~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$'
  ) from public.stories s join public.story_revisions r on r.id = s.public_revision_id and r.story_id = s.id
  where s.slug = p_slug and s.visibility = 'public' and public.revision_is_eligible(s.id, r.id)
$_$;



CREATE FUNCTION public.get_public_story_page(p_slug text) RETURNS TABLE(slug text, title text, summary text, sources jsonb, updates jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select s.slug, s.title, s.summary, s.sources,
    coalesce((select jsonb_agg(jsonb_build_object('kind', u.kind, 'notice', u.notice, 'published_at', u.published_at) order by u.published_at desc)
      from public.get_public_story_updates(p_slug) u), '[]'::jsonb)
  from public.get_public_story(p_slug) s
$$;



CREATE FUNCTION public.get_public_story_updates(p_slug text) RETURNS TABLE(kind text, notice text, published_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select e.action, e.public_notice, e.created_at from public.stories s
  join public.publication_events e on e.story_id = s.id and e.action in ('update', 'correction')
  where s.slug = p_slug and s.visibility = 'public' and public.revision_is_eligible(s.id, s.public_revision_id)
  order by e.id desc
$$;



CREATE FUNCTION public.get_public_topic_count(p_locale text, p_channel text, p_topic text) RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if p_locale is null or p_locale not in ('zh','en') or not exists(select 1 from public.manual_editor_topics t where t.channel=p_channel and t.topic=p_topic)
 then raise exception 'invalid topic query'; end if;
 return (select count(*)
 from public.manual_articles a join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
 join public.manual_revision_topics t on t.revision_id=r.id and t.channel=p_channel and t.topic=p_topic
 join lateral (select ev.* from public.manual_publication_events ev where ev.article_id=a.id order by ev.event_order desc limit 1) e on e.revision_id=r.id and e.action in ('publish','update','correction')
 where a.status='published' and (select enabled from public.manual_public_rollout where singleton)
 and exists(select 1 from public.manual_publication_events ev where ev.article_id=a.id and ev.action='publish'));
end $$;



CREATE FUNCTION public.get_public_unified_browse(p_locale text, p_bilingual boolean, p_query text, p_channel text, p_period text, p_sort text, p_offset integer) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone, content_type text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if p_locale not in ('zh','en') or p_locale is null or p_bilingual is null or p_query is null or length(p_query)>100
  or p_period is null or p_period not in ('all','day','week','month') or p_sort is null or p_sort not in ('latest','score')
  or p_offset is null or p_offset<0 or p_offset>10000 then raise exception 'invalid browse query'; end if;
 return query with normal as (
  select s.slug,r.title,r.summary,coalesce(case when p_bilingual then public.bilingual_reviewed_primary_channel(b.id) end,d.category) as category,
   public.index_score('story',s.slug,sc.holy_shit_score) as score,p.published_at,'story'::text as kind,array[]::text[] as related
  from public.stories s
  left join public.story_bilingual_batches b on p_bilingual and b.id=s.published_bilingual_batch_id and b.story_id=s.id
  join public.story_revisions r on r.id=case when p_bilingual then case p_locale when 'zh' then b.zh_revision_id else b.en_revision_id end else s.public_revision_id end
  join lateral (select min(ev.created_at) published_at from public.publication_events ev where ev.story_id=s.id and ev.action='publish') p on p.published_at is not null
  left join public.revision_discovery d on d.revision_id=s.public_revision_id
  left join public.story_scores sc on sc.id=d.score_id and sc.story_id=s.id and sc.revision_id=s.public_revision_id
  where s.visibility='public' and public.revision_is_eligible(s.id,s.public_revision_id)
   and (not p_bilingual or b.id is not null and public.bilingual_batch_evidence_gate(b.id))
 ), manual as (
  select a.slug,case p_locale when 'zh' then r.zh_title else r.en_title end as title,case p_locale when 'zh' then r.zh_summary else r.en_summary end as summary,
   r.primary_channel as category,public.index_score('manual',a.slug,e.final_score) as score,first_pub.published_at,'manual'::text as kind,r.related_channels as related
  from public.manual_articles a join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
  join lateral (select ev.* from public.manual_publication_events ev where ev.article_id=a.id order by ev.event_order desc limit 1) e on e.revision_id=r.id and e.action in ('publish','update','correction')
  join lateral (select min(ev.created_at) published_at from public.manual_publication_events ev where ev.article_id=a.id and ev.action='publish') first_pub on first_pub.published_at is not null
  where a.status='published' and (select enabled from public.manual_public_rollout where singleton)
 ), combined as (select * from normal union all select * from manual)
 select c.slug,c.title,c.summary,c.category,c.score,c.published_at,c.kind from combined c
 where (trim(p_query)='' or strpos(lower(c.title),lower(trim(p_query)))>0)
  and (p_channel is null or c.category=p_channel or p_channel=any(c.related))
  and (p_period='all' or c.published_at>=statement_timestamp()-case p_period when 'day' then interval '1 day' when 'week' then interval '7 days' else interval '30 days' end)
 order by case when p_sort='score' then c.score end desc nulls last,c.published_at desc,c.kind,c.slug limit 21 offset p_offset;
end $$;



CREATE FUNCTION public.get_public_unified_channel_counts() RETURNS TABLE(channel text, story_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select base.channel,base.story_count + coalesce(m.n,0) from public.get_public_channel_counts() base
 left join lateral (select count(*) n from public.manual_articles a join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
 where a.status='published' and (select enabled from public.manual_public_rollout where singleton) and (r.primary_channel=base.channel or base.channel=any(r.related_channels))) m on true
$$;



CREATE FUNCTION public.get_sitemap_article_shard(p_bucket integer, p_after_slug text, p_after_type text, p_limit integer, p_bilingual boolean) RETURNS TABLE(slug text, content_type text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
begin
 if p_bucket is null or p_bucket not between 0 and 7 or p_limit is null or p_limit not between 1 and 500 or p_bilingual is null
 or (p_after_slug is null)<>(p_after_type is null) or (p_after_slug is not null and (length(p_after_slug)>200 or p_after_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or p_after_type not in ('manual','story'))) then raise exception 'invalid sitemap cursor'; end if;
 return query select q.slug,q.kind from (
  select s.slug,'story'::text kind from public.stories s
  where s.visibility='public' and mod(ascii(left(s.slug,1)),8)=p_bucket and public.revision_is_eligible(s.id,s.public_revision_id)
   and exists(select 1 from public.publication_events ev where ev.story_id=s.id and ev.action='publish')
   and (not p_bilingual or exists(select 1 from public.story_bilingual_batches b where b.id=s.published_bilingual_batch_id and b.story_id=s.id and public.bilingual_batch_evidence_gate(b.id)))
  union all
  select a.slug,'manual'::text kind from public.manual_articles a
  join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
  join lateral (select ev.* from public.manual_publication_events ev where ev.article_id=a.id order by ev.event_order desc limit 1) e on e.revision_id=r.id and e.action in ('publish','update','correction')
  where a.status='published' and mod(ascii(left(a.slug,1)),8)=p_bucket and (select enabled from public.manual_public_rollout where singleton)
   and exists(select 1 from public.manual_publication_events ev where ev.article_id=a.id and ev.action='publish')
 ) q where p_after_slug is null or (q.slug collate "C",q.kind collate "C")>(p_after_slug collate "C",p_after_type collate "C")
 order by q.slug collate "C",q.kind collate "C" limit p_limit;
end $_$;



CREATE FUNCTION public.guard_bilingual_rollout_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare batch public.story_bilingual_batches%rowtype;
begin
  if not public.bilingual_rollout_enabled() then return new; end if;
  if new.visibility='public' and (old.visibility is distinct from 'public'
      or old.public_revision_id is distinct from new.public_revision_id
      or old.published_bilingual_batch_id is distinct from new.published_bilingual_batch_id) then
    select * into batch from public.story_bilingual_batches where id=new.published_bilingual_batch_id and story_id=new.id;
    if batch.id is null or new.public_revision_id is distinct from batch.en_revision_id
      or not public.bilingual_batch_evidence_gate(batch.id)
      or not coalesce((select decision='approved' from public.bilingual_editorial_reviews where batch_id=batch.id order by id desc limit 1),false)
      then raise exception 'eligible bilingual batch required'; end if;
    if old.public_revision_id is not null and not exists (
      select 1 from public.publication_events e join public.bilingual_publication_notices n on n.event_id=e.id
      where e.id=(select max(id) from public.publication_events where story_id=new.id)
        and e.story_id=new.id and e.revision_id=batch.en_revision_id and e.action in ('update','correction'))
      then raise exception 'bilingual update notice required'; end if;
  elsif new.visibility='retracted' and old.visibility is distinct from 'retracted' then
    if not exists(select 1 from public.retraction_notices n join public.bilingual_retraction_notices bn on bn.notice_id=n.id
      join public.retraction_approvals a on a.notice_id=n.id where n.id=new.public_retraction_id
        and n.story_id=new.id and n.revision_id=old.public_revision_id) then raise exception 'approved bilingual retraction required'; end if;
  end if;
  return new;
end $$;



CREATE FUNCTION public.guard_team_publication() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if auth.uid() is not null and exists(select 1 from public.site_team_roles where user_id=auth.uid())
    and public.manual_is_owner() is distinct from true
    and ((new.visibility='public' and (old.visibility is distinct from 'public' or new.public_revision_id is distinct from old.public_revision_id or new.published_bilingual_batch_id is distinct from old.published_bilingual_batch_id))
      or (old.visibility='public' and new.visibility is distinct from 'public'))
 then raise exception 'site owner publication required'; end if;
 return new;
end $$;



CREATE FUNCTION public.hide_story(p_story uuid, p_expected_version integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_reason is null or length(trim(p_reason)) = 0 then raise exception 'reason required'; end if;
  update public.stories set visibility = 'hidden', version = version + 1 where id = p_story and version = p_expected_version;
  if not found then raise exception 'story version conflict'; end if;
  insert into public.publication_events(story_id, actor_id, action, reason) values (p_story, auth.uid(), 'hide', p_reason);
end $$;



CREATE FUNCTION public.homepage_featured_for_bucket(p_bilingual boolean, p_bucket bigint) RETURNS TABLE(section text, slug text, content_type text, pos bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 with pool as materialized (
  select a.slug,a.content_type,a.published_at,
   row_number() over (order by a.score desc nulls last,(c.mode='pin') desc nulls last,
    case when c.mode='pin' then c.updated_at end desc,a.published_at desc,a.slug,a.content_type) as rank
  from public.homepage_public_articles('en',p_bilingual) a
  left join public.homepage_article_controls c on c.slug=a.slug and c.content_type=a.content_type
  where c.mode is distinct from 'exclude' and public.homepage_pick_is_today(a.published_at,statement_timestamp())
  order by rank limit 20
 ), headline as (
  select p.* from pool p where p.rank=mod(p_bucket,nullif(least((select count(*) from pool),3),0))+1
 ), remaining as (
  select p.*,row_number() over(order by p.rank) as n,count(*) over() as total
  from pool p where not exists(select 1 from headline h where h.slug=p.slug and h.content_type=p.content_type)
 ), picks as (
  select r.* from remaining r where mod(r.n-1-mod(p_bucket*4,r.total)+r.total,r.total)<4
 )
 select 'headline'::text,h.slug,h.content_type,1::bigint from headline h
 union all
 select 'picks',p.slug,p.content_type,row_number() over(order by p.rank) from picks p
 union all
 select 'picks_recent',p.slug,p.content_type,row_number() over(order by p.published_at desc,p.slug,p.content_type) from picks p
$$;



CREATE FUNCTION public.homepage_headline_for_bucket(p_bilingual boolean, p_bucket bigint) RETURNS TABLE(slug text, content_type text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select f.slug,f.content_type from public.homepage_featured_for_bucket(p_bilingual,p_bucket) f where f.section='headline'
$$;



CREATE FUNCTION public.homepage_pick_is_today(p_published timestamp with time zone, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 select p_published >= (date_trunc('day',p_at at time zone 'Asia/Shanghai') at time zone 'Asia/Shanghai')
    and p_published < ((date_trunc('day',p_at at time zone 'Asia/Shanghai')+interval '1 day') at time zone 'Asia/Shanghai')
$$;



CREATE FUNCTION public.homepage_public_articles(p_locale text, p_bilingual boolean) RETURNS TABLE(slug text, title text, summary text, category text, score integer, published_at timestamp with time zone, content_type text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select s.slug,r.title,r.summary,coalesce(case when p_bilingual then public.bilingual_reviewed_primary_channel(b.id) end,d.category),public.index_score('story',s.slug,sc.holy_shit_score),p.published_at,'story'::text
 from public.stories s
 left join public.story_bilingual_batches b on p_bilingual and b.id=s.published_bilingual_batch_id and b.story_id=s.id
 join public.story_revisions r on r.id=case when p_bilingual then case p_locale when 'zh' then b.zh_revision_id else b.en_revision_id end else s.public_revision_id end
 join lateral (select min(ev.created_at) published_at from public.publication_events ev where ev.story_id=s.id and ev.action='publish') p on p.published_at is not null
 left join public.revision_discovery d on d.revision_id=s.public_revision_id
 left join public.story_scores sc on sc.id=d.score_id and sc.story_id=s.id and sc.revision_id=s.public_revision_id
 where p_locale in ('zh','en') and s.visibility='public' and public.revision_is_eligible(s.id,s.public_revision_id)
 and (not p_bilingual or b.id is not null and public.bilingual_batch_evidence_gate(b.id))
 union all
 select a.slug,case p_locale when 'zh' then r.zh_title else r.en_title end,case p_locale when 'zh' then r.zh_summary else r.en_summary end,r.primary_channel,public.index_score('manual',a.slug,e.final_score),first_pub.published_at,'manual'::text
 from public.manual_articles a join public.manual_article_revisions r on r.id=a.published_revision_id and r.article_id=a.id
 join lateral (select ev.* from public.manual_publication_events ev where ev.article_id=a.id order by ev.event_order desc limit 1) e on e.revision_id=r.id and e.action in ('publish','update','correction')
 join lateral (select min(ev.created_at) published_at from public.manual_publication_events ev where ev.article_id=a.id and ev.action='publish') first_pub on first_pub.published_at is not null
 where p_locale in ('zh','en') and a.status='published' and (select enabled from public.manual_public_rollout where singleton)
$$;



CREATE FUNCTION public.hot_event_apply(p_job uuid, p_attempt integer, p_proposal jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare j public.hot_event_jobs%rowtype; ids text[]; anchor text; total integer; top_score integer;
 progress timestamptz; chosen uuid; existing_count integer; result_id uuid;
begin
 perform pg_advisory_xact_lock(hashtext('ihs_hot_events'));
 select * into j from public.hot_event_jobs where id=p_job and status='running' and attempts=p_attempt and locked_until>now() for update;
 if j.id is null then raise exception 'hot event lease expired'; end if;
 if jsonb_typeof(p_proposal->'ids')<>'array' then raise exception 'invalid event proposal'; end if;
 select array_agg(v) into ids from jsonb_array_elements_text(p_proposal->'ids') x(v);
 anchor:=case when j.job_type='match_manual' then 'manual:'||j.manual_article_id::text when j.job_type='match_story' then 'story:'||j.story_id::text else '' end;
 if cardinality(ids)<3 or cardinality(ids)>200 or not anchor=any(ids) or (select count(distinct x) from unnest(ids) x)<>cardinality(ids)
  or coalesce(length(trim(p_proposal->>'zh_title')),0)=0 or coalesce(length(trim(p_proposal->>'en_title')),0)=0
  or coalesce(length(trim(p_proposal->>'zh_summary')),0)=0 or coalesce(length(trim(p_proposal->>'en_summary')),0)=0 then raise exception 'invalid event proposal'; end if;
 with eligible as (
  select case a.content_type when 'manual' then 'manual:'||m.id::text else 'story:'||s.id::text end id,
   a.score,a.published_at,case a.content_type when 'manual' then m.hot_event_id else s.hot_event_id end event_id
  from public.homepage_public_articles('en',true) a
  left join public.manual_articles m on a.content_type='manual' and m.slug=a.slug
  left join public.stories s on a.content_type='story' and s.slug=a.slug
  where a.published_at between now()-interval '7 days' and now()
 ) select count(*)::integer,max(score),max(published_at),count(distinct event_id)::integer,(array_agg(distinct event_id) filter(where event_id is not null))[1]
 into total,top_score,progress,existing_count,chosen from eligible where id=any(ids);
 if total<>cardinality(ids) or coalesce(top_score,0)<80 or existing_count>1 then raise exception 'event membership no longer eligible'; end if;
 if chosen is null then
  result_id:=gen_random_uuid();
  insert into public.hot_events(id,slug,status) values(result_id,'event-'||result_id::text,'collecting');
 else result_id:=chosen; end if;
 update public.manual_articles set hot_event_id=result_id where 'manual:'||id::text=any(ids);
 update public.stories set hot_event_id=result_id where 'story:'||id::text=any(ids);
 select greatest(progress,coalesce((select max(e.created_at) from public.manual_publication_events e join public.manual_articles a on a.id=e.article_id where a.hot_event_id=result_id and a.status='published' and e.action in ('publish','update','correction')),progress),
  coalesce((select max(e.created_at) from public.publication_events e join public.stories a on a.id=e.story_id where a.hot_event_id=result_id and a.visibility='public' and e.action in ('publish','update','correction')),progress)) into progress;
 update public.hot_events set zh_title=trim(p_proposal->>'zh_title'),en_title=trim(p_proposal->>'en_title'),
  zh_summary=trim(p_proposal->>'zh_summary'),en_summary=trim(p_proposal->>'en_summary'),
  article_count=(select count(*) from public.get_hot_event_articles(result_id,'en')),
  max_index=(select max(score) from public.get_hot_event_articles(result_id,'en')),
  last_progress_at=greatest(coalesce(last_progress_at,progress),progress),summary_updated_at=now(),updated_at=now(),status='published'
 where id=result_id;
 update public.hot_event_jobs set status='completed',locked_until=null,updated_at=now() where id=j.id;
 return result_id;
end $$;



CREATE FUNCTION public.hot_event_claim() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare j public.hot_event_jobs%rowtype; anchor text; candidates jsonb;
begin
 select * into j from public.hot_event_jobs
 where (status='pending' and available_at<=now()) or (status='running' and locked_until<now())
 order by created_at for update skip locked limit 1;
 if j.id is null then return null; end if;
 update public.hot_event_jobs set status='running',attempts=attempts+1,locked_until=now()+interval '5 minutes',updated_at=now()
 where id=j.id returning * into j;
 anchor:=case when j.job_type='match_manual' then 'manual:'||j.manual_article_id::text
              when j.job_type='match_story' then 'story:'||j.story_id::text else '' end;
 select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'title',c.title,'summary',c.summary,'score',c.score,'published_at',c.published_at)
   order by (c.id=anchor) desc,c.published_at desc,c.id),'[]'::jsonb) into candidates
 from (
  select case a.content_type when 'manual' then 'manual:'||m.id::text else 'story:'||s.id::text end id,
   a.title,a.summary,a.score,a.published_at
  from public.homepage_public_articles('en',true) a
  left join public.manual_articles m on a.content_type='manual' and m.slug=a.slug
  left join public.stories s on a.content_type='story' and s.slug=a.slug
  where a.published_at between now()-interval '7 days' and now()
   and ((a.content_type='manual' and m.id is not null) or (a.content_type='story' and s.id is not null))
  order by (case a.content_type when 'manual' then 'manual:'||m.id::text else 'story:'||s.id::text end=anchor) desc,a.published_at desc
 ) c;
 return jsonb_build_object('job_id',j.id,'attempt',j.attempts,'anchor',anchor,'articles',candidates);
end $$;



CREATE FUNCTION public.hot_event_finish_empty(p_job uuid, p_attempt integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 update public.hot_event_jobs set status='completed',locked_until=null,updated_at=now()
 where id=p_job and status='running' and attempts=p_attempt and locked_until>now();
 if not found then raise exception 'hot event lease expired'; end if;
end $$;



CREATE FUNCTION public.hot_event_retry(p_job uuid, p_attempt integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 update public.hot_event_jobs j set status=case when attempts>=3 then 'failed' when exists (select 1 from public.hot_event_jobs other where other.id<>j.id and other.status='pending' and other.job_type=j.job_type and other.manual_article_id is not distinct from j.manual_article_id and other.story_id is not distinct from j.story_id and other.hot_event_id is not distinct from j.hot_event_id) then 'completed' else 'pending' end,
  available_at=now()+interval '15 minutes',locked_until=null,last_error='processing failed',updated_at=now()
 where id=p_job and status='running' and attempts=p_attempt and locked_until>now();
end $$;



CREATE FUNCTION public.index_score(p_type text, p_slug text, p_base integer) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select case when p_base is null then null else greatest(0::bigint,least(100::bigint,p_base::bigint+coalesce((select total/10-dislikes/10-shit/3 from public.article_index_clicks c where c.content_type=p_type and c.slug=p_slug),0)))::integer end
$$;



CREATE FUNCTION public.ingestion_apply_host_floor_on_dispatch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare floor_seconds integer;
begin
  select interval_floor_seconds into floor_seconds from public.ingestion_host_limits where hostname=new.hostname;
  if floor_seconds is null then raise exception 'host rate floor unavailable'; end if;
  new.interval_seconds := greatest(new.interval_seconds,floor_seconds);
  return new;
end $$;



CREATE FUNCTION public.ingestion_apply_host_floor_on_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare active_id uuid;
begin
  insert into public.ingestion_host_limits(hostname,interval_floor_seconds) values(new.hostname,new.min_interval_seconds)
    on conflict (hostname) do update set
      interval_floor_seconds=greatest(public.ingestion_host_limits.interval_floor_seconds,excluded.interval_floor_seconds),
      next_allowed_at=case when exists(select 1 from public.ingestion_dispatches d where d.hostname=new.hostname)
        then greatest(public.ingestion_host_limits.next_allowed_at,clock_timestamp()+make_interval(secs=>excluded.interval_floor_seconds))
        else public.ingestion_host_limits.next_allowed_at end;
  select active_dispatch_id into active_id from public.ingestion_host_limits where hostname=new.hostname;
  if active_id is not null then
    update public.ingestion_dispatches set interval_seconds=greatest(interval_seconds,new.min_interval_seconds) where id=active_id and state='checked';
  end if;
  return new;
end $$;



CREATE FUNCTION public.ingestion_claim_job() RETURNS TABLE(job_id uuid, source_id uuid, lease_token uuid, lease_expires_at timestamp with time zone, attempt integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare candidate uuid;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  select j.id into candidate from public.ingestion_jobs j
  where j.attempts < 3 and not public.ingestion_source_is_held(j.source_id) and (
    (j.status in ('pending', 'retry_scheduled') and j.available_at <= clock_timestamp())
    or (j.status = 'processing' and j.lease_expires_at <= clock_timestamp()))
  order by j.available_at, j.created_at, j.id for update skip locked limit 1;
  if candidate is null then return; end if;
  return query update public.ingestion_jobs j set status = 'processing', attempts = j.attempts + 1,
    lease_token = gen_random_uuid(), lease_expires_at = clock_timestamp() + interval '5 minutes'
    where j.id = candidate returning j.id, j.source_id, j.lease_token, j.lease_expires_at, j.attempts;
end $$;



CREATE FUNCTION public.ingestion_close_dispatch(p_dispatch uuid, p_lease uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare d public.ingestion_dispatches%rowtype; h public.ingestion_host_limits%rowtype;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  select * into d from public.ingestion_dispatches where id=p_dispatch;
  if d.id is null or d.lease_token is distinct from p_lease then raise exception 'dispatch unavailable'; end if;
  select * into h from public.ingestion_host_limits where hostname=d.hostname for update;
  select * into d from public.ingestion_dispatches where id=p_dispatch for update;
  if d.state='closed' then return false; end if;
  if h.active_dispatch_id is distinct from d.id then raise exception 'dispatch state conflict'; end if;
  update public.ingestion_dispatches set state='closed',closed_at=clock_timestamp() where id=d.id;
  update public.ingestion_host_limits set active_dispatch_id=null,
    next_allowed_at=greatest(next_allowed_at,clock_timestamp()+make_interval(secs=>d.interval_seconds)) where hostname=d.hostname;
  return true;
end $$;



CREATE FUNCTION public.ingestion_confirm_completion(p_job uuid, p_lease uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_job is not null and p_lease is not null and exists (
    select 1 from public.ingestion_jobs j where j.id = p_job and j.status = 'completed' and j.completed_lease_token = p_lease
  ) then return 'completed'; end if;
  return 'unresolved';
end $$;



CREATE FUNCTION public.ingestion_enqueue_job(p_source uuid, p_key text) RETURNS TABLE(job_id uuid, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare found_id uuid; found_source uuid;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_source is null or p_key is null or length(trim(p_key)) = 0 or length(p_key) > 200 or p_key <> trim(p_key) then
    raise exception 'invalid job identity';
  end if;
  insert into public.ingestion_jobs(source_id, idempotency_key) values(p_source, p_key)
    on conflict (idempotency_key) do nothing returning id into found_id;
  if found_id is not null then return query select found_id, true; return; end if;
  select id, source_id into found_id, found_source from public.ingestion_jobs where idempotency_key = p_key;
  if found_id is null or found_source <> p_source then raise exception 'job key belongs to another source'; end if;
  return query select found_id, false;
end $$;



CREATE FUNCTION public.ingestion_fail_exhausted_leases() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare changed integer;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  update public.ingestion_jobs j set status = 'failed', last_error_code = 'lease_expired', lease_token = null, lease_expires_at = null
  where j.status = 'processing' and j.attempts >= 3 and j.lease_expires_at <= clock_timestamp();
  get diagnostics changed = row_count;
  return changed;
end $$;



CREATE FUNCTION public.ingestion_finish_job(p_job uuid, p_lease uuid, p_error_code text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result text;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_error_code is not null and p_error_code not in ('temporary', 'invalid_data', 'policy_denied') then raise exception 'invalid error code'; end if;
  update public.ingestion_jobs j set
    status = case when p_error_code is null then 'completed' when p_error_code = 'temporary' and j.attempts < 3 then 'retry_scheduled' else 'failed' end,
    available_at = case when p_error_code = 'temporary' and j.attempts < 3 then clock_timestamp() + interval '1 minute' * power(2, j.attempts - 1) else j.available_at end,
    last_error_code = p_error_code, completed_lease_token = case when p_error_code is null then p_lease else null end,
    lease_token = null, lease_expires_at = null
  where j.id = p_job and j.status = 'processing' and j.lease_token = p_lease and j.lease_expires_at > clock_timestamp()
  returning j.status into result;
  if result is null then raise exception 'job lease unavailable'; end if;
  return result;
end $$;



CREATE FUNCTION public.ingestion_finish_not_modified(p_job uuid, p_lease uuid, p_dispatch uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid; d public.ingestion_dispatches%rowtype; v public.rss_endpoint_validators%rowtype;
begin
  sid := public.ingestion_lock_active_job(p_job,p_lease);
  perform 1 from public.ingestion_lock_rss_policy(sid);
  perform public.ingestion_lock_active_job(p_job,p_lease);
  select * into d from public.ingestion_dispatches where id=p_dispatch and job_id=p_job and lease_token=p_lease and state='closed';
  if d.id is null or not public.ingestion_validator_permission_current(d.endpoint_id) then raise exception 'conditional permission unavailable'; end if;
  select * into v from public.rss_endpoint_validators where endpoint_id=d.endpoint_id;
  if v.endpoint_id is null or (d.if_none_match is null and d.if_modified_since is null)
    or d.if_none_match is distinct from v.etag or d.if_modified_since is distinct from v.last_modified then raise exception 'conditional validators unavailable'; end if;
  return public.ingestion_finish_success(p_job,p_lease);
end $$;



CREATE FUNCTION public.ingestion_finish_success(p_job uuid, p_lease uuid) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select public.ingestion_finish_job(p_job,p_lease,null)
$$;



CREATE FUNCTION public.ingestion_hn_checkpoint(p_advance_to bigint DEFAULT NULL::bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare current_value bigint;
begin
 if session_user<>'news_ingestion_worker' then raise exception 'ingestion runtime required'; end if;
 if p_advance_to is not null and (p_advance_to<0 or p_advance_to>extract(epoch from clock_timestamp())::bigint) then raise exception 'invalid checkpoint'; end if;
 if p_advance_to is not null then
  update public.hn_discovery_checkpoint set next_before=least(coalesce(next_before,p_advance_to),p_advance_to) where singleton;
 end if;
 select next_before into current_value from public.hn_discovery_checkpoint where singleton;
 return current_value;
end $$;



CREATE FUNCTION public.ingestion_job_lock_policy(p_job uuid, p_lease uuid) RETURNS TABLE(source_id uuid, policy_version integer, permission_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid; policy_row record;
begin
  sid := public.ingestion_lock_active_job(p_job, p_lease);
  select * into policy_row from public.ingestion_lock_rss_policy(sid);
  -- The source lock may have been contended long enough for the lease to expire.
  perform public.ingestion_lock_active_job(p_job, p_lease);
  return query select sid, policy_row.policy_version, policy_row.permission_expires_at;
end $$;



CREATE FUNCTION public.ingestion_job_store_article(p_job uuid, p_lease uuid, p_policy_version integer, p_title text, p_url text) RETURNS TABLE(article_id uuid, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid;
begin
  sid := public.ingestion_lock_active_job(p_job, p_lease);
  perform 1 from public.ingestion_lock_rss_policy(sid);
  perform public.ingestion_lock_active_job(p_job, p_lease);
  return query select a.article_id, a.inserted from public.ingestion_store_article(sid, p_policy_version, p_title, p_url) a;
end $$;



CREATE FUNCTION public.ingestion_job_store_dated_article(p_job uuid, p_lease uuid, p_policy_version integer, p_title text, p_url text, p_published_at timestamp with time zone) RETURNS TABLE(article_id uuid, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid;
begin
 sid:=public.ingestion_lock_active_job(p_job,p_lease);
 perform 1 from public.ingestion_lock_rss_policy(sid);
 perform public.ingestion_lock_active_job(p_job,p_lease);
 return query select a.article_id,a.inserted from public.ingestion_store_dated_article(sid,p_policy_version,p_title,p_url,p_published_at) a;
end $$;



CREATE FUNCTION public.ingestion_lock_active_job(p_job uuid, p_lease uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare j public.ingestion_jobs%rowtype;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  select * into j from public.ingestion_jobs where id = p_job for update;
  -- Check the clock after obtaining the lock, including any lock wait.
  if j.id is null or j.status <> 'processing' or j.lease_token is distinct from p_lease
    or j.lease_expires_at is null or j.lease_expires_at <= clock_timestamp() then raise exception 'job lease unavailable'; end if;
  return j.source_id;
end $$;



CREATE FUNCTION public.ingestion_lock_rss_policy(p_source uuid) RETURNS TABLE(policy_version integer, permission_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare p public.source_policies%rowtype;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  perform 1 from public.sources where id = p_source for update;
  if not found then raise exception 'source not found'; end if;
  if public.ingestion_source_is_held(p_source) then raise exception 'source ingestion held'; end if;
  select * into p from public.source_policies where source_id = p_source order by version desc limit 1;
  if p.id is null or p.policy_status <> 'approved' or not p.access_allowed or p.access_method <> 'rss'
    or not p.title_storage_allowed or not p.url_storage_allowed or p.reviewed_by is null or p.reviewed_at is null
    or jsonb_typeof(p.policy_evidence) <> 'object' or p.policy_evidence = '{}'::jsonb
    or (p.permission_expires_at is not null and p.permission_expires_at <= clock_timestamp()) then
    raise exception 'current metadata permission unavailable';
  end if;
  return query select p.version, p.permission_expires_at;
end $$;



CREATE FUNCTION public.ingestion_prepare_dispatch(p_job uuid, p_lease uuid) RETURNS TABLE(dispatch_id uuid, feed_url text, send_before timestamp with time zone, server_epoch numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid; p public.source_policies%rowtype; e public.rss_endpoint_reviews%rowtype;
  j public.ingestion_jobs%rowtype; h public.ingestion_host_limits%rowtype; effective_interval integer; did uuid; deadline timestamptz;
begin
  sid := public.ingestion_lock_active_job(p_job,p_lease);
  perform 1 from public.ingestion_lock_rss_policy(sid);
  perform public.ingestion_lock_active_job(p_job,p_lease);
  select * into p from public.source_policies where source_id=sid order by version desc limit 1;
  select * into e from public.rss_endpoint_reviews where policy_id=p.id;
  select * into j from public.ingestion_jobs where id=p_job;
  if e.id is null or e.expires_at <= clock_timestamp() then raise exception 'current RSS endpoint review unavailable'; end if;
  if exists(select 1 from public.ingestion_dispatches where job_id=p_job and attempt=j.attempts) then
    raise exception 'dispatch already checked';
  end if;
  insert into public.ingestion_host_limits(hostname) values(e.hostname) on conflict do nothing;
  select * into h from public.ingestion_host_limits where hostname=e.hostname for update;
  perform public.ingestion_lock_active_job(p_job,p_lease);
  if h.active_dispatch_id is not null then raise exception 'host has an unresolved dispatch'; end if;
  if h.next_allowed_at > clock_timestamp() then raise exception 'host rate limit active'; end if;
  if e.expires_at <= clock_timestamp() or (p.permission_expires_at is not null and p.permission_expires_at <= clock_timestamp()) then
    raise exception 'current RSS endpoint review unavailable';
  end if;
  select greatest(e.min_interval_seconds,coalesce(max(other.min_interval_seconds),0)) into effective_interval
    from public.rss_endpoint_reviews other join public.source_policies op on op.id=other.policy_id
    where other.hostname=e.hostname and other.expires_at > clock_timestamp() and op.policy_status='approved'
      and op.version=(select max(latest.version) from public.source_policies latest where latest.source_id=op.source_id)
      and (op.permission_expires_at is null or op.permission_expires_at > clock_timestamp());
  deadline := least(j.lease_expires_at,e.expires_at,coalesce(p.permission_expires_at,'infinity'::timestamptz),clock_timestamp()+interval '1 minute');
  if deadline <= clock_timestamp()+interval '30 seconds' then raise exception 'dispatch window too short'; end if;
  insert into public.ingestion_dispatches(job_id,lease_token,attempt,endpoint_id,hostname,interval_seconds)
    values(p_job,p_lease,j.attempts,e.id,e.hostname,effective_interval) returning id into did;
  update public.ingestion_host_limits set active_dispatch_id=did,
    next_allowed_at=clock_timestamp()+make_interval(secs=>effective_interval) where hostname=e.hostname;
  return query select did,e.feed_url,deadline,extract(epoch from clock_timestamp());
end $$;



CREATE FUNCTION public.ingestion_prepare_or_defer(p_job uuid, p_lease uuid) RETURNS TABLE(dispatch_id uuid, feed_url text, send_before timestamp with time zone, server_epoch numeric, attempt integer, deferred boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare snap record; attempt_no integer; sid uuid;
begin
  select * into snap from public.ingestion_prepare_dispatch(p_job,p_lease);
  select j.attempts into attempt_no from public.ingestion_jobs j where j.id=p_job;
  return query select snap.dispatch_id,snap.feed_url,snap.send_before,snap.server_epoch,attempt_no,false;
exception when raise_exception then
  if sqlerrm not in ('host has an unresolved dispatch','host rate limit active') then raise; end if;
  sid := public.ingestion_lock_active_job(p_job,p_lease);
  select j.attempts into attempt_no from public.ingestion_jobs j where j.id=p_job;
  if attempt_no < 1 then raise exception 'invalid job attempt'; end if;
  update public.ingestion_jobs set status='retry_scheduled',attempts=attempt_no-1,
    available_at=clock_timestamp()+interval '1 minute',last_error_code='temporary',lease_token=null,lease_expires_at=null
    where id=p_job and source_id=sid;
  return query select null::uuid,null::text,null::timestamptz,null::numeric,attempt_no,true;
end $$;



CREATE FUNCTION public.ingestion_prepare_with_validators(p_job uuid, p_lease uuid) RETURNS TABLE(dispatch_id uuid, feed_url text, send_before timestamp with time zone, server_epoch numeric, attempt integer, deferred boolean, etag text, last_modified text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare snap record; eid uuid; v public.rss_endpoint_validators%rowtype; validator_expiry timestamptz; deadline timestamptz;
begin
  select * into snap from public.ingestion_prepare_or_defer(p_job,p_lease);
  if snap.deferred then return query select null::uuid,null::text,null::timestamptz,null::numeric,snap.attempt,true,null::text,null::text; return; end if;
  select d.endpoint_id into eid from public.ingestion_dispatches d where d.id=snap.dispatch_id;
  deadline := snap.send_before;
  if public.ingestion_validator_permission_current(eid) then
    select expires_at into validator_expiry from public.rss_validator_permissions where endpoint_id=eid;
    if validator_expiry > clock_timestamp()+interval '30 seconds' then
      select * into v from public.rss_endpoint_validators where endpoint_id=eid;
      if v.etag is not null or v.last_modified is not null then deadline := least(deadline,validator_expiry); end if;
    end if;
  end if;
  update public.ingestion_dispatches set if_none_match=v.etag,if_modified_since=v.last_modified where id=snap.dispatch_id;
  return query select snap.dispatch_id,snap.feed_url,deadline,snap.server_epoch,snap.attempt,false,v.etag,v.last_modified;
end $$;



CREATE FUNCTION public.ingestion_purge_expired_validators() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare removed integer;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  delete from public.rss_endpoint_validators v where not public.ingestion_validator_permission_current(v.endpoint_id);
  get diagnostics removed = row_count;
  update public.ingestion_dispatches d set if_none_match=null,if_modified_since=null
    where (d.if_none_match is not null or d.if_modified_since is not null)
      and not public.ingestion_validator_permission_current(d.endpoint_id);
  return removed;
end $$;



CREATE FUNCTION public.ingestion_recent_recall_scope() RETURNS TABLE(article_id uuid, policy_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select a.id,p.id from public.articles a
 join lateral (select sp.id from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1)p on true
 where public.candidate_title_allowed(a.id) order by a.published_at desc nulls last,a.created_at desc,a.id desc limit 200
$$;



CREATE FUNCTION public.ingestion_record_fetch_failure(p_job uuid, p_lease uuid, p_reason text, p_delay_seconds integer DEFAULT NULL::integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid; n integer; result text;
begin
  sid := public.ingestion_lock_active_job(p_job, p_lease);
  if p_reason not in ('access_denied','rate_limited','manual_review','temporary','invalid_data') or p_reason is null then
    raise exception 'invalid failure reason';
  end if;
  perform 1 from public.sources where id = sid for update;
  perform public.ingestion_lock_active_job(p_job, p_lease);
  select attempts into n from public.ingestion_jobs where id = p_job;
  if p_reason = 'temporary' and n < 3 then
    if p_delay_seconds is null or p_delay_seconds < 60 * power(2,n-1) or p_delay_seconds > 86400 then
      raise exception 'invalid retry delay';
    end if;
    update public.ingestion_jobs set status='retry_scheduled', available_at=clock_timestamp()+make_interval(secs => p_delay_seconds),
      last_error_code='temporary', lease_token=null, lease_expires_at=null where id=p_job;
    return 'retry_scheduled';
  end if;
  if p_delay_seconds is not null then raise exception 'unexpected retry delay'; end if;
  if p_reason in ('access_denied','rate_limited','manual_review') then
    if not public.ingestion_source_is_held(sid) then
      insert into public.ingestion_source_holds(source_id,job_id,reason) values(sid,p_job,p_reason);
    end if;
    result := 'policy_denied';
  elsif p_reason = 'temporary' then result := 'temporary';
  else result := 'invalid_data'; end if;
  update public.ingestion_jobs set status='failed', last_error_code=result, lease_token=null, lease_expires_at=null where id=p_job;
  return 'failed';
end $$;



CREATE FUNCTION public.ingestion_schedule_due(p_run uuid, p_limit integer DEFAULT 50) RETURNS TABLE(source_id uuid, job_id uuid, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare candidate record; current_policy public.source_policies%rowtype; endpoint public.rss_endpoint_reviews%rowtype;
  last_at timestamptz; queued record; scheduled_at timestamptz;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_run is null or p_limit is null or p_limit not between 1 and 100 then raise exception 'invalid schedule request'; end if;
  for candidate in
    select s.id from public.sources s
    join lateral (select * from public.source_policies p where p.source_id=s.id order by version desc limit 1) p on true
    join public.rss_endpoint_reviews e on e.policy_id=p.id
    left join public.ingestion_schedule_state st on st.source_id=s.id
    where p.policy_status='approved' and p.access_allowed and p.access_method='rss'
      and e.expires_at > clock_timestamp() and not public.ingestion_source_is_held(s.id)
      and (st.last_scheduled_at is null or st.last_scheduled_at+make_interval(secs=>e.min_interval_seconds) <= clock_timestamp())
      and not exists (select 1 from public.ingestion_jobs j where j.source_id=s.id and j.status in ('pending','processing','retry_scheduled'))
    order by coalesce(st.last_scheduled_at,'-infinity'::timestamptz),s.id
    for update of s skip locked limit p_limit
  loop
    -- Re-read after acquiring the lock; no stale policy or endpoint snapshot.
    select * into current_policy from public.source_policies p where p.source_id=candidate.id order by version desc limit 1;
    select * into endpoint from public.rss_endpoint_reviews e where e.policy_id=current_policy.id;
    select st.last_scheduled_at into last_at from public.ingestion_schedule_state st where st.source_id=candidate.id;
    if endpoint.id is null or endpoint.expires_at <= clock_timestamp() or public.ingestion_source_is_held(candidate.id)
      or (last_at is not null and last_at+make_interval(secs=>endpoint.min_interval_seconds)>clock_timestamp())
      or exists(select 1 from public.ingestion_jobs j where j.source_id=candidate.id and j.status in ('pending','processing','retry_scheduled')) then
      continue;
    end if;
    begin
      perform 1 from public.ingestion_lock_rss_policy(candidate.id);
    exception when raise_exception then
      continue;
    end;
    scheduled_at := clock_timestamp();
    select * into queued from public.ingestion_enqueue_job(candidate.id,'schedule:'||p_run::text||':'||candidate.id::text);
    insert into public.ingestion_schedule_state as st(source_id,last_scheduled_at) values(candidate.id,scheduled_at)
      on conflict on constraint ingestion_schedule_state_pkey do update set last_scheduled_at=excluded.last_scheduled_at;
    return query select candidate.id,queued.job_id,queued.inserted;
  end loop;
end $$;



CREATE FUNCTION public.ingestion_signal_candidate_scope() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result jsonb;
begin
 if session_user<>'news_ingestion_worker' then raise exception 'ingestion runtime required'; end if;
 with board_rows as (
  select o.platform,o.external_id,o.title,o.url,o.published_at,o.metric,b.board,
   case when last.obs>first.obs and extract(epoch from last.obs-first.obs)>=cfg.minimum_sample_seconds
     then greatest(0,(last.metric::numeric-first.metric::numeric)*3600/extract(epoch from last.obs-first.obs)) else null end as growth
  from public.signal_board_memberships b join public.signal_observations o using(platform,external_id)
  cross join public.signal_detection_config cfg
  left join lateral (select h.metric,h.observed_at obs from public.signal_metric_history h where h.platform=o.platform and h.external_id=o.external_id and h.observed_at>=b.first_seen_at-interval '5 seconds' order by h.observed_at limit 1) first on true
  left join lateral (select h.metric,h.observed_at obs from public.signal_metric_history h where h.platform=o.platform and h.external_id=o.external_id and h.observed_at>=b.first_seen_at order by h.observed_at desc limit 1) last on true
  where cfg.singleton
  order by o.published_at desc
 ), article_rows as (
  select a.id,a.title,a.canonical_url,a.published_at from public.articles a
  where a.canonical_url is not null and public.candidate_title_allowed(a.id)
  order by a.published_at desc
 )
 select jsonb_build_object('signals',coalesce((select jsonb_agg(to_jsonb(b)) from board_rows b),'[]'::jsonb),
 'articles',coalesce((select jsonb_agg(to_jsonb(a)) from article_rows a),'[]'::jsonb),
 'growth_threshold',(select growth_points_per_hour from public.signal_detection_config where singleton)) into result;
 return result;
end $$;



CREATE FUNCTION public.ingestion_source_is_held(p_source uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists (select 1 from public.ingestion_source_holds h
    where h.source_id = p_source and not exists
      (select 1 from public.ingestion_hold_releases r where r.hold_id = h.id))
$$;



CREATE FUNCTION public.ingestion_store_article(p_source uuid, p_policy_version integer, p_title text, p_url text) RETURNS TABLE(article_id uuid, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare p public.source_policies%rowtype; aid uuid; normal_url text;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_policy_version is null or p_policy_version < 1 then raise exception 'invalid policy version'; end if;
  if p_title is null or length(trim(p_title)) = 0 or p_title <> trim(p_title) or length(p_title) > 1000 then raise exception 'invalid title'; end if;
  begin
    normal_url := public.article_url_identity(p_url);
  exception when invalid_parameter_value then raise exception 'invalid https url'; end;
  if p_url is null or normal_url is distinct from p_url then raise exception 'invalid https url'; end if;
  perform 1 from public.sources where id = p_source for update;
  if not found then raise exception 'source not found'; end if;
  select * into p from public.source_policies where source_id = p_source order by version desc limit 1;
  if p.id is null or p.version <> p_policy_version or p.policy_status <> 'approved'
    or not p.access_allowed or p.access_method <> 'rss' or not p.title_storage_allowed or not p.url_storage_allowed
    or p.reviewed_by is null or p.reviewed_at is null or jsonb_typeof(p.policy_evidence) <> 'object' or p.policy_evidence = '{}'::jsonb
    or (p.permission_expires_at is not null and p.permission_expires_at <= clock_timestamp()) then
    raise exception 'current metadata permission unavailable';
  end if;
  select a.id into aid from public.articles a where a.source_id=p_source and a.canonical_url is not null
    and public.article_url_identity(a.canonical_url)=p_url;
  if aid is not null then return query select aid,false; return; end if;
  insert into public.articles(source_id,title,canonical_url,ingestion_policy_version)
    values(p_source,p_title,p_url,p.version) returning id into aid;
  return query select aid,true;
end $$;



CREATE FUNCTION public.ingestion_store_dated_article(p_source uuid, p_policy_version integer, p_title text, p_url text, p_published_at timestamp with time zone) RETURNS TABLE(article_id uuid, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare result record;
begin
 select * into result from public.ingestion_store_article(p_source,p_policy_version,p_title,p_url);
 update public.articles set published_at=p_published_at where id=result.article_id and published_at is null and p_published_at is not null;
 return query select result.article_id,result.inserted;
end $$;



CREATE FUNCTION public.ingestion_store_hn_signals(p_data jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare item jsonb; count_saved integer:=0; published timestamptz; entry_id text; item_title text; item_url text; points integer;
begin
 if session_user<>'news_ingestion_worker' then raise exception 'ingestion runtime required'; end if;
 if jsonb_typeof(p_data) is distinct from 'array' or jsonb_array_length(p_data)>100 then raise exception 'invalid signal batch'; end if;
 for item in select value from jsonb_array_elements(p_data) loop
  entry_id:=item->>'id'; item_title:=item->>'title';item_url:=item->>'url';
  published:=(item->>'published_at')::timestamptz;points:=(item->>'metric')::integer;
  if entry_id is null or entry_id !~ '^[0-9]{1,32}$' or item_title is null or length(trim(item_title)) not between 1 and 1000
    or item_url is null or length(item_url) not between 10 and 2048 or item_url !~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$'
    or points<0
    then raise exception 'invalid signal'; end if;
  insert into public.signal_observations(platform,external_id,title,url,published_at,metric)
  values('hacker_news',entry_id,item_title,item_url,published,points)
  on conflict(platform,external_id) do update set metric=excluded.metric,observed_at=clock_timestamp();
  if points is not null then insert into public.signal_metric_history(platform,external_id,metric) values('hacker_news',entry_id,points); end if;
  if item ? 'board' and item->>'board'='front_page' then
   insert into public.signal_board_memberships(platform,external_id,board) values('hacker_news',entry_id,'front_page')
   on conflict(platform,external_id,board) do update set last_seen_at=clock_timestamp();
  elsif item ? 'board' and item->>'board' is not null then raise exception 'invalid signal board'; end if;
  count_saved:=count_saved+1;
 end loop;
 return count_saved;
end $_$;



CREATE FUNCTION public.ingestion_store_signal_candidate(p_fingerprint text, p_reason text, p_members jsonb, p_articles uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare member jsonb; cid uuid; n int; valid_boards int; matched int; allowed_growth numeric; candidate_growth numeric;
begin
 if session_user<>'news_ingestion_worker' then raise exception 'ingestion runtime required'; end if;
 if p_fingerprint is null or p_fingerprint !~ '^[0-9a-f]{64}$' or p_reason not in ('boards','growth')
 or jsonb_typeof(p_members) is distinct from 'array' or jsonb_array_length(p_members)<1 then raise exception 'invalid candidate'; end if;
 select count(*),count(distinct (m->>'platform',m->>'board')) into n,valid_boards
 from jsonb_array_elements(p_members) m join public.signal_board_memberships b on b.platform=m->>'platform' and b.external_id=m->>'id' and b.board=m->>'board'
 join public.signal_observations o on (o.platform,o.external_id)=(b.platform,b.external_id)
 where true;
 if n<>jsonb_array_length(p_members) then raise exception 'current board signals required'; end if;
 if p_reason='boards' and valid_boards<3 then raise exception 'three distinct boards required'; end if;
 if p_reason='growth' then
  select growth_points_per_hour into allowed_growth from public.signal_detection_config where singleton;
  select max((s->>'growth')::numeric) into candidate_growth from jsonb_array_elements(public.ingestion_signal_candidate_scope()->'signals') s
   where exists(select 1 from jsonb_array_elements(p_members) m where m->>'platform'=s->>'platform' and m->>'id'=s->>'external_id' and m->>'board'=s->>'board');
  if candidate_growth is null or candidate_growth<allowed_growth then raise exception 'measured board growth below threshold'; end if;
 end if;
 select count(*) into matched from public.articles a where a.id=any(coalesce(p_articles,'{}'::uuid[]))
  and public.candidate_title_allowed(a.id);
 if matched<>cardinality(coalesce(p_articles,'{}'::uuid[])) then raise exception 'eligible source articles required'; end if;
 insert into public.signal_event_candidates(fingerprint,reason) values(p_fingerprint,p_reason)
 on conflict(fingerprint) do update set fingerprint=excluded.fingerprint returning id into cid;
 for member in select value from jsonb_array_elements(p_members) loop
  insert into public.signal_event_members(candidate_id,platform,external_id,board) values(cid,member->>'platform',member->>'id',member->>'board') on conflict do nothing;
 end loop;
 insert into public.signal_event_article_matches(candidate_id,article_id) select cid,x from unnest(coalesce(p_articles,'{}'::uuid[])) x on conflict do nothing;
 return cid;
end $_$;



CREATE FUNCTION public.ingestion_store_validators(p_dispatch uuid, p_lease uuid, p_etag text, p_last_modified text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare d public.ingestion_dispatches%rowtype; j public.ingestion_jobs%rowtype;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if (p_etag is not null and (length(p_etag) not between 1 and 512 or p_etag ~ '[^ -~]'))
    or (p_last_modified is not null and (length(p_last_modified) not between 1 and 512 or p_last_modified ~ '[^ -~]')) then raise exception 'invalid validators'; end if;
  select * into d from public.ingestion_dispatches where id=p_dispatch;
  if d.id is null or d.lease_token is distinct from p_lease or d.state<>'closed' then raise exception 'dispatch unavailable'; end if;
  select * into j from public.ingestion_jobs where id=d.job_id for update;
  if j.status<>'completed' or j.completed_lease_token is distinct from p_lease then raise exception 'job completion unavailable'; end if;
  perform 1 from public.sources where id=j.source_id for update;
  if not public.ingestion_validator_permission_current(d.endpoint_id) then return false; end if;
  insert into public.rss_endpoint_validators as v(endpoint_id,etag,last_modified,updated_at)
    values(d.endpoint_id,p_etag,p_last_modified,clock_timestamp())
    on conflict on constraint rss_endpoint_validators_pkey do update set etag=excluded.etag,last_modified=excluded.last_modified,updated_at=excluded.updated_at;
  return true;
end $$;



CREATE FUNCTION public.ingestion_validator_permission_current(p_endpoint uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select exists(select 1 from public.rss_validator_permissions v join public.rss_endpoint_reviews e on e.id=v.endpoint_id
    join public.source_policies p on p.id=e.policy_id
    where v.endpoint_id=p_endpoint and v.expires_at>clock_timestamp() and e.expires_at>clock_timestamp()
      and p.policy_status='approved' and p.access_allowed and p.access_method='rss'
      and (p.permission_expires_at is null or p.permission_expires_at>clock_timestamp())
      and p.version=(select max(latest.version) from public.source_policies latest where latest.source_id=p.source_id)
      and not exists(select 1 from public.rss_validator_revocations r where r.endpoint_id=v.endpoint_id))
$$;



CREATE FUNCTION public.invalidate_story_summary_on_unlink() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  insert into public.story_summary_request_invalidations(request_id)
    select req.request_id from public.story_summary_requests req join public.ai_request_preparation_inputs i on i.request_id=req.request_id
      where req.story_id=old.story_id and i.article_id=old.article_id on conflict do nothing;
  delete from public.story_summary_proposals p using public.story_summary_request_invalidations inv where inv.request_id=p.request_id;
  return old;
end $$;



CREATE FUNCTION public.is_active_editor() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
  select exists(select 1 from public.editors e join auth.users u on u.id = e.user_id
    where e.user_id = auth.uid() and e.active and u.deleted_at is null
      and (u.banned_until is null or u.banned_until <= now()))
$$;



CREATE FUNCTION public.latest_discovery_excerpt(p_summary text, p_document jsonb, p_locale text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
 summary_text text := btrim(regexp_replace(coalesce(p_summary,''),'[[:space:]]+',' ','g'));
 body_text text;
 excerpt text;
 sentence_end text;
 minimum_length integer := case when p_locale='zh' then 60 else 180 end;
 maximum_length integer := case when p_locale='zh' then 140 else 360 end;
begin
 if length(summary_text)>=minimum_length then return summary_text; end if;

 -- Visit paragraphs in document order, joining inline marks without splitting words.
 with recursive nodes(node,path) as (
  select p_document,array[]::bigint[]
  union all
  select child.value,nodes.path||child.ordinality
  from nodes cross join lateral jsonb_array_elements(
   case when jsonb_typeof(nodes.node->'content')='array'
        then nodes.node->'content' else '[]'::jsonb end
  ) with ordinality child(value,ordinality)
 ), paragraphs as (
  select nodes.path,
   (select string_agg(piece.value->>'text','' order by piece.ordinality)
    from jsonb_array_elements(
     case when jsonb_typeof(nodes.node->'content')='array'
          then nodes.node->'content' else '[]'::jsonb end
    ) with ordinality piece(value,ordinality)
    where piece.value->>'type'='text') paragraph_text
  from nodes where nodes.node->>'type'='paragraph'
 )
 select string_agg(paragraph_text,' ' order by path) into body_text
 from paragraphs where length(btrim(paragraph_text))>0;

 body_text:=btrim(regexp_replace(regexp_replace(coalesce(body_text,''),
  '((成品|项目|链接|Project|Product|Link)[：:][[:space:]]*)?https?://[^[:space:]]+',
  ' ','gi'),'[[:space:]]+',' ','g'));
 if body_text='' then return summary_text; end if;

 -- Keep the original caveats at the start of the teaser.
 excerpt:=case
  when summary_text='' or left(body_text,length(summary_text))=summary_text then body_text
  else summary_text||' '||body_text end;
 if length(excerpt)<=maximum_length then return excerpt; end if;
 excerpt:=left(excerpt,maximum_length);
 if p_locale='zh' then
  sentence_end:=regexp_replace(excerpt,'^(.*[。！？]).*$','\1');
 else
  sentence_end:=btrim(regexp_replace(excerpt,'^(.*[.!?][[:space:]]).*$','\1'));
 end if;
 if sentence_end<>excerpt and length(sentence_end)>=minimum_length then
  return sentence_end;
 end if;
 if p_locale<>'zh' then
  excerpt:=regexp_replace(excerpt,'[[:space:]]+[^[:space:]]*$','');
 end if;
 return btrim(excerpt)||'…';
end $_$;



CREATE FUNCTION public.list_article_anonymous_comments(p_type text, p_slug text, p_offset integer DEFAULT 0) RETURNS TABLE(id bigint, body text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select c.id,c.body,c.created_at from public.article_anonymous_comments c
 where c.content_type=p_type and c.slug=p_slug and not c.hidden
 and exists(select 1 from public.homepage_public_articles('en',false) a where a.content_type=p_type and a.slug=p_slug)
 order by c.created_at desc,c.id desc limit 21 offset greatest(0,least(coalesce(p_offset,0),100000))
$$;



CREATE FUNCTION public.list_article_comments_v2(p_type text, p_slug text, p_offset integer DEFAULT 0) RETURNS TABLE(id bigint, body text, created_at timestamp with time zone, display_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select c.id,c.body,c.created_at,nullif(btrim(p.display_name),'') from public.article_anonymous_comments c left join public.reader_profiles p on p.user_id=c.reader_user_id
 where c.content_type=p_type and c.slug=p_slug and not c.hidden and exists(select 1 from public.homepage_public_articles('en',false) a where a.content_type=p_type and a.slug=p_slug)
 order by c.created_at desc,c.id desc limit 21 offset greatest(0,least(coalesce(p_offset,0),100000))
$$;



CREATE FUNCTION public.lock_ai_price_schedule() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin perform 1 from public.ai_price_schedules where id=new.schedule_id for update; return new; end $$;



CREATE FUNCTION public.lock_ai_provider_grant_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid;
begin
  if tg_table_name='ai_provider_title_grants' then
    select source_id into sid from public.source_policies where id=new.policy_id;
  else
    select p.source_id into sid from public.ai_provider_title_grants g join public.source_policies p on p.id=g.policy_id where g.id=new.grant_id;
  end if;
  perform 1 from public.sources where id=sid for update;
  if not found then raise exception 'provider grant source unavailable'; end if;
  return new;
end $$;



CREATE FUNCTION public.lock_candidate_sources(p_first uuid, p_second uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_first is null or p_second is null or p_first = p_second then raise exception 'two different articles required'; end if;
  perform s.id from public.sources s where s.id in
    (select a.source_id from public.articles a where a.id in (p_first, p_second)) order by s.id for update;
  if not public.candidate_title_allowed(p_first) or not public.candidate_title_allowed(p_second) then
    raise exception 'candidate title permission unavailable';
  end if;
end $$;



CREATE FUNCTION public.lock_classification_processing(p_article uuid, p_provider text, p_region text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare deadline timestamptz;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed required'; end if;
  perform s.id from public.sources s join public.articles a on a.source_id=s.id where a.id=p_article for update of s;
  select g.expires_at into deadline from public.articles a join lateral
    (select * from public.source_policies p where p.source_id=a.source_id order by version desc limit 1) p on true
    join public.classification_processing_grants g on g.policy_id=p.id and g.provider=p_provider and g.region=p_region
    where a.id=p_article and p.policy_status='approved' and p.title_storage_allowed and p.ai_processing_allowed and p.reviewed_by is not null
      and p.reviewed_at is not null and p.policy_evidence<>'{}'::jsonb and (p.permission_expires_at is null or p.permission_expires_at>clock_timestamp())
      and g.expires_at>clock_timestamp() and not exists(select 1 from public.classification_processing_revocations r where r.grant_id=g.id)
    order by g.expires_at desc limit 1;
  if deadline is null or deadline<=clock_timestamp() then raise exception 'classification processing permission unavailable'; end if;
  return deadline;
end $$;



CREATE FUNCTION public.lock_classification_scope(p_article uuid, p_provider text, p_region text, p_action text) RETURNS TABLE(policy_id uuid, provider_grant_id uuid, title_sha256 text, deadline timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if current_setting('transaction_isolation')<>'read committed' or p_action not in ('store','editor_display') then raise exception 'invalid classification scope'; end if;
  perform s.id from public.sources s join public.articles a on a.source_id=s.id where a.id=p_article for update of s;
  return query select p.id,tg.id,encode(sha256(convert_to(a.title,'UTF8')),'hex'),least(p.permission_expires_at,tg.expires_at,g.expires_at)
    from public.articles a join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by version desc limit 1) p on true
    join public.ai_provider_title_grants tg on tg.policy_id=p.id and tg.provider=p_provider and tg.processing_region=p_region
    join lateral (select x.expires_at from public.classification_grants x where x.policy_id=p.id and x.provider=p_provider and x.region=p_region
      and x.action=p_action and x.expires_at>clock_timestamp() and not exists(select 1 from public.classification_grant_revocations r where r.grant_id=x.id)
      order by x.expires_at desc limit 1) g on true
    where a.id=p_article and a.title is not null and length(trim(a.title))>0 and p.policy_status='approved' and p.title_storage_allowed
      and p.ai_processing_allowed and p.reviewed_by is not null and p.reviewed_at is not null and p.policy_evidence<>'{}'::jsonb
      and (p.permission_expires_at is null or p.permission_expires_at>clock_timestamp())
      and (tg.expires_at is null or tg.expires_at>clock_timestamp())
      and not exists(select 1 from public.ai_provider_title_revocations tr where tr.grant_id=tg.id);
  if not found then raise exception 'classification permission unavailable'; end if;
end $$;



CREATE FUNCTION public.lock_editorial_channel_rollout() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare active boolean;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed required'; end if;
  select enabled into active from public.editorial_channel_rollout_settings where singleton for share;
  return coalesce(active,true);
end $$;



CREATE FUNCTION public.lock_policy_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  perform 1 from public.sources where id = new.source_id for update;
  if not found then raise exception 'source not found'; end if;
  return new;
end $$;



CREATE FUNCTION public.lock_revision_sources(p_revision uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  perform s.id from public.sources s
  where exists (select 1 from public.articles a join public.claim_evidence e on e.article_id = a.id
    join public.claims c on c.id = e.claim_id where a.source_id = s.id and c.revision_id = p_revision)
  order by s.id for update;
end $$;



CREATE FUNCTION public.lock_revision_story() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  perform 1 from public.stories where id = new.story_id for update;
  return new;
end $$;



CREATE FUNCTION public.lock_summary_fact(p_fact uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed required'; end if;
  perform 1 from public.ai_verified_fact_retention_control where singleton and not restore_quarantine for share;
  if not found then raise exception 'verified fact unavailable'; end if;
  perform s.id from public.sources s where s.id in (select a.source_id from public.ai_verified_facts f
    join public.ai_request_preparation_inputs i on i.request_id=f.request_id join public.articles a on a.id=i.article_id where f.id=p_fact)
    order by s.id for update;
  perform a.id from public.articles a where a.id in (select i.article_id from public.ai_verified_facts f
    join public.ai_request_preparation_inputs i on i.request_id=f.request_id where f.id=p_fact) order by a.id for share;
  perform 1 from public.ai_verified_facts where id=p_fact for share;
  if not found then raise exception 'verified fact unavailable'; end if;
end $$;



CREATE FUNCTION public.lock_summary_processing(p_fact uuid, p_provider text, p_region text, p_request uuid DEFAULT NULL::uuid) RETURNS TABLE(article_id uuid, grant_id uuid, deadline timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare expected integer; matched integer; base_deadline timestamptz;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed required'; end if;
  perform public.lock_summary_fact(p_fact);
  base_deadline:=least(public.summary_scope_deadline(p_fact,p_provider,p_region,'store'),
                       public.summary_scope_deadline(p_fact,p_provider,p_region,'editor_display'));
  -- PostgreSQL least ignores null: check each permission explicitly.
  if public.summary_scope_deadline(p_fact,p_provider,p_region,'store') is null
     or public.summary_scope_deadline(p_fact,p_provider,p_region,'editor_display') is null
     or base_deadline<=clock_timestamp() then raise exception 'summary fact permission unavailable'; end if;
  select count(*) into expected from public.ai_request_preparation_inputs x
    join public.ai_verified_facts f on f.request_id=x.request_id where f.id=p_fact;
  select count(*) into matched from public.ai_request_preparation_inputs x
    join public.ai_verified_facts f on f.request_id=x.request_id
    join lateral (select g.id from public.summary_processing_grants g where g.policy_id=x.policy_id
      and g.provider=p_provider and g.region=p_region and g.expires_at>clock_timestamp()
      and not exists(select 1 from public.summary_processing_revocations r where r.grant_id=g.id)
      and (p_request is null or exists(select 1 from public.summary_request_processing_grants rg
        where rg.request_id=p_request and rg.article_id=x.article_id and rg.grant_id=g.id))
      order by g.expires_at desc,g.id limit 1) grant_row on true where f.id=p_fact;
  if expected not between 1 and 50 or matched<>expected or (p_request is not null and
    (select count(*) from public.summary_request_processing_grants rg where rg.request_id=p_request)<>expected)
    then raise exception 'summary processing permission unavailable'; end if;
  return query select x.article_id,g.id,least(base_deadline,g.expires_at)
    from public.ai_request_preparation_inputs x join public.ai_verified_facts f on f.request_id=x.request_id
    join lateral (select sg.id,sg.expires_at from public.summary_processing_grants sg where sg.policy_id=x.policy_id
      and sg.provider=p_provider and sg.region=p_region and sg.expires_at>clock_timestamp()
      and not exists(select 1 from public.summary_processing_revocations r where r.grant_id=sg.id)
      and (p_request is null or exists(select 1 from public.summary_request_processing_grants rg
        where rg.request_id=p_request and rg.article_id=x.article_id and rg.grant_id=sg.id))
      order by sg.expires_at desc,sg.id limit 1) g on true where f.id=p_fact order by x.article_id;
end $$;



CREATE FUNCTION public.log_ingestion_job_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op='INSERT' then
    insert into public.ingestion_job_events(job_id,source_id,previous_status,status,error_code,attempts)
      values(new.id,new.source_id,null,new.status,new.last_error_code,new.attempts);
  elsif new.status is distinct from old.status then
    insert into public.ingestion_job_events(job_id,source_id,previous_status,status,error_code,attempts)
      values(new.id,new.source_id,old.status,new.status,new.last_error_code,new.attempts);
  end if;
  return new;
end $$;



CREATE FUNCTION public.manual_check_revision_embeds() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare node jsonb; src text;
begin
 for node in select jsonb_path_query(new.zh_document,'$.** ? (@.type == "youtube")') union all select jsonb_path_query(new.en_document,'$.** ? (@.type == "youtube")') loop
  src:=node->'attrs'->>'src';
  if not exists(select 1 from public.manual_video_embeds e where e.owner_id=auth.uid() and e.url=src) then raise exception 'video embed permission not registered'; end if;
 end loop;
 return new;
end $_$;



CREATE FUNCTION public.manual_check_revision_media() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare node jsonb; media_id uuid; expected text;
begin
 for node in select jsonb_path_query(new.zh_document,'$.** ? (@.type == "image" || @.type == "manualVideo")')
             union all select jsonb_path_query(new.en_document,'$.** ? (@.type == "image" || @.type == "manualVideo")') loop
  begin media_id:=substring(node->'attrs'->>'src' from '/api/manual-media/([0-9a-f-]{36})')::uuid; exception when others then raise exception 'invalid manual media'; end;
  expected:=case when node->>'type'='image' then 'image' else 'video' end;
  if media_id is null or not exists(select 1 from public.manual_media_assets m where m.id=media_id and m.owner_id=auth.uid() and m.media_kind=expected) then raise exception 'manual media not registered to owner'; end if;
 end loop;
 return new;
end $_$;



CREATE FUNCTION public.manual_document_node_safe(p_node jsonb, p_depth integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare t text; child jsonb; mark jsonb; href text; a jsonb;
begin
 if p_depth>16 or jsonb_typeof(p_node)<>'object' or exists(select 1 from jsonb_object_keys(p_node) k where k not in ('type','text','attrs','marks','content')) then return false; end if;
 t:=p_node->>'type';
 if t is null or t not in ('doc','paragraph','text','heading','blockquote','bulletList','orderedList','listItem','codeBlock','hardBreak','horizontalRule','table','tableRow','tableCell','tableHeader','image','youtube','manualVideo') then return false; end if;
 if p_node ? 'text' and (t<>'text' or jsonb_typeof(p_node->'text')<>'string' or length(p_node->>'text')>20000) then return false; end if;
 if t='text' and (not p_node ? 'text' or p_node ? 'content') then return false; end if;
 if p_node ? 'attrs' then
  a:=p_node->'attrs'; if jsonb_typeof(a)<>'object' then return false; end if;
  if t='heading' and (coalesce(a->>'level','') not in ('1','2','3','4')) then return false; end if;
  if t='image' and (coalesce(a->>'src','') !~ '^/api/manual-media/[0-9a-f-]{36}$' or length(coalesce(a->>'alt',''))>500) then return false; end if;
  if t='manualVideo' and coalesce(a->>'src','') !~ '^/api/manual-media/[0-9a-f-]{36}$' then return false; end if;
  if t='youtube' and coalesce(a->>'src','') !~ '^https://(www[.])?(youtube[.]com/(watch[?]v=|embed/)|youtu[.]be/)[A-Za-z0-9_-]{11}([&?][A-Za-z0-9_=&%-]*)?$' then return false; end if;
 end if;
 if t in ('image','youtube','manualVideo','heading') and not p_node ? 'attrs' then return false; end if;
 if p_node ? 'marks' then
  if t<>'text' or jsonb_typeof(p_node->'marks')<>'array' or jsonb_array_length(p_node->'marks')>8 then return false; end if;
  for mark in select value from jsonb_array_elements(p_node->'marks') loop
   if jsonb_typeof(mark)<>'object' or mark->>'type' not in ('bold','italic','strike','code','underline','link') then return false; end if;
   if mark->>'type'='link' then href:=mark->'attrs'->>'href'; if href is null or length(href)>2048 or href !~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$' then return false; end if; end if;
  end loop;
 end if;
 if p_node ? 'content' then
  if jsonb_typeof(p_node->'content')<>'array' or jsonb_array_length(p_node->'content')>1000 then return false; end if;
  for child in select value from jsonb_array_elements(p_node->'content') loop if not public.manual_document_node_safe(child,p_depth+1) then return false; end if; end loop;
 end if;
 return true;
exception when others then return false;
end $_$;



CREATE FUNCTION public.manual_document_safe(p_doc jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select coalesce(p_doc->>'type'='doc' and octet_length(p_doc::text)<=300000 and public.manual_document_node_safe(p_doc,0),false)
$$;



CREATE FUNCTION public.manual_get_article(p_article uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return (select jsonb_build_object('id',a.id,'slug',a.slug,'status',a.status,'revision_id',r.id,'zh_title',r.zh_title,'en_title',r.en_title,'zh_summary',r.zh_summary,'en_summary',r.en_summary,'zh_document',r.zh_document,'en_document',r.en_document,'primary_channel',r.primary_channel,'related_channels',r.related_channels,'tags',r.tags,'source_links',r.source_links) from public.manual_articles a join public.manual_article_revisions r on r.id=a.current_revision_id where a.id=p_article and a.owner_id=auth.uid());
end $$;



CREATE FUNCTION public.manual_get_article_with_topics(p_article uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare result jsonb;
begin
 result:=public.manual_get_article(p_article);
 if result is null then return null; end if;
 return result || jsonb_build_object(
  'topics',coalesce((select jsonb_agg(t.topic order by t.topic) from public.manual_revision_topics t where t.revision_id=(result->>'revision_id')::uuid),'[]'::jsonb),
  'editor_score',coalesce(
   (select a.draft_score from public.manual_articles a where a.id=p_article),
   (select e.final_score from public.manual_publication_events e where e.article_id=p_article and e.action in ('publish','update','correction') order by e.event_order desc limit 1)
  )
 );
end $$;



CREATE FUNCTION public.manual_get_media(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return (select jsonb_build_object('path',m.object_path,'kind',m.media_kind,'mime',m.mime_type,'bytes',m.byte_size) from public.manual_media_assets m where m.id=p_id and m.owner_id=auth.uid());
end $$;



CREATE FUNCTION public.manual_is_owner() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
 select public.is_active_editor() and exists(select 1 from public.manual_editor_owners o where o.user_id=auth.uid() and o.enabled)
$$;



CREATE FUNCTION public.manual_list_articles() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'slug',a.slug,'status',a.status,'revision_id',a.current_revision_id,'updated_at',a.updated_at,'zh_title',r.zh_title,'en_title',r.en_title) order by a.updated_at desc)
  from public.manual_articles a left join public.manual_article_revisions r on r.id=a.current_revision_id where a.owner_id=auth.uid()),'[]'::jsonb);
end $$;



CREATE FUNCTION public.manual_list_media() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'kind',m.media_kind,'mime',m.mime_type,'bytes',m.byte_size,'created_at',m.created_at) order by m.created_at desc) from public.manual_media_assets m where m.owner_id=auth.uid()),'[]'::jsonb);
end $$;



CREATE FUNCTION public.manual_public_media_path_allowed(p_path text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select exists(select 1 from public.manual_media_assets m where m.object_path=p_path and public.get_public_manual_media(m.id) is not null)
$$;



CREATE FUNCTION public.manual_publish_article(p_article uuid, p_revision uuid, p_score integer, p_kind text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare a public.manual_articles%rowtype; r public.manual_article_revisions%rowtype; result uuid;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed required'; end if;
 if p_score is null or p_score not between 0 and 100 or p_kind is null or p_kind not in ('publish','update','correction') or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'invalid manual publication'; end if;
 select * into a from public.manual_articles where id=p_article and owner_id=auth.uid() for update;
 if a.id is null or a.current_revision_id is distinct from p_revision then raise exception 'manual revision conflict'; end if;
 if (a.status in ('draft','retracted') and p_kind<>'publish') or (a.status='published' and p_kind not in ('update','correction')) then raise exception 'invalid manual publication state'; end if;
 select * into r from public.manual_article_revisions where id=p_revision and article_id=a.id;
 if not exists(select 1 from jsonb_path_query(r.zh_document,'$.** ? (@.type == "text")') n where length(trim(n->>'text'))>0)
  or not exists(select 1 from jsonb_path_query(r.en_document,'$.** ? (@.type == "text")') n where length(trim(n->>'text'))>0) then raise exception 'both language bodies required'; end if;
 insert into public.manual_publication_events(article_id,revision_id,final_score,action,reason,actor_id)
 values(a.id,r.id,p_score,p_kind,trim(p_reason),auth.uid()) returning id into result;
 update public.manual_articles set status='published',published_revision_id=r.id,draft_score=null,updated_at=clock_timestamp() where id=a.id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'manual_'||p_kind,'manual_article',a.id,trim(p_reason));
 return result;
end $_$;



CREATE FUNCTION public.manual_register_media(p_id uuid, p_path text, p_kind text, p_rights text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if p_kind is distinct from 'image' then raise exception 'only image uploads are supported'; end if;
 return public.manual_register_media_before_images_only(p_id,p_path,p_kind,p_rights);
end $$;



CREATE FUNCTION public.manual_register_media_before_images_only(p_id uuid, p_path text, p_kind text, p_rights text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare metadata jsonb; object_owner text; mime text; size bigint;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if p_id is null or p_kind not in ('image','video') or p_path is null or p_path<>auth.uid()::text||'/'||p_id::text
  or p_rights is null or length(trim(p_rights)) not between 8 and 1000 then raise exception 'invalid media registration'; end if;
 if to_regclass('storage.objects') is null then raise exception 'media storage unavailable'; end if;
 execute 'select metadata,owner_id from storage.objects where bucket_id=$1 and name=$2' into metadata,object_owner using 'manual-media',p_path;
 if metadata is null or object_owner is distinct from auth.uid()::text then raise exception 'uploaded media unavailable'; end if;
 mime:=metadata->>'mimetype'; begin size:=(metadata->>'size')::bigint; exception when others then raise exception 'invalid media metadata'; end;
 if size is null or size not between 1 and 52428800 or mime is null
  or (p_kind='image' and mime not in ('image/jpeg','image/png','image/webp','image/gif'))
  or (p_kind='video' and mime not in ('video/mp4','video/webm')) then raise exception 'media type or size not permitted'; end if;
 insert into public.manual_media_assets(id,owner_id,object_path,media_kind,mime_type,byte_size,rights_note)
 values(p_id,auth.uid(),p_path,p_kind,mime,size,trim(p_rights));
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'register_manual_media','manual_media',p_id,'Owner supplied media and rights attestation');
 return p_id;
end $_$;



CREATE FUNCTION public.manual_register_video_embed(p_url text, p_rights text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $_$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if p_url is null or p_url !~ '^https://www[.]youtube[.]com/watch[?]v=[A-Za-z0-9_-]{11}$' or p_rights is null or length(trim(p_rights)) not between 8 and 1000 then raise exception 'invalid video permission'; end if;
 insert into public.manual_video_embeds(owner_id,url,rights_note) values(auth.uid(),p_url,trim(p_rights)) on conflict do nothing;
 if not found then return false; end if;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'register_manual_video_embed','manual_video_embed',gen_random_uuid(),'Owner attested permitted external video');
 return true;
end $_$;



CREATE FUNCTION public.manual_reject_video_nodes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
begin
 if jsonb_path_exists(new.zh_document,'$.** ? (@.type == "manualVideo" || @.type == "youtube")') or
    jsonb_path_exists(new.en_document,'$.** ? (@.type == "manualVideo" || @.type == "youtube")')
 then raise exception 'video must be a hyperlink'; end if;
 return new;
end $_$;



CREATE FUNCTION public.manual_retract_article(p_article uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare a public.manual_articles%rowtype; result uuid;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'retraction reason required'; end if;
 select * into a from public.manual_articles where id=p_article and owner_id=auth.uid() for update;
 if a.id is null or a.status<>'published' or a.published_revision_id is null then raise exception 'published manual article required'; end if;
 insert into public.manual_publication_events(article_id,revision_id,action,reason,actor_id) values(a.id,a.published_revision_id,'retract',trim(p_reason),auth.uid()) returning id into result;
 update public.manual_articles set status='retracted',updated_at=clock_timestamp() where id=a.id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'manual_retract','manual_article',a.id,trim(p_reason));return result;
end $$;



CREATE FUNCTION public.manual_save_article(p_article uuid, p_expected_revision uuid, p_slug text, p_zh_title text, p_en_title text, p_zh_summary text, p_en_summary text, p_zh_document jsonb, p_en_document jsonb, p_primary text, p_related text[], p_tags text[], p_sources jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare article public.manual_articles%rowtype; rid uuid; n integer; item jsonb;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed required'; end if;
 if p_slug is null or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or length(p_slug)>160 or not public.manual_document_safe(p_zh_document) or not public.manual_document_safe(p_en_document)
  or p_related is null or cardinality(p_related)>5 or p_primary=any(p_related) or p_primary not in ('ai','robotics','industry','technology','internet','products')
  or exists(select 1 from unnest(p_related) x where x is null or x not in ('ai','robotics','industry','technology','internet','products'))
  or (select count(distinct x) from unnest(p_related) x)<>cardinality(p_related) or p_tags is null or cardinality(p_tags)>20
  or exists(select 1 from unnest(p_tags) x where x is null or length(trim(x)) not between 1 and 50)
  or p_sources is null or jsonb_typeof(p_sources)<>'array' or jsonb_array_length(p_sources)>30 then raise exception 'invalid manual article'; end if;
 for item in select value from jsonb_array_elements(p_sources) loop
  if jsonb_typeof(item)<>'object' or coalesce(item->>'url','') !~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$' or length(coalesce(item->>'label',''))>300 then raise exception 'invalid source link'; end if;
 end loop;
 if p_article is null then
  if p_expected_revision is not null then raise exception 'new draft cannot have parent'; end if;
  insert into public.manual_articles(slug,owner_id) values(p_slug,auth.uid()) returning * into article;
 else
  select * into article from public.manual_articles where id=p_article for update;
  if article.id is null or article.owner_id<>auth.uid() then raise exception 'manual article unavailable'; end if;
  if article.current_revision_id is distinct from p_expected_revision then raise exception 'manual revision conflict'; end if;
  if article.slug<>p_slug then raise exception 'manual slug cannot change'; end if;
 end if;
 select coalesce(max(revision_number),0)+1 into n from public.manual_article_revisions where article_id=article.id;
 insert into public.manual_article_revisions(article_id,revision_number,zh_title,en_title,zh_summary,en_summary,zh_document,en_document,primary_channel,related_channels,tags,source_links,created_by)
 values(article.id,n,trim(p_zh_title),trim(p_en_title),trim(p_zh_summary),trim(p_en_summary),p_zh_document,p_en_document,p_primary,p_related,p_tags,p_sources,auth.uid()) returning id into rid;
 update public.manual_articles set current_revision_id=rid,updated_at=clock_timestamp() where id=article.id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'save_manual_draft','manual_article',article.id,'Owner-authored bilingual draft; not automatically published');
 return jsonb_build_object('article_id',article.id,'revision_id',rid,'revision_number',n,'status',article.status);
end $_$;



CREATE FUNCTION public.manual_save_article_with_topics(p_article uuid, p_expected_revision uuid, p_slug text, p_zh_title text, p_en_title text, p_zh_summary text, p_en_summary text, p_zh_document jsonb, p_en_document jsonb, p_primary text, p_related text[], p_tags text[], p_sources jsonb, p_topics text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare result jsonb; topic text;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if p_topics is null or cardinality(p_topics)<1 or cardinality(p_topics)>20
 or (select count(distinct t) from unnest(p_topics) t)<>cardinality(p_topics)
 or exists(select 1 from unnest(p_topics) t where t is null or not exists(select 1 from public.manual_editor_topics x where x.channel=p_primary and x.topic=t))
 then raise exception 'invalid article topics'; end if;
 result:=public.manual_save_article(p_article,p_expected_revision,p_slug,p_zh_title,p_en_title,p_zh_summary,p_en_summary,p_zh_document,p_en_document,p_primary,p_related,p_tags,p_sources);
 foreach topic in array p_topics loop insert into public.manual_revision_topics values((result->>'revision_id')::uuid,p_primary,topic); end loop;
 return result;
end $$;



CREATE FUNCTION public.manual_save_editor_revision(p_article uuid, p_expected_revision uuid, p_slug text, p_zh_title text, p_en_title text, p_zh_summary text, p_en_summary text, p_zh_document jsonb, p_en_document jsonb, p_primary text, p_related text[], p_tags text[], p_sources jsonb, p_topics text[], p_score integer, p_operation text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare result jsonb; article_id uuid; revision_id uuid; sources jsonb; publication_id uuid;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if jsonb_typeof(p_sources) is distinct from 'array' or jsonb_array_length(p_sources)>30 then
  raise exception 'invalid source links';
 end if;
 if p_operation is null or p_operation not in ('save','publish','correction')
  or (p_score is not null and p_score not between 0 and 100)
  or (p_operation<>'save' and p_score is null) then raise exception 'invalid manual publication'; end if;
 -- Keep existing source labels when the editor leaves their URLs in place.
 select coalesce(jsonb_agg(
  incoming.item || jsonb_build_object('label',coalesce(previous.item->>'label',incoming.item->>'label',''))
  order by incoming.position),'[]'::jsonb) into sources
 from jsonb_array_elements(p_sources) with ordinality incoming(item,position)
 left join lateral (
  select old.item from public.manual_article_revisions r
  cross join lateral jsonb_array_elements(r.source_links) old(item)
  where r.id=p_expected_revision and r.article_id=p_article and old.item->>'url'=incoming.item->>'url'
  limit 1
 ) previous on true;
 result:=public.manual_save_article_with_topics(p_article,p_expected_revision,p_slug,p_zh_title,p_en_title,
  p_zh_summary,p_en_summary,p_zh_document,p_en_document,p_primary,p_related,p_tags,sources,p_topics);
 article_id:=(result->>'article_id')::uuid;
 revision_id:=(result->>'revision_id')::uuid;
 if p_operation='save' then
  update public.manual_articles set draft_score=p_score where id=article_id;
  return result;
 end if;
 publication_id:=public.manual_publish_article(article_id,revision_id,p_score,p_operation,p_reason);
 return result || jsonb_build_object('publication_id',publication_id);
end $$;



CREATE FUNCTION public.owner_article_index_stats() RETURNS TABLE(content_type text, slug text, base_score integer, clicks bigint, score integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return query select 'manual'::text,a.slug,e.final_score,coalesce(c.total,0),public.index_score('manual',a.slug,e.final_score)
 from public.manual_articles a join lateral (select ev.* from public.manual_publication_events ev where ev.article_id=a.id order by ev.event_order desc limit 1) e on e.revision_id=a.published_revision_id and e.action in ('publish','update','correction')
 left join public.article_index_clicks c on c.content_type='manual' and c.slug=a.slug where a.status='published'
 union all
 select 'story'::text,s.slug,sc.holy_shit_score,coalesce(c.total,0),public.index_score('story',s.slug,sc.holy_shit_score)
 from public.stories s left join public.revision_discovery d on d.revision_id=s.public_revision_id
 left join public.story_scores sc on sc.id=d.score_id and sc.story_id=s.id and sc.revision_id=s.public_revision_id
 left join public.article_index_clicks c on c.content_type='story' and c.slug=s.slug
 where exists(select 1 from public.homepage_public_articles('en',false) a where a.content_type='story' and a.slug=s.slug);
end $$;



CREATE FUNCTION public.owner_article_reaction_stats() RETURNS TABLE(content_type text, slug text, base_score integer, clicks bigint, dislikes bigint, shit bigint, score integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select s.content_type,s.slug,s.base_score,s.clicks,coalesce(c.dislikes,0),coalesce(c.shit,0),s.score
 from public.owner_article_index_stats() s left join public.article_index_clicks c on c.content_type=s.content_type and c.slug=s.slug
$$;



CREATE FUNCTION public.owner_article_read_stats() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return (select coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) from (
  select content_type,slug,count(*) reads from public.homepage_article_views
  where view_day between (statement_timestamp() at time zone 'UTC')::date-29 and (statement_timestamp() at time zone 'UTC')::date
  group by content_type,slug
 ) s);
end $$;



