    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return (select jsonb_build_object('bot_id',bot_id,'sources',source_publications,'created_at',created_at,'suggested_score',suggested_score)
  from public.duty_editor_submissions where article_id=p_article);
end $$;



