CREATE FUNCTION public.owner_hide_anonymous_comment(p_id bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 update public.article_anonymous_comments set hidden=true where id=p_id and not hidden;
 return found;
end $$;



CREATE FUNCTION public.owner_list_anonymous_comments(p_offset integer DEFAULT 0) RETURNS TABLE(id bigint, content_type text, slug text, body text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return query select c.id,c.content_type,c.slug,c.body,c.created_at from public.article_anonymous_comments c where not c.hidden order by c.created_at desc,c.id desc limit 21 offset greatest(0,least(coalesce(p_offset,0),100000));
end $$;



CREATE FUNCTION public.owner_list_duty_drafts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object(
  'article_id',a.id,'bot_id',s.bot_id,'zh_title',r.zh_title,'en_title',r.en_title,
  'channel',r.primary_channel,'topics',coalesce((select jsonb_agg(t.topic order by t.topic) from public.manual_revision_topics t where t.revision_id=r.id),'[]'::jsonb),
  'suggested_score',s.suggested_score,'created_at',s.created_at) order by s.created_at desc)
  from public.duty_editor_submissions s join public.manual_articles a on a.id=s.article_id
  join public.manual_article_revisions r on r.id=a.current_revision_id
  where a.owner_id=auth.uid() and a.status='draft'),'[]'::jsonb);
end $$;



CREATE FUNCTION public.owner_list_duty_identities() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('bot_id',bot_id,'enabled',enabled,'updated_at',updated_at) order by bot_id) from public.duty_editor_identities),'[]'::jsonb);
end $$;



CREATE FUNCTION public.owner_list_readers(p_search text DEFAULT ''::text, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if length(coalesce(p_search,''))>120 then raise exception 'search too long'; end if;
 return coalesce((select jsonb_agg(to_jsonb(q) order by q.created_at desc,q.id) from (
  select u.id,u.email,u.created_at,u.last_sign_in_at,u.email_confirmed_at,u.banned_until,count(*) over() total,coalesce(p.display_name,'') display_name,
   coalesce(p.newsletter_opt_in,false) newsletter_opt_in,coalesce(p.history_opt_in,false) history_opt_in,
   (select count(*) from public.reader_bookmarks b where b.user_id=u.id) bookmarks,
   (select count(*) from public.article_anonymous_comments c where c.reader_user_id=u.id and not c.hidden) comments
  from auth.users u left join public.reader_profiles p on p.user_id=u.id
  where u.deleted_at is null and u.email is not null
   and not exists(select 1 from public.editors e where e.user_id=u.id)
   and not exists(select 1 from public.manual_editor_owners o where o.user_id=u.id)
   and not exists(select 1 from public.site_team_roles t where t.user_id=u.id)
   and (coalesce(p_search,'')='' or position(lower(p_search) in lower(u.email))>0 or position(lower(p_search) in lower(coalesce(p.display_name,'')))>0)
  order by u.created_at desc,u.id limit 21 offset greatest(0,least(coalesce(p_offset,0),100000))
 ) q),'[]'::jsonb);
end $$;



CREATE FUNCTION public.owner_list_team() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('email',u.email,'user_id',u.id,'roles',t.roles,'active',e.active) order by u.email)
 from (select user_id,array_agg(role order by role) roles from public.site_team_roles group by user_id) t
 join auth.users u on u.id=t.user_id join public.editors e on e.user_id=t.user_id),'[]'::jsonb);
end $$;



CREATE FUNCTION public.owner_manage_duty_identity(p_bot text, p_hash text, p_enabled boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $_$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if p_bot is null or p_bot !~ '^[a-z0-9][a-z0-9_-]{0,63}$' or p_enabled is null then raise exception 'invalid identity'; end if;
 if p_enabled then
  if p_hash is null or p_hash !~ '^[0-9a-f]{64}$' then raise exception 'invalid credential hash'; end if;
  insert into public.duty_editor_identities(bot_id,secret_hash,enabled) values(p_bot,p_hash,true)
  on conflict(bot_id) do update set secret_hash=excluded.secret_hash,enabled=true,updated_at=clock_timestamp();
 else
  update public.duty_editor_identities set enabled=false,updated_at=clock_timestamp() where bot_id=p_bot;
  if not found then raise exception 'identity unavailable'; end if;
 end if;
 return true;
end $_$;



CREATE FUNCTION public.owner_reader_target_allowed(p_user uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 return exists(select 1 from auth.users u where u.id=p_user and u.deleted_at is null)
  and not exists(select 1 from public.editors e where e.user_id=p_user)
  and not exists(select 1 from public.manual_editor_owners o where o.user_id=p_user)
  and not exists(select 1 from public.site_team_roles t where t.user_id=p_user);
end $$;



CREATE FUNCTION public.owner_save_robot_prompt(p_robot text, p_prompt text, p_expected_version integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare latest integer;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if p_robot is null or p_robot not in ('selection','editor') or p_prompt is null or length(trim(p_prompt)) not between 1 and 60000 then raise exception 'invalid robot prompt'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_robot,921));
 select max(version) into latest from public.robot_prompt_versions where robot=p_robot;
 if latest is distinct from p_expected_version then raise exception 'robot prompt changed; refresh'; end if;
 insert into public.robot_prompt_versions(robot,prompt,version,updated_by) values(p_robot,p_prompt,latest+1,auth.uid());
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'update_robot_prompt','user',auth.uid(),p_robot||' prompt version '||(latest+1));
 return latest+1;
end $$;



CREATE FUNCTION public.owner_set_article_visibility(p_article uuid, p_published boolean, p_expected_status text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare a public.manual_articles%rowtype; previous_score integer; target text;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if p_published is null or p_expected_status is null or p_expected_status not in ('published','retracted') then raise exception 'invalid visibility request'; end if;
 select * into a from public.manual_articles where id=p_article and owner_id=auth.uid() for update;
 if a.id is null or a.status not in ('published','retracted') or a.published_revision_id is null then raise exception 'previously published article required'; end if;
 target:=case when p_published then 'published' else 'retracted' end;
 if a.status=target then return target; end if;
 if a.status<>p_expected_status then raise exception 'article status changed'; end if;
 if not p_published then
  perform public.manual_retract_article(a.id,'站长在文章列表一键下线');
 else
  select e.final_score into previous_score from public.manual_publication_events e
   where e.article_id=a.id and e.revision_id=a.published_revision_id and e.action in ('publish','update','correction')
   order by e.event_order desc limit 1;
  if previous_score is null then raise exception 'previous publication score unavailable'; end if;
  insert into public.manual_publication_events(article_id,revision_id,final_score,action,reason,actor_id)
   values(a.id,a.published_revision_id,previous_score,'publish','站长在文章列表恢复上次已发布版本',auth.uid());
  update public.manual_articles set status='published',updated_at=clock_timestamp() where id=a.id;
  insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
   values(auth.uid(),'manual_publish','manual_article',a.id,'站长在文章列表恢复上次已发布版本');
 end if;
 return target;
end $$;



CREATE FUNCTION public.owner_set_homepage_control(p_type text, p_slug text, p_mode text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare target uuid;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if p_type is null or p_slug is null or p_type not in ('manual','story') or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or length(p_slug)>200 or p_mode is null or p_mode not in ('pin','exclude','auto') then raise exception 'invalid homepage control'; end if;
 if p_mode='auto' then delete from public.homepage_article_controls where content_type=p_type and slug=p_slug;
 else
  if not exists(select 1 from public.homepage_public_articles('en',false) a where a.slug=p_slug and a.content_type=p_type) then raise exception 'published article required'; end if;
  insert into public.homepage_article_controls(content_type,slug,mode,updated_by) values(p_type,p_slug,p_mode,auth.uid())
  on conflict(content_type,slug) do update set mode=excluded.mode,updated_by=excluded.updated_by,updated_at=clock_timestamp();
 end if;
 select case when p_type='manual' then (select id from public.manual_articles where slug=p_slug) else (select id from public.stories where slug=p_slug) end into target;
 if target is null then raise exception 'article unavailable'; end if;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason) values(auth.uid(),'homepage_'||p_mode,'homepage_article',target,p_type||':'||p_slug);
end $_$;



CREATE FUNCTION public.owner_set_signal_growth_threshold(p_threshold numeric) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if p_threshold is null or p_threshold<=0 or p_threshold>=1000000000 then raise exception 'invalid growth threshold'; end if;
 update public.signal_detection_config set growth_points_per_hour=p_threshold where singleton;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
 values(auth.uid(),'set_signal_growth_threshold','user',auth.uid(),'points per hour: '||p_threshold::text);
 return p_threshold;
end $$;



CREATE FUNCTION public.owner_set_team_role(p_email text, p_role text, p_enabled boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
declare target uuid; matches uuid[]; changed boolean;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if p_email is null or length(trim(p_email)) not between 3 and 320 or p_role is null or p_role not in ('website_editor','reviewer') or p_enabled is null then raise exception 'invalid team role'; end if;
 select array_agg(id) into matches from auth.users where lower(email)=lower(trim(p_email)) and deleted_at is null and (banned_until is null or banned_until<=now());
 if coalesce(array_length(matches,1),0)<>1 then raise exception 'account not found or ambiguous'; end if;
 target:=matches[1];
 if exists(select 1 from public.manual_editor_owners where user_id=target and enabled) then raise exception 'owner roles cannot be changed here'; end if;
 perform pg_advisory_xact_lock(hashtextextended(target::text,197));
 if p_enabled then
  insert into public.site_team_roles(user_id,role,granted_by) values(target,p_role,auth.uid()) on conflict do nothing;
  changed:=found;
  insert into public.editors(user_id,active,can_review_sources,can_manage_ai_budget) values(target,true,false,false) on conflict(user_id) do update set active=true,can_review_sources=false,can_manage_ai_budget=false;
 else
  delete from public.site_team_roles where user_id=target and role=p_role;
  changed:=found;
  if changed and not exists(select 1 from public.site_team_roles where user_id=target) then update public.editors set active=false where user_id=target; end if;
 end if;
 if changed then insert into public.audit_logs(actor_id,action,resource_type,resource_id,reason)
  values(auth.uid(),case when p_enabled then 'grant_team_role' else 'revoke_team_role' end,'editor',target,p_role); end if;
 return changed;
end $$;



CREATE FUNCTION public.owner_traffic_analytics(p_period text DEFAULT '7d'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare first_day date;last_day date;report jsonb;today date:=(statement_timestamp() at time zone 'Asia/Shanghai')::date;
begin
 if public.manual_is_owner() is distinct from true then raise exception 'site owner access required'; end if;
 if p_period is null or p_period not in ('today','yesterday','7d','30d') then raise exception 'invalid analytics period'; end if;
 last_day:=case when p_period='yesterday' then today-1 else today end;
 first_day:=case p_period when '7d' then today-6 when '30d' then today-29 else last_day end;
 with visits as materialized (
  select *, (visited_at at time zone 'Asia/Shanghai')::date as bucket_day from public.site_page_visits
  where visited_at>=first_day::timestamp at time zone 'Asia/Shanghai'
   and visited_at<(last_day+1)::timestamp at time zone 'Asia/Shanghai'
   and visited_at>=statement_timestamp()-interval '30 days'
 ), sessions as (
  select session_hash,min(visitor_hash) visitor_hash,count(*) views,sum(engagement_seconds) seconds,
   (array_agg(referrer_host order by visited_at,event_id))[1] referrer,
   (array_agg(path order by visited_at,event_id))[1] entry,
   (array_agg(path order by visited_at desc,event_id desc))[1] exit
  from visits group by session_hash
 ), days as (
  select d::date as bucket_day from generate_series(first_day::timestamp,last_day::timestamp,interval '1 day') d
 ), breakdowns as (
  select key,label,count(*) views,count(distinct visitor_hash) visitors
  from visits v cross join lateral (values
   ('devices',v.device),('browsers',v.browser),('systems',v.os),('countries',v.country),('languages',v.locale),('pages',v.path)
  ) b(key,label) group by key,label
  union all select 'referrers',case when referrer='' then 'direct' else referrer end,sum(views),count(distinct visitor_hash) from sessions group by referrer
  union all select 'channels',case when referrer='' then 'direct' when referrer ~ '(^|\.)(google\.[a-z.]+|bing\.com|baidu\.com|duckduckgo\.com|yahoo\.com|yandex\.ru)$' then 'search' when referrer ~ '(^|\.)(x\.com|twitter\.com|t\.co|facebook\.com|instagram\.com|reddit\.com|youtube\.com|weibo\.com|zhihu\.com|bilibili\.com|tiktok\.com|threads\.net)$' then 'social' else 'referral' end,sum(views),count(distinct visitor_hash) from sessions group by 2
 ), ranked as (select *,row_number() over(partition by key order by views desc,label) pos from breakdowns),
 hourly as (select extract(hour from visited_at at time zone 'Asia/Shanghai')::integer as hour_bucket,count(*) views from visits group by 1)
 select jsonb_build_object(
  'as_of',statement_timestamp(),'started_at',(select started_at from public.site_analytics_rollout where singleton),'period',p_period,'first_day',first_day,'last_day',last_day,
  'totals',jsonb_build_object('views',(select count(*) from visits),'visitors',(select count(distinct visitor_hash) from visits),
   'sessions',(select count(*) from sessions),'engaged_sessions',(select count(*) from sessions where seconds>=10 or views>=2),
   'engagement_seconds',coalesce((select sum(seconds) from sessions),0)),
  'recent_visitors',(select count(distinct visitor_hash) from public.site_page_visits where visited_at>=statement_timestamp()-interval '5 minutes'),
  'daily',(select jsonb_agg(jsonb_build_object('day',d.bucket_day,'views',coalesce(v.views,0),'visitors',coalesce(v.visitors,0)) order by d.bucket_day) from days d left join (
   select bucket_day,count(*) views,count(distinct visitor_hash) visitors from visits group by bucket_day
  ) v using(bucket_day)),
  'hourly',(select jsonb_agg(jsonb_build_object('hour',h,'views',coalesce(v.views,0)) order by h) from generate_series(0,23) h left join hourly v on v.hour_bucket=h),
  'breakdowns',coalesce((select jsonb_object_agg(key,items) from (
   select key,jsonb_agg(jsonb_build_object('label',label,'views',views,'visitors',visitors) order by views desc,label) items from ranked where pos<=20 group by key
  ) g),'{}'::jsonb),
  'entry_pages',coalesce((select jsonb_agg(to_jsonb(s)) from (select entry path,count(*) sessions from sessions group by entry order by sessions desc,entry limit 10) s),'[]'::jsonb),
  'exit_pages',coalesce((select jsonb_agg(to_jsonb(s)) from (select exit path,count(*) sessions from sessions group by exit order by sessions desc,exit limit 10) s),'[]'::jsonb)
 ) into report;
 return report;
end $_$;



CREATE FUNCTION public.prepare_bilingual_retraction_internal(p_story uuid, p_version integer, p_zh text, p_en text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare nid uuid; bilingual boolean;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_zh is null or length(trim(p_zh)) not between 1 and 4000 or p_en is null or length(trim(p_en)) not between 1 and 4000
    then raise exception 'both language notices required'; end if;
  select published_bilingual_batch_id is not null into bilingual from public.stories where id=p_story and version=p_version and visibility='public' for update;
  if not coalesce(bilingual,false) then raise exception 'public bilingual story required'; end if;
  nid := public.prepare_retraction(p_story,p_version,trim(p_en));
  insert into public.bilingual_retraction_notices(notice_id,zh) values(nid,trim(p_zh));
  return nid;
end $$;



CREATE FUNCTION public.prepare_retraction(p_story uuid, p_expected_version integer, p_notice text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare rid uuid; nid uuid;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_notice is null or length(trim(p_notice)) = 0 then raise exception 'notice required'; end if;
  select public_revision_id into rid from public.stories where id = p_story and version = p_expected_version and visibility = 'public' for update;
  if rid is null then raise exception 'story version conflict or not public'; end if;
  insert into public.retraction_notices(story_id, revision_id, notice, created_by) values(p_story, rid, p_notice, auth.uid()) returning id into nid;
  return nid;
end $$;



CREATE FUNCTION public.prevent_retracted_republish() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.visibility = 'public' and exists (select 1 from public.publication_events
    where story_id = new.id and revision_id = new.public_revision_id and action = 'retract') then
    raise exception 'retracted revision cannot be republished';
  end if;
  return new;
end $$;



CREATE FUNCTION public.prevent_syndication_cycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.syndicated_from_article_id is null then return new; end if;
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'read committed isolation required';
  end if;
  perform 1 from public.stories where id = new.story_id for update;
  if exists (
    with recursive origins(article_id) as (
      select new.syndicated_from_article_id
      union
      select sa.syndicated_from_article_id
      from public.story_articles sa join origins o on sa.article_id = o.article_id
      where sa.story_id = new.story_id and sa.syndicated_from_article_id is not null
    ) select 1 from origins where article_id = new.article_id
  ) then raise exception 'syndication cycle'; end if;
  return new;
end $$;



CREATE FUNCTION public.protect_candidate_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op='UPDATE' and old.content_sha256 is not null and new.content_sha256 is null
    and new.request_id is not distinct from old.request_id and new.created_at is not distinct from old.created_at then return new; end if;
  raise exception 'candidate receipt is immutable';
end $$;



CREATE FUNCTION public.protect_reviewed_claims() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare rev uuid;
begin
  if tg_table_name = 'claims' then
    if tg_op = 'INSERT' then rev := new.revision_id; else rev := old.revision_id; end if;
    if tg_op = 'UPDATE' and new.revision_id is distinct from old.revision_id then
      raise exception 'claim revision cannot be changed';
    end if;
  else
    if tg_op = 'INSERT' then
      select revision_id into rev from public.claims where id = new.claim_id;
    else
      select revision_id into rev from public.claims where id = old.claim_id;
    end if;
    if tg_op = 'UPDATE' and new.claim_id is distinct from old.claim_id then
      raise exception 'evidence claim cannot be changed';
    end if;
  end if;
  perform 1 from public.stories s join public.story_revisions r on r.story_id = s.id
    where r.id = rev for update of s;
  if exists (select 1 from public.editorial_reviews where revision_id = rev) then
    raise exception 'reviewed evidence is immutable';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;



CREATE FUNCTION public.publish_bilingual_first_internal(p_batch uuid, p_version integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.story_bilingual_batches%rowtype; s public.stories%rowtype;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'reason required'; end if;
  select * into b from public.story_bilingual_batches where id=p_batch;
  if b.id is null then raise exception 'batch unavailable'; end if;
  select * into s from public.stories where id=b.story_id and archived_at is null for update;
  if s.id is null or s.version is distinct from p_version then raise exception 'story version conflict'; end if;
  if s.visibility<>'hidden' or s.public_revision_id is not null or s.published_bilingual_batch_id is not null
    or exists(select 1 from public.publication_events where story_id=s.id) then raise exception 'only never-published stories'; end if;
  if s.bilingual_translation_status<>'ready'
    or b.zh_revision_id is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id where l.story_id=s.id and l.locale='zh' order by r.revision_number desc limit 1)
    or b.en_revision_id is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id where l.story_id=s.id and l.locale='en' order by r.revision_number desc limit 1)
    or not coalesce((select decision='approved' from public.bilingual_editorial_reviews where batch_id=b.id order by id desc limit 1),false)
    then raise exception 'latest approved bilingual batch required'; end if;
  perform src.id from public.sources src where exists(
    select 1 from public.articles a join public.claim_evidence e on e.article_id=a.id join public.claims c on c.id=e.claim_id
    where a.source_id=src.id and c.revision_id in (b.zh_revision_id,b.en_revision_id)) order by src.id for update;
  if not public.bilingual_batch_evidence_gate(b.id) then raise exception 'bilingual evidence tier requirements not met'; end if;
  insert into public.publication_events(story_id,revision_id,actor_id,action,reason)
    values(s.id,b.en_revision_id,auth.uid(),'publish',trim(p_reason));
  update public.stories set visibility='public',public_revision_id=b.en_revision_id,published_bilingual_batch_id=b.id,version=version+1 where id=s.id;
end $$;



CREATE FUNCTION public.publish_bilingual_update_internal(p_batch uuid, p_version integer, p_kind text, p_notice_zh text, p_notice_en text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare b public.story_bilingual_batches%rowtype; s public.stories%rowtype; event_id bigint;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_kind is null or p_kind not in ('update','correction')
    or p_notice_zh is null or length(trim(p_notice_zh)) not between 1 and 4000
    or p_notice_en is null or length(trim(p_notice_en)) not between 1 and 4000
    or p_reason is null or length(trim(p_reason)) not between 1 and 1000 then raise exception 'kind, bilingual notices and reason required'; end if;
  select * into b from public.story_bilingual_batches where id=p_batch;
  if b.id is null then raise exception 'batch unavailable'; end if;
  select * into s from public.stories where id=b.story_id and archived_at is null for update;
  if s.id is null or s.version is distinct from p_version then raise exception 'story version conflict'; end if;
  if s.visibility<>'public' or s.public_revision_id is null or s.published_bilingual_batch_id is null
    or s.published_bilingual_batch_id=b.id or s.public_revision_id=b.en_revision_id
    then raise exception 'new bilingual update required'; end if;
  if s.bilingual_translation_status<>'ready'
    or b.zh_revision_id is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id where l.story_id=s.id and l.locale='zh' order by r.revision_number desc limit 1)
    or b.en_revision_id is distinct from (select l.revision_id from public.story_revision_locales l join public.story_revisions r on r.id=l.revision_id where l.story_id=s.id and l.locale='en' order by r.revision_number desc limit 1)
    or not coalesce((select decision='approved' from public.bilingual_editorial_reviews where batch_id=b.id order by id desc limit 1),false)
    then raise exception 'latest approved bilingual batch required'; end if;
  perform src.id from public.sources src where exists(
    select 1 from public.articles a join public.claim_evidence e on e.article_id=a.id join public.claims c on c.id=e.claim_id
    where a.source_id=src.id and c.revision_id in (b.zh_revision_id,b.en_revision_id)) order by src.id for update;
  if not public.bilingual_batch_evidence_gate(b.id) then raise exception 'bilingual evidence tier requirements not met'; end if;
  insert into public.publication_events(story_id,revision_id,actor_id,action,public_notice,reason)
    values(s.id,b.en_revision_id,auth.uid(),p_kind,trim(p_notice_en),trim(p_reason)) returning id into event_id;
  insert into public.bilingual_publication_notices(event_id,zh,en) values(event_id,trim(p_notice_zh),trim(p_notice_en));
  update public.stories set public_revision_id=b.en_revision_id,published_bilingual_batch_id=b.id,version=version+1 where id=s.id;
end $$;



CREATE FUNCTION public.publish_revision(p_story uuid, p_revision uuid, p_expected_version integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare current_version integer;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_reason is null or length(trim(p_reason)) = 0 then raise exception 'reason required'; end if;
  select version into current_version from public.stories where id = p_story for update;
  if current_version is null or current_version <> p_expected_version then raise exception 'story version conflict'; end if;
  if p_revision is distinct from (select id from public.story_revisions where story_id = p_story order by revision_number desc limit 1) then raise exception 'revision is not latest'; end if;
  perform public.lock_revision_sources(p_revision);
  if not public.revision_is_eligible(p_story, p_revision) then raise exception 'revision is not eligible'; end if;
  update public.stories set visibility = 'public', public_revision_id = p_revision, version = version + 1 where id = p_story;
  insert into public.publication_events(story_id, revision_id, actor_id, action, reason) values (p_story, p_revision, auth.uid(), 'publish', p_reason);
end $$;



CREATE FUNCTION public.publish_story_update(p_story uuid, p_revision uuid, p_expected_version integer, p_kind text, p_notice text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare current_version integer; current_revision uuid; current_visibility text;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_kind is null or p_kind not in ('update', 'correction') then raise exception 'invalid update kind'; end if;
  if p_notice is null or length(trim(p_notice)) = 0 or p_reason is null or length(trim(p_reason)) = 0 then raise exception 'notice and reason required'; end if;
  select version, public_revision_id, visibility into current_version, current_revision, current_visibility
    from public.stories where id = p_story for update;
  if current_version is null or current_version <> p_expected_version then raise exception 'story version conflict'; end if;
  if current_visibility <> 'public' or current_revision is null then raise exception 'story is not public'; end if;
  if p_revision = current_revision or p_revision is distinct from (select id from public.story_revisions where story_id = p_story order by revision_number desc limit 1) then
    raise exception 'a new latest revision is required';
  end if;
  perform public.lock_revision_sources(p_revision);
  if not public.revision_is_eligible(p_story, p_revision) then raise exception 'revision is not eligible'; end if;
  insert into public.publication_events(story_id, revision_id, actor_id, action, public_notice, reason)
    values(p_story, p_revision, auth.uid(), p_kind, p_notice, p_reason);
  update public.stories set visibility = 'public', public_revision_id = p_revision, version = version + 1 where id = p_story;
end $$;



CREATE FUNCTION public.purge_classification_on_processing_revoke() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare g public.classification_processing_grants%rowtype;
begin
  select * into g from public.classification_processing_grants where id=new.grant_id;
  delete from public.classification_proposals p using public.classification_model_receipts r
    where r.proposal_id=p.id and p.policy_id=g.policy_id and p.provider=g.provider and p.region=g.region;
  return new;
end $$;



CREATE FUNCTION public.purge_classification_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  delete from public.classification_proposals where article_id in(select id from public.articles where source_id=new.source_id);
  return new;
end $$;



CREATE FUNCTION public.purge_classification_provider() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  delete from public.classification_proposals where provider_grant_id=new.grant_id;
  return new;
end $$;



CREATE FUNCTION public.purge_derived_claims_on_policy_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  delete from public.ai_claim_proposals c where exists(select 1 from public.ai_request_preparation_inputs i
    join public.articles a on a.id=i.article_id where i.request_id=c.request_id and a.source_id=new.source_id);
  return new;
end $$;



CREATE FUNCTION public.purge_derived_claims_on_revocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare g public.ai_derived_claim_grants%rowtype; sid uuid;
begin
  select * into g from public.ai_derived_claim_grants where id=new.grant_id;
  if g.permitted_action='store' then
    select source_id into sid from public.source_policies where id=g.policy_id;
    delete from public.ai_claim_proposals c using public.ai_request_preparations p where p.request_id=c.request_id
      and p.processor=g.provider and p.processing_region=g.processing_region
      and exists(select 1 from public.ai_request_preparation_inputs i join public.articles a on a.id=i.article_id
        where i.request_id=c.request_id and a.source_id=sid);
  end if;
  return new;
end $$;



CREATE FUNCTION public.purge_story_summary_on_claim_revoke() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare g public.ai_derived_claim_grants%rowtype;
begin
  select * into g from public.ai_derived_claim_grants where id=new.grant_id;
  if g.permitted_action='store' then delete from public.story_summary_proposals p where exists(
    select 1 from public.story_summary_request_facts rf join public.ai_verified_facts f on f.id=rf.fact_id
    join public.ai_request_preparations prep on prep.request_id=f.request_id join public.ai_request_preparation_inputs i on i.request_id=f.request_id
    where rf.request_id=p.request_id and prep.processor=g.provider and prep.processing_region=g.processing_region and i.policy_id=g.policy_id); end if;
  return new;
end $$;



CREATE FUNCTION public.purge_story_summary_on_fact_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  delete from public.story_summary_proposals p using public.story_summary_request_facts f where f.request_id=p.request_id and f.fact_id=old.id;
  return old;
end $$;



CREATE FUNCTION public.purge_story_summary_on_processing_revoke() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  delete from public.story_summary_proposals p using public.story_summary_request_grants g where g.request_id=p.request_id and g.grant_id=new.grant_id;
  return new;
end $$;



CREATE FUNCTION public.purge_story_summary_on_store_revoke() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare g public.summary_grants%rowtype;
begin
  select * into g from public.summary_grants where id=new.grant_id;
  if g.action='store' then delete from public.story_summary_proposals p using public.ai_request_preparations prep
    where prep.request_id=p.request_id and prep.processor=g.provider and prep.processing_region=g.region and exists(
      select 1 from public.story_summary_request_facts rf join public.ai_verified_facts f on f.id=rf.fact_id
      join public.ai_request_preparation_inputs i on i.request_id=f.request_id where rf.request_id=p.request_id and i.policy_id=g.policy_id); end if;
  return new;
end $$;



CREATE FUNCTION public.purge_summaries_on_claim_revoke() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare g public.ai_derived_claim_grants%rowtype;
begin
  select * into g from public.ai_derived_claim_grants where id=new.grant_id;
  if g.permitted_action='store' then
    delete from public.summary_proposals s using public.ai_verified_facts f,public.ai_request_preparations p
      where f.id=s.fact_id and p.request_id=f.request_id and p.processor=g.provider and p.processing_region=g.processing_region
        and exists(select 1 from public.ai_request_preparation_inputs i where i.request_id=f.request_id and i.policy_id=g.policy_id);
  end if;
  return new;
end $$;



CREATE FUNCTION public.purge_summary_on_processing_revoke() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  delete from public.summary_proposals p using public.summary_model_receipts mr,public.summary_request_processing_grants rg
    where mr.proposal_id=p.id and rg.request_id=mr.request_id and rg.grant_id=new.grant_id;
  return new;
end $$;



CREATE FUNCTION public.purge_verified_facts_on_policy_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  delete from public.ai_verified_facts f where exists(select 1 from public.ai_request_preparation_inputs i
    join public.articles a on a.id=i.article_id where i.request_id=f.request_id and a.source_id=new.source_id);
  return new;
end $$;



CREATE FUNCTION public.purge_verified_facts_on_provider_revocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare grant_row public.ai_provider_title_grants%rowtype; sid uuid;
begin
  select * into grant_row from public.ai_provider_title_grants where id=new.grant_id;
  select source_id into sid from public.source_policies where id=grant_row.policy_id;
  delete from public.ai_verified_facts f using public.ai_request_preparations p
    where p.request_id=f.request_id and p.processor=grant_row.provider and p.processing_region=grant_row.processing_region
      and exists(select 1 from public.ai_request_preparation_inputs i join public.articles a on a.id=i.article_id
        where i.request_id=f.request_id and a.source_id=sid);
  return new;
end $$;



CREATE FUNCTION public.purge_verified_facts_on_review_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.decision<>'supported' then
    delete from public.ai_verified_facts f using public.ai_claim_editor_reviews r
      where r.id=f.review_id and r.request_id=new.request_id and r.proposal_index=new.proposal_index;
  end if;
  return new;
end $$;



CREATE FUNCTION public.reader_can_delete_account() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
 select auth.uid() is not null and not exists(select 1 from public.editors where user_id=auth.uid()) and not exists(select 1 from public.manual_editor_owners where user_id=auth.uid()) and not exists(select 1 from public.site_team_roles where user_id=auth.uid())
$$;



CREATE FUNCTION public.reader_saved_items(p_locale text, p_kind text, p_offset integer DEFAULT 0) RETURNS TABLE(content_type text, slug text, title text, saved_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
 select s.content_type,s.slug,coalesce(a.title,s.slug),s.saved_at from (
  select b.content_type,b.slug,b.created_at saved_at from public.reader_bookmarks b where b.user_id=auth.uid() and p_kind='bookmarks'
  union all
  select h.content_type,h.slug,h.viewed_at saved_at from public.reader_history h where h.user_id=auth.uid() and p_kind='history'
 ) s left join public.homepage_public_articles(p_locale,false) a on a.content_type=s.content_type and a.slug=s.slug
 where p_locale in ('zh','en') order by s.saved_at desc,s.slug limit 21 offset greatest(0,least(coalesce(p_offset,0),100000))
$$;



CREATE FUNCTION public.recall_advance_run(p_run uuid, p_version integer, p_offset integer, p_digest text, p_next integer, p_total integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare result text;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  if p_digest is null or p_digest !~ '^[0-9a-f]{64}$' or p_offset is null or p_next is null or p_total is null
    or p_offset < 0 or p_next < p_offset or p_next > p_offset + 100 or p_next > p_total
    or (p_next < p_total and p_next <> p_offset + 100) then raise exception 'invalid recall progress'; end if;
  update public.recall_runs r set snapshot_digest=p_digest,next_offset=p_next,
    status=case when p_next = p_total then 'completed' else 'running' end,version=r.version+1,updated_at=clock_timestamp()
  where r.id=p_run and r.version=p_version and r.next_offset=p_offset and r.status in ('pending','running')
    and (r.snapshot_digest is null or r.snapshot_digest=p_digest) returning r.status into result;
  if result is null then raise exception 'recall run conflict'; end if;
  return result;
end $_$;



CREATE FUNCTION public.recall_create_run(p_ids uuid[], p_key text) RETURNS TABLE(run_id uuid, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare ids uuid[]; found_id uuid; found_ids uuid[]; n integer;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  n := coalesce(cardinality(p_ids), 0);
  if n < 1 or n > 200 or (select count(distinct x) from unnest(p_ids) x) <> n
    or p_key is null or p_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$' then raise exception 'invalid recall run'; end if;
  select array_agg(x order by x) into ids from unnest(p_ids) x;
  -- Plain reads of an existing run avoid source-lock/run-lock inversion.
  select r.id,r.article_ids into found_id,found_ids from public.recall_runs r where r.idempotency_key=p_key;
  if found_id is not null then
    if found_ids is distinct from ids then raise exception 'recall key belongs to different articles'; end if;
    return query select found_id,false; return;
  end if;
  if (select count(*) from public.recall_lock_articles_with_policy(ids)) <> n then raise exception 'candidate title permission unavailable'; end if;
  select r.id,r.article_ids into found_id,found_ids from public.recall_runs r where r.idempotency_key=p_key;
  if found_id is not null then
    if found_ids is distinct from ids then raise exception 'recall key belongs to different articles'; end if;
    return query select found_id,false; return;
  end if;
  insert into public.recall_runs(article_ids,idempotency_key) values(ids,p_key) on conflict (idempotency_key) do nothing returning id into found_id;
  if found_id is not null then return query select found_id,true; return; end if;
  select r.id,r.article_ids into found_id,found_ids from public.recall_runs r where r.idempotency_key=p_key;
  if found_id is null or found_ids is distinct from ids then raise exception 'recall key belongs to different articles'; end if;
  return query select found_id,false;
end $_$;



CREATE FUNCTION public.recall_lock_articles(p_ids uuid[]) RETURNS TABLE(article_id uuid, title text, observed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare n integer;
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  n := coalesce(cardinality(p_ids), 0);
  if n < 1 or n > 200 or (select count(distinct x) from unnest(p_ids) x) <> n then raise exception 'invalid article batch'; end if;
  perform s.id from public.sources s where s.id in (select a.source_id from public.articles a where a.id = any(p_ids)) order by s.id for update;
  perform a.id from public.articles a where a.id = any(p_ids) order by a.id for share;
  if (select count(*) from public.articles a where a.id = any(p_ids) and public.candidate_title_allowed(a.id)) <> n then
    raise exception 'candidate title permission unavailable';
  end if;
  return query select a.id, a.title, a.created_at from public.articles a where a.id = any(p_ids) order by a.id;
end $$;



CREATE FUNCTION public.recall_lock_articles_with_policy(p_ids uuid[]) RETURNS TABLE(article_id uuid, title text, observed_at timestamp with time zone, policy_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
 perform 1 from public.recall_lock_articles(p_ids);
 return query select a.id,a.title,coalesce(a.published_at,a.created_at),p.id
 from public.articles a join lateral
 (select sp.id from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1)p on true
 where a.id=any(p_ids) and public.candidate_title_allowed(a.id) order by a.id;
end $$;



CREATE FUNCTION public.recall_lock_run(p_run uuid) RETURNS TABLE(article_ids uuid[], status text, snapshot_digest text, next_offset integer, version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  return query select r.article_ids,r.status,r.snapshot_digest,r.next_offset,r.version from public.recall_runs r where r.id=p_run for update;
end $$;



CREATE FUNCTION public.recall_propose_pair(p_first uuid, p_second uuid, p_rule text) RETURNS TABLE(candidate_id uuid, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare a uuid; b uuid; cid uuid; policy_a uuid; policy_b uuid;
begin
  if p_rule is distinct from 'title_overlap_v1' then raise exception 'invalid recall rule'; end if;
  perform public.lock_candidate_sources(p_first, p_second);
  a := least(p_first, p_second); b := greatest(p_first, p_second);
  -- A plain read does not wait on an editor's lock or modify an existing pair.
  select c.id into cid from public.editor_candidate_pairs c where c.first_article_id = a and c.second_article_id = b;
  if cid is not null then return query select cid, false; return; end if;
  select p.id into policy_a from public.articles x join lateral
    (select sp.id from public.source_policies sp where sp.source_id=x.source_id order by sp.version desc limit 1) p on true where x.id=a;
  select p.id into policy_b from public.articles x join lateral
    (select sp.id from public.source_policies sp where sp.source_id=x.source_id order by sp.version desc limit 1) p on true where x.id=b;
  insert into public.editor_candidate_pairs(first_article_id,second_article_id,origin,rule_version,first_policy_id,second_policy_id)
    values(a,b,'rule',p_rule,policy_a,policy_b) on conflict (first_article_id,second_article_id) do nothing returning id into cid;
  if cid is not null then return query select cid, true; return; end if;
  select c.id into cid from public.editor_candidate_pairs c where c.first_article_id=a and c.second_article_id=b;
  if cid is null then raise exception 'candidate conflict unavailable'; end if;
  return query select cid, false;
end $$;



CREATE FUNCTION public.record_article_index_click(p_type text, p_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare current_total bigint; current_score integer;
begin
 if p_type is null or p_type not in ('manual','story') or p_slug is null or length(p_slug)>200 or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'invalid article'; end if;
 if not exists(select 1 from public.homepage_public_articles('en',false) a where a.content_type=p_type and a.slug=p_slug and a.score is not null) then return null; end if;
 insert into public.article_index_clicks(content_type,slug,total) values(p_type,p_slug,1) on conflict(content_type,slug) do update set total=public.article_index_clicks.total+1 returning total into current_total;
 insert into public.article_index_daily(content_type,slug,click_day,clicks) values(p_type,p_slug,(statement_timestamp() at time zone 'UTC')::date,1) on conflict(content_type,slug,click_day) do update set clicks=public.article_index_daily.clicks+1;
 if random()<0.01 then delete from public.article_index_daily where click_day < (statement_timestamp() at time zone 'UTC')::date-30; end if;
 select a.score into current_score from public.homepage_public_articles('en',false) a where a.content_type=p_type and a.slug=p_slug;
 return jsonb_build_object('score',current_score,'clicks',current_total);
end $_$;



CREATE FUNCTION public.record_article_reaction(p_type text, p_slug text, p_reaction text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare current_score integer;
begin
 if p_reaction is null or p_reaction not in ('like','dislike','shit') then raise exception 'invalid reaction'; end if;
 if p_type is null or p_type not in ('manual','story') or p_slug is null or length(p_slug)>200 or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'invalid article'; end if;
 if p_reaction='like' then return public.record_article_index_click(p_type,p_slug); end if;
 if not exists(select 1 from public.homepage_public_articles('en',false) a where a.content_type=p_type and a.slug=p_slug and a.score is not null) then return null; end if;
 insert into public.article_index_clicks(content_type,slug,dislikes,shit) values(p_type,p_slug,case when p_reaction='dislike' then 1 else 0 end,case when p_reaction='shit' then 1 else 0 end)
 on conflict(content_type,slug) do update set dislikes=public.article_index_clicks.dislikes+excluded.dislikes,shit=public.article_index_clicks.shit+excluded.shit;
 select a.score into current_score from public.homepage_public_articles('en',false) a where a.content_type=p_type and a.slug=p_slug;
 return jsonb_build_object('score',current_score);
end $_$;



CREATE FUNCTION public.record_homepage_view(p_type text, p_slug text, p_browser_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare inserted integer;
begin
 if p_type is null or p_slug is null or p_type not in ('manual','story') or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or length(p_slug)>200 or p_browser_hash is null or p_browser_hash !~ '^[0-9a-f]{64}$' then raise exception 'invalid view'; end if;
 if not exists(select 1 from public.homepage_public_articles('en',false) a where a.slug=p_slug and a.content_type=p_type) then return false; end if;
 insert into public.homepage_article_views(content_type,slug,view_day,browser_hash) values(p_type,p_slug,(statement_timestamp() at time zone 'UTC')::date,p_browser_hash) on conflict do nothing;
 get diagnostics inserted = row_count;
 if random()<0.01 then delete from public.homepage_article_views where view_day < (statement_timestamp() at time zone 'UTC')::date-30; end if;
 return inserted > 0;
end $_$;



CREATE FUNCTION public.record_limited_article_reaction(p_type text, p_slug text, p_reaction text, p_visitor_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare used smallint; result jsonb;
begin
 if p_type is null or p_type not in ('manual','story') or p_slug is null or length(p_slug)>200 or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or p_reaction is null or p_reaction not in ('like','dislike','shit') or p_visitor_hash is null or p_visitor_hash !~ '^[0-9a-f]{64}$' then raise exception 'invalid reaction'; end if;
 if not exists(select 1 from public.homepage_public_articles('en',false) a where a.content_type=p_type and a.slug=p_slug and a.score is not null) then return null; end if;
 insert into public.article_reaction_limits(content_type,slug,visitor_hash,clicks) values(p_type,p_slug,p_visitor_hash,1)
 on conflict(content_type,slug,visitor_hash) do update set clicks=public.article_reaction_limits.clicks+1 where public.article_reaction_limits.clicks<5 returning clicks into used;
 if used is null then return jsonb_build_object('limited',true); end if;
 result:=public.record_article_reaction(p_type,p_slug,p_reaction);
 if result is null then raise exception 'article unavailable'; end if;
 return jsonb_build_object('score',(result->>'score')::integer,'remaining',5-used);
end $_$;



CREATE FUNCTION public.record_site_engagement(p_event uuid, p_visitor text, p_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare changed integer;
begin
 if p_seconds is null or p_seconds<0 or p_seconds>1800 then raise exception 'invalid engagement'; end if;
 update public.site_page_visits set engagement_seconds=greatest(engagement_seconds,least(p_seconds,greatest(0,floor(extract(epoch from statement_timestamp()-visited_at))::integer)))
 where event_id=p_event and visitor_hash=p_visitor;
 get diagnostics changed=row_count;
 return changed>0;
end $$;



CREATE FUNCTION public.record_site_page_view(p_event uuid, p_visitor text, p_session text, p_path text, p_referrer text, p_device text, p_browser text, p_os text, p_country text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare inserted integer;
begin
 insert into public.site_page_visits(event_id,visitor_hash,session_hash,path,referrer_host,device,browser,os,country,locale)
 values(p_event,p_visitor,p_session,p_path,p_referrer,p_device,p_browser,p_os,p_country,split_part(p_path,'/',2)) on conflict(event_id) do nothing;
 get diagnostics inserted=row_count;
 if random()<0.01 then delete from public.site_page_visits where visited_at<statement_timestamp()-interval '30 days'; end if;
 return inserted>0;
end $$;



