CREATE FUNCTION public.require_editor_source_access_for_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.decision='approved' then
    if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
    perform 1 from public.stories s join public.story_revisions r on r.story_id=s.id where r.id=new.revision_id for update of s;
    perform public.lock_revision_sources(new.revision_id);
    if not public.editor_revision_sources_available(new.revision_id) then raise exception 'source display permission unavailable'; end if;
  end if;
  return new;
end $$;



CREATE FUNCTION public.require_recorded_story_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare event_action text; event_revision uuid;
begin
  if old.public_revision_id is not null and new.visibility = 'public'
    and (old.visibility <> 'public' or new.public_revision_id is distinct from old.public_revision_id) then
    select action, revision_id into event_action, event_revision from public.publication_events
      where story_id = new.id order by id desc limit 1;
    if event_action is null or event_action not in ('update', 'correction') or event_revision is distinct from new.public_revision_id then
      raise exception 'recorded update required';
    end if;
  end if;
  return new;
end $$;



CREATE FUNCTION public.retract_bilingual_story_internal(p_story uuid, p_notice uuid, p_version integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if not exists(select 1 from public.bilingual_retraction_notices where notice_id=p_notice) then raise exception 'bilingual notice required'; end if;
  perform public.retract_story(p_story,p_notice,p_version,p_reason);
end $$;



CREATE FUNCTION public.retract_story(p_story uuid, p_notice uuid, p_expected_version integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare rid uuid;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_reason is null or length(trim(p_reason)) = 0 then raise exception 'reason required'; end if;
  select public_revision_id into rid from public.stories where id = p_story and version = p_expected_version and visibility = 'public' for update;
  if rid is null then raise exception 'story version conflict or not public'; end if;
  if not exists (select 1 from public.retraction_notices n join public.retraction_approvals a on a.notice_id = n.id
    where n.id = p_notice and n.story_id = p_story and n.revision_id = rid) then raise exception 'approved notice required'; end if;
  update public.stories set visibility = 'retracted', public_retraction_id = p_notice, version = version + 1 where id = p_story;
  insert into public.publication_events(story_id, revision_id, actor_id, action, reason) values(p_story, rid, auth.uid(), 'retract', p_reason);
end $$;



CREATE FUNCTION public.review_revision(p_revision uuid, p_decision text, p_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare sid uuid;
begin
  if not public.is_active_editor() then raise exception 'editor access required'; end if;
  if p_decision not in ('approved', 'rejected', 'needs_changes', 'needs_evidence') then raise exception 'invalid decision'; end if;
  select story_id into sid from public.story_revisions where id = p_revision;
  if sid is null then raise exception 'revision not found'; end if;
  perform 1 from public.stories where id = sid for update;
  if p_revision is distinct from (select id from public.story_revisions where story_id = sid order by revision_number desc limit 1) then
    raise exception 'revision is not latest';
  end if;
  insert into public.editorial_reviews(revision_id, reviewer_id, decision, notes)
    values (p_revision, auth.uid(), p_decision, p_notes);
end $$;



CREATE FUNCTION public.revision_eligible_before_archive(p_story uuid, p_revision uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select public.revision_eligible_before_merge(p_story,p_revision)
    and not exists(select 1 from public.story_merge_events e where e.source_story_id=p_story)
    and not exists(select 1 from public.story_merge_events e join public.story_revisions r on r.id=p_revision and r.story_id=p_story
      where e.target_story_id=p_story and r.revision_number<=e.target_revision_number)
    and not exists(select 1 from public.translation_revision_imports i where i.target_revision_id=p_revision
      and not public.translation_request_accessible(i.request_id))
$$;



CREATE FUNCTION public.revision_eligible_before_bilingual(p_story uuid, p_revision uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select public.revision_eligible_before_archive(p_story,p_revision)
    and exists(select 1 from public.stories where id=p_story and archived_at is null)
$$;



CREATE FUNCTION public.revision_eligible_before_merge(p_story uuid, p_revision uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  select exists (select 1 from public.story_revisions where id = p_revision and story_id = p_story)
  and exists (select 1 from public.claims where revision_id = p_revision)
  and not exists (
    select 1 from public.claims c where c.revision_id = p_revision and (
      c.status <> 'verified' or not exists (
        select 1 from public.claim_evidence e
        join public.articles a on a.id = e.article_id
        join public.story_articles sa on sa.article_id = a.id and sa.story_id = p_story
        join lateral (select * from public.source_policies sp where sp.source_id = a.source_id order by version desc limit 1) p on true
        where e.claim_id = c.id and e.relation = 'supports'
          and e.verified_by is not null and e.verified_at is not null
          and length(trim(e.evidence_reference)) > 0
          and p.policy_status = 'approved' and p.display_allowed and p.story_publication_allowed
          and p.source_display_allowed and p.link_display_allowed and p.permitted_region = 'global'
          and length(trim(p.attribution_requirements)) > 0
          and a.canonical_url ~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$'
          and p.reviewed_by is not null and p.reviewed_at is not null
          and p.policy_evidence <> '{}'::jsonb
          and (p.permission_expires_at is null or p.permission_expires_at > now())
      ) or exists (select 1 from public.claim_evidence e where e.claim_id = c.id and e.relation = 'contradicts')
    )
  )
  and not exists (select 1 from public.story_split_events e join public.story_revisions r on r.id=p_revision and r.story_id=p_story
    where e.source_story_id=p_story and r.revision_number<=e.source_revision_number)
  and coalesce((select decision = 'approved' from public.editorial_reviews where revision_id = p_revision order by review_order desc limit 1), false)
$_$;



CREATE FUNCTION public.revision_is_eligible(p_story uuid, p_revision uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select public.revision_eligible_before_bilingual(p_story,p_revision)
    and coalesce((select case when s.visibility='public' and s.public_revision_id=p_revision
      then case when s.published_bilingual_batch_id is null then not public.bilingual_rollout_enabled()
        else public.bilingual_batch_evidence_gate(s.published_bilingual_batch_id)
          and coalesce((select decision='approved' from public.bilingual_editorial_reviews r
            where r.batch_id=s.published_bilingual_batch_id order by r.id desc limit 1),false) end
      else true end from public.stories s where s.id=p_story),false)
$$;



CREATE FUNCTION public.score_claim_pending() RETURNS TABLE(assessment_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare candidate record; skipped uuid[] := '{}';
begin
  if current_setting('transaction_isolation') <> 'read committed' then raise exception 'read committed isolation required'; end if;
  for attempt in 1..100 loop
    select i.id,i.story_id,i.story_version,i.revision_id into candidate from public.editorial_score_inputs i
    join public.stories s on s.id=i.story_id and s.version=i.story_version
    where not (i.id=any(skipped))
      and i.revision_id=(select r.id from public.story_revisions r where r.story_id=i.story_id order by r.revision_number desc limit 1)
      and not exists(select 1 from public.editorial_reviews r where r.revision_id=i.revision_id)
      and not exists(select 1 from public.story_scores sc where sc.assessment_id=i.id)
    order by i.created_at,i.id
    for update of s skip locked limit 1;
    if not found then return; end if;
    if exists(select 1 from public.stories s where s.id=candidate.story_id and s.version=candidate.story_version)
      and candidate.revision_id=(select r.id from public.story_revisions r where r.story_id=candidate.story_id order by r.revision_number desc limit 1)
      and not exists(select 1 from public.editorial_reviews r where r.revision_id=candidate.revision_id)
      and not exists(select 1 from public.story_scores sc where sc.assessment_id=candidate.id) then
      return query select candidate.id;
      return;
    end if;
    skipped := array_append(skipped,candidate.id);
  end loop;
end $$;



CREATE FUNCTION public.score_find_receipt(p_input uuid) RETURNS TABLE(status text, score_id uuid, score integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare s public.story_scores%rowtype;
begin
  select * into s from public.story_scores where assessment_id=p_input;
  if s.id is null then return query select 'unresolved'::text,null::uuid,null::integer;
  else return query select 'stored'::text,s.id,s.holy_shit_score; end if;
end $$;



CREATE FUNCTION public.score_lock_input(p_id uuid) RETURNS TABLE(technical_breakthrough integer, future_impact integer, novelty integer, attention integer, unexpectedness integer, reasons jsonb, attention_evidence text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare entry public.editorial_score_inputs%rowtype; current_version integer;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  select * into entry from public.editorial_score_inputs where id=p_id;
  if entry.id is null then raise exception 'score input not found'; end if;
  select version into current_version from public.stories where id=entry.story_id for update;
  if current_version is distinct from entry.story_version or entry.revision_id is distinct from
    (select id from public.story_revisions where story_id=entry.story_id order by revision_number desc limit 1)
    or exists(select 1 from public.editorial_reviews where revision_id=entry.revision_id) then raise exception 'score input is no longer editable'; end if;
  return query select entry.technical_breakthrough,entry.future_impact,entry.novelty,entry.attention,entry.unexpectedness,entry.reasons,entry.attention_evidence;
end $$;



CREATE FUNCTION public.score_store_result(p_input uuid, p_score integer) RETURNS TABLE(score_id uuid, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare entry public.editorial_score_inputs%rowtype; existing public.story_scores%rowtype; weighted integer; expected integer; sid uuid;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  select * into entry from public.editorial_score_inputs where id=p_input;
  if entry.id is null then raise exception 'score input not found'; end if;
  perform 1 from public.stories where id=entry.story_id for update;
  select * into existing from public.story_scores where assessment_id=p_input;
  if existing.id is not null then
    if existing.holy_shit_score is distinct from p_score then raise exception 'score replay conflict'; end if;
    return query select existing.id,false; return;
  end if;
  perform 1 from public.score_lock_input(p_input);
  if entry.attention is null then expected := null;
  else
    weighted := 30*entry.technical_breakthrough+25*entry.future_impact+20*entry.novelty+15*entry.attention+10*entry.unexpectedness;
    expected := weighted / 100;
    if weighted % 100 > 50 or (weighted % 100 = 50 and expected % 2 = 1) then expected := expected + 1; end if;
  end if;
  if p_score is distinct from expected then raise exception 'score total mismatch'; end if;
  insert into public.story_scores(story_id,revision_id,scoring_version,technical_breakthrough,future_impact,novelty,attention,unexpectedness,holy_shit_score,reason,assessment_id)
    values(entry.story_id,entry.revision_id,'holy_shit.v1',entry.technical_breakthrough,entry.future_impact,entry.novelty,entry.attention,entry.unexpectedness,p_score,entry.editorial_reason,entry.id)
    returning id into sid;
  return query select sid,true;
end $$;



CREATE FUNCTION public.scrub_classification_model_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin update public.classification_model_receipts set content_sha256=null where proposal_id=old.id; return old; end $$;



CREATE FUNCTION public.scrub_deleted_candidate_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  update public.ai_claim_proposal_receipts set content_sha256=null where request_id=old.request_id and content_sha256 is not null;
  return old;
end $$;



CREATE FUNCTION public.scrub_summary_model_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin update public.summary_model_receipts set content_sha256=null where proposal_id=old.id; return old; end $$;



CREATE FUNCTION public.story_summary_valid_content(p_content jsonb, p_request uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare item jsonb; all_items jsonb; ids jsonb;
begin
  if p_request is null or p_content is null or jsonb_typeof(p_content)<>'object' or octet_length(p_content::text)>32768
    or (select count(*) from jsonb_object_keys(p_content))<>4 or not (p_content ?& array['schema_version','headline','summary','why_it_matters'])
    or p_content->>'schema_version'<>'summary_proposal.v1' or jsonb_typeof(p_content->'headline')<>'object'
    or jsonb_typeof(p_content->'summary')<>'array' or jsonb_typeof(p_content->'why_it_matters')<>'array' then return false; end if;
  if jsonb_array_length(p_content->'summary') not between 1 and 4 or jsonb_array_length(p_content->'why_it_matters') not between 1 and 3 then return false; end if;
  all_items:=jsonb_build_array(p_content->'headline') || (p_content->'summary') || (p_content->'why_it_matters');
  for item in select value from jsonb_array_elements(all_items) loop
    if jsonb_typeof(item)<>'object' or (select count(*) from jsonb_object_keys(item))<>2 or not (item ?& array['text','claim_ids'])
      or jsonb_typeof(item->'text')<>'string' or length(trim(item->>'text')) not between 1 and 500
      or jsonb_typeof(item->'claim_ids')<>'array' then return false; end if;
    ids:=item->'claim_ids';
    if jsonb_array_length(ids) not between 1 and 5 or (select count(distinct value) from jsonb_array_elements_text(ids))<>jsonb_array_length(ids)
      or exists(select 1 from jsonb_array_elements(ids) e where jsonb_typeof(e)<>'string' or not exists(
        select 1 from public.story_summary_request_facts f where f.request_id=p_request and f.fact_id::text=e#>>'{}')) then return false; end if;
  end loop;
  return true;
exception when others then return false;
end $$;



CREATE TABLE public.story_summary_proposals (
    id uuid NOT NULL,
    request_id uuid NOT NULL,
    content jsonb NOT NULL,
    content_sha256 text NOT NULL,
    created_by uuid NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT story_summary_proposals_content_sha256_check CHECK ((content_sha256 ~ '^[0-9a-f]{64}$'::text))
);



CREATE FUNCTION public.story_summary_visible(p public.story_summary_proposals) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select p.expires_at>statement_timestamp() and exists(select 1 from public.story_summary_retention_control where singleton and not restore_quarantine)
    and exists(select 1 from public.story_summary_requests req join public.ai_request_preparations prep on prep.request_id=req.request_id
      where req.request_id=p.request_id and not exists(select 1 from public.story_summary_request_invalidations x where x.request_id=req.request_id)
      and req.fact_count=(select count(*) from public.story_summary_request_facts f where f.request_id=req.request_id)
      and not exists(select 1 from public.story_summary_request_facts rf join public.ai_verified_facts f on f.id=rf.fact_id
        join public.ai_request_identities br on br.request_id=f.request_id join public.ai_processing_jobs job on job.id=br.job_id
        where rf.request_id=req.request_id and (rf.fact_sha256<>encode(sha256(convert_to(f.fact_text,'UTF8')),'hex')
          or job.story_id is distinct from req.story_id or not exists(select 1 from public.story_articles sa where sa.story_id=req.story_id and sa.article_id=f.article_id)
          or exists(select 1 from public.ai_request_preparation_inputs i where i.request_id=f.request_id and not exists(
            select 1 from public.story_articles sa where sa.story_id=req.story_id and sa.article_id=i.article_id))
          or coalesce(public.summary_scope_deadline(f.id,prep.processor,prep.processing_region,'store')>statement_timestamp(),false)=false
          or coalesce(public.summary_scope_deadline(f.id,prep.processor,prep.processing_region,'editor_display')>statement_timestamp(),false)=false))
      and not exists(select 1 from public.story_summary_request_facts rf join public.ai_verified_facts f on f.id=rf.fact_id
        join public.ai_request_preparation_inputs i on i.request_id=f.request_id
        left join public.story_summary_request_grants rg on rg.request_id=rf.request_id and rg.fact_id=rf.fact_id and rg.article_id=i.article_id
        left join public.summary_processing_grants g on g.id=rg.grant_id and g.policy_id=i.policy_id and g.provider=prep.processor and g.region=prep.processing_region
        where rf.request_id=req.request_id and (g.id is null or g.expires_at<=statement_timestamp()
          or exists(select 1 from public.summary_processing_revocations rv where rv.grant_id=g.id)))
      and not exists(select 1 from public.ai_request_preparation_inputs x join public.articles a on a.id=x.article_id
        join public.ai_provider_title_grants tg on tg.id=x.provider_grant_id where x.request_id=req.request_id
        and (tg.provider<>prep.processor or tg.processing_region<>prep.processing_region or (tg.expires_at is not null and tg.expires_at<=statement_timestamp())
          or exists(select 1 from public.ai_provider_title_revocations tr where tr.grant_id=tg.id)
          or x.title_sha256<>encode(sha256(convert_to(a.title,'UTF8')),'hex'))))
$$;



CREATE FUNCTION public.submit_article_anonymous_comment(p_type text, p_slug text, p_body text) RETURNS TABLE(id bigint, body text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
begin
 if p_type is null or p_type not in ('manual','story') or p_slug is null or length(p_slug)>200 or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or p_body is null or length(btrim(p_body)) not between 1 and 500 then raise exception 'invalid comment'; end if;
 if not exists(select 1 from public.homepage_public_articles('en',false) a where a.content_type=p_type and a.slug=p_slug) then return; end if;
 return query insert into public.article_anonymous_comments(content_type,slug,body) values(p_type,p_slug,btrim(p_body)) returning article_anonymous_comments.id,article_anonymous_comments.body,article_anonymous_comments.created_at;
end $_$;



CREATE FUNCTION public.submit_article_comment_v2(p_type text, p_slug text, p_body text, p_reader uuid DEFAULT NULL::uuid) RETURNS TABLE(id bigint, body text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
begin
 if p_type is null or p_type not in ('manual','story') or p_slug is null or length(p_slug)>200 or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or p_body is null or length(btrim(p_body)) not between 1 and 500 then raise exception 'invalid comment'; end if;
 if not exists(select 1 from public.homepage_public_articles('en',false) a where a.content_type=p_type and a.slug=p_slug) then return; end if;
 return query insert into public.article_anonymous_comments(content_type,slug,body,reader_user_id) values(p_type,p_slug,btrim(p_body),p_reader) returning article_anonymous_comments.id,article_anonymous_comments.body,article_anonymous_comments.created_at;
end $_$;



CREATE FUNCTION public.submit_candidate(p_id uuid, p_url text, p_title text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  -- Serialize closure against submissions already using the gate.
  perform 1 from public.candidate_submission_control where singleton and enabled for share;
  if not found then raise exception 'submissions unavailable'; end if;
  return public.submit_candidate_before_gate(p_id,p_url,p_title);
end $$;



CREATE FUNCTION public.submit_candidate_before_gate(p_id uuid, p_url text, p_title text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare prior public.candidate_submissions%rowtype;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed isolation required'; end if;
  if p_id is null or p_url is null or length(p_url) not between 9 and 2048
    or p_url !~ '^https://[^/@?#[:space:]]+([/?#][^[:space:]]*)?$'
    or p_title is null or length(trim(p_title)) not between 1 and 200 then raise exception 'invalid submission'; end if;
  perform pg_advisory_xact_lock(103103);
  select * into prior from public.candidate_submissions where id=p_id;
  if found then
    if prior.url is distinct from p_url or prior.title is distinct from trim(p_title) then raise exception 'submission identity conflict'; end if;
    return false;
  end if;
  if exists(select 1 from public.candidate_submissions where url=p_url) then return false; end if;
  if (select count(*) from public.candidate_submissions where created_at>clock_timestamp()-interval '1 minute')>=30
    or (select count(*) from public.candidate_submissions where created_at>clock_timestamp()-interval '1 day')>=500
    then raise exception 'submission capacity reached'; end if;
  insert into public.candidate_submissions(id,url,title) values(p_id,p_url,trim(p_title));
  return true;
end $_$;



CREATE FUNCTION public.summary_scope_deadline(p_fact uuid, p_provider text, p_region text, p_action text) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select case when count(*)=count(x.article_id) and count(*) between 1 and 50 then min(least(
    f.expires_at,pol.permission_expires_at,tg.expires_at,vs.expires_at,vd.expires_at,ds.expires_at,dd.expires_at,sg.expires_at)) end
  from public.ai_verified_facts f
  join public.ai_claim_editor_reviews rev on rev.id=f.review_id and rev.article_id=f.article_id and rev.decision='supported'
    and rev.id=(select r.id from public.ai_claim_editor_reviews r where r.request_id=rev.request_id and r.proposal_index=rev.proposal_index order by r.created_at desc,r.id desc limit 1)
  join public.ai_request_preparations prep on prep.request_id=f.request_id and prep.request_id=rev.request_id
  join public.ai_request_preparation_inputs x on x.request_id=prep.request_id
  join public.articles a on a.id=x.article_id
  join lateral (select * from public.source_policies p where p.source_id=a.source_id order by version desc limit 1) pol on pol.id=x.policy_id
  join public.ai_provider_title_grants tg on tg.id=x.provider_grant_id and tg.policy_id=pol.id and tg.provider=prep.processor and tg.processing_region=prep.processing_region
  join lateral (select g.expires_at from public.ai_verified_fact_grants g where g.policy_id=pol.id and g.provider=prep.processor and g.processing_region=prep.processing_region
    and g.permitted_action='verified_store' and g.expires_at>statement_timestamp() and not exists(select 1 from public.ai_verified_fact_grant_revocations r where r.grant_id=g.id) order by g.expires_at desc limit 1) vs on true
  join lateral (select g.expires_at from public.ai_verified_fact_grants g where g.policy_id=pol.id and g.provider=prep.processor and g.processing_region=prep.processing_region
    and g.permitted_action='verified_display' and g.expires_at>statement_timestamp() and not exists(select 1 from public.ai_verified_fact_grant_revocations r where r.grant_id=g.id) order by g.expires_at desc limit 1) vd on true
  join lateral (select g.expires_at from public.ai_derived_claim_grants g where g.policy_id=pol.id and g.provider=prep.processor and g.processing_region=prep.processing_region
    and g.permitted_action='store' and g.expires_at>statement_timestamp() and not exists(select 1 from public.ai_derived_claim_revocations r where r.grant_id=g.id) order by g.expires_at desc limit 1) ds on true
  join lateral (select g.expires_at from public.ai_derived_claim_grants g where g.policy_id=pol.id and g.provider=prep.processor and g.processing_region=prep.processing_region
    and g.permitted_action='editor_display' and g.expires_at>statement_timestamp() and not exists(select 1 from public.ai_derived_claim_revocations r where r.grant_id=g.id) order by g.expires_at desc limit 1) dd on true
  join lateral (select g.expires_at from public.summary_grants g where g.policy_id=pol.id and g.provider=p_provider and g.region=p_region and g.action=p_action
    and g.expires_at>statement_timestamp() and not exists(select 1 from public.summary_grant_revocations r where r.grant_id=g.id) order by g.expires_at desc limit 1) sg on true
  where f.id=p_fact and p_action in ('store','editor_display') and f.expires_at>statement_timestamp()
    and exists(select 1 from public.ai_request_preparation_inputs i where i.request_id=f.request_id and i.article_id=f.article_id)
    and exists(select 1 from public.ai_verified_fact_retention_control c where c.singleton and not c.restore_quarantine)
    and pol.policy_status='approved' and pol.title_storage_allowed and pol.ai_processing_allowed and pol.reviewed_by is not null and pol.reviewed_at is not null
    and pol.policy_evidence<>'{}'::jsonb and (pol.permission_expires_at is null or pol.permission_expires_at>statement_timestamp())
    and (tg.expires_at is null or tg.expires_at>statement_timestamp()) and not exists(select 1 from public.ai_provider_title_revocations r where r.grant_id=tg.id)
    and x.title_sha256=encode(sha256(convert_to(a.title,'UTF8')),'hex')
  having count(*)=(select count(*) from public.ai_request_preparation_inputs i where i.request_id=(select request_id from public.ai_verified_facts where id=p_fact))
$$;



CREATE FUNCTION public.summary_valid_content(p_content jsonb, p_fact uuid) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare item jsonb; all_items jsonb;
begin
  if p_fact is null or p_content is null or jsonb_typeof(p_content)<>'object' or octet_length(p_content::text)>32768
    or (select count(*) from jsonb_object_keys(p_content))<>4
    or not (p_content ?& array['schema_version','headline','summary','why_it_matters'])
    or p_content->>'schema_version'<>'summary_proposal.v1' or jsonb_typeof(p_content->'headline')<>'object'
    or jsonb_typeof(p_content->'summary')<>'array' or jsonb_typeof(p_content->'why_it_matters')<>'array' then return false; end if;
  if jsonb_array_length(p_content->'summary') not between 1 and 4 or jsonb_array_length(p_content->'why_it_matters') not between 1 and 3 then return false; end if;
  all_items=jsonb_build_array(p_content->'headline') || (p_content->'summary') || (p_content->'why_it_matters');
  for item in select value from jsonb_array_elements(all_items) loop
    if jsonb_typeof(item)<>'object' or (select count(*) from jsonb_object_keys(item))<>2 or not (item ?& array['text','claim_ids'])
      or jsonb_typeof(item->'text')<>'string' or length(trim(item->>'text')) not between 1 and 500
      or item->'claim_ids'<>jsonb_build_array(p_fact::text) then return false; end if;
  end loop;
  return true;
exception when others then return false;
end $$;



CREATE TABLE public.summary_proposals (
    id uuid NOT NULL,
    fact_id uuid NOT NULL,
    provider text NOT NULL,
    region text NOT NULL,
    content jsonb NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_by uuid NOT NULL,
    origin text DEFAULT 'manual_import_unverified'::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT summary_proposals_origin_check CHECK ((origin = 'manual_import_unverified'::text)),
    CONSTRAINT summary_proposals_region_check CHECK ((region ~ '^[a-z0-9-]{2,40}$'::text))
);



CREATE FUNCTION public.summary_visible(p public.summary_proposals) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select p.expires_at>statement_timestamp()
    and exists(select 1 from public.summary_retention_control where singleton and not restore_quarantine)
    and public.summary_scope_deadline(p.fact_id,p.provider,p.region,'store')>statement_timestamp()
    and public.summary_scope_deadline(p.fact_id,p.provider,p.region,'editor_display')>statement_timestamp()
    and (not exists(select 1 from public.summary_model_receipts mr where mr.proposal_id=p.id)
      or exists(select 1 from public.summary_model_receipts mr join public.summary_request_facts rf on rf.request_id=mr.request_id
        join public.ai_verified_facts f on f.id=rf.fact_id
        where mr.proposal_id=p.id and rf.fact_id=p.fact_id and rf.fact_sha256=encode(sha256(convert_to(f.fact_text,'UTF8')),'hex')
          and exists(select 1 from public.summary_request_processing_grants rg where rg.request_id=mr.request_id)
          and not exists(select 1 from public.ai_request_preparation_inputs x join public.articles a on a.id=x.article_id
            join public.ai_provider_title_grants tg on tg.id=x.provider_grant_id
            where x.request_id=mr.request_id and (tg.provider<>p.provider or tg.processing_region<>p.region
              or (tg.expires_at is not null and tg.expires_at<=statement_timestamp())
              or exists(select 1 from public.ai_provider_title_revocations tr where tr.grant_id=tg.id)
              or x.title_sha256<>encode(sha256(convert_to(a.title,'UTF8')),'hex')))
          and not exists(select 1 from public.summary_request_processing_grants rg join public.summary_processing_grants g on g.id=rg.grant_id
            where rg.request_id=mr.request_id and (g.provider<>p.provider or g.region<>p.region or g.expires_at<=statement_timestamp()
              or exists(select 1 from public.summary_processing_revocations rv where rv.grant_id=g.id)))))
$$;



CREATE FUNCTION public.sweep_classification_proposals() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare n integer;
begin
  if current_setting('transaction_isolation')<>'read committed' then raise exception 'read committed required'; end if;
  perform 1 from public.classification_retention_control where singleton for update;
  delete from public.classification_proposals where id in(select id from public.classification_proposals where expires_at<=clock_timestamp() order by expires_at,id limit 500);
  get diagnostics n=row_count;
  update public.classification_retention_control set last_sweep_at=clock_timestamp() where singleton;
  return n;
end $$;



CREATE FUNCTION public.sweep_story_summary_proposals() RETURNS integer
