end $$;



CREATE FUNCTION public.translation_request_accessible(p_request uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 select coalesce((select
   coalesce((select not ctl.restore_quarantine from public.translation_retention_control ctl where ctl.singleton),false)
   and public.translation_revision_scope_available(t.source_revision_id,p.processor,p.processing_region,'process')
   and public.translation_revision_scope_available(t.source_revision_id,p.processor,p.processing_region,'store')
   and public.translation_revision_scope_available(t.source_revision_id,p.processor,p.processing_region,'editor_display')
   and r.draft_sha256=encode(sha256(convert_to(public.translation_source_payload(t.source_revision_id)::text,'UTF8')),'hex')
   and (select count(*) from public.translation_request_grants x where x.request_id=r.request_id)=9*(
     select count(distinct a.source_id) from public.claims c join public.claim_evidence e on e.claim_id=c.id
       join public.articles a on a.id=e.article_id where c.revision_id=t.source_revision_id)
   and not exists(select 1 from public.translation_request_grants x join public.translation_scope_grants g on g.id=x.grant_id
     join public.source_policies sp on sp.id=g.policy_id where x.request_id=r.request_id and (
       g.provider is distinct from p.processor or g.processing_region is distinct from p.processing_region
       or g.expires_at<=statement_timestamp() or exists(select 1 from public.translation_scope_revocations v where v.grant_id=g.id)
       or sp.id is distinct from (select v.id from public.source_policies v where v.source_id=sp.source_id order by v.version desc limit 1)
       or not exists(select 1 from public.claims c join public.claim_evidence e on e.claim_id=c.id join public.articles a on a.id=e.article_id
         where c.revision_id=t.source_revision_id and a.source_id=sp.source_id)))
   from public.translation_requests r join public.translation_task_intents t on t.id=r.intent_id
   join public.ai_request_preparations p on p.request_id=r.request_id where r.request_id=p_request),false)
$$;



CREATE FUNCTION public.translation_revision_scope_available(p_revision uuid, p_provider text, p_region text, p_action text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(p_provider is not null and p_region is not null and p_action in ('process','store','editor_display')
    and public.editor_revision_sources_available(p_revision)
    and exists(select 1 from public.claims c where c.revision_id=p_revision)
    and not exists(select 1 from public.claims c where c.revision_id=p_revision and
      (c.status<>'verified' or not exists(select 1 from public.claim_evidence e where e.claim_id=c.id and e.relation='supports'
        and e.verified_by is not null and e.verified_at is not null and length(trim(e.evidence_reference))>0)))
    and not exists(select 1 from public.claims c join public.claim_evidence e on e.claim_id=c.id
      where c.revision_id=p_revision and e.relation='contradicts')
    and not exists(select 1 from public.claims c join public.claim_evidence e on e.claim_id=c.id
      join public.articles a on a.id=e.article_id
      left join lateral (select * from public.source_policies sp where sp.source_id=a.source_id order by sp.version desc limit 1) p on true
      cross join (values ('title'),('summary'),('claims')) f(name)
      where c.revision_id=p_revision and not exists(select 1 from public.translation_scope_grants g
        where g.policy_id=p.id and g.provider=p_provider and g.processing_region=p_region and g.field_name=f.name
          and g.permitted_action=p_action and g.expires_at>statement_timestamp()
          and not exists(select 1 from public.translation_scope_revocations r where r.grant_id=g.id)))
    ,false)
$$;



CREATE FUNCTION public.translation_source_payload(p_revision uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select jsonb_build_object('title',r.title,'summary',r.summary,'claims',coalesce((
    select jsonb_agg(jsonb_build_object('id',c.id,'text',c.claim_text,'status',c.status,'evidence',coalesce((
      select jsonb_agg(jsonb_build_object('article',e.article_id,'relation',e.relation,'reference',e.evidence_reference,
        'verified_by',e.verified_by,'verified_at',e.verified_at) order by e.article_id,e.relation)
      from public.claim_evidence e where e.claim_id=c.id),'[]'::jsonb)) order by c.id)
    from public.claims c where c.revision_id=r.id),'[]'::jsonb)) from public.story_revisions r where r.id=p_revision
$$;



CREATE FUNCTION public.translation_valid_proposal(p_request uuid, p_content jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare rev uuid; ids jsonb; n integer; row jsonb; i integer;
begin
  select t.source_revision_id into rev from public.translation_requests r join public.translation_task_intents t on t.id=r.intent_id where r.request_id=p_request;
  if rev is null or jsonb_typeof(p_content)<>'object' or not (p_content ?& array['schema_version','headline','segments']) or (select count(*) from jsonb_object_keys(p_content))<>3
    or p_content->>'schema_version'<>'translation_proposal.v1' or jsonb_typeof(p_content->'headline')<>'string'
    or length(trim(p_content->>'headline')) not between 1 and 500 or jsonb_typeof(p_content->'segments')<>'array'
    or octet_length(p_content::text)>65536 then return false; end if;
  select count(*),jsonb_agg(to_jsonb(c.id::text) order by c.id) into n,ids from public.claims c where c.revision_id=rev;
  if n not between 1 and 20 or jsonb_array_length(p_content->'segments')<>n+1 then return false; end if;
  for i in 0..n loop
    row:=p_content->'segments'->i;
    if jsonb_typeof(row)<>'object' or not (row ?& array['segment_id','text','claim_ids']) or (select count(*) from jsonb_object_keys(row))<>3
      or jsonb_typeof(row->'segment_id')<>'string' or jsonb_typeof(row->'text')<>'string'
      or length(trim(row->>'text')) not between 1 and 4000 or jsonb_typeof(row->'claim_ids')<>'array' then return false; end if;
    if i=0 then
      if row->>'segment_id'<>rev::text or row->'claim_ids'<>ids then return false; end if;
    elsif row->>'segment_id'<>ids->>(i-1) or row->'claim_ids'<>jsonb_build_array(ids->>(i-1)) then return false;
    end if;
  end loop;
  return true;
exception when others then return false;
end $$;



CREATE TABLE public.ai_alert_outbox (
    incident_id uuid NOT NULL,
