    attempts integer DEFAULT 0 NOT NULL,
    available_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT ai_alert_outbox_attempts_check CHECK (((attempts >= 0) AND (attempts <= 3))),
    CONSTRAINT ai_alert_outbox_check CHECK ((((status = 'processing'::text) AND (lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR ((status <> 'processing'::text) AND (lease_token IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT ai_alert_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'retry_wait'::text, 'delivered'::text, 'unknown'::text, 'failed'::text])))
);



