    ai_processing_allowed boolean DEFAULT false NOT NULL,
    display_allowed boolean DEFAULT false NOT NULL,
    fulltext_storage_allowed boolean DEFAULT false NOT NULL,
    image_usage_allowed boolean DEFAULT false NOT NULL,
    policy_evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    story_publication_allowed boolean DEFAULT false NOT NULL,
    permission_expires_at timestamp with time zone,
    access_method text DEFAULT 'manual'::text NOT NULL,
    title_storage_allowed boolean DEFAULT false NOT NULL,
    url_storage_allowed boolean DEFAULT false NOT NULL,
    source_display_allowed boolean DEFAULT false NOT NULL,
    link_display_allowed boolean DEFAULT false NOT NULL,
    terms_url text,
    robots_url text,
    attribution_requirements text,
    permitted_region text,
    title_ai_processing_allowed boolean DEFAULT false NOT NULL,
    ai_processor text,
    ai_processing_region text,
