    CONSTRAINT source_policies_access_method_check CHECK ((access_method = ANY (ARRAY['manual'::text, 'rss'::text, 'api'::text]))),
    CONSTRAINT source_policies_policy_status_check CHECK ((policy_status = ANY (ARRAY['unreviewed'::text, 'approved'::text, 'restricted'::text, 'paused'::text, 'rejected'::text]))),
    CONSTRAINT source_policies_version_check CHECK ((version > 0)),
    CONSTRAINT source_policy_ai_scope_check CHECK (((NOT title_ai_processing_allowed) OR (ai_processing_allowed AND (ai_processor IS NOT NULL) AND (ai_processor = 'openai'::text) AND (ai_processing_region IS NOT NULL) AND (ai_processing_region ~ '^[a-z0-9-]{2,40}$'::text))))
