    CONSTRAINT translation_scope_grants_field_name_check CHECK ((field_name = ANY (ARRAY['title'::text, 'summary'::text, 'claims'::text]))),
    CONSTRAINT translation_scope_grants_permitted_action_check CHECK ((permitted_action = ANY (ARRAY['process'::text, 'store'::text, 'editor_display'::text]))),
    CONSTRAINT translation_scope_grants_processing_region_check CHECK ((processing_region ~ '^[a-z0-9-]{2,40}$'::text))
);



CREATE TABLE public.translation_scope_revocations (
    grant_id uuid NOT NULL,
    revoked_by uuid NOT NULL,
    reason text NOT NULL,
    revoked_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT translation_scope_revocations_reason_check CHECK (((length(TRIM(BOTH FROM reason)) >= 1) AND (length(TRIM(BOTH FROM reason)) <= 1000)))
);



CREATE TABLE public.translation_task_intents (
    id uuid NOT NULL,
    story_id uuid NOT NULL,
    source_revision_id uuid NOT NULL,
    source_locale text NOT NULL,
    target_locale text NOT NULL,
    glossary_version text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT translation_task_intents_check CHECK (((target_locale = ANY (ARRAY['zh'::text, 'en'::text])) AND (target_locale <> source_locale))),
    CONSTRAINT translation_task_intents_glossary_version_check CHECK ((glossary_version = 'glossary.v1'::text)),
    CONSTRAINT translation_task_intents_source_locale_check CHECK ((source_locale = ANY (ARRAY['zh'::text, 'en'::text])))
);



